window.NM_LIT = {"w001":{"t":"길","a":"김소월","who":[["화자","고향을 잃고 정처 없이 떠도는 나그네"],["기러기","공중을 자유롭게 나는, 화자와 대비되는 존재"]],"steps":[{"h":"1~2연","ev":"화자는 어제도 나그네 집에서 가마귀 울음 속에 밤을 새웠고, 오늘은 또 몇십 리를 어디로 갈지 막막해한다.","feel":"불안","who":["화자"]},{"h":"3연","ev":"산으로 갈지 들로 갈지 망설이지만 오라는 곳이 없어 어디에도 가지 못한다.","feel":"막막함","who":["화자"],"q":"오라는 곳이 없어 나는 못 가오"},{"h":"4연","ev":"고향 정주 곽산은 차도 배도 다니는 곳이지만, 화자는 그곳에 갈 수 없는 처지임을 털어놓는다.","feel":"서러움","who":["화자"]},{"h":"5~6연","ev":"공중에는 길이 있어 잘 가느냐고 기러기에게 말을 건네고, 갈림길 열십자 복판에 선 자신을 기러기와 견준다.","feel":"자조","who":["화자","기러기"]},{"h":"7연","ev":"갈래갈래 갈린 길이 많아도 정작 자신이 갈 길은 하나도 없다고 말하며 절망한다.","feel":"절망","who":["화자"]}],"key":"고향을 잃고 갈림길 한복판에 선 나그네의 절망을, 대화하듯 건네는 말투로 노래한다.","pt":["3음보 율격의 변주와 ‘-오/-소’ 종결 반복이 만드는 리듬, 대화하듯 건네는 말투","공중을 나는 ‘기러기’와 ‘열십자’ 복판에 선 화자의 대비(정답: 기러기·열십자)","‘길’은 끝없는 나그네의 여정이자 일제강점기 유랑민의 삶의 행로를 뜻한다"],"src":"해설 p.1 · 본책 p.9~11","g":"현대시","s":"수특 1부 1강","th":"고향을 잃고 떠도는 나그네의 비애"},"w002":{"t":"고울사 저 꽃이여~","a":"안민영","who":[["화자","반쯤 시든 꽃을 바라보며 감탄하는 사람"],["꽃","화자가 말을 건네는 반쯤 여윈 꽃"],["나비","봄바람에 향기를 좇아 오는 나비"]],"steps":[{"h":"초장","ev":"반쯤 여윈 꽃을 고운 꽃이라 부르며 말을 건넨다. 활짝 핀 때를 지나 시들기 시작한 꽃의 자태를 예찬한다.","feel":"예찬","who":["화자","꽃"],"q":"고울사 저 꽃이여 반(半)만 여윈 저 꽃이여"},{"h":"중장","ev":"더도 덜도 말고 늘 지금 그대로 있어 주기를 바란다. 더 시들지 않기를 비는 마음에 안타까움이 깔려 있다.","feel":"소망","who":["화자","꽃"],"q":"더도 덜도 말고 매양 그만하여 있어"},{"h":"종장","ev":"봄바람에 향기를 좇아 온 나비를 꽃이 웃으며 맞이하는 표정을 그린다. 꽃과 나비가 어울려 화자의 만족감이 드러난다.","feel":"만족","who":["꽃","나비"],"q":"춘풍에 향기 좇는 나비를 웃고 맞이하노라"}],"key":"반쯤 시든 꽃을 예찬하면서 곧 질 꽃에 대한 안타까움도 깔린 시조이다","pt":["‘반쯤 시든’ 꽃을 긍정하는 관점: 늙음·원숙의 가치를 예찬하는 인생 비유로도 읽힌다","예찬의 어조 이면에, 모든 꽃은 결국 시든다는 안타까움이 엿보인다","‘저 꽃’과 ‘나비’는 서로 조화를 이루는 자연물로 화자의 만족감을 드러낸다"],"src":"해설 p.2 · 본책 p.13~14","g":"고전시가","s":"수특 1부 2강","th":"반쯤 시든 꽃의 원숙한 아름다움"},"w003":{"t":"꾀꼴꾀꼴 우는 소리에~","a":"오경화","who":[["화자","삼대가 사는 집의 가장, 손자의 할아버지"],["식구들","글 읽는 아들, 베 짜는 며느리, 꽃놀이하는 손자"],["아내","술을 거르며 맛보라고 권하는 지어미"]],"steps":[{"h":"초장","ev":"봄날 꾀꼬리 울음소리에 낮잠을 깨고 일어난다. 청각적 이미지로 한가롭고 평화로운 장면이 열린다.","feel":"한가","who":["화자"],"q":"꾀꼴꾀꼴 우는 소리에 낮잠 깨어 일어나 보니"},{"h":"중장","ev":"작은아들은 글을 읽고 며느리는 베를 짜며 어린 손자는 꽃놀이를 한다. 식구들이 제 몫의 일과 놀이를 하는 평화로운 일상이다.","feel":"평화","who":["화자","식구들"],"q":"작은아들 글을 읽고 며늘아기 베 짜는데"},{"h":"종장","ev":"마침 아내가 술을 거르며 맛보라고 권한다. 가장이 누리는 소박한 행복이 담담하게 마무리된다.","feel":"만족","who":["화자","아내"],"q":"때마침 지어미 술 거르며 맛보라고 하더라"}],"key":"삼대가 함께 사는 봄날의 한가롭고 평화로운 일상을 담담하게 그린 시조이다","pt":["화자는 ‘작은아들’의 아버지·‘손자’의 할아버지인 한 가정의 가장이다","‘꾀꼴꾀꼴’ 외에 ‘글을 읽고’·‘베 짜는데’도 다른 공간에서 들려오는 청각적 심상이다","‘낮잠’과 ‘술’은 범주가 달라도 평화롭고 한가로운 일상이라는 하나의 의미로 모인다"],"src":"해설 p.2 · 본책 p.13~14","g":"고전시가","s":"수특 1부 2강","th":"삼대 가족이 함께 누리는 평화로운 일상"},"w004":{"t":"농부를 대신하여 읊다(대농부음)","a":"이규보","who":[["화자","수탈당하는 농부(작가가 설정한 화자)"],["왕손공자","농부를 얕보는 부귀한 지배층"],["아전","때가 되기 전에 조세를 거두는 관리"]],"steps":[{"h":"1연 앞","ev":"비를 맞으며 논바닥에 엎드려 김을 매니, 흙투성이 험한 꼴이 사람 모습 같지 않다고 스스로 말한다.","feel":"고달픔","who":["화자"],"q":"비 맞으며 논바닥에 엎드려 김매니"},{"h":"1연 뒤","ev":"왕손공자들에게 더 이상 얕보지 말라고 항변한다. 그대들의 부귀와 호사가 바로 우리 농부에게서 나온다고 따진다.","feel":"항변","who":["화자","왕손공자"],"q":"왕손공자들아 더 이상 얕보지 마오"},{"h":"2연 앞","ev":"햇곡식은 아직 푸릇푸릇 논밭에서 자라는데, 아전들은 벌써부터 조세를 거둔다고 성화를 부린다.","feel":"원망","who":["화자","아전"],"q":"아전들은 벌써부터 조세 거둔다고 성화로세"},{"h":"2연 뒤","ev":"힘써 경작해 나라를 부유하게 한 이는 바로 우리들인데, 어찌 이리 극성스럽게 침탈하느냐고 되묻는다.","feel":"분노","who":["화자","아전"],"q":"어찌 이리도 극성스레 침탈하는가"}],"key":"고려 문신이 농부의 목소리를 빌려 지배층의 수탈을 항변하는 한시이다","pt":["작가 이규보는 고려의 문신이고 화자는 ‘우리 농부’ — 작가와 화자를 구분한다","비판 대상은 농민을 얕보고 때 이른 조세를 거두는 지배층(왕손공자·아전)이다","‘조세’는 노동의 보람이 아니라 수탈의 수단으로 표현된다"],"src":"해설 p.2 · 본책 p.13~14","g":"고전시가","s":"수특 1부 2강","th":"농민 수탈에 대한 주체적 항변"},"w005":{"t":"징 소리","a":"문순태","who":[["칠복","수몰로 고향을 잃고 징을 울리며 떠도는 실향민"],["봉구","칠복의 마을 친구, 쫓아내면서도 미안해한다"],["강촌영감","칠복을 내보내기로 결단하는 마을 어른"],["순덕","도시에서 온 칠복의 아내, 도시 생활을 원한다"],["방울재 사람들","수몰 뒤 매운탕 장사로 사는 칠복의 고향 이웃"]],"steps":[{"h":"발단","ev":"부모 없이 외가에서 머슴처럼 자란 칠복은 도시에서 온 순덕과 부부가 되지만, 도시 생활을 바라는 아내 탓에 광주의 사글셋방에서 궁색하게 산다.","feel":"고단함","who":["칠복","순덕"]},{"h":"전개·수록","ev":"품삯을 쥐고 돌아온 집에서 아내가 다른 남자와 있는 모습을 본 칠복은, 아내를 찾아다니느라 돈을 다 쓰고 징 하나만 든 채 거지처럼 떠돈다.","feel":"상실감","who":["칠복","순덕"]},{"h":"전개·수록","ev":"징에서 고향 사람들이 부르는 소리가 들려오자 칠복은 딸을 업고 하루를 꼬박 걸어, 수몰된 마을 사람들이 모여 사는 댐 근처에 이른다.","feel":"그리움","who":["칠복","방울재 사람들"]},{"h":"위기·수록","ev":"댐 인근에서 징을 울려 낚시꾼들을 방해하다 매를 맞는 칠복을, 낚시꾼 상대 매운탕 장사로 먹고사는 방울재 사람들은 동정하면서도 쫓아내기로 한다.","feel":"서러움","who":["칠복","방울재 사람들"]},{"h":"절정·수록","ev":"칠복은 무릎 꿇고 내쫓지 말라고 빌지만 모두 말이 없고, 고향 사람들과 어울려 사는 환각에 빠져 춤을 추다가 정신이 들면 호수와 댐뿐이다.","feel":"애원","who":["칠복","강촌영감","봉구"]},{"h":"결말·수록","ev":"강촌영감이 단칼에 정을 끊자며 재촉하자 칠복 부녀는 밤에 버스에 태워져 쫓겨나고, 봉구는 돈을 쥐여 주며 다시는 오지 말라고 울먹인다.","feel":"체념","who":["칠복","강촌영감","봉구"],"q":"징헌 고향 다시는 오지 말어."},{"h":"여운·수록","ev":"그날 밤 방울재 사람들은 잠들지 못하고, 봉구는 빗소리 사이로 쉬지 않고 들려오는 징 소리에 놀라 깨어 칠복이 돌아올 것만 같아 뒤척인다.","feel":"죄책감","who":["봉구","방울재 사람들"],"q":"바람소린지, 징소린지."}],"key":"수몰로 고향을 잃은 칠복의 한을 징 소리에 실어, 무너진 공동체와 실향민의 아픔을 그린다.","pt":["초점화자 구분: [A]는 칠복(고향 그리움), [B]는 봉구(칠복에 대한 죄책감)","환각: 방울재를 현재와 다르게 보는 칠복의 상태 — ‘쫓아낼 구실’이라는 선지는 오답","징 소리가 환기하는 것: 비인간화된 현대 비판과 공동체적 삶의 회복 염원"],"src":"해설 p.3 · 본책 p.16~18 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 1부 3강","th":"수몰로 고향을 잃은 사람들의 상실과 한"},"w006":{"t":"임진록","a":"작자 미상","who":[["김응서","용맹한 장수. 홀로 평양성에 잠입해 적장을 벤다"],["이원익","조선군 장수. 김응서를 찾아 출전을 청한다"],["종일","왜장 평행장의 부장. 평양성을 지킨다"],["기생","평양성의 기생(해설: 계월향). 적진 사정을 일러 준다"]],"steps":[{"h":"발단","ev":"이원익이 왜장 종일에게 크게 패해 달아나자 한 도사가 신통한 도구로 적을 묶어 구하고, 종일은 성안에 틀어박혀 굳게 지킨다.","feel":"위태로움","who":["이원익","종일"],"q":"문득 한 도사가 원익의 위태함을 보고"},{"h":"천거","ev":"한 군사가 큰 범을 붙잡아 죽인 용강의 김응서를 천거한다. 상중이던 응서는 국세가 위태롭다는 이원익의 간청에 못 이겨 평복으로 갈아입고 진에 온다.","feel":"망설임","who":["김응서","이원익"],"q":"백성 된 자가 어찌 사사로운 정을 돌아보리오"},{"h":"잠입","ev":"응서는 밤에 비수를 끼고 평양성을 넘어 잠든 수문군을 베고 들어가, 소피보러 나온 기생에게 적장의 동정을 일러 달라고 한다.","feel":"결연함","who":["김응서","기생"],"q":"나라를 위하여 적장의 동정을 자세히 이르라"},{"h":"기생의 도움","ev":"기생은 종일이 휘장과 방울로 침입에 대비하고 자면서도 눈과 귀를 번갈아 열어 둔다고 알리며, 먼저 들어가 방울을 솜으로 막겠다고 한다.","feel":"협조적","who":["기생","종일"],"q":"방울을 솜으로 막고 나오거든 장군이 들어가소서"},{"h":"절정","ev":"응서가 술에 취해 자던 종일의 머리를 치자 떨어진 머리가 분기를 내며 일어나 보검으로 들보를 치고, 이내 머리와 몸이 상 아래로 쓰러진다.","feel":"용맹","who":["김응서","종일"],"q":"종일의 머리 떨어지며 분기를 발하여 일어서며"},{"h":"탈출","ev":"소란 속에 응서는 기생을 데리고 나와 왜장 평의지를 물리친다. 평수맹이 기생을 베자 노한 응서가 그를 한 칼에 베고 적을 헤치며 성을 넘는다.","feel":"분노","who":["김응서","기생"],"q":"응서의 칼이 있는 곳에 도적의 머리 추풍낙엽 같으니"},{"h":"결말","ev":"매복했던 부장 안일봉의 도움으로 진중에 돌아온 응서가 전말을 고하자, 이원익이 크게 기뻐하며 공을 치하하고 종일의 머리를 깃발에 단다.","feel":"기쁨","who":["이원익","김응서"]}],"key":"임진왜란 때 김응서가 평양성에 잠입해 왜장 종일을 베는 영웅담. 사실에 설화적 상상력을 더했다","pt":["서술자의 평가 ‘응서의 칼이~추풍낙엽 같으니’는 김응서의 무력 예찬(1번)","종일의 치밀함은 방울 장치·눈과 귀를 번갈아 여는 잠으로 드러남. 방비 허술은 서사 전략(2번)","도사·기생·초현실 장면은 설화적 위안과 민중의 활약을 보여 줌(3번)"],"src":"해설 p.4 · 본책 p.20~22","g":"고전산문","s":"수특 1부 4강","th":"전란의 패배를 허구적 승리로 보상하려는 민중 의식"},"w007":{"t":"길삼봉뎐","a":"김민정","who":[["선조","길삼봉 수사로 신하끼리 싸우게 해 왕권을 키우는 왕"],["정철","서인, 위관으로 길삼봉을 찾다 몰락하는 인물"],["이산해","동인, 정철을 몰아붙여 위관 자리를 넘겨받는다"],["최영경","길삼봉으로 몰려 국청에 선 재야의 처사"]],"steps":[{"h":"앞부분 줄거리","ev":"정여립이 역모죄로 죽자 선조는 서인 정철에게 반란의 우두머리 길삼봉 수사를 맡기고, 정철은 처사 최영경을 길삼봉으로 의심해 체포한다.","feel":"불안","who":["선조","정철","최영경"]},{"h":"국청 신문","ev":"술에 취한 정철이 행함 없는 뜻은 헛것이라며 몰아세우자, 최영경은 헛것을 핑계로 선비의 목을 치는 쪽이 누구냐고 되받으며 당쟁만 일삼는 위정자를 꾸짖는다.","feel":"당당함","who":["정철","최영경"],"q":"행함이 없으면 다 헛것인 것을"},{"h":"옥사와 고발","ev":"최영경이 옥사하자 분노한 선조 앞에서 이산해는 정철 수하들의 무고를 들어 계략이라 몰아붙이며 서찰을 내밀고, 정철은 충정이며 모함이라고 맞선다.","feel":"분노","who":["선조","정철","이산해"]},{"h":"선조의 처분","ev":"서찰을 본 선조는 정철의 관직을 폐하고 위리안치하게 하며, 이산해에게 위관을 맡기고 최영경을 무고한 이들을 반좌율로 다스리라 명한다.","feel":"엄정함","who":["선조","정철","이산해"]},{"h":"웃음의 반전","ev":"이산해와 함께 웃던 선조가 갑자기 웃음을 거두고 길삼봉을 어서 잡아들이라 재촉하자 이산해는 놀라 형틀을 준비시키고, 선조는 여유롭게 웃는다.","feel":"여유","who":["선조","이산해"]}],"key":"실체 없는 길삼봉을 내세워 신하들을 싸우게 하고 왕권을 키우는 선조, 정치 권력의 비정함","pt":["㉠~㉤ 지시문이 행동·심리·반어를 어떻게 드러내는지 판별하기","ⓐ 국청(옥사)과 ⓑ 서찰을 둘러싼 정철·이산해·최영경·선조의 입장과 관계 변화","보기(기축옥사, 선조의 왕권 강화)와 연결해 '헛것'·'갑자기 웃음을 거두며' 찾기"],"src":"해설 p.4~5 · 본책 p.24~27 · 수록 부분만","g":"극·수필","s":"수특 1부 5강","th":"선조의 공포 정치와 인물 간 권력 관계"},"w008":{"t":"율정설","a":"백문보","who":[["글쓴이","윤공과 같은 해 급제한 벗, 밤나무에 빗대 설을 짓는다"],["윤공(윤택)","밤나무가 있는 곳에 집을 짓고 정자를 율정이라 부른 사람"]],"steps":[{"h":"사실","ev":"윤공은 집을 살 때마다 밤나무가 있는 곳을 골라 정자를 율정이라 이름 짓고, 봄의 꽃·여름 그늘·가을 밤맛·겨울 땔감을 들어 까닭을 말한다.","feel":"애정","who":["윤공(윤택)"]},{"h":"같은 기운","ev":"글쓴이는 불이 마른 데로 가고 물이 젖은 데로 흐르듯 사람도 숭상하는 바와 닮는다고 하며, 밤이 가장 늦게 나지만 자라면 빨리 큰다는 점을 짚는다.","feel":"관찰","who":["글쓴이"]},{"h":"윤공의 삶","ev":"윤공도 서른이 넘어 급제하고 마흔이 넘어서야 벼슬했으나 임금의 눈에 들자 하루에 아홉 번 승진해 중책을 맡았으니, 손질 없이 무성해진 밤나무와 같다.","feel":"칭송","who":["윤공(윤택)"]},{"h":"이치 풀이","ev":"싹이 깊으면 올라옴이 늦어도 끝내 줄기를 이루고 샘물은 고이면 바다에 닿듯 느린 것은 반드시 빨라진다며, 이를 이지러지면 차는 이치로 일반화한다.","feel":"확신","who":["글쓴이"],"q":"이지러지면 가득 차게 되고 빠지면 더해지는"},{"h":"깨달음","ev":"윤공의 영달은 밤의 생장이고 물러남은 밤을 거두어 간직함이니, 나아감에는 세상을 돕는 도가, 물러남에는 삶을 닦는 작용이 있다며 이를 들어 설을 짓는다.","feel":"정리","who":["글쓴이","윤공(윤택)"]}],"key":"늦게 자라도 크게 결실하는 밤나무에 견주어, 늦되어도 이룰 수 있다는 이치와 윤공의 삶을 칭송한 설","pt":["설 갈래의 특성: 밤나무의 생장(사실)과 윤공의 삶을 유추로 이어 이치를 끌어냄","윤공의 말에 대한 글쓴이의 속뜻, ㉠(어려움·쉬움, 빠름·느림)에 대한 관점","보기의 역설을 겸손에 적용: '자신을 낮추면 (높아진다)' 서답형"],"src":"해설 p.6 · 본책 p.29~30","g":"극·수필","s":"수특 1부 6강","th":"‘설(說)’ — 사물에서 이치를 끌어내는 교술"},"w009":{"t":"하나씩의 별","a":"이용악","who":[["화자","함경도 사내, 고향과 다른 쪽으로 가는 사람"],["유랑민들","열차 지붕 위에서 고향으로 돌아가는 사람들"]],"steps":[{"h":"1연","ev":"문이 굳게 잠긴 화물열차 지붕 위에 사람들이 제각기 누워, 바람 속에서 한결같이 하나씩의 별을 쳐다본다.","feel":"답답함","who":["화자","유랑민들"]},{"h":"2연","ev":"두만강 저쪽과 쟈무스에서 온 사람들, 고향 남도로 가는 사람들과 요기를 나누며, 화자는 서울이 그리워 고향과 딴 방향으로 간다.","feel":"쓸쓸함","who":["화자","유랑민들"]},{"h":"3연","ev":"광복의 기쁨 속에서도, 헐벗은 채 돌아오는 사람들과 헐벗은 자신을 바라보며 민족의 앞날에 대한 불안을 느낀다.","feel":"불안","who":["화자"]},{"h":"4연","ev":"다시 열차 지붕 위에 누운 사람들이 저마다 별을 쳐다보며, 불안한 현실 속에서도 각자의 미래에 대한 희망을 품는다.","feel":"희망","who":["화자","유랑민들"],"q":"한결같이 쳐다보는 하나씩의 별"}],"key":"처지는 달라도 헐벗은 유랑민들이 열차 지붕 위에서 저마다의 별에 희망을 건다.","pt":["첫 연과 끝 연의 같은 시구 반복이 주제(저마다의 희망)를 부각한다","‘푸르른 바다와 거리거리’는 이민 열차에서 서러이 내다보던 풍경이지 귀국의 감격이 아니다","작가 맥락(간도 유랑민의 비참한 실상에 주목한 시인)과 해방기 귀향 상황을 연결해 감상"],"src":"해설 p.7 · 본책 p.32~34","g":"현대시","s":"수특 1부 7강","th":"해방 직후 귀국하는 유랑민들의 고단한 처지와 소망"},"w010":{"t":"카인의 후예(시나리오)","a":"황순원 원작·이상현 각색","who":[["박훈","지주의 아들이자 학당 교사, 떠날 마음을 품은 인물"],["오작녀","소작인의 딸, 훈 곁에서 그를 돌보는 데 헌신하는 여인"],["도섭 영감","옛 마름, 지금은 훈에게 적대적인 오작녀의 아버지"],["개털","농민대회 결정을 들어 훈을 악질 반동 지주로 규정"]],"steps":[{"h":"S#32 훈의 방","ev":"밥상을 받다 손이 겹친 훈은 오작녀에게 남편도 돌아왔으니 자기 일을 생각하라 하고, 자신도 이곳을 떠나야 할 것 같다고 어렵게 말한다.","feel":"어색함","who":["박훈","오작녀"]},{"h":"오작녀의 청","ev":"오작녀는 나가라는 말씀만 말아 달라고 간청하다 끝내 말을 맺지 못하고 격정에 못 이겨 밖으로 뛰어나가고, 훈은 눈을 감는다.","feel":"애틋함","who":["오작녀","박훈"]},{"h":"S#33 과수원","ev":"과수원으로 달려간 오작녀는 나무 기둥에 이마를 대고 흐느끼다 불 밝은 훈의 방을 올려다보고, 멀리서 뻐꾸기 소리가 들린다.","feel":"서러움","who":["오작녀"]},{"h":"중략 줄거리","ev":"농민대회에서 토지 개혁이 결정되어 농민들이 지주의 집을 차례로 찾아 재산을 몰수하고, 마침내 훈의 집에도 찾아온다.","feel":"긴박","who":["박훈","개털"]},{"h":"S#101 마당","ev":"개털이 훈을 악질 반동 지주로 규정하고 재산 몰수를 선언하자 열에 뜬 오작녀가 나서서 항의하고, 들어가라는 도섭에게 이미 아버지의 딸이 아니라고 맞선다.","feel":"결연함","who":["개털","오작녀","도섭 영감"]},{"h":"우리는 부부","ev":"열쇠를 내놓으라는 개털에게 오작녀는 이 집은 내 집이라며 버티다 부부가 되었다고 외치고, 훈과 사람들은 아연해한다.","feel":"단호함","who":["오작녀","박훈","개털"],"q":"우리는 부부가 되시요!"}],"key":"이념 대립이 지주를 몰아붙이는 위기에서, 신분과 금기를 넘어 훈을 지키려는 오작녀의 선택","pt":["원작 소설(보기)과 시나리오 [A] 비교: 장면 번호·행동·표정으로 내면 표현","보기(토지 개혁 배경)로 본 훈의 비탐욕적 태도와 오작녀의 애정(학생 의견 고르기)","예상 못 한 오작녀의 발언에 당황하는 훈, 두 위기가 모두 없기를 바라는 오작녀"],"src":"해설 p.8 · 본책 p.36~39 · 수록 부분만","g":"극·수필","s":"수특 1부 8강","th":"해방 직후 북한 토지 개혁 속 증오와 사랑"},"w011":{"t":"고향","a":"현진건","who":[["나","기차 안에서 ‘그’의 이야기를 듣는 서술자"],["그","기이한 차림으로 고향 없이 떠도는 농민"],["혼담이 있던 여인","유곽에 팔려 갔다 풀려난 ‘그’의 옛 혼담 상대"]],"steps":[{"h":"발단·수록","ev":"대구에서 서울로 가는 기차에서 ‘나’는 기모노 두루마기에 중국식 바지, 짚신 차림의 기이한 ‘그’와 마주 앉아 흥미롭게 살핀다.","feel":"호기심","who":["나","그"]},{"h":"전개·수록","ev":"‘그’의 고향은 역둔토를 부쳐 평화롭게 살던 마을이었으나, 땅이 동양척식회사에 넘어가고 중간 소작인까지 끼어 수확의 삼 할도 못 쥐게 되자 사람들이 떠난다.","feel":"울분","who":["그"]},{"h":"전개·수록","ev":"열일곱에 간도로 이사한 ‘그’는 아버지와 어머니를 차례로 잃고, 신의주와 안동현을 거쳐 일본의 탄광과 철공장을 떠돌며 방탕해진다.","feel":"서러움","who":["그"]},{"h":"위기·수록","ev":"구 년 만에 찾은 고향은 집도 사람도 없는 폐동이어서, ‘그’는 무덤을 파헤친 듯한 폐허 앞에서 가슴이 터질 듯한 심정으로 눈물을 떨군다.","feel":"절망","who":["그"],"q":"고향이 통 없어졌드마."},{"h":"절정·수록","ev":"‘그’는 읍내에서 혼담이 오갔다가 아비 손에 유곽에 팔린 여인을 만나는데, 병들고 늙어 버린 그녀 앞에서 눈물도 안 나와 술만 나누고 헤어진다.","feel":"참담함","who":["그","혼담이 있던 여인"],"q":"눈물도 안 나오드마."},{"h":"결말(해설)","ev":"‘나’는 ‘그’의 처지에 공감해 술잔을 나누며 일제에 대한 분노와 절망을 곱씹다가, 어린 시절 부르던 노래를 함께 부르며 유대감을 느낀다.","feel":"연민","who":["나","그"]}],"key":"액자식 구성으로 ‘그’의 얼굴에 겹친 일제강점기 조선 민중의 참혹한 삶을 고발한다.","pt":["사회·역사적 맥락 탐구: 노동숙박소·옷차림·찻간 풍경 같은 시대 자료를 찾아보는 계획(ⓒⓓⓔ)","동척의 토지 수탈에 중간 소작인의 착취가 더해져 ‘그’와 고향 사람들의 소득이 크게 준다(2번)","㉣ ‘눈물도 안 나오드마’를 취업난에 따른 인간관계 변질로 읽는 이해는 오답(3번 ④)"],"src":"해설 p.9 · 본책 p.41~44 · 결말은 해설 줄거리","g":"현대소설","s":"수특 1부 9강","th":"일제 수탈로 고향을 잃은 농민의 비참한 삶"},"w012":{"t":"원가","a":"신충","who":[["화자","임금에게 잊힌 신하 신충(작가와 겹쳐 읽음)"],["임","신충을 중히 여기겠다 약속한 효성왕"]],"steps":[{"h":"1~2구","ev":"질 좋은 잣나무는 가을에도 말라 떨어지지 않는다고 한다. 잣나무가 증인이 되리라던 왕의 말을 떠올리게 하는 소재이다.","feel":"회상","who":["화자","임"],"q":"가을에 말라 떨어지지 아니하매"},{"h":"3~4구","ev":"‘너를 중히 여겨 가겠다’ 하시던 말씀과 달리 임의 낯이 변해 버린 겨울이라고 탄식한다. 왕의 마음이 식어 싸늘해졌다.","feel":"탄식","who":["화자","임"],"q":"낯이 변해 버리신 겨울에여"},{"h":"5~6구","ev":"달그림자 내린 연못가에서 지나가는 물결(왕)을 바라보는 모래(자신)에 스스로를 빗댄다. 왕의 마음을 붙잡지 못한다.","feel":"소외감","who":["화자","임"],"q":"지나가는 물결에 대한 모래로다"},{"h":"7~8구","ev":"임의 모습은 바라볼 뿐 세상 모든 것을 여읜 처지라며 상실감과 괴로움을 토로한다. 후구는 소실되어 전하지 않는다.","feel":"상실감","who":["화자"],"q":"세상 모든 것 여희여 버린 처지(處地)여"}],"key":"약속을 잊은 임금을 원망하는 향가로, 잣·달·물의 비유로 이별의 분위기를 드러낸다","pt":["배경 설화(노래를 잣나무에 붙이자 말랐다가 등용되자 되살아남)와 노래의 관계를 묻는다","‘너를 중히 여겨’ 직접 인용은 자신을 잊지 않겠다던 왕의 장담을 환기한다","‘지나가는 물결’은 왕, ‘모래’는 화자 — 모래에 왕을 빗대면 오답이다"],"src":"해설 p.10~11 · 본책 p.46~47","g":"고전시가","s":"수특 고전시가 1강","th":"약속을 잊은 임금에 대한 원망"},"w013":{"t":"진중음","a":"이순신","who":[["화자","바다를 지키며 난리 속에 공을 세우는 장수"],["시기하는 이들","화자의 업적을 깎아내리려는 많은 사람들"]],"steps":[{"h":"기(1~2행)","ev":"한바다에 가을바람이 부는 밤, 화자는 홀로 높은 누각에 앉아 하염없이 생각에 잠긴다. 외로움과 고뇌가 깔린 배경이다.","feel":"고뇌","who":["화자"],"q":"홀로 높은 누각에 앉아 하염없이 생각에 잠기네"},{"h":"승(3~4행)","ev":"이 나라가 어느 날에야 다시 태평해질까 묻는다. 지금은 큰 난리를 겪는 때라, 평화로운 시절이 오기를 간절히 바란다.","feel":"우국","who":["화자"],"q":"어느 날에야 이 나라가 다시 태평해질까"},{"h":"전(5~6행)","ev":"많은 사람이 업적을 깎아내리려 하지만 이름은 오히려 온 세상이 알게 된다. 명성을 알리는 일에는 관심을 두지 않는다.","feel":"담담","who":["화자","시기하는 이들"],"q":"이름은 오히려 온 세상이 알게 되네"},{"h":"결(7~8행)","ev":"변방의 근심만 평정할 수 있다면 도연명처럼 귀거래사를 읊겠다고 한다. 소망은 명성이 아니라 평화와 전원생활이다.","feel":"소망","who":["화자"],"q":"도연명의 귀거래사 응당 읊으리"}],"key":"나라를 먼저 걱정하는 충정과 공명 대신 전원을 꿈꾸는 선비의 마음을 담은 한시이다","pt":["‘한바다·가을바람·이 밤’은 공간·계절·시간 배경으로 작품의 분위기를 만든다","‘언제 태평해질까’ 물음은 사람들을 의심하는 심리가 아니라 나라 걱정과 바람이다","‘변방의 근심 평정’은 나라 우선의 충성, ‘귀거래사’는 전원 지향을 보여 준다"],"src":"해설 p.10~11 · 본책 p.46~47","g":"고전시가","s":"수특 고전시가 1강","th":"전란 속 우국충정"},"w014":{"t":"만전춘별사","a":"작자 미상","who":[["화자","임과의 사랑을 지키려는 마음과 외로움을 가진 이"],["임","곁에 없는, 함께 있고 싶은 사랑하는 사람"],["비오리","4연에서 화자가 말을 건네는 오리(임을 비유)"]],"steps":[{"h":"1연","ev":"얼음 위에 댓잎 자리를 보아 임과 함께 얼어 죽을지언정, 정을 나눈 오늘 밤이 더디 새기를 바란다. 사랑을 지키려는 의지가 크다.","feel":"열망","who":["화자","임"],"q":"얼음 위에 댓잎 자리 보아 임과 나와 얼어 죽을망정"},{"h":"2연","ev":"외로운 잠자리에서 잠이 오지 않아 서창을 열자 복사꽃이 피어 있다. 시름없이 봄바람에 웃는 꽃이 화자의 처지와 대비된다.","feel":"외로움","who":["화자"],"q":"도화는 시름없어 소춘풍(笑春風)하도다"},{"h":"3연","ev":"넋이라도 임과 함께 지내자고 여겼는데 우기시던(또는 어기신) 이가 누구냐고 묻는다. 임과의 관계가 어긋난 데 대한 원망이다.","feel":"원망","who":["화자","임"],"q":"넋이라도 임을 한데 지내겠다고 여겼더니"},{"h":"4연","ev":"비오리에게 여울을 두고 왜 소에 자러 오느냐고 묻고, 소마저 얼면 여울도 좋겠다고 한다. 임을 기다리는 마음이다.","feel":"기다림","who":["화자","비오리"],"q":"여울은 어디 두고 소(沼)에 자러 오느냐"}],"key":"얼음 위에서 얼어 죽더라도 임과 함께하려는 사랑을 노래한 고려가요이다","pt":["6모 연계: 얼음 위 댓잎 자리를 ‘더디 새오시라’로 잇는 극한 상황의 역설","6모 연계: 연별 정서가 의지→외로움→원망→기다림으로 바뀐다","시간(오늘 밤)과 추상적 대상(넋)을 주관적으로 다루는 발상이 임을 향한 그리움이다"],"src":"해설 p.11~13 · 본책 p.48~50","g":"고전시가","s":"수특 고전시가 2강","th":"임과의 영원한 사랑 소망과 이별의 불안"},"w015":{"t":"내 영혼 술에 섞여~","a":"김삼현","who":[["화자","임이 다른 이를 마음에 두어 원망하는 사람"],["임","화자를 잊고 다른 이를 향해 있는 사람"],["남","임의 마음이 향해 있는 다른 사람"]],"steps":[{"h":"초장","ev":"내 영혼이 술에 섞여 임의 속으로 흘러 들어간다고 상상한다. 형체 없는 영혼을 술처럼 섞을 수 있다는 참신한 발상이다.","feel":"그리움","who":["화자","임"],"q":"내 영혼 술에 섞여 임의 속에 흘러들어"},{"h":"중장","ev":"임의 마음속을 굽이굽이 샅샅이 찾아다닌다. 그만큼 임을 향한 사랑과 그리움이 깊다.","feel":"간절함","who":["화자","임"],"q":"굽이굽이 창자를 다 찾아다닐망정"},{"h":"종장","ev":"나를 잊고 남을 향한 임의 마음을 다 태우겠다고 한다. 원망과 함께 임의 사랑을 되찾겠다는 의지가 겹친다.","feel":"원망","who":["화자","임","남"],"q":"날 잊고 남 향한 마음을 다 태우려 하노라"}],"key":"영혼을 술에 섞어 임의 마음속에 들어가 다른 이를 향한 마음을 태우겠다는 시조이다","pt":["‘남 향한 마음’ — 임이 화자 아닌 다른 이에게 마음을 둔 상황이 핵심이다","영혼을 술에 섞고 마음을 태우는 것은 실제가 아닌 시적 상상(사물화)으로, 원망과 그리움을 드러낸다","‘남’은 임이 마음을 주는 사람으로, 화자의 처지와 대비되는 인물이다"],"src":"해설 p.11~13 · 본책 p.48~50","g":"고전시가","s":"수특 고전시가 2강","th":"자신을 잊고 남을 향한 임에 대한 원망과 임의 사랑을 되찾으려는 마음"},"w016":{"t":"창밖에 가마솥 때우라는 장사~","a":"작자 미상","who":[["화자","임과 이별해 슬퍼하는 사람(‘나’)"],["장사","가마솥 때우라며 다니는 장사꾼"],["임","화자가 오래 이별해야 하는 사랑하는 사람"]],"steps":[{"h":"초장","ev":"창밖을 지나는 솥 때우는 장사에게 이별 나는 구멍도 때우느냐고 묻는다. 이별을 솥의 구멍에 빗대어 해학이 생긴다.","feel":"간절함","who":["화자","장사"],"q":"창밖에 가마솥 때우라는 장사 이별 나는 구멍도 때우는가"},{"h":"중장","ev":"장사는 진시황·한무제·제갈량·서초패왕 같은 영웅도 이별 구멍은 막지 못했다며 그런 말이 우습다고 대답한다.","feel":"낙담","who":["장사"],"q":"이 구멍 때우라는 말이 아마도 우스워라"},{"h":"종장","ev":"장사의 말이 옳다면 임과 오래 이별하게 되리라고 한탄한다. 해학적으로 풀던 어조가 한탄으로 끝난다.","feel":"한탄","who":["화자","임"],"q":"진실로 장사의 말과 같을진대 긴 이별인가 하노라"}],"key":"이별을 때울 수 있는 구멍에 빗대어 장사와 문답하는 해학적인 사설시조이다","pt":["화자와 장사의 문답 형식, 영웅들을 나열해 이별을 막을 수 없음을 강조한다","‘이별 나는 구멍’은 이별을 솥의 구멍처럼 때울 수 있는 것으로 사물화한 발상이다","장사는 화자의 처지(막을 수 없는 이별)를 환기시켜 주는 인물이다"],"src":"해설 p.11~13 · 본책 p.48~50","g":"고전시가","s":"수특 고전시가 2강","th":"이별의 아픔을 해학적으로 드러냄"},"w017":{"t":"월곡답가","a":"정훈","who":[["화자","향촌사족, 월곡을 그리워하고 닮고 싶어 하는 이"],["벗(월곡)","작가가 존경한 인물, 속세에 초연한 삶"],["각시님네","분 바르고 웃고 다니며 화자를 알아주지 않는 이들"]],"steps":[{"h":"제1·2수","ev":"옛사람을 그리워하다 지금도 옛사람 같은 분이 계시니 내 벗이라 한다. 분 바른 각시들이 웃고 다닐 때 엊그제 지나간 한 분만 나를 곱다고 한다.","feel":"친밀","who":["화자","벗(월곡)","각시님네"],"q":"이제도 옛 사람 계시니 긔 내 벗인가 하노라"},{"h":"제4수","ev":"푸른 소나무를 울타리 삼고 흰 구름을 담장 삼아 초가삼간에 숨어 사는 벗을 사랑한다고 한다. 욕심 없이 사는 벗을 예찬한다.","feel":"예찬","who":["화자","벗(월곡)"],"q":"흉중에 진념이 없으니 그를 사랑하노라"},{"h":"제5수","ev":"벗이 사는 곳은 용추동 밖 구름다리 위쪽이라 멀게만 느껴진다. 밤마다 외로운 꿈으로만 혼자 다녀온다.","feel":"그리움","who":["화자","벗(월곡)"],"q":"밤마다 외로운 꿈만 혼자 다녀오노라"},{"h":"제6수","ev":"달 밝을 때는 잔을 들며 생각하고 좋은 철에는 경치를 보며 그리워한다. 벗이 잊힐 때가 적다고 하여 변함없는 애정을 드러낸다.","feel":"흠모","who":["화자","벗(월곡)"],"q":"달이 밝은 제는 잔을 들고 생각하고"},{"h":"제7수","ev":"산은 첩첩하고 구름이 잦아 벗의 집 쪽을 바라보아도 보이지 않는다. 마음만 길을 알아 두고 오락가락한다.","feel":"아쉬움","who":["화자","벗(월곡)"],"q":"마음만 길 알아두고 오락가락하노라"},{"h":"제9·10수","ev":"상산사호처럼 벗과 둘이 지초를 캐러 가 세상의 어지러운 일은 듣지도 보지도 말자고 한다. 신선이 타는 청학을 나도 타면 어떻겠느냐고 한다.","feel":"초탈","who":["화자","벗(월곡)"],"q":"세상의 어지러운 일들 듣도 보도 마사이다"}],"key":"존경하는 월곡을 그리워·흠모하며 속세를 벗어나 선계를 동경하는 연시조이다(10수 중 8수 수록)","pt":["제6수는 ‘달이 밝은 제’·‘시절이 좋은 제’에 따른 행위가 대구의 형식으로 나타난다","제2수의 ‘한 분’은 분 바른 각시님네와 달리 화자를 곱다고 하는 대조적 대상이다","제9·10수는 속세와 거리를 두고 신선처럼 되고 싶은 마음이지 비판에 맞서려는 의지가 아니다"],"src":"해설 p.13~14 · 본책 p.51~52","g":"고전시가","s":"수특 고전시가 3강","th":"‘월곡’을 향한 그리움과 흠모, 속세를 벗어나려는 마음"},"w018":{"t":"두류산 양단수를~","a":"조식","who":[["화자","두류산(지리산) 경치를 직접 보고 감탄하는 사람"],["아희","화자가 말을 건네는 아이(시적 청자)"]],"steps":[{"h":"초장","ev":"예전에 듣기만 하던 두류산 양단수를 이제야 직접 눈으로 본다. 말로만 듣던 곳을 실제로 마주한 때이다.","feel":"감탄","who":["화자"],"q":"두류산 양단수를 예 듣고 이제 보니"},{"h":"중장","ev":"복숭아꽃이 떠 있는 맑은 물에 산 그림자까지 잠겨 있다. 무릉도원을 떠올리게 하는 아름다운 경치이다.","feel":"황홀","who":["화자"],"q":"도화 뜬 맑은 물에 산영조차 잠겼어라"},{"h":"종장","ev":"아이를 불러 무릉이 어디냐고 묻고는 나는 여기가 바로 무릉인가 한다. 눈앞의 현실 공간을 이상향으로 여긴다.","feel":"만족","who":["화자","아희"],"q":"아희야 무릉이 어디오 나는 옌가 하노라"}],"key":"지리산의 빼어난 경치를 보고 그곳이 바로 무릉도원이라며 예찬한 시조이다","pt":["‘예 듣고’의 때와 ‘이제 보니’의 때 — 시각적 실제 경험으로 충족감을 느낀다","‘도화 뜬 맑은 물’과 ‘산영’을 ‘무릉도원’에 이어 현실 공간을 낙원처럼 표현한다","‘아희야’ 호명은 궁금증 해소가 아니라 화자의 만족감을 드러내려는 것이다"],"src":"해설 p.14~15 · 본책 p.53~54","g":"고전시가","s":"수특 고전시가 4강","th":"지리산 경치를 무릉도원에 견주는 자연 예찬"},"w019":{"t":"요일월 순건곤은~","a":"김천택","who":[["화자","요순 시절을 그리며 늦게 태어난 것을 슬퍼하는 이"]],"steps":[{"h":"초장","ev":"요임금·순임금 시절의 해와 달, 하늘과 땅은 옛날 그대로 있다고 말한다. 변하지 않는 자연을 먼저 내세운다.","feel":"회상","who":["화자"],"q":"요(堯) 일월 순(舜) 건곤은 옛날대로 있건마는"},{"h":"중장","ev":"그런데 세상 인사는 어찌 저리 달라졌느냐고 탄식한다. 자연은 그대로이나 사람 사는 세상이 변해 버렸다.","feel":"탄식","who":["화자"],"q":"세상 인사는 어이 저리 달랐는고"},{"h":"종장","ev":"요순 시절이 지난 뒤 늦게 태어난 것을 못내 슬퍼한다. 평민으로 살 수밖에 없는 작가의 처지를 담았다고 보기도 한다.","feel":"한탄","who":["화자"],"q":"이 몸이 늦게 난 줄을 못내 슬퍼하노라"}],"key":"변함없는 자연과 달라진 세상을 견주어 요순 시절에 늦게 난 것을 탄식하는 시조이다","pt":["한결같은 자연을 예찬하는 대조가 아니라 달라진 세상 인사에 대한 탄식이다","‘슬퍼하노라’처럼 슬픔을 직접 드러내는 시어로 부정적 정서를 강조한다","요순 시절(시간)은 무릉도원(공간)과 함께 낙원을 표상하는 말이다"],"src":"해설 p.14~15 · 본책 p.53~54","g":"고전시가","s":"수특 고전시가 4강","th":"요순 시절 같은 태평성대 예찬"},"w020":{"t":"대장부 공 이루고~","a":"작자 미상","who":[["화자","공을 이루고 물러나 임천에 사는 대장부"]],"steps":[{"h":"초장","ev":"대장부가 공을 이룬 뒤 벼슬에서 물러난 상황을 먼저 제시한다. 이후의 삶은 이 물러남에서 비롯된다.","feel":"여유","who":["화자"],"q":"대장부 공 이루고 물러난 뒤에"},{"h":"중장","ev":"임천에 초당을 짓고 책·준마·보라매·가인·술·거문고를 곁에 두고, 남풍시에 화답하며 태평한 세월 속에 누워 지낸다.","feel":"풍류","who":["화자"],"q":"남풍시 화답하여 강구연월에 누웠으니"},{"h":"종장","ev":"보고 듣기 좋은 것과 마음의 즐거움이 이것뿐이라며 지극한 만족감을 드러낸다.","feel":"만족","who":["화자"],"q":"보고 듣기 좋음과 마음의 즐거움은 이뿐인가 하노라"}],"key":"공을 이룬 뒤 물러나 임천에서 누리는 것들을 길게 열거해 충만감을 드러내는 사설시조이다","pt":["중장에 누리는 것들을 열거해 의식주에 결핍 없는 충만감을 드러낸다","‘강구연월’은 태평성대를 가리키고, 즐거움 같은 감정이 직접 제시된다","세속적 욕망을 부정하는 것이 아니라 성취 뒤에 누리는 충족된 삶이다"],"src":"해설 p.14~15 · 본책 p.53~54","g":"고전시가","s":"수특 고전시가 4강","th":"공을 이룬 뒤 물러나 자연 속에서 사는 삶"},"w021":{"t":"눈 맞아 휘어진 대를~","a":"원천석","who":[["화자","대나무의 절개를 예찬하는 사람(고려 유신인 작가와 겹침)"],["대","눈에도 꺾이지 않고 푸른 대나무"]],"steps":[{"h":"초장","ev":"눈을 맞아 휘어진 대나무를 두고 누가 굽었다고 하느냐고 되묻는다. 남의 말을 끌어와 대나무의 곧음을 변호한다.","feel":"반문","who":["화자","대"],"q":"눈 맞아 휘어진 대를 뉘라셔 굽다던고"},{"h":"중장","ev":"정말 굽을 것이었다면 눈 속에서 푸르겠느냐고 반문한다. 눈은 시련이고, 푸른빛은 변치 않는 대의 속성이다.","feel":"확신","who":["화자","대"],"q":"굽을 절이면 눈 속에 푸를쏘냐"},{"h":"종장","ev":"추운 계절에도 홀로 지키는 절개는 오직 너뿐이라고 대나무를 예찬한다. 두 왕조를 섬길 수 없다는 지조가 겹친다.","feel":"예찬","who":["화자","대"],"q":"아마도 세한고절(歲寒孤節)은 너뿐인가 하노라"}],"key":"눈에도 굽지 않는 대나무를 빌려 고려 왕조에 대한 변치 않는 절개를 노래한 시조이다","pt":["대는 절개, 눈은 시련이며 눈의 흰색과 대의 푸름은 색채 대비를 이룬다","‘뉘라서 굽다던고’는 남의 말을 인용해 그 말을 비판하는 표현이다","‘너뿐인가’는 대에 인격을 부여해 예찬하는 태도를 드러낸다"],"src":"해설 p.15~16 · 본책 p.55~57","g":"고전시가","s":"수특 고전시가 5강","th":"고려 왕조에 대한 변치 않는 절개"},"w022":{"t":"연못에 비 오는 소리~","a":"작자 미상","who":[["화자","꿈에서도 임을 만나지 못해 아쉬워하는 사람"],["임","화자가 꿈에서 보러 가던 사랑하는 사람"]],"steps":[{"h":"초장","ev":"연못에 비 떨어지는 소리가 들린다. 그 소리가 무엇이 그리 놀랍기에 잠을 깨우는지 의아해한다.","feel":"의아","who":["화자"],"q":"연(蓮)못에 비 오는 소리 그 무엇이 놀랍관데"},{"h":"중장","ev":"임을 보러 가던 꿈이 임을 만나기도 전에 빗소리에 깨어 버린다. 꿈에서도 만남이 좌절된다.","feel":"아쉬움","who":["화자","임"],"q":"임 보러 가던 꿈이 못 보고 깨돗던고"},{"h":"종장","ev":"연잎 위에 빗방울이 구슬처럼 맺혀 눈물이 떨어지는 듯하다. 빗방울을 임을 못 만난 슬픔의 눈물에 빗댄 것이다.","feel":"슬픔","who":["화자"],"q":"잎 위에 구슬만 담겨 눈물 듣듯 하더라"}],"key":"임을 꿈에서도 만나지 못한 아쉬움과 슬픔을 연잎 위 빗방울에 빗댄 시조이다","pt":["비는 꿈에서 임을 만나려던 화자를 깨워 만남에 제약을 가하는 소재이다","‘구슬’은 연잎에 맺힌 빗방울이고 눈물은 그것에 빗댄 말이다 — 눈물로 읽으면 오답","독백 형식의 애상적 정서이며 말을 주고받는 방식은 아니다"],"src":"해설 p.15~16 · 본책 p.55~57","g":"고전시가","s":"수특 고전시가 5강","th":"꿈에서도 임을 만나지 못한 그리움과 슬픔"},"w023":{"t":"임으란 회양 금성 오리나무 되고~","a":"이정보","who":[["화자","임과 떨어지지 않고 얽혀 살고 싶은 사람"],["임","오리나무에 빗댄, 곧고 든든한 사람"]],"steps":[{"h":"초장","ev":"임은 회양·금성의 오리나무, 나는 삼사월 칡넝쿨이 되겠다고 상상한다. 곧고 든든한 나무에 칡이 기대어 오르는 모습이다.","feel":"소망","who":["화자","임"],"q":"임으란 회양 금성 오리나무 되고"},{"h":"중장","ev":"칡이 납거미가 나비를 감듯 이리저리 칭칭 감아 빈틈없이 밑부터 끝까지 밤낮없이 감겨 있겠다고 한다. 임과 한 몸처럼 붙어 살고 싶다.","feel":"간절함","who":["화자","임"],"q":"납거미 나비 감듯 이리로 칭칭 저리로 칭칭"},{"h":"종장","ev":"동지섣달의 바람·비·눈·서리를 아무리 맞아도 떨어질 리 없다고 단언한다. 시련 속에서도 변치 않는 사랑을 다짐한다.","feel":"다짐","who":["화자","임"],"q":"아무리 맞은들 떨어질 줄 있으랴"}],"key":"임은 오리나무, 나는 칡넝쿨이 되어 어떤 시련에도 떨어지지 않겠다는 사랑의 사설시조이다","pt":["6모 연계: 임은 오리나무(곧고 든든함), 화자는 칡넝쿨(감아 결속함)이라는 비유","6모 연계: 칡이 납거미처럼 빈틈없이 감기려는 화자의 소망을 읽는다","화자가 칡넝쿨이 되는 발상은 있으나 칡이 납거미로 변신하지는 않는다"],"src":"해설 p.15~16 · 본책 p.55~57","g":"고전시가","s":"수특 고전시가 5강","th":"죽어서도 임과 얽혀 함께하고 싶은 사랑"},"w024":{"t":"면앙정가","a":"송순","who":[["화자","고향에 면앙정을 짓고 풍류를 누리는 사람"],["벗","술과 노래를 함께 즐기는 이들"],["임금","풍류의 삶이 가능하게 해 준 은혜의 주체"]],"steps":[{"h":"서사","ev":"무등산 한 줄기가 뻗어 제월봉이 되고, 그 일곱 굽이 가운데 너럭바위 위에 정자를 앉혔다. 구름 탄 청학이 날개를 편 듯한 모습이다.","feel":"감탄","who":["화자"],"q":"너럭바위 위에 송죽(松竹)을 헤치고"},{"h":"본사 1","ev":"아래로는 정자 앞 들의 비단 같은 물과 모래밭 기러기를 굽어보고, 위로는 병풍 같은 산봉우리와 푸른 절벽을 우러러본다.","feel":"감탄","who":["화자"],"q":"두르고 꽂은 것은 산인가 병풍인가"},{"h":"본사 2","ev":"봄엔 녹양의 꾀꼬리, 여름엔 난간의 서늘한 바람, 가을엔 금수 같은 산빛과 누런 들, 겨울엔 눈 덮인 산천을 즐긴다. 간 데마다 승경이다.","feel":"흥취","who":["화자"],"q":"된서리 걷힌 후에 산빛이 금수(錦繡)로다"},{"h":"결사 ①","ev":"바람 쐬고 달 맞고 밤 줍고 고기 낚느라 쉴 틈이 없어도 버릴 일이 하나도 없다. 술이 익으면 벗들과 노래하며 취흥에 젖어 근심을 잊는다.","feel":"흥취","who":["화자","벗"],"q":"술이 익었으니 벗이야 없을쏘냐"},{"h":"결사 ②","ev":"태평성대를 몰랐는데 지금이 바로 그때이고 이 몸이 신선이라 여긴다. 이백도 이보다 낫지 않으리라며, 이 모두가 임금의 은혜라고 맺는다.","feel":"감사","who":["화자","임금"],"q":"이 몸이 이러함도 역군은(亦君恩)이샷다"}],"key":"면앙정 둘레의 경치와 사계절을 노래하고, 풍류의 삶을 임금의 은혜로 맺는 은일 가사이다","pt":["시선 이동: 아래 들판은 ‘면’(굽어봄), 위 산봉우리는 ‘앙’(우러름), 구름·산람은 둘 다","결사의 ‘역군은이샷다’는 풍류의 삶이 임금의 은혜라는 연군을 드러낸다","‘구름 탄 청학’은 정자의 외형을 비유하고, 꾀꼬리는 화자의 정서가 이입된 대상이다"],"src":"해설 p.16~18 · 본책 p.58~62","g":"고전시가","s":"수특 고전시가 6강","th":"면앙정 자연 속 풍류와 연군지정"},"w025":{"t":"사친가","a":"작자 미상","who":[["화자","철마다 부모를 그리며 효를 일깨우는 자식"],["소년들","달구경하는 젊은이들, 효를 권유받는 청자"],["부모님","때마다 명절·절기를 누리지 못하는 부모"]],"steps":[{"h":"정월령","ev":"정월 대보름 달구경하는 소년들에게 부모 봉양을 생각하라고 권한다. 부모 은덕이 태산 같아 불로초도 구할 수 없으니 슬프다고 한다.","feel":"권계","who":["화자","소년들","부모님"],"q":"슬프다 우리 부모 대보름인 줄 모르시나"},{"h":"이월령","ev":"한식날 개자추를 떠올리며 후인들이 슬퍼해 한식을 지은 내력을 말한다. 효자 이영백, 충신 적인걸의 고사를 들며 청명을 모르시는 부모를 슬퍼한다.","feel":"안타까움","who":["화자","부모님"],"q":"후인들이 슬퍼하여 한식을 지었도다"},{"h":"삼월령","ev":"삼짇날 제비와 나비가 찾아오고 산꽃은 붉은 비단, 버들은 푸른 실 같다. 봄을 즐기는 사람들 속에서 답청절을 모르시는 부모를 슬퍼한다.","feel":"슬픔","who":["화자","부모님"],"q":"산화(山花)는 붉은 비단이오 세류(細柳)는 푸른 실이로다"},{"h":"사월령","ev":"초파일에 태평성대를 칭송하는 경성가가 울리고 집집마다 등을 달고 만세를 부른다. 그런 관등절을 모르시는 부모를 슬퍼한다.","feel":"슬픔","who":["화자","부모님"],"q":"만백성 화합하는 경성가를 오늘날에 보리로다"},{"h":"오월령","ev":"단오에 그네 타는 미인들과 보리타작하는 농부들을 보며, 일신이 한가하고 넉넉해도 맺힌 설움은 부모 생각뿐이라고 한다.","feel":"그리움","who":["화자","부모님"],"q":"일촌간장 맺힌 설움 부모 생각뿐이로다"}],"key":"달마다 명절과 풍속을 따라가며, 철마다 부모를 생각하고 섬기라고 일러 주는 월령체 가사이다","pt":["월령체: ‘정월·이월·삼월’ 같은 시간 표지와 절기·명절로 내용을 나눈다","‘슬프(도)다 우리 부모~모르시나’ 반복, ‘그달을 허송하니’로 시간의 경과를 나타낸다","‘소년’에게는 효를 권하지만 ‘후인’·‘아이’를 가르치려는 청자로 삼은 것은 아니다"],"src":"해설 p.18~19 · 본책 p.63~66","g":"고전시가","s":"수특 고전시가 7강","th":"사시사철 부모를 그리워하고 섬기려는 마음"},"w026":{"t":"속사미인곡","a":"이진유","who":[["화자","추자도에 유배된 신하(여성 화자의 목소리)"],["임","화자가 의지하고 그리워하는 임금"],["뭇 여자","화자를 질투해 모함하는 소인배"]],"steps":[{"h":"서사","ev":"삼 년 동안 임을 떠나 섬에 유배되었으나 임에게 죄를 지은 일도, 임이 박정했던 일도 없다고 한다. 질투하는 뭇 여자의 모함이라 여긴다.","feel":"억울함","who":["화자","임","뭇 여자"],"q":"내 언제 무심하여 임에게 득죄했나"},{"h":"본사","ev":"섬에서는 겨울 양식과 반찬이 모자라 설 상에도 갯물에 절인 배추가 오르고, 여름엔 파리·모기·뱀에 시달린다. 밤이면 신세를 한탄한다.","feel":"고통","who":["화자"],"q":"어와 이 몰골은 태어나 처음 보네"},{"h":"결사 ①","ev":"임이 아니면 누구를 의지하겠느냐 하고, 옛 잘못을 헤아리며 그 근본은 임을 위한 정성이었다고 해명한다. 임이 굽어보리라 기대한다.","feel":"의지","who":["화자","임"],"q":"근본을 생각하면 임 위한 정성일세"},{"h":"결사 ②","ev":"임이 더 이상 찾지 않는 가을부채 같은 신세를 한탄하고, 마름·연으로 옷을 지어 둔들 누구를 위해 단장하겠느냐고 한다. 임을 향한 정성과 결핍의 슬픔이 드러난다.","feel":"서글픔","who":["화자","임"],"q":"광주리의 가을부채 어느 날 다시 날꼬"},{"h":"결사 ③","ev":"밤마다 꿈에서 옥루 높은 곳에 임을 모시고, 깨면 임의 목소리와 향이 완연하다. 이 꿈이 현실이 되기를 바라며 임금이 고쳐 주시기를 날마다 바란다.","feel":"소망","who":["화자","임"],"q":"두어라 임금께서 고치시기를 날마다 바라노라"}],"key":"유배지의 참담한 생활과 임금을 향한 그리움·정성을 여성 화자의 목소리로 노래한 유배 가사이다","pt":["9모 연계: 유배지 생활상(양식·음식·벌레)을 의문 형식으로 부각하며 임에 대한 마음을 읽는다","가을부채는 임과 헤어진 자신, 마름·연으로 지은 옷은 임을 향한 정성 — 원망·체념이 아니다","고난을 자세히 서술하고 임금을 문제 해결의 주체로 믿는 점이 후기 유배가사의 특징이다"],"src":"해설 p.20~21 · 본책 p.67~70","g":"고전시가","s":"수특 고전시가 8강","th":"유배 생활의 고통과 연군"},"w027":{"t":"몽금포 타령","a":"작자 미상","who":[["화자","바다로 나간 임을 기다리는 어촌 사람"],["임","배를 타고 고기를 잡으러 나가는 어부"],["성황님","순조로운 뱃길을 비는 대상"]],"steps":[{"h":"1~3연","ev":"장산곶마루에 북소리가 나자 오늘은 임을 만나 보겠다고 기대한다. 갈 길은 먼데 배가 더디니 성황님께 늦바람을 빌고, 몽금포·개암포에 들렀다 가라고 한다.","feel":"기대","who":["화자","임","성황님"],"q":"장산곶마루에 북소리 나더니"},{"h":"8~9연","ev":"바다의 흰 돛은 쌍쌍이 조는데 화자의 외로운 사랑에는 눈물만 겹다. 몽금포 백사장엔 해당화가 붉고 푸른 솔가지엔 두루미가 앉아 있다.","feel":"외로움","who":["화자"],"q":"외로운 사랑엔 눈물만 겨워라"},{"h":"10~12연","ev":"장산곶마루에 새 소식이 들리더니 정든 임이 오셨다. 말없이 떠났던 임이 만선으로 돌아오고, 임 실으러 갈 땐 반 돛, 싣고 올 땐 온 돛을 단다.","feel":"반가움","who":["화자","임"],"q":"봉죽을 받고서 돌아를 오셨네"},{"h":"13~14연","ev":"배가 거친 물결에 출렁이며 북소리를 울리며 떠들썩하게 돌아온다. 가는 임에게 속태우지 말라며, 갔다 올 때가 더 반갑다고 한다.","feel":"반가움","who":["화자","임"],"q":"갔다가 올 때가 더 반갑답니다"}],"key":"배를 보내는 이별과 돌아오는 임을 맞는 반가움을 담은 황해도 어촌의 민요이다","pt":["후렴 ‘에헤요 에헤요 에헤야’가 ‘임 만나 보겠네’·‘눈물만 겨워라’와 함께 되풀이된다","포구는 이별과 재회가 오가는 열린 공간이며, ‘돛 달지 말고요’는 원망이 아니라 들르라는 말이다","‘봉죽을 받고서’는 만선으로 돌아온 생업의 어부(진어옹)의 모습이다"],"src":"해설 p.21~22 · 본책 p.71~73","g":"고전시가","s":"수특 고전시가 9강","th":"어촌의 정경과 삶"},"w028":{"t":"어부별곡","a":"이중경","who":[["화자","어부로 자처하며 강호에 사는 사대부"],["세상 사람들","옳고 그름을 따지는 세속의 사람들"]],"steps":[{"h":"제2수","ev":"처음엔 시서를 일삼았고 중간엔 망령되이 명리를 바랐다고 지난날을 돌아본다. 이제는 세속 밖 풍월강산이 내 분수인가 한다.","feel":"성찰","who":["화자"],"q":"중간에 망령되어 명리를 바라도다"},{"h":"제3수","ev":"옳거나 그르거나 나도 내 일을 모른다며, 세상은 시비를 따지지 말라고 한다. 어부가 무엇이 그르냐고 되물어 어부의 삶을 긍정한다.","feel":"초연","who":["화자","세상 사람들"],"q":"세상이 시비를 마라 어부 무삼 그르리"},{"h":"제4수","ev":"세상을 다스릴 경륜을 내가 알겠느냐며 구제할 사람이 없겠느냐고 되묻는다. 태평시세는 멀어서 필부의 위국충심을 내보일 데가 없다고 한다.","feel":"안타까움","who":["화자"],"q":"필부의 위국충심을 내어 뵐 데 없어라"},{"h":"제6수","ev":"푸른 산은 높고 흐르는 물은 길어 산고수장이 좋지 않으냐고 한다. 산수 사이의 한가한 사람으로 허물없이 산다.","feel":"만족","who":["화자"],"q":"산수간 일한인(一閑人) 되어 허물없이 사노라"}],"key":"명리를 좇던 지난날을 돌아보고 어부로 자처해 자연에서 한가롭게 살려는 연시조이다","pt":["‘어부’로 자처한 사대부(가어옹) — 생계로 고기 잡는 「몽금포 타령」의 진어옹과 비교한다","제2수 ‘명리를 바라도다’는 지난날의 성찰이지, 속세에 미련을 못 버린 고뇌가 아니다","제4수 ‘위국충심을 내어 뵐 데 없어’는 뜻을 펴지 못하는 사회 현실에 대한 인식이다"],"src":"해설 p.22 · 본책 p.72~73","g":"고전시가","s":"수특 고전시가 9강","th":"자연 속 어부의 삶 지향"},"w029":{"t":"유산가","a":"작자 미상","who":[["화자","벗들에게 봄 산천 구경을 권하는 사람"],["벗님네","함께 산천 구경을 가자고 청하는 상대"]],"steps":[{"h":"서사","ev":"꽃이 만발하고 만물이 자라는 좋은 때에 벗들에게 산천 경치를 구경하러 가자고 청한다. 지팡이와 짚신, 표주박만 들고 천리강산으로 들어간다.","feel":"들뜸","who":["화자","벗님네"],"q":"때 좋다 벗님네야 산천경개 구경 가세"},{"h":"본사 1","ev":"산마다 붉고 푸른 꽃이 봄빛을 자랑하고, 버들 위 꾀꼬리와 꽃 사이 나비가 어울린다. 복사꽃 만발한 이곳이 무릉도원이 아니냐고 한다.","feel":"감탄","who":["화자"],"q":"무릉도원이 예 아니냐"},{"h":"본사 2","ev":"첩첩한 산과 층층 기암, 광풍에 춤추는 장송 사이로 폭포가 콸콸 흐른다. 여러 골 물이 합쳐 주르륵·솰솰 소리를 내며 은옥처럼 흩어진다.","feel":"흥취","who":["화자"],"q":"이 골물이 주르륵 저 골물이 솰솰"},{"h":"결사","ev":"그 물결을 소부와 허유가 문답하던 기산 영수에 견주며 감흥을 드러낸다. 봄 경치를 고사 속 은자의 공간처럼 여긴다.","feel":"감흥","who":["화자"],"q":"문답하던 기산(箕山) 영수(潁水)가 예 아니냐"}],"key":"봄 산천의 꽃과 산, 폭포를 음성 상징어·열거·고사로 그려 낸 12잡가의 하나이다","pt":["‘콸콸·주르륵·솰솰’ 등 음성 상징어로 폭포수 물살의 역동성을 형상화한다","공간 이동에 따라 시상이 전개되고, ‘예 아니냐’ 설의로 만족을 드러내며 정서 변화는 없다","‘소부 허유’ 고사는 경치가 은거지 같다는 뜻이지 그 삶을 따른다는 뜻이 아니다"],"src":"해설 p.23~24 · 본책 p.74~77","g":"고전시가","s":"수특 고전시가 10강","th":"봄 경치의 완상"},"w030":{"t":"백석정별곡","a":"신교","who":[["화자","백석정에 은거해 풍류를 즐기는 사람"],["홍진의 벗님네","속세에 사는 사람들(화자의 삶을 웃을 이들)"]],"steps":[{"h":"경치 감상","ev":"붉은 난간에서 달은 은촛불, 구름은 휘장 같다고 보며, 낚시하는 늙은이의 노래와 소 먹이는 아이의 피리 소리를 듣는다. 물에 비친 다리는 무지개 같다.","feel":"평화","who":["화자"],"q":"물결에 비친 다리 반공(半空)에 무지개로다"},{"h":"낚시와 술","ev":"석양 무렵 돌길로 돌아가며 꽃과 버들을 보고, 낚은 고기를 회 쳐 연잎에 빚은 술을 마신다. 공명을 잊으니 부귀도 부럽지 않다고 한다.","feel":"여유","who":["화자"],"q":"공명을 다 잊으니 부귀인들 부러우랴"},{"h":"거문고","ev":"속세 벗들에게 이 삶을 웃지 말라 하고, 거문고로 유수고산을 타며 노래를 주고받는다. 신선이 노니는 듯하니 여기가 무릉도원이라 한다.","feel":"흥취","who":["화자","홍진의 벗님네"],"q":"삼신산 어디인가 무릉도원 여기로다"},{"h":"세사 잊음","ev":"정자 속 매학을 벗 삼아 자연을 사랑하는 병이 들어 백 년을 지내니, 있으나 없으나 세상일은 나 몰라라 한다.","feel":"만족","who":["화자"],"q":"있으나 없으나 세사(世事)도 나 몰라라"}],"key":"정자 둘레의 경치와 낚시·술·거문고의 풍류를 즐기며 세상일을 잊는 은일 가사의 본사 부분이다","pt":["은유: 물에 비친 다리(원관념)가 무지개(보조관념)이고, 단풍은 금병풍에 빗댄다","정자 둘레 자연 속 은거에 만족하는 정서이며 정서 변화는 나타나지 않는다","「유산가」는 경치를 둘러보며 동경하고, 이 작품은 자연에 거주하는 삶의 만족을 드러낸다"],"src":"해설 p.23~24 · 본책 p.75~77","g":"고전시가","s":"수특 고전시가 10강","th":"정자 주변 자연 속 풍류"},"w031":{"t":"성패관천운","a":"김상헌","who":[["화자","병자호란 뒤 청에 잡혀가 원칙(경)을 지키려는 사람"],["이치에 밝은 선비","시가 건네는 상대, 심양 옥에 갇힌 최명길"]],"steps":[{"h":"기(1~2행)","ev":"성공과 실패는 하늘의 운에 달렸으니 반드시 의로움으로 돌아가야 한다고 말한다. 결과보다 의가 중요하다는 주장이다.","feel":"단호","who":["화자"],"q":"성공과 실패는 천운에 달려 있으니"},{"h":"승(3~4행)","ev":"아침과 저녁은 바꿀 수 있어도 윗옷과 아래옷을 거꾸로 입을 수는 없다고 비유한다. 어떤 경우에도 바뀌지 않는 원칙과 기준이 있다는 뜻이다.","feel":"단호","who":["화자"],"q":"윗옷과 아래옷을 거꾸로야 입을쏘냐"},{"h":"전(5~6행)","ev":"권(상황에 맞게 변통하는 방편)은 현명한 사람도 그르칠 수 있지만, 경(변할 수 없는 원칙)은 여러 사람이 어길 수 없다고 한다.","feel":"권계","who":["화자"],"q":"경만은 마땅히 여러 사람이 어길 수 없다"},{"h":"결(7~8행)","ev":"이치에 밝은 선비에게 말하노니 아무리 급한 때라도 저울질(권도)을 삼가라고 조언한다. 위급해도 경을 따르라는 당부이다.","feel":"조언","who":["화자","이치에 밝은 선비"],"q":"급한 때라도 저울질을 삼가라"}],"key":"결과보다 의를 앞세워, 급해도 권도보다 변치 않는 원칙(경)을 따르라고 이르는 한시이다","pt":["김상헌(경·원칙)과 최명길(권·현실 대응)의 시가 서로 주고받는 구조이다","‘이치에 밝은 선비’ 호칭과 ‘급한 때라도’는 상대를 인정하며 조언하는 방식이다","‘윗옷과 아래옷을 거꾸로’는 서로 바꿔 쓸 수 없는 것들을 뜻한다"],"src":"해설 p.24~25 · 본책 p.78~80","g":"고전시가","s":"수특 고전시가 11강","th":"병자호란 위기 속 원칙(대의)의 입장"},"w032":{"t":"정처관군동","a":"최명길","who":[["화자","화친을 택한 최명길, 서로 다른 선택도 같다고 이르는 이"],["김상헌","원칙(경)을 지키려는 상대(시의 청자)"]],"steps":[{"h":"기(1~2행)","ev":"고요한 곳에서 여러 움직임을 두루 볼 수 있어야 진실로 원만한 귀결을 지을 수 있다고 말한다. 전체 상황을 보는 안목이 필요하다는 뜻이다.","feel":"차분","who":["화자"],"q":"고요한 곳에서 뭇 움직임을 볼 수 있어야"},{"h":"승(3~4행)","ev":"끓는 물도 얼음장도 다 같은 물이고, 털옷도 삼베옷도 옷 아닌 것이 없다고 비유한다. 달라 보여도 본질은 같다는 주장이다.","feel":"설득","who":["화자"],"q":"끓는 물도 얼음장도 다 같은 물이요"},{"h":"전(5~6행)","ev":"일이 때에 따라 달라지더라도 속마음이 어찌 정도와 어긋나겠느냐고 되묻는다. 선택은 달라도 마음은 정도에서 벗어나지 않는다.","feel":"확신","who":["화자","김상헌"],"q":"속맘이야 어찌 정도와 어긋나겠는가"},{"h":"결(7~8행)","ev":"그대가 이 이치를 깨닫는다면 말함도 침묵함도 각각 하늘의 이치라고 말한다. 서로의 주장이 모두 타당할 수 있음을 열어 둔다.","feel":"포용","who":["화자","김상헌"],"q":"말함도 침묵함도 각기 천기로세"}],"key":"겉모습이 달라도 본질과 속마음은 정도에 어긋나지 않는다며, 말함도 침묵함도 천기라고 이르는 한시이다","pt":["(가)는 서로 바꿀 수 없는 것을, (나)는 달라 보여도 본질이 같은 것을 말한다","‘그대 이 이치를 깨닫는다면’은 상대의 생각도 틀리지 않음을 인정하는 말이다","‘고요한 곳에서 뭇 움직임’은 위기일수록 전체 시국을 보는 넓은 시야를 뜻한다"],"src":"해설 p.24~25 · 본책 p.78~80","g":"고전시가","s":"수특 고전시가 11강","th":"병자호란 위기 속 현실 대응의 입장"},"w033":{"t":"빼앗긴 들에도 봄은 오는가","a":"이상화","who":[["화자","봄 들판을 걷다 국권 상실을 깨닫는 사람"],["들","빼앗긴 국토, 화자가 말을 건네는 자연"]],"steps":[{"h":"1연","ev":"화자는 지금은 남의 땅이 된 ‘빼앗긴 들’에도 과연 봄이 오는지 스스로에게 묻는 데서 시작한다.","feel":"의문","who":["화자","들"],"q":"빼앗긴 들에도 봄은 오는가?"},{"h":"2~3연","ev":"햇살 속에서 하늘과 들이 맞붙은 논길을 꿈속처럼 걸으며, 아무 말 없는 하늘과 들에게 답답해하며 말을 해 달라고 한다.","feel":"답답함","who":["화자","들"]},{"h":"4~8연","ev":"바람·종다리·보리밭·도랑 같은 봄 들판의 존재와 어울리며, 호미를 쥐고 흙을 밟고 땀 흘리고 싶다고 애정을 드러낸다.","feel":"애정","who":["화자","들"]},{"h":"9~10연","ev":"강가의 아이처럼 철없이 내닫는 자신의 혼을 우습게 여기며, 푸른 웃음과 푸른 설움 속을 다리를 절며 걷는다.","feel":"자각","who":["화자"]},{"h":"11연","ev":"봄을 한껏 누리던 화자는 마지막에 들을 빼앗기면 봄조차 빼앗기겠다고 암담한 현실을 다시 인식한다.","feel":"비애","who":["화자"],"q":"들을 빼앗겨 봄조차 빼앗기겠네"}],"key":"봄 들판의 아름다움에 이끌리다가, 들을 빼앗기면 봄도 빼앗긴다는 현실로 돌아오는 시.","pt":["마지막 연은 1연 물음에 대한 걱정스러운 대답 — ‘봄조차 빼앗기겠네’의 위기의식","‘푸른 웃음 푸른 설움’과 ‘다리를 절며’: 국토의 아름다움과 암담한 현실 인식의 공존","‘보리밭’ 의인화(머리를 감았다), ‘도랑’ 소리의 청각·모성적 이미지, 강가에 나온 ‘아이’는 철없이 들뜬 화자"],"src":"해설 p.25~27 · 본책 p.81~83","g":"현대시","s":"수특 현대시 1강","th":"국권 상실의 비애와 회복 의지"},"w034":{"t":"초토의 시 1","a":"구상","who":[["화자","폐허가 된 거리를 걷다 희망을 느끼는 사람"],["아이들","판잣집 유리창의 아이들과 언덕을 달리는 소녀"],["개나리","잿더미 울타리에 망울진 꽃"]],"steps":[{"h":"1연","ev":"화자는 판잣집 유리창에 해바라기처럼 걸려 있는 아이들의 얼굴을 본다.","feel":"연민","who":["화자","아이들"],"q":"불타는 해바라기마냥"},{"h":"2연","ev":"눈부신 햇발에 돌아서는 화자도 전쟁의 비극을 떠올리며 괴로워하고, 울상이 된 그림자가 뒤를 따른다.","feel":"괴로움","who":["화자"]},{"h":"3연","ev":"접어든 골목에서 걸음을 멈춘 화자는 잿더미가 소복한 울타리에 개나리가 망울진 것을 발견한다.","feel":"놀라움","who":["화자","개나리"]},{"h":"4연","ev":"언덕을 내려 달리는 소녀의 앞니 빠진 미소에서 죄 하나 없는 순수함을 본다.","feel":"감동","who":["화자","아이들"],"q":"죄 하나도 없다"},{"h":"5연","ev":"화자는 술 취한 듯 흥그러워지고, 울상이던 그림자는 웃으며 앞장선다. 조국의 미래에 대한 희망을 느낀다.","feel":"희망","who":["화자"]}],"key":"폐허 속 아이들 모습에 괴로워하다가, 개나리와 소녀의 미소에서 희망을 발견한다.","pt":["‘불타는 해바라기마냥’ 직유는 판잣집의 누추함과 대비되는 아이들의 생동감","‘나도 돌아선다’는 슬픔·미안함 때문이지 현실을 달관한 태도가 아니다","그림자의 변화(울상으로 뒤따름 → 웃으며 앞장섬)와 ‘개나리’는 극복 의지·생명력"],"src":"해설 p.25~27 · 본책 p.81~83","g":"현대시","s":"수특 현대시 1강","th":"전쟁 폐허 속 아이들에게서 본 희망"},"w035":{"t":"오월 소식","a":"정지용","who":[["화자","먼 곳의 그리운 이에게서 소식을 받은 사람"],["너","섬에 교원으로 가 편지를 보낸 그리운 사람"]],"steps":[{"h":"1연","ev":"화자는 오동나무 꽃이 불 밝힌 이곳의 첫여름을 떠올리며, 그리운 이가 남기고 간 기억만이 소곤거리는 것을 느낀다.","feel":"그리움","who":["화자","너"]},{"h":"2연","ev":"모처럼 날아온 소식에 반가운 마음이 울렁거리고, 가여운 글자마다 먼 황해가 남실거리는 듯하다.","feel":"반가움","who":["화자","너"]},{"h":"3~4연","ev":"갈매기 같은 종선을 치달리는 자신을 상상하고, 오월 넥타이가 순풍이 되어 외딴 섬을 찾아가고 싶어 한다.","feel":"설렘","who":["화자"],"q":"외따른 섬 로맨틱을 찾아갈까나"},{"h":"5연","ev":"일본말과 아라비아 글씨를 가르치러 간 선생님이 풍랑에 시달릴까 걱정하며, 멀리서 우는 듯한 오르간 소리를 느낀다.","feel":"애틋함","who":["화자","너"]}],"key":"먼 섬의 그리운 이가 보낸 편지를 읽고, 상상 속 항해로 찾아가고 싶어 하는 마음을 노래한다.","pt":["‘그립지 아니한가?’ 같은 의문형 종결이 그리움의 정서를 강조한다","‘오르간 소리’는 그리운 이의 소식을 듣고 싶은 화자의 소망이 담긴 소리","상상 속 이미지와 이국적 시어(‘로맨틱’), 감각적 이미지로 드러낸 정지용의 모더니즘 경향"],"src":"해설 p.27~28 · 본책 p.84~86","g":"현대시","s":"수특 현대시 2강","th":"멀리 있는 고향·그리운 이에 대한 그리움"},"w036":{"t":"와사등","a":"김광균","who":[["화자","도시의 황혼 속에서 갈 곳을 잃은 현대인"],["와사등","빈 하늘에 걸린 가스등, 슬픈 신호"]],"steps":[{"h":"1연","ev":"텅 빈 하늘에 걸린 차단한 등불을 보며, 홀로 어디로 가라는 슬픈 신호냐고 묻는다.","feel":"막막함","who":["화자","와사등"],"q":"내 호올로 어델 가라는 슬픈 신호냐"},{"h":"2연","ev":"긴 여름 해가 지고, 늘어선 고층 건물은 창백한 묘석처럼, 찬란한 야경은 헝클어진 잡초처럼 보인다.","feel":"삭막함","who":["화자"]},{"h":"3연","ev":"말문이 막힌 채 피부에 스미는 어둠과 낯선 거리의 아우성 소리를 느끼며 까닭 없이 눈물겨워한다.","feel":"비애","who":["화자"]},{"h":"4연","ev":"공허한 군중의 행렬에 섞여, 어디서 그리 무거운 비애를 지니고 왔기에 그림자가 이토록 어두운지 스스로 묻는다.","feel":"고독","who":["화자"]},{"h":"5연","ev":"어디로 어떻게 가라는 슬픈 신호기냐고 다시 묻고, 처음처럼 빈 하늘에 등불이 걸려 있음을 본다.","feel":"방황","who":["화자","와사등"]}],"key":"도시의 황혼 속 가스등을 바라보며 삶의 방향을 잃은 현대인의 고독과 비애를 노래한다.","pt":["1연과 5연이 ‘등불이 하나 비인 하늘에 걸려 있다’를 거의 되풀이해 안정감을 주는 수미상관","‘아우성 소리’는 낯선 도시 문명에서 고독감·소외감을 일으키는 소리","‘늘어선 고층’·‘신호기’ 같은 도시 문명 소재와 ‘피부의 바깥에 스미는 어둠’ 같은 공감각"],"src":"해설 p.27~28 · 본책 p.84~86","g":"현대시","s":"수특 현대시 2강","th":"도시 문명 속 현대인의 고독과 방황"},"w037":{"t":"연륜","a":"김기림","who":[["화자","서른 남짓의 지난 삶을 초라하게 돌아보는 사람"],["육지","초라한 경력이 쌓인 과거의 삶"],["섬","산호 핀 바다에 있는 이상적인 새 삶"]],"steps":[{"h":"1연","ev":"화자는 무너지는 꽃잎처럼 발아래 깔리는 ‘서른 남은 해’를 돌아보며 지나온 삶을 초라하게 느낀다.","feel":"초라함","who":["화자"],"q":"무너지는 꽃이파리처럼"},{"h":"2연","ev":"구름같이 피려던 뜻은 펴지 못한 채 날로 굳고, 연륜만 한 금 두 금 곱다랗게 감겨 쌓인다고 느낀다.","feel":"회한","who":["화자"]},{"h":"3연","ev":"갈매기처럼 산호 핀 바다에 내려앉은 섬으로 가자고 스스로에게 권한다.","feel":"소망","who":["화자","섬"]},{"h":"4연","ev":"그 섬의 비췻빛 하늘 아래 피는 꽃은 맑을 것이며, 무너질 때도 눈빛 파도에 적시겠다고 그려 본다.","feel":"동경","who":["화자","섬"]},{"h":"5연","ev":"초라한 경력은 육지에 막아 두고 연륜마저 끊어 버려, 불꽃처럼 열렬히 살겠다고 다짐한다.","feel":"의지","who":["화자","육지","섬"],"q":"불꽃처럼 열렬히 살리라"}],"key":"덧없이 쌓인 연륜을 돌아보고, 육지(과거)와 단절해 섬(새 삶)으로 가 열렬히 살겠다는 다짐.","pt":["‘연륜’=뜻을 이루지 못한 채 쌓인 세월, ‘육지’=초라한 과거, ‘섬’=열정적인 새 삶","‘가자’는 타인에게 확장하는 말이 아니라 스스로를 독려하는 청유(자기 다짐)","꽃잎이 ‘발아래 깔리는’ 하강 이미지는 초라함, ‘끊어버리고’는 회한이 아닌 과거와의 단절 의지"],"src":"해설 p.28~29 · 본책 p.87~89","g":"현대시","s":"수특 현대시 3강","th":"지나온 삶의 성찰과 새로운 삶의 의지"},"w038":{"t":"정릉 살면서","a":"박재삼","who":[["화자","건강을 회복해 정릉에 살며 지난 삶을 돌아보는 사람"],["자연","바람·햇빛·실개천, 충고와 위로를 건네는 존재"],["친구","마지막에 말을 건네는 청자"]],"steps":[{"h":"1연","ev":"솔잎 사이를 빠져나온 빗질 잘된 바람이 뇌혈관에 닿아, 허술했던 목숨의 운영을 잘해 보라고 일러 준다.","feel":"깨우침","who":["화자","자연"]},{"h":"2연","ev":"금싸라기 햇빛이 잘못 살아온 서른여섯 해를 덮어 쓰다듬어 주는 것을 느낀다.","feel":"위안","who":["화자","자연"]},{"h":"3연","ev":"세월의 동생 같은 실개천이 시름으로 고인 간장 속 웅덩이를 말갛게 씻어 주며 흐른다고 느낀다.","feel":"후련함","who":["화자","자연"]},{"h":"4연","ev":"친구에게 말하듯, 사람들이 돌아보지 않는 눈물나게 넘치는 자연을 소중한 자산으로 혼자 아껴 곱게 가지겠다고 다짐한다.","feel":"다짐","who":["화자","친구","자연"]}],"key":"병을 앓고 난 화자가 바람·햇빛·실개천에서 충고와 위로를 얻고, 자연을 아끼며 살겠다고 다짐한다.","pt":["바람·햇빛·실개천을 의인화해 자연에 대한 화자의 친근감을 드러낸다","‘웅덩이’는 쌓인 시름이고, 실개천이 이를 씻어 주는 정화·치유의 이미지","‘일러 주고 있고’는 자연의 말로 받아들인 주관적 인식, ‘눈물나게 넘치는 자산’은 자연을 귀히 여기는 과장"],"src":"해설 p.28~29 · 본책 p.87~89","g":"현대시","s":"수특 현대시 3강","th":"지나온 삶의 성찰과 새로운 삶의 의지"},"w039":{"t":"꽃","a":"이육사","who":[["화자","극한 현실에서도 꽃이 피리라 믿는 사람"],["꽃","비 한 방울 없는 때에도 빨갛게 피는 희망"],["회상의 무리","화자가 불러 보는, 나비처럼 취한 무리"]],"steps":[{"h":"1연","ev":"하늘도 끝난 듯 비 한 방울 내리지 않는 때에도 꽃은 오히려 빨갛게 핀다고 확신하며, 내 목숨을 꾸미는 쉼 없는 날들을 부른다.","feel":"확신","who":["화자","꽃"],"q":"꽃은 빨갛게 피지 않는가"},{"h":"2연","ev":"북쪽 툰드라의 찬 새벽, 눈 속 깊이 움츠린 꽃 맹아리가 제비 떼 날아오길 기다리는 모습을 ‘저바리지 못할 약속’이라 부른다.","feel":"기다림","who":["화자","꽃"]},{"h":"3연","ev":"한 바다 복판에서 타오르는 꽃 성을 그리며, 나비처럼 취한 회상의 무리를 오늘 여기서 불러 본다.","feel":"기대","who":["화자","회상의 무리"]}],"key":"비 한 방울 없는 극한 속에서도 꽃은 핀다는 믿음으로, 광복의 미래를 기다리며 부르는 시.","pt":["‘비 한 방울 나리잖는 그때’=일제강점의 극한, ‘꽃’=희망·조국 광복, ‘제비떼’=봄","‘~날이여’·‘~약속이여’ 영탄과 ‘피지 않는가’ 설의가 믿음과 의지를 부각한다","‘빨갛게’·‘까맣게’ 색채어로 꽃의 생명력과 희망적 상황을 상징한다"],"src":"해설 p.29~31 · 본책 p.90~92","g":"현대시","s":"수특 현대시 4강","th":"극한 상황에서도 꺾이지 않는 미래·광복에 대한 믿음"},"w040":{"t":"누룩","a":"이성부","who":[["화자","누룩에서 민중의 힘을 읽어 내는 사람"],["누룩","스스로 썩어 술이 되는, 의인화된 민중"],["청자","‘알겠느냐’로 말을 건네는 대상"]],"steps":[{"h":"1연","ev":"무력함에 부대끼던 누룩 한 덩이가 알맞은 바람을 만나 살며시 더운 가슴이 되어 뜨는 까닭을 아느냐고 묻는다.","feel":"일깨움","who":["화자","누룩","청자"]},{"h":"2연","ev":"밤새 우는 울음과 무르팍이 으깨지는 시련 속에서도, 혼자 찾는 길이 여럿이 찾는 길임을 칼별은 안다고 말한다.","feel":"연민","who":["화자","누룩"]},{"h":"3연","ev":"속 깊이 쌓이는 기다림과 삭고 삭아 부서지는 인내의 모습을 보았느냐고 묻는다.","feel":"경외","who":["화자","누룩","청자"]},{"h":"4연","ev":"제 몸이 썩어 문드러져 좋은 물을 만나면 함께 끓어올라 춤과 기쁨, 해 솟는 얼굴이 되는 죽음을 아느냐고 묻는다.","feel":"예찬","who":["화자","누룩"]},{"h":"5연","ev":"마침내 감춰 두었던 누룩이 뜨며 냄새가 퍼진다고 확신에 차 말한다.","feel":"희망","who":["화자","누룩"],"q":"아 지금 감춰 둔 누룩 뜨나니"}],"key":"스스로를 희생해 술이 되는 누룩처럼, 연대한 민중의 힘이 새 시대를 연다는 희망의 시.","pt":["대명사 ‘지’로 누룩을 인격화하고 ‘알겠느냐’ 의문형을 반복해 속성을 강조한다","‘알맞은 바람’·‘살며시 더운’은 누룩이 뜨는 조건 — 민중이 힘을 얻으려면 연대가 필요","‘지가 죽어 썩어 문드러져’는 무력감이 아니라 ‘춤’·‘기쁨’으로 이어지는 과정(누룩은 깨달음을 주는 대상)"],"src":"해설 p.30~31 · 본책 p.90~92","g":"현대시","s":"수특 현대시 4강","th":"응축된 민중의 힘으로 새 시대를 여는 희망"},"w041":{"t":"나비와 광장","a":"김규동","who":[["흰 나비","연약하고 순수하지만 문명의 폭력에 맞서는 존재"],["광장","활주로·제트기가 있는, 전쟁 같은 문명 공간"]],"steps":[{"h":"1연","ev":"활주로의 현기증 나는 절정에서 흰 나비는 돌진할 방향을 잊고 피 묻은 육체의 파편들을 내려다본다.","feel":"혼란","who":["흰 나비","광장"]},{"h":"2연","ev":"작열하는 심장을 축일 샘물 한 모금 없는 허망한 광장에서, 어린 나비의 시야는 투명한 광선의 바다에 가로막힌다.","feel":"허망함","who":["흰 나비","광장"]},{"h":"3연","ev":"제트기의 백선과 인광의 조수에 밀려, 흰 나비는 말없이 이즈러진 날개를 파닥거린다.","feel":"고통","who":["흰 나비","광장"]},{"h":"4연","ev":"하얀 미래의 어느 지점에 아름다운 영토와 화려한 희망이 있을지 묻는다.","feel":"갈망","who":["흰 나비"]},{"h":"5연","ev":"신도 기적도 떠난 마지막 종점을 향해, 흰 나비는 다시 한 번 스스로의 신화와 더불어 대결해 본다.","feel":"의지","who":["흰 나비"],"q":"스스로의 신화와 더불어 대결하여 본다"}],"key":"현대 문명의 폭력 속에서 상처 입은 흰 나비가 끝내 순수함을 지키려 대결에 나선다.","pt":["흰 나비=순수·연약함, 활주로·제트기=전쟁을 연상시키는 현대 문명(나비가 처한 현실)","‘허망한 광장’은 나비가 좌절감을 느끼는 공간(민들레의 ‘내 자리’는 수용의 공간)","‘기계처럼 작열한 심장’은 문명의 힘이 아니라 한계에 이른 나비의 상태, 마지막 연은 의지적 태도"],"src":"해설 p.31~32 · 본책 p.93~95","g":"현대시","s":"수특 현대시 5강","th":"전쟁·기계 문명의 폭력 속 순수한 생명"},"w042":{"t":"민들레꽃","a":"이형기","who":[["민들레","작지만 한계 안에서 전력을 다해 피는 꽃"],["화자","민들레를 지켜보며 예찬하는 사람"]],"steps":[{"h":"1~2연","ev":"쬐그만 민들레가 아무 곳도 넘보지 않고 주어진 한계 안에서 한 치의 틈도 없이 끝까지 샛노랗게 피어 있다.","feel":"경탄","who":["민들레","화자"]},{"h":"3연","ev":"바위 틈이든 잡초 속이든 씨 뿌려진 자리를 내 자리로 받아들이고 터를 잡는다.","feel":"수용","who":["민들레"],"q":"씨 뿌려진 그 자리가 바로 내 자리"},{"h":"4연","ev":"실뿌리는 물을 길어 올리고 떡잎은 어둠을 밀어내며, 한데 어울려 열심히 한 댓새를 피어난다.","feel":"열심","who":["민들레"]},{"h":"5연","ev":"세상에 그것밖에 할 일이 없는 듯 노랗게만 피다가, 피어서는 질 수밖에 없는 꽃이라고 말한다.","feel":"허무","who":["민들레","화자"]},{"h":"6연","ev":"‘혼자 가는 자의 헛된 꿈’일지라도 한 댓새를 영원인 듯 피어 있는 민들레를 보라고 예찬한다.","feel":"예찬","who":["화자","민들레"]}],"key":"작고 덧없는 민들레가 한계와 허무를 받아들이고 끝까지 피어, 어떤 자로도 잴 수 없는 가치를 얻는다.","pt":["‘노랗게’ 색채 이미지가 민들레의 생명력·강인함을 부각한다(나비의 흰색은 순수·연약)","‘씨 뿌려진 그 자리가 바로 내 자리’는 주어진 자리를 받아들이는 수용적 자세","‘짐짓 영원인 양’ 피어 있음은 허무에 매몰되지 않고 삶의 의미를 추구하는 태도"],"src":"해설 p.31~32 · 본책 p.93~95","g":"현대시","s":"수특 현대시 5강","th":"허무에 맞서는 순수한 생명 의지"},"w043":{"t":"그 방을 생각하며","a":"김수영","who":[["화자","혁명이 좌절된 뒤 방을 바꾼 사람"],["그 방","혁명의 열정과 노래를 남기고 온 과거의 공간"]],"steps":[{"h":"1연","ev":"혁명은 안 되고 방만 바꾼 화자는, 벽에 남았을 ‘싸우라’는 말과 두고 온 노래를 떠올리며 가슴이 이유 없이 메말랐다고 한다.","feel":"허탈","who":["화자","그 방"],"q":"혁명은 안 되고 나는 방만 바꾸어 버렸다"},{"h":"2연","ev":"‘일하라’는 말이 헛소리처럼 아직 가슴을 울리지만, 화자는 그 노래도 그 전의 노래도 다 잊어버렸다고 말한다.","feel":"자책","who":["화자","그 방"]},{"h":"3연","ev":"녹슬은 펜과 뼈와 광기뿐인 자신을 인정하며, 실망의 가벼움을 재산으로 삼겠다고 한다.","feel":"수용","who":["화자"]},{"h":"4~6연","ev":"방과 낙서, 기대와 노래, 가벼움마저 잃어도 이제는 무엇인지 모르게 기쁘고 가슴이 이유 없이 풍성하다고 말한다.","feel":"기대","who":["화자"]}],"key":"혁명이 좌절된 환멸 속에서도 실망을 재산으로 삼아, 새로운 삶에 대한 기쁨과 기대로 나아간다.","pt":["‘그 방’은 과거 화자가 중시하던 가치(혁명의 열정)를 상징하는 공간","‘혁명은 안 되고 나는 방만 바꾸어 버렸다’를 변주 반복해 정서의 전환을 드러낸다","‘실망의 가벼움’을 재산으로 삼는 것은 실패를 기억하겠다는 의지(불완전함을 배제하는 것이 아님)"],"src":"해설 p.32~33 · 본책 p.96~98","g":"현대시","s":"수특 현대시 6강","th":"혁명 좌절 뒤의 환멸과 새 삶으로 나아가려는 의지"},"w044":{"t":"달밤","a":"황동규","who":[["화자","상상 속에서 자문자답하며 새 삶을 찾는 사람"],["친구들","상상 속에서 화자가 길을 보여 줄 사람들"]],"steps":[{"h":"1~5행","ev":"누가 와서 부른다면 얼어붙은 들판의 달빛과 그 위를 걷는 한 그림자를 보여 주겠다며, 지금까지 생각해 온 것이 무엇인지 자문한다.","feel":"성찰","who":["화자"]},{"h":"6~9행","ev":"친구 몇몇에게 이제 내 것 가운데 외로움이 아닌 길을 보여 주겠다고 다짐하며, 오래 여며 온 고의춤에 남은 것이 무엇인지 묻는다.","feel":"다짐","who":["화자","친구들"]},{"h":"10~12행","ev":"두 팔을 들고 얼음을 밟으며 구름 갠 들판을 걸을 때, 헐벗은 옷 가득히 달빛을 받는 모습을 그린다.","feel":"충만","who":["화자"],"q":"헐벗은 옷 가득히 받는 달빛 달빛"}],"key":"상상 속 대화와 자문자답으로 지난날을 성찰하고, 외로움이 아닌 열린 길로 나아가려는 마음.","pt":["달빛과 구름 갠 들판은 어두운 과거를 털어 낸 밝은 전망, 외로움 아닌 열린 관계로의 의지","‘구름 개인 들판’은 이전과 달라진, 긍정적이고 개방적인 태도를 암시하는 공간","‘달빛 달빛’처럼 시각적 이미지의 명사로 시행을 마무리해 의미를 강조한다"],"src":"해설 p.32~33 · 본책 p.96~98","g":"현대시","s":"수특 현대시 6강","th":"과거를 성찰하고 새 삶으로 나아가려는 의지"},"w045":{"t":"눈 오는 날에","a":"조지훈","who":[["화자","창가에서 눈을 보며 위안을 찾는 외로운 사람"],["눈","고요히 내려 쌓여 화자를 감싸는 눈발"]],"steps":[{"h":"1~2연","ev":"검정 두루마기에 흰 동정을 단 화자가 창에 기대자, 박 넌출 남은 울타리와 장독대 위로 새하얀 눈이 내려 쌓인다.","feel":"고요함","who":["화자","눈"]},{"h":"3연","ev":"홀로 지니던 값진 보람과 빛나는 자랑을 모두 불사르고 낙엽처럼 무념히 썩어 가는 처지를 떠올린다.","feel":"허망함","who":["화자"]},{"h":"4연","ev":"허망한 시공 위, 외로운 영혼 가까이 꽃다발처럼 하이얀 눈발이 내려 쌓이는 것을 바라본다.","feel":"외로움","who":["화자","눈"]},{"h":"5연","ev":"마음이 고요한 날이면 서라벌 천 년의 풀피리 소리가 아련히 들려온다고 느낀다.","feel":"평온","who":["화자"]},{"h":"6연","ev":"비애로 혼이 야윌 때 절망이 오히려 내리는 눈처럼 포근하다고 깨닫는다.","feel":"위안","who":["화자","눈"],"q":"나리는 눈처럼 포근하고나"}],"key":"삶의 보람이 스러져 허망하던 화자가, 내려 쌓이는 눈에서 절망마저 포근하다는 위안을 얻는다.","pt":["‘보람’·‘자랑’을 ‘불사르고’로 구체화해 화자의 내면적 고통을 드러낸다","‘꽃다발처럼’은 눈을 아름답게 보는 태도, ‘풀피리 소리’는 청각적 이미지로 경건한 분위기","‘절망이란 오히려 나리는 눈처럼 포근하고나’는 전환된 인식이나, 눈은 지속되지 않는 일시적 위안"],"src":"해설 p.33~35 · 본책 p.99~102","g":"현대시","s":"수특 현대시 7강","th":"삶의 비애를 씻고 평안을 얻으려는 소망"},"w046":{"t":"유등제","a":"이수익","who":[["화자","유등제를 보고 싶어 하는, 설움 많은 사람"],["사람들","강가에서 등불을 보내며 간절히 비는 이들"],["유등","물 위에 떠 어둠 속으로 흘러가는 연등 불빛"]],"steps":[{"h":"1연","ev":"해 저문 강가에서 밝은 연등 불빛이 행렬을 이루어 흘러가는 ‘눈물의 제의’, 유등제를 보고 싶다고 소망한다.","feel":"소망","who":["화자","유등"],"q":"유등제를 한번 보고 싶다"},{"h":"2연","ev":"자신도 함께 따라갈 수 있다면 온갖 설움을 푼 몸으로 불빛을 던지며 흘러가 불귀의 하늘에 닿아도 좋겠다고 한다.","feel":"열망","who":["화자","유등"]},{"h":"3연","ev":"길가에 옷을 차려입은 사람들이 멀어지는 등불을 보며 차마 돌아서지 못하고, 부디 저 길이 극락에 이르기를 두 손 모아 빈다.","feel":"경건함","who":["사람들","유등"]},{"h":"4연","ev":"수천수만 개의 연꽃 등불이 별빛처럼 어둠 속으로 흘러가는, 눈물 글썽이는 축복의 제의를 보고 싶다고 되풀이한다.","feel":"염원","who":["화자","유등"]}],"key":"삶의 설움을 유등에 실어 떠나보내는 의식을 보고 싶다는 소망을, 처음과 끝에 반복한다.","pt":["처음과 끝의 ‘유등제를 한번 보고 싶다’ 반복(수미상관)과 어둠–불빛의 시각적 대비","유등은 번민·설움을 떠나보내는 수단(‘불빛’은 일상에서 발견한 희망이 아님), ‘따라갈 수 있다면’은 가정적 소망","화자 개인을 넘어 ‘수천, 수만 개’ 행렬과 사람들의 마음으로 의식이 확장된다"],"src":"해설 p.34~35 · 본책 p.99~102","g":"현대시","s":"수특 현대시 7강","th":"삶의 비애를 씻고 평안을 얻으려는 소망"},"w047":{"t":"포스터 속의 비둘기","a":"신동집","who":[["화자","포스터 속 비둘기의 과거를 떠올리는 사람"],["비둘기","포스터에 갇혀 자유와 생명력을 잃은 존재"]],"steps":[{"h":"1~4행","ev":"포스터 속에 들어앉은 비둘기가 자꾸 곁눈질을 하고, 오래 있으면 비둘기의 습성도 웬만큼 변한다고 말한다.","feel":"안타까움","who":["화자","비둘기"]},{"h":"5~9행","ev":"비둘기가 한때 노닐던 지붕마루를 화자는 알고 있지만, 지금은 비어 버린 집통만 비바람에 삭고 있다.","feel":"아쉬움","who":["화자","비둘기"]},{"h":"10~12행","ev":"포스터 속에는 비둘기가 날아 볼 하늘도, 마셔 볼 공기도 없다.","feel":"답답함","who":["비둘기"]},{"h":"13~19행","ev":"답답해 몸부림쳐도 열없고, 몸을 구기고 찢고 불에 태워도 피 한 방울 나지 않고 재도 남지 않는다.","feel":"허탈","who":["화자","비둘기"]},{"h":"20~23행","ev":"수많은 복사 속에 다친 데 하나 없이 들어앉은 비둘기를 두고, 차라리 죽지 못해 탈이라고 한다.","feel":"비판","who":["화자","비둘기"],"q":"차라리 죽지 못해 그는 탈이다"}],"key":"자유롭게 날던 비둘기가 포스터에 갇힌 모습으로, 자유를 잃은 현대인의 처지를 우의한다.","pt":["포스터는 인위적·획일적인 현대문명을, ‘수많은 복사’는 똑같은 모습의 획일성을 환기한다","비어 버린 ‘집통’은 비둘기가 머무르다 떠난 곳 — 비둘기의 부재를 확인하게 하는 공간","‘차라리 죽지 못해 그는 탈이다’에 부자유한 현실에 대한 화자의 비판적 시선이 담긴다"],"src":"해설 p.35~36 · 본책 p.103~105","g":"현대시","s":"수특 현대시 8강","th":"자유를 억압하는 현대 현실 비판"},"w048":{"t":"대설주의보","a":"최승호","who":[["굴뚝새","작은 날개로 눈보라를 피하는 연약한 존재"],["눈보라","해일·군단·계엄령에 빗댄 거대한 위협"],["화자","눈 내리는 산골을 지켜보는 관찰자"]],"steps":[{"h":"1연","ev":"해일처럼 굽이치는 백색의 산과 골짜기를 굵은 눈발이 메우는 가운데, 숯덩이만 한 굴뚝새가 눈보라 속으로 날아간다.","feel":"긴장","who":["굴뚝새","눈보라"]},{"h":"2연","ev":"길 잃은 등산객과 끊긴 마을 길을 떠올릴 만큼 눈보라의 군단이 은하수처럼 덤비고, 백색의 계엄령이 내린다.","feel":"위압","who":["눈보라","화자"],"q":"눈보라가 내리는 백색의 계엄령"},{"h":"3연","ev":"꺼칠한 굴뚝새가 서둘러 뒷간에 몸을 감추고, 어디 솔개라도 도사리는 걸까 두려워한다.","feel":"공포","who":["굴뚝새"]},{"h":"4연","ev":"산짐승과 소나무, 외딴집 굴뚝까지 모두 부술 듯 눈보라가 백색의 계엄령으로 몰아친다.","feel":"압도","who":["눈보라","화자"]}],"key":"폭설을 군단·계엄령으로 그려 억압적 현실을 상징하고, 몸을 숨기는 굴뚝새로 민중의 처지를 환기한다.","pt":["‘눈보라의 군단’·‘백색의 계엄령’은 1980년대 군부독재의 폭력성을 환기한다","‘뒷간’은 굴뚝새가 위협을 피해 숨는 공간, 굴뚝새는 자유를 박탈당한 민중","‘-(으)ㄹ 듯’ 추측 표현의 반복과 ‘해일처럼’ 직유가 눈보라의 역동적 위협을 부각한다"],"src":"해설 p.35~36 · 본책 p.103~105","g":"현대시","s":"수특 현대시 8강","th":"폭력적 억압의 현실과 그 속 연약한 존재"},"w049":{"t":"그 여름의 끝","a":"이성복","who":[["화자","폭풍 같은 절망을 겪고 이겨 낸 사람"],["백일홍","폭풍에도 쓰러지지 않고 붉은 꽃을 피운 나무"]],"steps":[{"h":"1연","ev":"그 여름 백일홍은 거듭된 폭풍에도 쓰러지지 않고, 우박처럼 쏟아지는 붉은 꽃들을 매달고 무사했다.","feel":"경탄","who":["백일홍","화자"]},{"h":"2연","ev":"같은 여름 화자도 폭풍의 한가운데에서 절망을 겪었지만 여러 차례 폭풍에도 쓰러지지 않고 버텼다.","feel":"절망","who":["화자"]},{"h":"3연","ev":"넘어지면 매달리고 불을 뿜듯 억센 백일홍 꽃들이 좁은 마당을 피로 덮을 때, 화자의 절망도 끝났다.","feel":"극복","who":["화자","백일홍"],"q":"장난처럼 나의 절망은 끝났습니다"}],"key":"폭풍을 이겨 붉은 꽃을 피운 백일홍을 보며, 화자 자신의 절망도 끝났다는 극복의 깨달음.","pt":["‘장난처럼’은 반어적 표현 — 절망이 결코 가볍지 않았음을 드러낸다","백일홍과 화자는 시련을 견딘다는 점에서 대응하며, ‘붉은 꽃들’은 시련을 이겨 낸 결실","「그 나무」와 함께: 색채어(‘붉은’, ‘푸릇한’)로 대상의 이미지를 선명하게 제시"],"src":"해설 p.37~38 · 본책 p.106~108","g":"현대시","s":"수특 현대시 9강","th":"절망을 견디고 이겨 내는 자세"},"w050":{"t":"그 나무","a":"김명인","who":[["화자","봄길에서 늦된 나무를 발견한 사람"],["그 나무","꽃을 못 피우고 멈칫거리는 늦된 나무"]],"steps":[{"h":"1~4행","ev":"벚꽃이 한 해 꽃잎을 피웠다 지운 가로를 따라가다, 제 꽃 한 송이도 펼치지 못하고 멈칫거리는 늦된 나무를 발견한다.","feel":"눈길","who":["화자","그 나무"],"q":"늦된 그 나무 발견했지요"},{"h":"5~11행","ev":"들킨 게 부끄러운 듯 비틀린 뿌리를 감추고 그늘에 숨은 나무가, 꽃철이 지난 줄 모르고 멍울을 가득 달고 있어 안쓰럽다.","feel":"연민","who":["화자","그 나무"]},{"h":"12~18행","ev":"나무가 밝힐 꽃불 성화를 기다리며 길이 끝났다는 생각을 잊고, 헤매던 지난 봄길을 떠올리며 병든 나무 곁에서 서성인다.","feel":"동질감","who":["화자","그 나무"]},{"h":"19~22행","ev":"이 봄이 가기 전, 또 여름이 지쳐 갈 때 저 나무도 푸른 잎과 가난한 소지를 피워 올릴 수 있을지 묻는다.","feel":"기대","who":["화자","그 나무"]}],"key":"꽃을 못 피운 늦된 나무에서 헤매던 자신을 보고, 나무와 자신의 뒤늦은 결실을 기대한다.","pt":["6모: 늦된 나무는 화자의 지지부진한 처지를 환기하는 연민의 대상","6모: 교감을 통해 삶의 긍정적 전망을 스스로 묻는 전개, ‘꽃불 성화’를 기다리는 시간","수특: ‘저 나무도 푸릇한 잎새 매달까요?’는 안타까움이 아니라 결실을 바라는 마음"],"src":"해설 p.37~38 · 본책 p.106~108","g":"현대시","s":"수특 현대시 9강","th":"자연물에서 발견한 자기 성찰"},"w051":{"t":"원시","a":"오세영","who":[["화자","늙음을 통해 이별을 담담히 받아들이는 사람"],["사랑하는 사람","이별을 서러워 말라고 달래는 청자"]],"steps":[{"h":"1~6행","ev":"무지개나 별, 벼랑에 핀 꽃처럼 손에 닿을 수 없는 멀리 있는 것은 그 까닭에 아름답다고 말한다.","feel":"깨달음","who":["화자"]},{"h":"7~11행","ev":"사랑하는 사람에게 이별을 서러워하지 말라며, 내 나이의 이별은 헤어짐이 아니라 멀어짐일 뿐이라고 달랜다.","feel":"위로","who":["화자","사랑하는 사람"]},{"h":"12~19행","ev":"마지막 편지를 읽으려면 돋보기가 필요한 나이가 되어, 늙음은 사랑하는 이를 멀리 보내고 멀리서 바라볼 줄 아는 것이라 깨닫는다.","feel":"원숙함","who":["화자","사랑하는 사람"],"q":"머얼리서 바라볼 줄을"}],"key":"멀리 있어 아름답듯 이별은 멀어짐일 뿐이라는, 늙음이 가져다준 사랑과 이별에 대한 원숙한 깨달음.","pt":["원시(遠視)의 비유 — 가까운 것은 흐릿하고 먼 것은 선명하다는 점에서 이별을 긍정하는 역설","‘멀리 있는 것은 아름답다’가 ‘이별을 서러워하지 마라’의 이유가 된다","무지개·별·벼랑의 꽃은 멀리 있어 아름다운 대상(가까이 두려는 대상 아님), 돋보기는 나이듦"],"src":"해설 p.38~39 · 본책 p.109~111","g":"현대시","s":"수특 현대시 10강","th":"거리를 둘 때 보이는 사랑·관계의 성숙"},"w052":{"t":"차심","a":"손택수","who":[["화자","차심 이야기를 옮기며 깨달음을 얻는 사람"],["너","금이 간 사이로 마주한 상대"]],"steps":[{"h":"1~3행","ev":"물이끼인 줄 알았던 것이 찻잔을 길들이는 ‘차심’이라는 이야기를 듣는다.","feel":"발견","who":["화자"]},{"h":"4~6행","ev":"가마 속에서 흙과 유약이 다투며 그릇에 잔금이 생기고, 뜨거운 찻물이 파고들어 그릇 색이 변해 가는 과정을 전해 듣는다.","feel":"호기심","who":["화자"]},{"h":"7~8행","ev":"차심이 박힌 그릇의 금은 병균을 막고 그릇을 더 단단하게 조여 준다는 이야기를 듣는다.","feel":"놀라움","who":["화자"]},{"h":"9~10행","ev":"불가마 속 고통을 다스리는 차심이 ‘차의 마음’이라는 말처럼 들렸다고 한다.","feel":"공감","who":["화자"]},{"h":"11~15행","ev":"대를 이은 잔처럼, 갈라진 너와 나 사이에도 그런 빛깔을 우려내어 금마저 몸의 일부인 양 받아들였으면 하고 바란다.","feel":"소망","who":["화자","너"]}],"key":"금 간 그릇이 차심으로 단단해지듯, 갈라진 너와 나 사이도 상처를 품어 더 단단해지길 바란다.","pt":["잔금(상처)이 차심이 되어 그릇을 지키는 역설을 ‘갈라진 너와 나’ 관계에 적용(유추)","전개: 발견 → 생성 과정 → 효과 → 화자의 인식 → 자기 문제에 적용(마지막에 ‘너와 나’로 확장)","‘차심’은 ‘잔금’ 자체가 아니라 잔금에 찻물이 배어 생긴 것(‘차의 마음’은 새로 떠올린 의미)"],"src":"해설 p.38~39 · 본책 p.109~111","g":"현대시","s":"수특 현대시 10강","th":"상처를 통해 성숙하는 관계"},"w053":{"t":"면면함에 대하여","a":"고재종","who":[["화자","청자에게 느티나무 이야기를 들려주는 사람"],["느티나무","겨울 시련을 견디고 초록을 되찾은 마을의 나무"],["농민들","앞들에서 모를 내다 나무를 바라보는 사람들"]],"steps":[{"h":"1~2연","ev":"동구 밖 느티나무의 푸르른 울음소리를 들어 보았느냐고 묻고, 삭풍이 몰아친 지난겨울 상처마다에서 뽑아내던 소리라고 한다.","feel":"연민","who":["화자","느티나무"],"q":"푸르른 울음소리"},{"h":"3연","ev":"다 떠나 버리는 마을에서 ‘지킬 것은 지켜야 한다’며 소리 죽여 흐느끼던 나무의 소리를 떠올린다.","feel":"비장함","who":["화자","느티나무"]},{"h":"4연","ev":"오늘은 그 울음을 이파리마다 내주고, 나무가 생생한 초록의 광휘를 내뿜는다고 말한다.","feel":"경이","who":["화자","느티나무"]},{"h":"5연","ev":"앞들에서 모를 내다 허리 펴는 사람들이 나무를 한참 쳐다보고, 어디선가 북소리가 울린다고 묻듯 말한다.","feel":"희망","who":["농민들","느티나무"]}],"key":"혹독한 겨울을 견디고 초록으로 살아난 느티나무에서, 이농에도 마을을 지키는 농민들이 힘을 얻는다.","pt":["‘너 들어 보았니’·‘왜 ~겠니’ 같은 문장 구조와 물음의 반복이 주제의식을 강조한다","‘푸르른 울음소리’는 색채+청각 — ‘울음’은 ‘초록의 광휘’로 이어져 희망을 뜻한다","이농으로 비어 가는 마을과 ‘지킬 것은 지켜야 한다’는 의연함의 대비, 나무를 보며 힘을 얻는 농민들"],"src":"해설 p.39~41 · 본책 p.112~115","g":"현대시","s":"수특 현대시 11강","th":"시련 속에서도 이어지는 민중의 생명력"},"w054":{"t":"며느리밥풀꽃","a":"송수권","who":[["화자","뜰에서 풀꽃과 설화를 떠올리는 사람"],["며느리","설화 속 시집살이에 서러웠던 여인"],["며느리밥풀꽃","설움을 딛고 바위섬 그늘에 피는 꽃"]],"steps":[{"h":"1연","ev":"햇빛 좋은 날 뜰에 내려, 산부추와 개망초 같은 풀꽃들로 가득 찬 섬들을 떠올리며 물길 백 리 송이섬에 갈까 생각한다.","feel":"그리움","who":["화자"]},{"h":"2연","ev":"밟으면 으스러져도 주저앉은 우리를 다시 일으켜 세우는 꽃으로, 시어머니 몰래 밥알 두 알을 혀끝에 감추고 울음을 삼킨 며느리의 설화를 떠올린다.","feel":"서러움","who":["화자","며느리","며느리밥풀꽃"]},{"h":"3연","ev":"햇빛이 기진하면 혀를 빼문 채, 며느리밥풀꽃은 지금도 그 바위섬 그늘에 피어 있다고 한다.","feel":"한","who":["화자","며느리밥풀꽃"],"q":"지금도 그 바위섬 그늘에 피었느니라"}],"key":"며느리밥풀꽃 설화로 시련과 설움 속에서도 끈질기게 삶을 이어 가는 민중의 모습을 그린다.","pt":["‘밟으면 으스러지는 꽃’·‘일으켜 세우는 꽃’·‘추스림 끝에 피는 꽃’ — ‘~는 꽃’ 구조의 반복","‘울음’은 설화 속 며느리의 서러움을 담는다(느티나무의 ‘울음’은 희망과 연결)","‘밟으면 으스러지는 꽃’은 핍박받는 민중의 처지이지 저항·희망을 찾아냄이 아니다"],"src":"해설 p.40~41 · 본책 p.112~115","g":"현대시","s":"수특 현대시 11강","th":"시련 속에서도 이어지는 민중의 생명력"},"w055":{"t":"포천이문","a":"이현기","who":[["정공","포천 현감(실존 인물 정태화). 북벌의 길흉을 묻는다"],["하공","개국공신 하륜의 혼령. 북벌론의 허상을 짚는다"]],"steps":[{"h":"앞부분","ev":"정공이 포천 현감으로 온 밤 하륜의 혼령이 폐허가 된 묘를 돌봐 달라 청한다. 정공이 묘를 이장·단장하고 후손에게 땅을 주자 하공이 감사하러 다시 온다.","feel":"공손함","who":["정공","하공"]},{"h":"혼령의 말","ev":"하공은 보은할 길이 없다며 정공의 수명이 늘 것이라 축하하고, 넋이 오래 남는 정도는 타고난 기질에 달렸으며 저승 일은 말할 수 없다고 한다.","feel":"호기심","who":["정공","하공"],"q":"저승의 일은 누설할 수 없으니 묻지 말아 주시오"},{"h":"북벌 논의","ev":"정공은 명나라와의 의리를 내세워 청나라를 칠 북벌의 길흉을 묻는다. 하공은 절개를 지켜 죽는 일은 영예롭지만 명성을 노려 겉으로만 외치는 북벌은 인정하지 않는다고 답한다.","feel":"단호함","who":["정공","하공"],"q":"속으로는 오랑캐를 두려워하면서 겉으로만"},{"h":"탁상공론","ev":"정공이 병력과 곡식, 오삼계와의 연합을 들어 북벌이 가능하다고 하자, 하공은 천시·지리·인사 모두 조선이 열세라며 반박하고 정공은 화의를 지키겠다고 한다.","feel":"확신","who":["하공","정공"],"q":"사또는 아직도 탁상공론을 하고 있소"},{"h":"폐단의 해법","ev":"정공이 국정의 폐단을 바로잡을 방도를 묻자, 하공은 집안의 종을 부리는 일에 빗대어 가장 용렬하고 게으른 종을 갈아 치우면 모든 일이 잘 돌아간다고 답한다.","feel":"간명함","who":["하공","정공"],"q":"게으른 종을 도태시키고 똑똑하고 부지런한 자를"},{"h":"결말","ev":"정공은 가르침이 간명하고 핵심을 찔렀다며 사례하고, 하공은 작별을 고하고 표연히 떠난다. 정공은 훗날 공명을 드날리고 후손도 번성한다.","feel":"경복","who":["정공","하공"],"q":"참으로 간명하면서도 핵심을 찌른 말씀"}],"key":"혼령 하공과 현감 정공의 문답으로 북벌론의 허상을 비판하고 인재 등용을 강조한 한문 단편","pt":["㉠은 종 비유로 인재를 가려 써야 국정의 폐단을 막는다는 뜻(3번)","[B]에서 하공은 군대에 대한 정공의 견해에 동의하지 않고 반박함(2번)","혼령의 입을 빌려 북벌 비판을 우회함. ‘양측을 대등하게 다뤘다’는 감상은 오답(4번)"],"src":"해설 p.41~42 · 본책 p.116~119","g":"고전산문","s":"수특 고전산문 1강","th":"북벌론의 허상과 올바른 인재 등용"},"w056":{"t":"왕수재취득용녀설","a":"작자 미상","who":[["왕수재","활솜씨가 뛰어난 사신 일행. 해신이 꺼린다고 지목된다"],["노인","서해용왕의 아들. 구미호를 물리쳐 달라 청한다"],["구미호","삼천 년 묵은 요물. 아름다운 부인으로 나타난다"],["상사","사행의 우두머리. 멈춘 배를 두고 애태운다"],["용녀","노인의 딸. 왕수재의 아내가 되어 왕건을 낳는다"]],"steps":[{"h":"발단","ev":"바람도 파도도 없는데 사신 배가 사흘째 나아가지 못한다. 상사 일행이 해신에게 거듭 제사를 올려도 소용이 없어 모두 두려움에 떤다.","feel":"초조함","who":["상사"]},{"h":"옷깃 점괘","ev":"왕수재가 각자 윗옷을 던져 해신의 뜻을 묻자고 하니, 다른 옷은 모두 가라앉고 수재의 옷만 떠올라 그가 지목된다. 수재는 운명이라며 바다에 뛰어들려 한다.","feel":"체념","who":["왕수재","상사"],"q":"유독 수재의 옷 하나만이 물 위에 떠"},{"h":"섬의 노인","ev":"일행은 수재를 말려 가까운 섬에 내려 주고 떠난다. 섬에서 만난 노인은 서해용왕의 아들이라 밝히며 집을 빼앗으려는 구미호를 활솜씨로 물리쳐 달라고 청한다.","feel":"겸손","who":["왕수재","노인"],"q":"삼천 년 묵은 구미호가 내 집을 빼앗으려"},{"h":"구미호 출현","ev":"오후에 신선의 음악이 들리더니 임금의 가마를 탄 아름다운 부인이 행렬과 함께 나타난다. 노인은 지금 쏘면 막히니 싸우는 틈을 타 명치를 쏘라고 일러 준다.","feel":"황홀","who":["왕수재","노인","구미호"],"q":"부인 한 사람이 임금이 타는 가마 위에 앉아"},{"h":"차마 못 쏨","ev":"이튿날 노인이 바다 위를 평지처럼 걸어 싸우는 사이 수재는 시위를 당기지만, 부인이 너무 아름다워 사람 같다며 차마 쏘지 못하고 손을 푼다.","feel":"망설임","who":["왕수재","구미호"],"q":"사람이 사람을 쏴 죽여서야 되겠는가"},{"h":"이후","ev":"수록 부분 뒤에 수재는 결국 활을 쏘아 여우를 죽이고, 노인은 보답으로 딸 용녀를 아내로 준다. 부자가 된 수재의 아내는 훗날 나라의 주인이 될 왕건을 낳는다.","feel":"성취감","who":["왕수재","노인","용녀"]},{"h":"결말","ev":"용녀는 변신해야 하니 방에 들 때 알려 달라 청했으나, 수재가 실수로 그냥 들어가 용으로 변한 모습을 보고 정이 식는다. 아내는 신의를 저버렸다며 떠난다.","feel":"정이 식음","who":["왕수재","용녀"]}],"key":"해신에게 지목돼 섬에 남은 왕수재가 용왕의 아들을 도와 구미호를 쏘고 용녀와 맺어진 이야기","pt":["「거타지 설화」를 원천으로 뼈대는 잇고 일부를 바꾼 작품 — 비교 감상(4번)","[B]에서 노인은 수재의 신궁 솜씨를 근거로 도움을 청함(2번)","㉤ ‘바다 위를 평지 밟듯’은 초현실적 대상에 견준 표현이 아님(3번)"],"src":"해설 p.43~44 · 본책 p.120~124","g":"고전산문","s":"수특 고전산문 2강","th":"왕수재의 영웅적 활약과 용녀와의 결연"},"w057":{"t":"서해무릉기","a":"작자 미상","who":[["유생","해설의 유연. 여승으로 변장해 신부를 찾아다닌다"],["최씨","유생의 신부 최월혜. 납치되어 서해무릉에 있다"],["금산사 부처","꿈에 나타나 두 사람을 돕는 초월적 조력자"],["장군","최씨를 납치한 도적. 혼례를 서두른다"],["정부인","장군의 어머니. 최씨에게 혼례를 권한다"]],"steps":[{"h":"혼사 장애","ev":"유연은 친척 최월혜에게 반해 상사병을 앓다 부모의 허락으로 혼인하지만, 혼삿날 밤 도적이 신부를 빼앗아 간다. 유연은 10년을 기한으로 신부를 찾아 집을 떠난다.","feel":"애끓음","who":["유생","최씨","장군"]},{"h":"서해무릉","ev":"도적은 최씨를 서해무릉에 데려가 억지로 혼인하지 않고 기다린다. 3년 뒤 여승으로 변장한 유생이 서해를 헤매다 이 섬에 닿고, 마을 사람들은 후하게 양식을 내어 준다.","feel":"기대","who":["유생","장군"],"q":"이곳은 서해무릉이라는 곳이오"},{"h":"부처의 현몽","ev":"고향을 그리던 최씨의 꿈에 금산사 부처가 나타나 내일 올 여승이 남편 유생이라 알려 준다. 시녀 계선의 권유로 나간 최씨는 초췌한 여승이 유생임을 알아본다.","feel":"애통함","who":["최씨","금산사 부처","유생"],"q":"나는 금산사의 부처로다"},{"h":"중략 이후","ev":"장군에게 쫓겨난 유생은 부처의 도움으로 찾은 굴에 숨는다. 정부인이 혼례를 재촉하자 최씨는 죽는 것이 마땅하다며 거절하고 식음을 전폐한다.","feel":"절망","who":["유생","최씨","정부인"]},{"h":"재회 약속","ev":"다시 꿈에 부처가 나타나 장원 밖에 유생이 와 있으니 달아날 기약을 정하라 한다. 최씨가 하늘에 계책을 빌자 담 밖의 유생이 목소리를 듣고 만날 기약을 알리라고 답한다.","feel":"반가움","who":["최씨","유생","금산사 부처"],"q":"서로 만날 기약을 정해 알려 주십시오"},{"h":"결말","ev":"수록 부분 뒤에 유연은 금산사 부처의 도움으로 최씨를 되찾아 완전한 결연을 이룬다.","feel":"안도","who":["유생","최씨"]}],"key":"인척 혼인과 납치라는 두 겹의 장애를 금산사 부처의 도움으로 넘고 재결합하는 혼사 장애 소설","pt":["정부인의 혼례 권유와 부처의 도피 권유는 모두 상대가 할 일을 제시함(2번)","첫 번째 꿈은 최씨가 계선의 말을 따라 나가 보게 되는 계기(3번)","여승은 유생의 변장, 비현실적 조력자는 금산사 부처 — 혼동하면 오답(4번)"],"src":"해설 p.44~46 · 본책 p.125~128","g":"고전산문","s":"수특 고전산문 3강","th":"관습과 시련을 넘어선 남녀의 사랑"},"w058":{"t":"반씨전","a":"작자 미상","who":[["반씨","위윤의 아내인 맏며느리. 어질지만 모함을 받는다"],["위흥","반씨의 아들. 어머니를 모시고 위기를 피한다"],["채씨","둘째 며느리. 반씨를 시기해 모해한다"],["채영","채씨의 아버지. 권세가 높은 좌승상"],["산신령","산을 지키는 노인. 반씨 모자를 구한다"]],"steps":[{"h":"앞부분","ev":"위씨 삼형제의 아내 중 맏며느리 반씨는 어질지만 동서 채씨와 맹씨의 시기를 받는다. 시어머니 양부인이 두 며느리를 꾸짖자 채씨는 분을 품고 친정으로 간다.","feel":"억울함","who":["반씨","채씨"]},{"h":"채영의 음모","ev":"채씨의 호소를 들은 아버지 채영은 위윤과 반옥의 죄를 천자에게 아뢴다. 신하들은 채영의 권세가 두려워 말이 없어, 천자는 두 사람을 아끼면서도 유배 보낸다.","feel":"위세","who":["채씨","채영"],"q":"제신이 다 채영의 권세를 두려워하여"},{"h":"화공 모의","ev":"채씨는 반씨의 아들 흥이 스승에게 배우고 선관이 밤마다 온다는 말을 음란한 행실로 몰아 위진에게 이른다. 위진은 창두 이십여 명을 보내 반씨 모자의 여막에 불을 지르게 한다.","feel":"악의","who":["채씨","반씨","위흥"],"q":"이제 바삐 처치하소서"},{"h":"초월적 조력","ev":"꿈에 한 부인이 위기를 알리자 반씨 모자는 급히 산으로 피한다. 집이 불타는 것을 보고 방황하다 만난 노인은 산신령으로, 양부인의 청으로 구하러 왔다며 먹을 것을 준다.","feel":"다급함","who":["반씨","위흥","산신령"],"q":"나는 이 산을 지키는 신령이더니"},{"h":"외가로","ev":"정신이 맑아진 모자는 양강에 이르러 외가 반부를 찾아간다. 유부인이 장성한 흥을 반기고, 반공과 위상서의 유배를 슬퍼하는 모녀가 서로 위로한다.","feel":"안도","who":["반씨","위흥"]},{"h":"이후","ev":"수록 부분 뒤에 반씨는 선녀와 거북의 도움으로 살아나고, 위흥은 장원급제해 악인을 벌하고 가족을 복권시키며 부마가 된다. 황제의 훈계로 비극이 마무리된다.","feel":"안정","who":["반씨","위흥"]}],"key":"동서의 시기와 모함으로 위기에 빠진 선한 반씨가 초월적 조력으로 이겨 내는 권선징악의 가정 소설","pt":["음모 모티프(악인의 음모-선인의 위기-고난 극복-권선징악), 갈등 축은 동서 대립(4번)","위윤·반옥의 유배는 선인의 위기이지 권선징악의 실현이 아님(4번)","ⓐ(꿈속 부인)로 목숨을 구한 뒤 조력자 ⓑ(산신령)를 만남. 비현실 세계로의 이동은 아님(3번)"],"src":"해설 p.46~47 · 본책 p.129~132","g":"고전산문","s":"수특 고전산문 4강","th":"선한 인물의 고난과 권선징악"},"w059":{"t":"현몽쌍룡기","a":"작자 미상","who":[["정소저","정채임. 계모를 피해 남장하고 달아난다"],["용홍","조공자 형제의 형. 소저와 정혼한 사이"],["용창","용홍의 동생. 형과 함께 소저 일행을 구한다"],["춘앵·벽란","정소저의 시비. 소저의 사연을 공자에게 알린다"],["계모 박씨","정참정의 후처. 소저의 혼사를 가로막는다"]],"steps":[{"h":"앞부분","ev":"용홍은 정채임과 정혼하지만, 채임의 아버지 정참정이 계모의 말만 믿고 다른 곳으로 시집보내려 하자 채임은 시비들과 남장해 달아나다 강물에 몸을 던진다.","feel":"절박함","who":["정소저","계모 박씨"]},{"h":"구출","ev":"용홍과 용창이 이들을 구해 남자가 아님을 짚으며 캐묻는다. 춘앵과 벽란은 반악·위개를 비웃을 만큼 빼어난 공자들의 어진 덕을 보고 소저의 정혼자 조씨 형제임을 알게 된다.","feel":"다행스러움","who":["용홍","용창","춘앵·벽란"],"q":"결코 남자가 아니다"},{"h":"소저의 당부","ev":"시비에게 이야기를 전해 들은 소저는 조숙모에게 부끄럽고 아버지의 허물도 드러내기 싫어 사정을 숨긴다. 타향에서 친척을 찾다 도적을 만났다고만 말하라고 이른다.","feel":"부끄러움","who":["정소저","춘앵·벽란"],"q":"아버지의 허물을 드러내고 싶지 않아서"},{"h":"시비의 고백","ev":"춘앵과 벽란은 좋은 기회를 놓칠 수 없다며 소저의 당부와 달리 계모의 박해, 박수관과의 혼사 강요, 남장 도피와 투신까지 공자에게 모두 털어놓는다.","feel":"간절함","who":["춘앵·벽란","용홍","계모 박씨"],"q":"소저의 백년가약을 어느 날 이루겠는가"},{"h":"모르는 척","ev":"사연을 들은 두 공자는 소저의 절개에 감동해 강정에 머물게 하고 종들에게 비밀을 당부한다. 정작 소저에게는 근본을 모르는 체하며 안심하고 화를 피하라 권한다.","feel":"측은함","who":["용홍","용창","정소저"],"q":"근본을 모르는 체하고"},{"h":"소저의 생각","ev":"형제가 떠난 뒤 소저는 외간 남자의 손에 구해진 일에 놀라지만 그가 조공자라 다행이라 여긴다. 절간에 의탁해 은혜를 생각하려 하며 공자들이 사연을 안 줄은 모른다.","feel":"감사","who":["정소저"]},{"h":"이후","ev":"수록 부분 뒤에 형제는 각자의 인연과 혼인하고 용홍은 황제의 뜻으로 금선공주를 맞아 부마가 된다. 형제는 국가의 위기와 집안의 분란을 해결해 가문의 평온을 되찾는다.","feel":"화목함","who":["용홍","용창"]}],"key":"계모 때문에 남장해 떠돌던 정소저를 구한 조씨 형제가 사연을 알고도 모르는 척 보호하는 가문 소설","pt":["정보의 격차: 공자는 소저의 사정을 알지만 소저는 모른다. 독자는 먼저 앎(4번)","남장한 일행의 모습이 공자 형제가 사연에 관심을 갖는 계기가 됨(1번)","계모·정참정이 만든 혼사 장애와 그 극복, 통속적 재미를 추구하는 가문 소설(2번)"],"src":"해설 p.47~49 · 본책 p.133~137","g":"고전산문","s":"수특 고전산문 5강","th":"조씨 형제의 결연과 영웅적 활약"},"w060":{"t":"대관재몽유록","a":"심의","who":[["나(심모)","현실에 불만을 품은 문인. 꿈속에서 공을 세운다"],["천자","꿈속 문인 왕국의 임금. 해설은 최치원이라 한다"],["김시습","반란을 일으킨 적장. 휘파람에 항복한다"],["한림선생","‘나’를 탄핵하는 상소를 올린 신하"],["이색","상국. ‘나’를 꿈에서 깨어나게 한다"]],"steps":[{"h":"입몽","ev":"현실에 불만을 품은 문인 ‘나’는 꿈속 천상 세계에서 천자 최치원의 총애를 받아 관직을 얻는다. 규벽부를 맡아 자신의 시론을 인정받는다.","feel":"기대","who":["나(심모)","천자"]},{"h":"반란 진압","ev":"김시습의 난이 일어나자 ‘나’는 단출하게 길을 떠나 적의 성채 앞에서 휘파람을 분다. 반란군이 흩어지고 적장 김시습은 두 손을 묶고 항복한다.","feel":"당당함","who":["나(심모)","김시습"],"q":"한 번 휘파람을 불었더니 적은 용기를 잃었고"},{"h":"공신과 청렴","ev":"천자는 ‘나’에게 공신의 호와 안동백 작위를 내리고, 벼슬 10년에 문벌이 빛난다. ‘나’는 사사로운 교제를 사양하고 이규보를 탄핵해 오거서와 영경연사 직을 받는다.","feel":"자부심","who":["나(심모)","천자"],"q":"신하 된 도리로 사사로이 교제할 수가 없습니다"},{"h":"사단","ev":"두 선녀가 두보와 이백이 사단에 모였다고 알리자 천자는 구름처럼 단에 오르지만, 삼정승과 신하들은 중간층에서 떨며 시종하지 못한다. 천자는 두 천자에 못 미침을 탄식한다.","feel":"탄식","who":["천자"],"q":"짐이 감히 당할 수가 없다"},{"h":"탄핵과 하직","ev":"한림선생이 ‘나’가 속세의 허물을 못 벗고 사욕이 지나치다고 탄핵하자, 천자는 대관선생이라는 호를 내리고 옛 직분으로 돌아가라 한다. ‘나’는 눈물로 하직한다.","feel":"서러움","who":["나(심모)","천자","한림선생"],"q":"공은 옛날 직분으로 돌아가시오"},{"h":"각몽","ev":"이색이 ‘나’의 오장육부를 가르고 먹물을 부으며 40여 년 뒤를 기약한다. 복통에 깨어 보니 배가 부풀었고 병든 아내가 곁에 있다. ‘나’는 궁달이 팔자소관이라 탄식한다.","feel":"허탈","who":["나(심모)","이색"],"q":"배가 북처럼 부풀어 올랐고"}],"key":"현실에 불만을 품은 문인이 꿈속 문인 왕국에서 공을 세우다 탄핵받고 깨어나는 몽유록","pt":["환몽 구조: 깨어나는 계기(복통)와 꿈속·꿈밖을 잇는 증거(부푼 배)(3번)","사단은 천자만 끝까지 오르고 신하는 한계를 느끼는 환상 공간. 주인공이 재능을 뽐내는 곳은 아님(2번)","꿈속 이상 세계도 시기·참소가 있는 곳으로 그려 현실을 비판함(4번, 보기)"],"src":"해설 p.49~50 · 본책 p.138~141","g":"고전산문","s":"수특 고전산문 6강","th":"꿈속 문인 왕국에서 경험한 이상 세계"},"w061":{"t":"금방울전","a":"작자 미상","who":[["해룡","장해룡. 금령의 도움으로 어사가 되어 부모를 찾는다"],["금령","금방울. 신통한 능력으로 해룡을 돕는다"],["공주","요괴에게 잡혔다 해룡에게 구해진 금선공주"],["천자","공주를 되찾고 해룡을 부마로 삼는 임금"],["사또","뇌양현의 사또. 해룡의 친아버지 장원"]],"steps":[{"h":"전생과 환생","ev":"전생에 부부였던 남해용왕의 딸과 동해용왕의 아들이 억울하게 죽은 뒤 각각 신통한 금방울(금령)과 장원 부부의 아들 해룡으로 태어난다. 해룡은 전란 중 부모를 잃는다.","feel":"고난","who":["금령","해룡"]},{"h":"금령의 활약","ev":"금령은 어머니 막씨를 돕고 변씨의 박해를 받는 해룡을 위기마다 구한다. 해룡은 지하국의 요괴를 퇴치해 금령과 납치된 금선공주를 구한다.","feel":"헌신","who":["금령","해룡","공주"]},{"h":"환궁과 혼인","ev":"공주가 꿈속 선인의 말과 금령의 활약을 알리자, 천자는 해룡의 공이 태산보다 크다며 둘을 천정배필이라 하여 부마로 삼는다. 해룡은 혼인 전까지 어림군을 다스린다.","feel":"감사","who":["해룡","공주","천자"],"q":"동해용왕의 아들이 인간 세상에 내려갔으니"},{"h":"꿈과 족자","ev":"북흉노를 물리쳐 위왕이 된 해룡은 어사로 순찰하다 뇌양현에서 꿈에 백발노인에게 부모를 찾지 않는다고 꾸중을 듣는다. 깨어 관가에서 사또 벽의 족자가 자기 것과 같음을 본다.","feel":"번민","who":["해룡","사또"],"q":"내가 그대를 위해 부끄러워하노라"},{"h":"부모 상봉","ev":"사또는 전란 중 잃은 아들을 그리워해 족자를 걸었다 하고, 해룡의 사연을 들은 뒤 아들 등의 사마귀를 말해 부자임을 확인한다. 부인과 함께 셋이 통곡한다.","feel":"사무침","who":["해룡","사또"],"q":"내 아이는 등에 일곱 개의 사마귀가"},{"h":"결말","ev":"금령이 신선의 도움으로 껍질을 벗고 아름다운 여인이 되어 해룡과 혼인한다. 둘은 백년해로하다가 한날한시에 승천한다.","feel":"행복","who":["금령","해룡"]}],"key":"용왕의 딸과 아들이 환생한 금령과 해룡이 고난을 이기고 전생의 인연과 부모를 되찾는 이야기","pt":["꿈(㉡)이 어사의 행동을 촉발해 사또와의 부자 관계가 밝혀짐(2번)","ⓓ는 부모를 찾지 않는 해룡을 꾸짖는 말이지 미안함의 표현이 아님(3번)","금령은 여성 영웅이나 해룡을 돕는 조력자에 그침. 껍질을 벗기 전에만 활약(4번, 보기)"],"src":"해설 p.50~52 · 본책 p.142~145","g":"고전산문","s":"수특 고전산문 7강","th":"금령(금방울)의 영웅적 활약과 전생의 인연"},"w062":{"t":"적벽가","a":"작자 미상","who":[["조조","백만 대군의 승상. 교만하게 호기를 부린다"],["화병","선봉장 합의 화병. 두고 온 까치를 설움으로 내놓는다"],["군사들","고향을 그리며 조조를 원망하는 병졸"],["유복","양주자사. 노래가 불길하다 아뢰다 창에 찔린다"],["풍채 좋은 군사","공을 세워 돌아가자며 호기를 부르는 병졸"]],"steps":[{"h":"큰 잔치","ev":"건안 12년 11월 15일, 조조는 전선을 쇠사슬로 묶어 띄우고 큰 잔치를 연다. 장강을 바라보며 강남을 얻으면 이교녀를 동작대에 데려가겠다고 자랑한다.","feel":"교만","who":["조조"],"q":"태산을 흔들려는 개미와 같은가"},{"h":"불길한 노래","ev":"까마귀가 남쪽으로 울며 가자 조조는 노래를 지어 부른다. 양주자사 유복이 노래가 불길하다고 아뢰자 조조는 크게 화를 내며 창으로 유복을 찌른다.","feel":"분노","who":["조조","유복"],"q":"내 속의 흥을 네까짓 게 감히 깨느냐"},{"h":"화병의 설움","ev":"중략 뒤 전쟁터로 끌려온 군사들이 신세를 한탄하며 조조를 원망한다. 벙거지 끈에 매달린 작은 화병이 두고 온 새끼 까치가 서럽다고 하소연하자 좌중이 웃는다.","feel":"서러움","who":["화병","군사들"],"q":"벙거지가 울고 있네"},{"h":"군사의 한탄","ev":"한 군사는 군사가 교만하면 패하는데 승상은 아랫사람을 생각지 않아 싸움에 질 것이라 한다. 시체가 까마귀와 솔개에 뜯겨도 뼈를 묻어 줄 사람이 없을 거라며 서러워한다.","feel":"비통함","who":["군사들"],"q":"군사가 교만하면 패한다는 말"},{"h":"대장부의 호기","ev":"풍채 좋은 군사는 전쟁터에서 고향 생각이 소용없다며 적장의 머리를 베어 깃발에 달고 노래하며 돌아가는 것이 대장부의 바람이라 말한다. 다른 군사는 상대의 앞날을 모르겠다고 한다.","feel":"호기","who":["풍채 좋은 군사","군사들"],"q":"그게 대장부 바라는 바"},{"h":"적벽대전","ev":"수록 부분 뒤 조조의 선봉이 제갈공명의 지략에 패하고, 공명이 손권·주유를 설득해 벌인 적벽대전에서 조조는 대패한다. 화용도에서 관우에게 목숨을 구걸하고 겨우 돌아간다.","feel":"비굴함","who":["조조"]}],"key":"적벽대전을 재구성해 조조를 희화화하고 끌려온 군사들의 설움을 드러낸 판소리계 소설","pt":["㉢ ‘이게 어인 변고인가’는 물음으로 개입하는 서술자의 말(2번)","해학(화병의 까치)과 비장(군사의 한탄)이 교차. 화병 사연을 전쟁 비판으로 읽으면 오답(4번)","조조의 면모: 표면은 대의, 실제는 개인 이익(이교녀)과 부하를 해치는 비인간성(보기)"],"src":"해설 p.52~54 · 본책 p.146~149","g":"고전산문","s":"수특 고전산문 8강","th":"전쟁 희생자(군사)의 설움과 기득권 풍자"},"w063":{"t":"옹고집전","a":"작자 미상","who":[["실옹가","진짜 옹고집. 쫓겨나 고생하다 개과천선한다"],["허옹가","도사가 허수아비로 만든 가짜 옹고집"],["도사","취암사의 도사. 부적으로 옹고집을 깨우친다"],["사또","송사에서 허옹가를 진짜로 판정한다"],["아내","허옹가를 남편으로 알고 자식을 낳아 기른다"]],"steps":[{"h":"앞부분","ev":"옹당촌의 옹고집은 구걸하는 이를 쫓고 병든 노모를 방치하는 수전노이다. 보다 못한 도사가 허수아비로 가짜 옹고집을 만들어 보내 두 사람이 사또 앞에 서게 된다.","feel":"고집","who":["실옹가","허옹가","도사"]},{"h":"송사의 판결","ev":"사또는 허옹가를 참 옹좌수로 판결하고 실옹가를 곤장으로 다스려 내쫓는다. 실옹가는 곤장 밑에 죽을까 두려워 ‘옹가 아니오’ 하고 쫓겨나 통곡한다.","feel":"두려움","who":["사또","실옹가","허옹가"],"q":"예, 옹가 아니오. 처분대로 하옵소서"},{"h":"허옹가의 득의","ev":"송사에 이긴 허옹가는 의기양양하게 조롱하며 돌아와 실옹가의 아내와 지내고, 열 달 뒤 아내는 허수아비 같은 자식들을 무수히 낳는다.","feel":"득의양양","who":["허옹가","아내"],"q":"하마터면 우리 고운 마누라 빼앗길 뻔하였다"},{"h":"산중의 후회","ev":"세간과 처자를 잃고 곤장까지 맞은 실옹가는 산에 들어가 우는데, 백발 도사가 나타나 늙은 모친을 구박하고 불도를 능멸한 죄를 꾸짖으며 부적을 주고 개과천선하라 이른다.","feel":"뉘우침","who":["실옹가","도사"],"q":"돌아가 개과천선하라"},{"h":"허수아비로","ev":"부적을 몸에 붙이고 집에 돌아가자 허옹가는 짚 한 묶음으로 변하고 그 자식들도 허수아비가 되어 사람들이 박장대소한다. 아내는 어이없어 말이 없고 부끄러워한다.","feel":"당당함","who":["실옹가","허옹가","아내"],"q":"이제도 네가 옹가라 장담할까"},{"h":"개과천선","ev":"옹좌수는 도승의 술법에 탄복하고 어머니께 효도하며 불도를 공경하는 사람이 되어 그 어짊을 칭찬받는다.","feel":"뉘우침","who":["실옹가"],"q":"모친께 효성하고 불도를 공경하여"}],"key":"가짜 옹고집에게 쫓겨난 옹고집이 도사의 가르침으로 뉘우치고 효와 불도를 되찾는 해학적 풍자","pt":["허수아비는 아내가 허옹가를 남편으로 오인한 결과로 낳아 기른 대상(3번)","곤장이 무서워 ‘옹가 아니오’ 한 것은 잘못을 인정한 것이 아님(4번)","신이한 존재의 개입으로 개과천선, 공동체로 포용하려는 당대 의식(보기)"],"src":"해설 p.54~55 · 본책 p.150~153","g":"고전산문","s":"수특 고전산문 9강","th":"개과천선을 통한 인간의 참된 도리"},"w064":{"t":"옥단춘전","a":"작자 미상","who":[["이혈룡","가난해진 양반. 암행어사가 되어 돌아온다"],["김진희","평양감사. 옛 친구를 배신하고 죽이려 한다"],["옥단춘","기생. 신의로 이혈룡을 구하고 곁을 지킨다"]],"steps":[{"h":"우정과 배신","ev":"이혈룡과 김진희는 출세하면 서로 돕자고 맹세한 친구였다. 평양감사가 된 김진희는 찾아온 가난한 이혈룡을 괄시하고 물에 던지라 명하나 기생 옥단춘이 그를 구해 연분을 맺는다.","feel":"배신감","who":["이혈룡","김진희","옥단춘"]},{"h":"신분 숨김","ev":"옥단춘의 도움으로 급제해 암행어사가 된 이혈룡은 신분을 숨기고 돌아와 빚 때문에 과거를 못 보고 도적에게 털렸다고 둘러댄다. 옥단춘은 운수라며 위로한다.","feel":"능청","who":["이혈룡","옥단춘"],"q":"과거를 못 보신 것은 역시 운수입니다"},{"h":"연광정 소동","ev":"옥단춘이 감사의 잔치에 불려 나간 사이 이혈룡이 남루한 차림으로 연광정에 오르려다 쫓겨난다. 김진희의 이름을 부르며 호통치자 크게 노한 감사가 그를 잡아들이게 한다.","feel":"분노","who":["이혈룡","김진희"],"q":"네 이놈 김진희야, 나 이혈룡을 모른단 말이냐"},{"h":"대동강의 북소리","ev":"두 사람을 물에 던지라는 북이 세 번 울리고 사공들이 재촉한다. 이혈룡은 신의를 저버린 친구를 탄식하고, 옥단춘은 자기만 자결할 테니 낭군을 살려 달라고 애원한다.","feel":"절박함","who":["옥단춘","이혈룡"],"q":"결의형제 쓸데없다"},{"h":"어사출두","ev":"옥단춘이 눈을 감고 뛰어들려는 순간 이혈룡이 손을 잡고 죽어도 같이 죽고 살아도 같이 살자 하며 역졸을 부르자, 역졸들이 마패를 치켜들고 암행어사 출두를 외친다.","feel":"당당함","who":["이혈룡","옥단춘"],"q":"죽어도 같이 죽고 살아도 같이 살자"},{"h":"결말","ev":"이혈룡은 김진희의 죄를 물어 벌을 주고 우의정에 오르며, 옥단춘은 정덕부인에 봉해져 함께 부귀를 누린다.","feel":"통쾌함","who":["이혈룡","김진희","옥단춘"]}],"key":"배신한 친구 김진희와 신의를 지킨 기생 옥단춘이 대비되고 암행어사 이혈룡이 징치하는 이야기","pt":["북소리 세 번은 감사의 명에 따라 인물을 재촉하며 긴장감을 높임(2번)","㉤은 호통이지 서운함을 우회해 드러낸 말이 아님(1번)","「춘향전」 장면과 비교: 옥단춘은 낭군이 곁에 있음을 알고 있음(3번)"],"src":"해설 p.55~57 · 본책 p.154~158","g":"고전산문","s":"수특 고전산문 10강","th":"신분을 초월한 사랑과 신의"},"w065":{"t":"김순부전","a":"이광정","who":[["김순부","안동의 선비. 총명하고 효성스럽다"],["정양빈","진수. 공을 세우려 김씨 집안을 무고한다"],["종인","향권을 노려 순부를 거듭 고발하는 인물"],["지부","안동부의 관리. 순부를 회유한다"]],"steps":[{"h":"발단","ev":"진수 정양빈은 반란군에 빌붙었던 과오를 덮고 공을 세우려 한다. 한 종인이 김씨 집안의 군청 모임을 반란 모의로 몰아 처음 모이자고 한 사람을 고발하게 하라고 부추긴다.","feel":"야심","who":["정양빈","종인"]},{"h":"순부의 변론","ev":"집안의 간청으로 관청에 나선 순부는 해마다 열던 친족 화목 모임이고 공개된 마당에서 모반을 꾸밀 리 없다고 조리 있게 반박해 풀려난다.","feel":"당당함","who":["김순부","정양빈"],"q":"수령 앞에서 풍악을 울리며 비밀스런 일을 모의하겠소"},{"h":"거듭된 모함","ev":"며칠 뒤 종인이 순부를 김상헌 사당 철거 사건의 주모자라며 다시 고발하고, 진수는 순부를 잡아들여 상사에 보고한다. 서인 세력은 안동 사람들을 원수로 여기던 때였다.","feel":"불안","who":["종인","정양빈","김순부"]},{"h":"옥에 갇힘","ev":"경신년 정월 초하루 불길한 점괘를 본 순부는 병든 아들에게 곤액을 예고한다. 안동부에서 진상과 다른 조서에 서명하기를 거부하고 조서를 직접 불러 쓰게 한다.","feel":"침착함","who":["김순부","지부"]},{"h":"회유 거절","ev":"지부가 김씨 문장과 유사를 대신 고발하면 사면하겠다 하자 순부는 집안 사람을 곤경에 빠뜨릴 수 없다고 거절한다. 살 방도를 찾으라는 유인도 물리치고 감옥에 갇힌다.","feel":"의연함","who":["김순부","지부"],"q":"살아날 방도를 찾아야 한다는 것이 슬프오"},{"h":"죽음","ev":"풀려난 순부는 집에서 몸조리했으나 온 집안이 천연두에 걸려 2월 28일 48세로 세상을 떠나고 아내 홍씨도 뒤따라 죽는다. 2남 2녀는 모두 온전하다.","feel":"비운","who":["김순부"]},{"h":"평결","ev":"작가는 점으로 세상일을 다 알 수는 없다는 정첨윤의 말을 빌려 재앙을 피하지 못한 순부를 논평한다. 순부의 총명과 귀양지 명승을 다니며 남긴 문장을 칭찬한다.","feel":"안타까움","who":["김순부"],"q":"순부가 재앙을 만나지 않았다면"}],"key":"당파 싸움의 무고에 맞서면서도 가족을 지키려다 천연두로 생을 마친 김순부를 기린 전","pt":["[A]·[B]의 공통 특성: 고난을 알면서도 가족·가문을 지키는 것을 우선함(2번)","전의 구조: 행적 뒤 평결([C])에서 작가가 인용·논평·안타까움·예찬(3번)","사면 조건은 문장·유사를 대신 고발하는 것. ‘남인이 아님을 밝힘’은 오답(4번)"],"src":"해설 p.57~58 · 본책 p.159~163","g":"고전산문","s":"수특 고전산문 11강","th":"당파 싸움 속 김순부의 현실 대응과 비극적 삶"},"w066":{"t":"소설가 구보 씨의 일일","a":"박태원","who":[["구보","소설가, 목적 없이 경성을 걷는 무기력한 지식인"],["어머니","아들의 앞날을 걱정해 잔소리하는 구보의 어머니"],["중학 동창","전당포집 둘째 아들, 구보를 찻집으로 이끄는 옛 동창"],["시인 겸 기자","다방에서 구보와 대화를 나누는 친구"]],"steps":[{"h":"전차 안·수록","ev":"걱정 섞인 어머니의 잔소리에 쫓기듯 집을 나온 구보는 동대문행 전차에서 맞선 보았던 여인을 모른 척하고, 갈 곳 없이 전차에 실려 고독을 두려워한다.","feel":"막막함","who":["구보","어머니"],"q":"어디서든 섣불리 내릴 수 없다"},{"h":"다방","ev":"다방에 앉아 차를 마시던 구보는 여행 경비만 마련되면 행복해질 수 있겠다는 생각에 잠긴다.","feel":"소망","who":["구보"]},{"h":"경성역·수록","ev":"고독을 군중 속에 묻으려 경성역 대합실에 가지만, 서로 믿지 않는 사람들과 병자, 무직자를 보며 연민과 우울을 느끼고 자리를 뜬다.","feel":"우울","who":["구보"]},{"h":"찻집·수록","ev":"대합실에서 만난 열등생 출신 중학 동창을 따라 찻집에 간 구보는 그의 교양 없는 이야기에 건성으로 맞장구를 치며 불쾌해한다.","feel":"불쾌","who":["구보","중학 동창"]},{"h":"벗과의 대화","ev":"다방에서 시인 겸 기자인 벗과 이야기를 나눈 뒤, 구보는 동경 시절의 옛사랑을 떠올리고 오랜 벗의 편지를 기다리는 마음이 된다.","feel":"그리움","who":["구보","시인 겸 기자"]},{"h":"귀가","ev":"종로의 술집에서 벗과 술잔을 기울인 구보는 앞으로는 생활도 꾸리고 글도 쓰겠다고 마음먹으며 집으로 돌아온다.","feel":"다짐","who":["구보"]}],"key":"목적 없이 경성을 하루 종일 배회하는 구보의 고독과 우울을 따라가는 모더니즘 소설이다.","pt":["서술 특징: 쉼표의 잦은 사용, 추정 표현의 반복, 소제목 같은 어구로 의식·장면 전환을 드러냄(1번)","경성역: 기대를 배반하고 소통 없이 불신이 가득한 곳 — 옛 친구 애인에게 호감을 느끼는 곳은 아님(3번 ④)","〈보기〉 감상: 세속적 행복 탐색과 속물 근성에 대한 염증 — 광산 구경 생각은 창작 때문(4번)"],"src":"해설 p.58~59 · 본책 p.164~168 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 1강","th":"1930년대 지식인의 무기력한 내면과 경성 풍경"},"w067":{"t":"인간 문제","a":"강경애","who":[["첫째","덕호에게 맞서다 마을을 떠나 노동자가 되는 청년"],["선비","덕호에게 겁탈당한 뒤 마을을 떠나는 몸종"],["덕호","인자한 척하며 농민을 착취하는 용연마을 지주"],["개똥이","타작날 빚으로 벼를 빼앗기자 울분을 터뜨리는 농민"],["풍헌 영감","벼를 베기도 전에 입도차압을 당한 첫째의 회상 속 농민"]],"steps":[{"h":"배경","ev":"용연마을에서 첫째는 어머니가 몸을 팔아 버는 돈으로 끼니를 잇는 가난 속에 자라고, 선비는 아버지가 덕호의 매질에 죽고 어머니마저 잃어 덕호네 몸종이 된다.","feel":"서러움","who":["첫째","선비","덕호"]},{"h":"전개·수록","ev":"개똥네 타작이 끝나 열다섯 섬 닷 말이 나자 기뻐하던 농민들에게, 덕호는 빚과 이자, 비룟값을 그 자리에서 벼로 셈해 일곱 섬을 가져가게 한다.","feel":"허탈","who":["덕호","개똥이"]},{"h":"전개·수록","ev":"지친 농민들이 볏짚 위에 주저앉자 첫째는 벼를 베기도 전에 입도차압을 당해 미친 듯 뛰어다니던 풍헌 영감을 떠올리며 부당함을 곱씹는다.","feel":"문제의식","who":["첫째","풍헌 영감"],"q":"이런 법이 있는가, 벼를 베기도 전에"},{"h":"위기·수록","ev":"억울함을 참지 못한 개똥이가 소리를 지르자 첫째와 농민들이 실린 볏섬을 끌어내리지만, 곧 순사들이 들이닥쳐 이들을 주재소로 끌고 간다.","feel":"분노","who":["개똥이","첫째"]},{"h":"절정·수록","ev":"선처를 빌러 온 개똥어머니에게 덕호는 후한 어른 행세를 하지만, 속으로는 눈 오기 전 마당질을 끝내려 어쩔 수 없이 풀어 주는 것이라 셈한다.","feel":"위선","who":["덕호"]},{"h":"후반부","ev":"덕호에게 겁탈당한 선비가 먼저 마을을 떠나 인천 방적공장에 들어가고, 선비를 마음에 둔 첫째도 덕호의 등쌀을 견디다 못해 인천 부두 노동자가 되어 파업을 이끈다.","feel":"저항","who":["선비","첫째","덕호"]},{"h":"결말","ev":"소꿉친구 간난이의 권유로 공장주에 맞서 싸우던 선비는 폐결핵이 깊어져 숨지고, 그 주검을 마주한 첫째는 자신이 풀어야 할 인간 문제가 있음을 깨닫는다.","feel":"각성","who":["선비","첫째"]}],"key":"지주 덕호의 착취 속에서 첫째가 농촌을 떠나 노동자로 서며 계급 의식에 눈뜨는 과정을 그린다.","pt":["인물의 각성: 개똥이가 당하는 일과 풍헌 영감의 입도차압 회상을 이어 첫째가 부당함을 자각","덕호의 겉말(후한 어른)과 속셈(마당질을 끝내려 석방)을 맞세워 위선을 폭로(〈보기〉, 4번)","서술: 인물의 내면을 서술해 타작날 덕호와 농민의 갈등을 보여 줌(1번 ④)"],"src":"해설 p.60~61 · 본책 p.169~172 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 2강","th":"1930년대 농민·노동자의 참혹한 현실과 계급 의식의 각성"},"w068":{"t":"치숙","a":"채만식","who":[["나","일본인 상점 점원, 일제에 순응해 출세하려는 조카"],["아저씨","사회주의 운동 뒤 폐병으로 누운 오촌 고모부"],["아주머니","아저씨를 헌신적으로 돌보는 아내"]],"steps":[{"h":"발단","ev":"‘나’는 사회주의 운동으로 옥살이를 하고 나와 폐병으로 누운 오촌 고모부의 처지를 못마땅해하고, 그를 정성껏 간호하는 아주머니도 답답하게 본다.","feel":"답답함","who":["나","아저씨","아주머니"]},{"h":"전개","ev":"일본인 가게에서 일하는 ‘나’는 주인에게 인정받아 독립한 뒤 일본에서 살겠다는 꿈을 품고, 아저씨는 그런 ‘나’를 한심하게 보며 꾸짖는다.","feel":"야심","who":["나","아저씨"]},{"h":"아첨 논쟁·수록","ev":"아저씨가 일본 여자와 결혼해 성명까지 바꾸려는 것은 주인과 이웃의 비위를 맞추는 아첨이라 하자, ‘나’는 주인의 신용을 받아야 한다며 맞선다.","feel":"자신만만","who":["나","아저씨"]},{"h":"세상물정·수록","ev":"‘나’가 나폴레옹과 칠전팔기를 들어 성공을 장담하자, 아저씨는 나폴레옹도 세상물정을 거스르다 실패했고 일어서지 못한 사람도 많다고 일깨운다.","feel":"반발","who":["나","아저씨"]},{"h":"은공 논쟁·수록","ev":"‘나’가 아주머니의 은공을 갚으라고 몰아세우자 아저씨는 ‘바빠서’라고 받아넘기고, ‘나’는 시치미 떼고 누워 바쁘다는 소리라며 비꼰다.","feel":"냉소","who":["나","아저씨","아주머니"],"q":"시치미 뚝 따고 누워서 바쁘다는군요!"},{"h":"결말·수록","ev":"‘나’는 아저씨를 남에게 폐만 끼치고 세상에 해독을 끼칠 사람이라며, 하루바삐 죽어야 마땅하다고 여긴다.","feel":"경멸","who":["나","아저씨"]}],"key":"신뢰할 수 없는 ‘나’의 입을 빌려 아저씨와 ‘나’ 모두를 풍자하는 이중 풍자 소설이다.","pt":["풍자의 이중성: 비판받는 아저씨(무능·무책임)와 비판하는 ‘나’(일제 순응) 모두 문제적 인간","[A] 아저씨의 질문과 [B] ‘나’의 질문은 모두 상대 인식의 문제점을 드러내는 데 쓰임(2번 ②)","나폴레옹: 아저씨는 ‘나’가 일면만 보고 세상물정을 거스르려 한다고 비판(3번 ②)"],"src":"해설 p.61~62 · 본책 p.173~176 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 3강","th":"식민지 현실의 문제적 인간들에 대한 풍자"},"w069":{"t":"나룻배 이야기","a":"하근찬","who":[["삼바우","마을과 외지를 잇는 나룻배 사공"],["양생원","아들 천달을 전쟁터에서 잃는 마을 노인"],["순녀","천달의 아내, 아들 대열을 업고 우는 며느리"],["두칠","전쟁터에서 눈을 잃고 돌아온 마을 청년"],["갑분이","두칠을 좋아한 삼바우의 딸"]],"steps":[{"h":"발단","ev":"전쟁으로 징병이 시작되자 뱃사공 삼바우는 아들 용팔을 비롯해 천달, 두칠 같은 마을 청년들을 자신의 배로 강 건너 전쟁터로 실어 보낸다.","feel":"자부심·괴로움","who":["삼바우","두칠"]},{"h":"전개","ev":"눈을 잃고 도깨비처럼 변해 돌아온 두칠을 보고, 그를 좋아했던 삼바우의 딸 갑분이는 무서우면서도 서글픈 마음이 된다.","feel":"서러움","who":["두칠","갑분이"]},{"h":"위기·수록","ev":"천달의 전사 통지서가 오자 양생원네에서 곡성이 터지고, 삼바우는 읍내에 다녀온 양생원이 흰 보에 싼 상자를 안고 돌아오자 받아 들려다 거절당한다.","feel":"안타까움","who":["양생원","순녀","삼바우"]},{"h":"위기·수록","ev":"총을 멘 사람과 양복쟁이가 다가오자 삼바우는 또 누굴 데려가려느냐며 분노하지만, 얼굴이 또렷해질수록 다리가 후들거리고 어금니가 떨린다.","feel":"분노→두려움","who":["삼바우"],"q":"안 되지, 안 돼!"},{"h":"절정·수록","ev":"그때 ‘옳지!’ 하는 생각이 스친 삼바우는 닻줄을 풀고 힘껏 노를 저어, 두 사람을 태우지 않은 채 떠나 강 길을 끊어 버린다.","feel":"통쾌함","who":["삼바우"],"q":"이만저만 통쾌하지가 않았다."},{"h":"결말·수록","ev":"통쾌함도 잠시, 삼바우는 차츰 술이 깨는 듯 오스스 몸이 떨려 오며 불안에 잠긴다.","feel":"불안","who":["삼바우"]}],"key":"삼바우가 청년들을 끌고 가려는 이들을 태우지 않고 강 길을 끊는, 전쟁에 맞선 소박한 저항이다.","pt":["6모에서 물음: 묘사와 내면의 목소리(속말)가 이어진 서술의 효과","6모에서 물음: 분노 → 두려움 → 통쾌함 → 불안으로 바뀌는 심리","6모에서 물음: 배를 몰아 ‘강 길을 끊어 버’린 행동(징집에 맞선 저항)"],"src":"해설 p.63~64 · 본책 p.177~180 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 4강","th":"전쟁의 폭력성과 참혹성 폭로"},"w070":{"t":"불신 시대","a":"박경리","who":[["진영","전쟁으로 남편과 아들을 잃고 사회를 불신하는 여인"],["문수","진영의 외아들, 의사의 무관심 속에 죽는다"],["어머니","추석에 절을 찾는 진영의 어머니"],["갈월동 아주머니","진영의 돈을 쓰고 사기당한 사연을 털어놓는 이"]],"steps":[{"h":"발단","ev":"6·25로 남편을 잃은 진영은 외아들 문수까지 잃는데, 의사가 엑스레이 한 장 찍지 않고 약도 주지 않은 무관심이 원인이어서 세상을 믿지 못하게 된다.","feel":"절망","who":["진영","문수"]},{"h":"전개","ev":"아들을 잃은 허전함을 종교로 달래려 하나 타락한 종교계에 분노만 커지고, 폐결핵 치료를 위해 찾은 병원은 하나같이 부실하며 거리엔 가짜 주사약이 떠돈다.","feel":"분노","who":["진영"]},{"h":"전개·수록","ev":"한여름 내내 앓으며 육신과 정신이 해체되는 공포를 겪고, 병원이 빈 약병을 파는 모습을 보고는 의사까지 불신해 발길을 끊는다.","feel":"공포","who":["진영"]},{"h":"위기·수록","ev":"추석날 문수의 위패를 모신 절에 가는 어머니를 말리지 않던 진영은 산에 올라 빈민굴을 보며, 슬퍼하는 자신이 오히려 사치스러운 존재임을 깨닫는다.","feel":"부끄러움","who":["진영","어머니"]},{"h":"위기·수록","ev":"돈을 떼어먹은 갈월동 아주머니마저 대학생에게 사기당한 사정을 호소하자, 진영은 모두가 믿을 수 없는 세상에 지쳐 끝내 분노를 터뜨린다.","feel":"환멸","who":["진영","갈월동 아주머니"]},{"h":"결말·수록","ev":"진영은 절에 맡겼던 문수의 사진과 위패를 찾아와 뒷산에서 불사르고, 눈물 속에서도 자신에게 항거할 생명이 남아 있음을 되새기며 살아갈 의지를 다진다.","feel":"결의","who":["진영","문수"],"q":"내게는 아직 생명이 남아 있었다"}],"key":"전쟁 뒤 타락한 병원·종교·사람들에게 분노하던 진영이 아들의 위패를 태우며 항거의 의지를 다진다.","pt":["고발 대상: 전후 사회의 타락 — 가짜 주사약·빈 약병을 파는 병원, 타락한 종교계, 사기","서술: [A]는 인물 의식을 스쳐 가는 장면의 나열, [B]는 관찰한 현실로 내면 심리를 부각(2번 ⑤)","㉠ ‘항거할 수 있는 생명’은 진영이 앞으로의 삶을 살아갈 원동력(3번 ⑤)"],"src":"해설 p.64~65 · 본책 p.181~184 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 5강","th":"전후 부조리한 사회에 대한 분노와 고발"},"w071":{"t":"관부 연락선","a":"이병주","who":[["유태림","C시 유지의 자제, 일본 유학 뒤 학병이 된 수재"],["나(이 선생)","유태림을 기억하며 그의 수기를 받아 보는 서술자"],["안달영","병영에서 공산주의 교양회를 열려는 나이 든 인물"],["허봉도","태림의 고향 친구, 안달영 편에서 창고를 부탁한다"]],"steps":[{"h":"발단","ev":"해방 뒤 ‘나’는 일본인 대학 동문 E와 편지를 주고받으며, 행방불명된 유태림의 소식을 알려 주는 대가로 그가 쓴 수기 ‘관부연락선’을 받아 보기로 한다.","feel":"회고","who":["나(이 선생)","유태림"]},{"h":"전개","ev":"C시 유지의 아들로 총명했던 유태림은 항일운동에 연루되어 고교를 중퇴하고 일본 대학 문학과로 건너가, 일본 학우들과 문학·철학을 논하며 조국의 앞날을 고민한다.","feel":"번민","who":["유태림"]},{"h":"전개","ev":"유태림은 학병으로 징집되어 중국 전선으로 끌려가고, 일본군 병영에서 부대의 소모품 창고를 관리하는 임무를 맡는다.","feel":"고뇌","who":["유태림"]},{"h":"위기·수록","ev":"고향 친구 허봉도가 태림을 방공호로 끌어들여 안달영의 교양회에 창고를 빌려 달라 하자, 태림은 ‘정신이 있느냐’고 쏘아붙이고 시간을 달라며 헤어진다.","feel":"난처함","who":["허봉도","유태림"]},{"h":"절정·수록","ev":"안달영이 애국심과 정의감을 내세워 협조를 압박하자, 태림은 독립운동은 독립만을 목적으로 해야 하며 정체는 독립 뒤 다수가 정할 일이라고 맞선다.","feel":"흥분","who":["유태림","안달영"],"q":"독립운동은 독립에만 목적을 두는 운동이라야"},{"h":"절정·수록","ev":"태림은 창고를 빌려줄 수 없고 모임에도 반대한다고 선언하며 부대 친구들의 생명을 앞세우지만, 안달영은 그를 비겁하다고 몰아세운다.","feel":"단호","who":["유태림","안달영"]},{"h":"결말","ev":"중국에서 해방을 맞아 돌아온 태림은 이념으로 갈라진 고향에서 교사로 일하며 학생들을 보호하려 하지만, 빨치산에게 납치되어 종적을 감춘다.","feel":"비애","who":["유태림"]}],"key":"‘나’의 기억과 유태림의 수기를 교차해 해방 전후 지식인 청년의 고뇌와 비극을 조명한다.","pt":["서술 방식: ‘나’의 기억과 유태림의 수기 교차 — 당시 시점과 1960년대 회고 시점의 결합","[A]는 서술자가 인물 간 갈등이 생긴 배경을 제시(2번 ②), 태림은 다른 나라 사례를 열거해 반박(3번 ④)","〈보기〉 감상: 태림의 반대 이유(부대 친구들의 생명)를 이념 혼란의 결과로 읽은 ⑤가 오답(4번)"],"src":"해설 p.66~67 · 본책 p.185~188 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 6강","th":"해방 전후 지식인의 고뇌와 비극"},"w072":{"t":"세상에서 제일 무거운 틀니","a":"박완서","who":[["나","분단의 압박을 안고 사는 서술자, 틀니 통증을 겪는다"],["어머니","‘나’와 함께 간첩 남파 소식을 두려워하는 노모"],["설희엄마","장애 있는 딸과 미국으로 떠나는 이웃, ‘나’의 선망 대상"],["기관원","오빠의 남파를 알리며 자수 권유를 종용하는 사람"],["월부 책장수","‘나’가 오빠로 착각하는 방문객"]],"steps":[{"h":"발단","ev":"이웃집 설희엄마는 살림이 펴지면 지체장애가 있는 딸 설희를 미국에서 수술시키겠다는 바람을 품고, ‘나’는 6·25 때 의용군으로 나간 오빠가 소식이 없어 늘 막연히 불안하다.","feel":"불안","who":["설희엄마","나"]},{"h":"전개·수록","ev":"정보기관에 끌려간 ‘나’는 집안 사정을 훤히 아는 기관원 앞에서 무력해져, 오빠가 간첩으로 내려오면 자수시키겠다며 서툴게 아양을 떤다.","feel":"무력감","who":["나","기관원"]},{"h":"전개·수록","ev":"그 뒤로 대문 소리에 가슴이 내려앉는 날이 이어지고, 어머니와 ‘나’는 오빠가 넘어오다 차라리 사살되기를 바랄 만큼 잔인해진다.","feel":"두려움","who":["나","어머니"]},{"h":"위기·수록","ev":"설희네가 미국으로 떠난 날 ‘나’는 천근 같은 틀니에 턱뼈가 눌려 발광 직전의 통증을 겪고, 집에 와 틀니를 빼서야 공중에 뜬 듯 가벼워진다.","feel":"고통","who":["나","설희엄마"],"q":"틀니가 천근의 무게로 턱뼈를 눌러"},{"h":"절정·수록","ev":"문밖에서 낮게 오가는 남자의 목소리를 오빠가 온 것으로 착각한 ‘나’는 ‘그 남자’와 결판을 내려 일어서지만, 어머니는 끈덕진 월부 책장수였다고 말한다.","feel":"공포","who":["나","어머니","월부 책장수"]},{"h":"결말·수록","ev":"가시지 않는 통증 앞에서 ‘나’는 자신의 아픔이 틀니가 아니라 미국으로 떠난 설희엄마를 향한 부러움과 질투, 그리고 나라가 주는 제약의 무게에서 온 것임을 인정한다.","feel":"부끄러움","who":["나"],"q":"빼 버릴 틀니도 없는데"}],"key":"틀니의 무게와 통증으로 분단 현실이 소시민에게 가하는 정신적 압박과 자기기만을 드러낸다.","pt":["서술: [A]는 촉각적 묘사로 신체적 고통의 심화, [B]는 청각적 묘사로 심리적 불안 고조(1번 ⑤)","틀니와 대문 소리는 감시·공포의 상징, 오빠를 ‘그 남자’로 부르는 호칭 변화","틀니를 빼도 계속되는 아픔 = 설희엄마에 대한 선망·질투와 분단 현실의 중압감"],"src":"해설 p.67~68 · 본책 p.189~192 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 7강","th":"분단 현실이 소시민의 일상에 가하는 정신적 압박"},"w073":{"t":"해벽","a":"이문구","who":[["조등만","사포곶 어업조합장이던 어민, 마을을 지키려 애쓴다"],["요상","조의 작은아들, 아버지의 어살 일을 창피해한다"],["사포곶 어민들","간척으로 생계를 잃고 망연자실한 마을 사람들"]],"steps":[{"h":"발단","ev":"어업조합장 조등만은 학교를 세우고 출어세를 걷는 등 사포곶과 수산업을 일으키려 힘쓰지만, 산업화·도시화의 거센 흐름 앞에서 뜻이 꺾인다.","feel":"열의","who":["조등만"]},{"h":"전개·수록","ev":"숭산 마루를 깎아 미군부대가 들어서자 주민들은 덕 볼 궁리를 하는 이와 불안해하는 이로 갈리고, 조는 밤마다 산꼭대기 불빛에 소름이 끼쳐 잠을 이루지 못한다.","feel":"불안","who":["조등만","사포곶 어민들"]},{"h":"위기","ev":"미군의 횡포로 마을이 어지러워지고, 변한 세태에 편승해 이익을 챙기려는 무리에 밀려 조는 조합장 자리를 내놓은 데다 자기 배까지 바다에서 잃는다.","feel":"좌절","who":["조등만"]},{"h":"위기·수록","ev":"간척사업으로 사포곶이 폐항이 되어 어민들이 망연자실하자, 조는 정부 덕을 본 적이 있느냐 되물으며 우리 힘으로 세월을 맞자고 설득한다.","feel":"의지","who":["조등만","사포곶 어민들"],"q":"우리는 바다만 믿고 살아왔던 것"},{"h":"결말·수록","ev":"조는 십여 리 밖 개펄에 어살을 매기 시작하고, 청승맞아 못 보겠다는 작은아들 요상의 투덜거림에도 못 들은 척하며 조합장 같은 허울을 이미 떨쳤다고 여긴다.","feel":"의연함","who":["조등만","요상"]}],"key":"산업화로 개펄과 어장을 잃은 어촌에서, 조가 허울을 버리고 어살을 매며 다시 일어서려 한다.","pt":["[A] 서술: 서술 주체가 인식 주체(조)의 관점에서 그의 생각과 심리를 서술(1번 ②)","ⓐ 봉홧불과 ⓑ 적신호등은 모두 조에게 불길함을 떠올리게 하는 소재(3번 ①)","공동체 해체의 양상: 변화는 기대와 불안을 함께 줌 — 조가 변화를 기대했다는 감상은 오답(4번 ③)"],"src":"해설 p.69~70 · 본책 p.193~196 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 8강","th":"산업화·도시화로 몰락하는 어촌 공동체"},"w074":{"t":"미망","a":"김원일","who":[["나","서울에서 할머니와 어머니를 모시는 큰아들, 서술자"],["어머니","남편 일로 고초를 겪으며 두 아들을 홀로 키운 사람"],["할머니","아들을 끝내 기다리다 숨을 거두는 시어머니"],["고모","할머니를 모셨던 딸, 임종 앞에서 넋두리를 쏟는다"],["아버지","좌익 운동을 하다 6·25 때 종적을 감춘 사람"]],"steps":[{"h":"발단","ev":"서울에서 할머니와 어머니를 한집에 모신 ‘나’는 지난 다섯 달 동안 여섯 차례 부딪친 고부 사이를 아내와 함께 말려 보지만 번번이 소용이 없다.","feel":"곤혹","who":["나","어머니","할머니"]},{"h":"전개·수록","ev":"해방 뒤 아버지가 좌익 운동에 나서자 순경들이 어머니를 지서로 끌고 가 매질하고, 어머니는 어린 ‘나’를 안고 밤마다 공포에 떤다.","feel":"공포","who":["어머니","아버지","할머니"]},{"h":"전개·수록","ev":"아버지는 자수해 보도연맹에 들었으나 6·25가 터지자 말없이 사라지고, 할머니는 다시 고모네로 가 버려 어머니는 원망 속에 두 아들을 데리고 울산으로 떠난다.","feel":"원망","who":["아버지","할머니","어머니"]},{"h":"전개·수록","ev":"울산에서 걸식하며 두 아들을 키운 어머니는 피로 십자가를 그려 세상에 맞서기로 다지고, 그 이야기를 들은 ‘나’는 어머니를 뜨겁게 이해하게 된다.","feel":"독한 의지","who":["어머니","나"]},{"h":"절정·수록","ev":"고모의 넋두리 속에 할머니가 눈을 감고, 그 사이 나가 있던 어머니는 말과 달리 시어머니가 즐기던 갈치 두 마리를 사 들고 돌아온다.","feel":"원망과 연민","who":["고모","할머니","어머니","나"]},{"h":"결말·수록","ev":"그날 저녁 유품을 정리하던 고모가, 할머니가 사십 년 넘게 지니고 다닌 낡은 비단 꽃주머니 속에서 아버지 사진이 붙은 ‘보도연맹 가입증’을 찾아낸다.","feel":"못다 푼 한","who":["고모","할머니","아버지"],"q":"보도연맹 가입증"}],"key":"고부의 불화에 얽힌 이념 대립의 상처와, 가입증에 남은 풀리지 않은 한을 보여 준다.","pt":["직접 경험과 전해 들은 이야기의 구분: 젖먹이 때 일을 ‘나’의 경험처럼 쓴 대목은 들은 것(1번 ⓑ)","‘피로 십자가를 그린 손가락’은 시련을 주는 세상에 맞선 어머니의 독한 의지(3번 ④)","보도연맹 가입증 = 풀리지 않은 한과 역사의 상처, 순경의 연행은 좌익 활동 탓(4번 ①)"],"src":"해설 p.70~71 · 본책 p.197~201 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 9강","th":"현대사의 질곡과 가족의 상처"},"w075":{"t":"눈이 오면","a":"임철우","who":[["그(찬우)","실직한 가장, 치매 어머니와 충동적으로 귀향한다"],["어머니","치매 증세로 ‘우리 집’을 찾는 노모"],["동사무소 사내","이장 공고를 몰랐던 ‘그’를 의아하게 보는 남자"],["아버지","‘그’가 세 살 때 세상을 떠나 무덤마저 잃는다"]],"steps":[{"h":"발단","ev":"‘그’는 홀어머니를 모시며 가족의 생계를 짊어진 가장인데, 몇 달째 월급이 나오지 않는 회사에 사직서를 내고 나자 살길이 막막해진다.","feel":"막막함","who":["그(찬우)"]},{"h":"전개·수록","ev":"두 달째 ‘꼬두메’에 가자고 보채던 치매 어머니를 모시고 ‘그’는 충동적으로 밤기차에 올라, 병든 개처럼 도시를 헤매던 삶 속에 잊고 지낸 고향을 떠올린다.","feel":"그리움","who":["그(찬우)","어머니"],"q":"병든 개처럼"},{"h":"전개·수록","ev":"K시에 닿아 택시를 타지만 운전수도 꼬두메를 모르고, 잣고개 일대는 고층 아파트와 고급 주택으로 바뀌어 기억 속 풍경과 눈곱만큼도 닮지 않았다.","feel":"허탈","who":["그(찬우)"]},{"h":"위기·수록","ev":"어머니는 어린아이처럼 우리 집에 가자고 보채고, ‘그’는 옛 공동묘지 자리에 선 아파트를 보며 십 년 넘게 돌보지 못한 아버지 무덤을 떠올리고 후회한다.","feel":"죄책감","who":["그(찬우)","어머니","아버지"],"q":"어서 우리 집으로 가자니께"},{"h":"절정·수록","ev":"어머니를 다방에 앉혀 두고 동사무소를 찾은 ‘그’는 분묘 이장 공고도 못 봤느냐는 말에 부끄러워 얼굴이 달아올라 도망치듯 빠져나온다.","feel":"부끄러움","who":["그(찬우)","동사무소 사내"]},{"h":"결말","ev":"아버지의 무덤조차 찾을 길이 없어 넋이 나간 ‘그’가 이장 경위를 알아보는 동안, 다방에 두고 온 어머니는 어디론가 사라지고 만다.","feel":"망연자실","who":["그(찬우)","어머니"]}],"key":"치매 어머니와 떠난 귀향길에서 개발로 사라진 고향과 아버지 무덤을 마주하는 여로형 소설이다.","pt":["서술: [A]는 비유적 표현으로 인물의 처지를, [B]는 지시 표현으로 기억 속 공간을 제시(1번 ⑤)","귀향의 역설: 기억 속 고향과 개발로 사라진 현실의 충돌, 치매 어머니의 ‘우리 집’ 찾기","사라진 아버지 무덤 = 가족사의 소멸, 이장 공고를 몰라 부끄러워하는 ‘그’(4번 ②)"],"src":"해설 p.72~73 · 본책 p.202~206 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 10강","th":"산업화 속 잃어버린 고향"},"w076":{"t":"눈사람 속의 검은 항아리","a":"김소진","who":[["나","어른이 되어 옛일을 돌아보는 서술자이자 어린 주인공"],["엄마","잘못을 알고도 볼을 비틀며 핀잔하는 엄마"],["이웃 할머니","짠지 단지의 주인인 공동주택 이웃"],["창이 형","재개발 지역에서 ‘나’가 만나 술을 마시는 사람"]],"steps":[{"h":"발단","ev":"재개발로 곧 없어질 고향 산동네를 찾은 어른 ‘나’는, 겨울날 짠지 항아리를 깨뜨렸던 어린 시절을 되새긴다.","feel":"그리움","who":["나"]},{"h":"전개·수록","ev":"새벽에 변소에 다녀오던 어린 ‘나’는 눈 덮인 가마니 밑의 빠루를 밟아 쓰러뜨려 이웃 할머니의 짠지 단지를 깨뜨리고, 돌이킬 수 없는 일을 저질렀다고 느낀다.","feel":"당황","who":["나","이웃 할머니"]},{"h":"위기·수록","ev":"기절이라도 하면 모면하리라는 ‘맹렬한 위안’에 빠진 ‘나’는 깨진 단지를 눈사람 속에 숨기고, 탄로가 두려워 하루 종일 가출해 더러운 골목만 떠돈다.","feel":"불안","who":["나"],"q":"맹렬한 위안"},{"h":"절정·수록","ev":"해질녘 집에 돌아오니 누구도 아는 체하지 않고 눈사람과 단지는 치워져 있어, ‘나’는 세계가 나와 상관없이 돌아간다는 것을 깨닫고 소리 없이 운다.","feel":"혼돈","who":["나"]},{"h":"결말·수록","ev":"엄마가 젖은 손으로 볼을 야무지게 비틀며 핀잔하자 ‘나’는 얼얼함에 균형 감각을 되찾고 울음을 그치며, 가슴이 터지도록 달려 나가며 자란다.","feel":"깨달음","who":["나","엄마"]},{"h":"후일","ev":"현재로 돌아온 ‘나’는 재개발 지역에서 창이 형과 술잔을 나누고, 주민이 떠난 빈집에서 깨진 항아리 조각을 보며 자신을 키워 낸 산동네의 기억이 사라져 감을 곱씹는다.","feel":"쓸쓸함","who":["나","창이 형"]}],"key":"항아리를 깨뜨린 유년의 사건을 통해, 세상이 나를 중심으로 돌지 않음을 깨닫는 성장을 그린다.","pt":["서술: [A]는 음성 상징어로 앞일을 예측 못 한 과거 상황을 생동감 있게 묘사(1번 ⑤)","‘맹렬한 위안’은 기절이라도 하면 모면하리라는 마음 — 어른의 만족감이라는 이해는 오답(3번)","성장: 세계는 나와 상관없이 돌아가고 나는 중심이 아니라는 깨달음, 경험자아와 서술자아의 구분"],"src":"해설 p.73~74 · 본책 p.207~211 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 현대소설 11강","th":"유년의 기억과 성장의 의미"},"w077":{"t":"꼭두각시놀음","a":"작자 미상","who":[["표생원","해남 양반, 본처와 소실 사이에서 낭패를 겪는 영감"],["꼭두각시","환갑 넘은 본처, 세간을 나눠 달라 하다 밀려난다"],["박첨지","구장을 자처해 편파 판결을 내리고 홍동지를 천거"],["홍동지","벌거벗고 상여를 메러 와 감사에게 맞서는 조카"],["평안감사","모친상에 슬퍼하기는커녕 좋아하는 권위적 상주"]],"steps":[{"h":"제5막 시작","ev":"표생원은 환갑 넘은 본처 꼭두각시에게 자식 없는 처지를 한탄하며 작은집을 얻었다 하고, 꼭두각시는 집을 얻은 줄 알고 반기다 소실임을 듣고 당황한다.","feel":"당혹","who":["표생원","꼭두각시"]},{"h":"인사 소동","ev":"표생원이 돌모리집에게 큰부인께 인사하라 하자 돌모리집은 버티다 화가 나 머리로 들이받으며 인사하고, 꼭두각시는 인사도 싫으니 세간을 나눠 달라 한다.","feel":"격분","who":["표생원","꼭두각시"]},{"h":"편파 판결","ev":"구장을 자처한 박첨지는 좋은 논과 은장·봉장 같은 세간을 돌모리집에게 몰아주고 꼭두각시에게는 개똥밭과 깨진 독 따위를 안기며, 꼭두각시는 춤추며 나간다.","feel":"씁쓸함","who":["박첨지","꼭두각시"]},{"h":"제7막 시작","ev":"평안감사 모친의 상여가 나가는데 상주인 평안감사는 슬픔은커녕 좋다며 양산도를 부르고, 상두꾼이 발병이 나 상여가 멈춘다.","feel":"뻔뻔함","who":["평안감사"],"q":"아이고 좋아. 콩나물 안방 차지 내 차지."},{"h":"홍동지 천거","ev":"인부를 사라는 감사에게 박첨지가 이상야릇한 조카 홍동지를 천거하고, 홍동지는 빨가벗어도 되느냐 묻더니 상여에서 개 썩는 냄새가 난다며 놀린다.","feel":"익살","who":["박첨지","홍동지"]},{"h":"벌거숭이 상여꾼","ev":"빨가벗고 문안하는 홍동지를 감사가 꾸짖자 홍동지는 상여만 잘 메면 된다고 받아치고, 화가 난 감사는 박첨지를 잡아들여 태장을 친다.","feel":"당당함","who":["홍동지","평안감사","박첨지"],"q":"빨가벗었더라도 상여만 잘 메면 됐지"}],"key":"본처가 밀려나는 가부장적 모순과 지배층의 허위를 인형극 재담과 익살로 풍자한 민속극","pt":["풍자 대상: 권위적 남성 중심 질서(표생원)와 지배층의 횡포·허위(평안감사)","인형을 조종하며 대사·노래를 하는 대잡이, 거리 단위로 이어지는 인형극 구성","동음이의 재담·박첨지의 편파 판결·홍동지의 반항을 풍자 기법으로 해석하기"],"src":"해설 p.74~75 · 본책 p.212~216 · 수록 부분만","g":"극·수필","s":"수특 극·수필 1강","th":"권력과 가부장적 질서에 대한 풍자"},"w078":{"t":"불모지","a":"차범석","who":[["최노인","낡은 한옥에 집착하는 환갑의 가장"],["어머니","허리가 아파도 가족 사이를 다독이는 최노인의 아내"],["경수","제대군인으로 일자리 없는 큰아들"],["경운","인쇄소 식자공으로 생계를 떠맡은 차녀"],["경재","대학 진학을 앞두고 물 긷기에 불만인 막내"]],"steps":[{"h":"공동수도","ev":"공동수도에서 물을 긷던 경재가 물 흔한 집으로 옮기자고 투덜대자 최노인은 싫으면 나가라며 집을 두둔하고, 경운이 재빨리 분위기를 수습한다.","feel":"고집","who":["경재","최노인","경운"]},{"h":"옛 이웃","ev":"최노인과 어머니는 이 집에서 산 지 사십칠 년, 강약방과 사귄 지 사십 년임을 떠올리고, 높은 집들이 햇볕을 가린다며 변해 가는 세상을 못마땅해한다.","feel":"회한","who":["최노인","어머니"]},{"h":"복덕방 소동","ev":"(중략) 이백오십만 환이 터무니없다며 경수가 복덕방 영감에게 막말을 하자 영감은 크게 화를 내고 가 버리고, 어머니는 용서를 구하며 최노인은 사죄하러 뒤쫓는다.","feel":"당황","who":["경수","어머니","최노인"]},{"h":"오해와 호통","ev":"집을 판다고 오해한 경수에게 최노인은 노발대발하며 전세로 육 개월만 내놓으려던 것이라 밝히며, 샤뿔뽀오드 가게를 해 보려던 계획을 털어놓는다.","feel":"분노","who":["최노인","경수","어머니"]},{"h":"화초밭","ev":"집안에서는 되는 일이 하나도 없다며 화가 난 최노인이 정성껏 가꾼 화초밭을 짓밟고 뽑아 헤치자, 어머니가 맨발로 뛰어내려 말린다.","feel":"절망","who":["최노인","어머니"],"q":"나는 모든 일에 정성을 들였지만 안 되지 않아!"}],"key":"높은 건물에 둘러싸인 낡은 집이 근대화 속 세대 갈등과 가족의 몰락을 상징하는 '불모지'","pt":["[A]·[B]에서 인물의 표정이 어떻게 달라져야 하는지 묻는 연출 조언 문제","㉠~㉤ 대사의 속생각 추론: 경운의 수습, 경수의 막말, 어머니의 오해","보기(1950년대 도시화·근대화)와 연결: 햇볕 안 드는 집, 층층이 쌓인 건물, 세대 갈등"],"src":"해설 p.76 · 본책 p.217~221 · 수록 부분만","g":"극·수필","s":"수특 극·수필 2강","th":"근대화 속 전통적 가족의 몰락"},"w079":{"t":"노비 문서","a":"윤대성","who":[["노승","방량을 조건으로 노비군을 꾸리자고 설득하는 인물"],["이자헌","충주성을 다스리는 대감, 위기가 지나자 약속을 뒤집는다"],["부사","나라와 왕을 앞세워 방량에 반대하는 관리"],["판관","전례와 후환을 들어 반대하다 결국 수긍하는 관리"]],"steps":[{"h":"앞부분 줄거리","ev":"몽골군이 쳐들어오자 부호와 사대부, 군사 상당수가 도망가 충주성이 위기에 빠지고, 노승이 노비군을 조직하자고 제안한다.","feel":"다급","who":["노승"]},{"h":"방량 제안","ev":"노승이 노비를 방량하는 조건을 내걸자 하니, 부사와 판관은 전례가 없고 부호가 들고일어나며 관노를 풀면 일은 누가 하느냐고 반대한다.","feel":"반발","who":["노승","부사","판관"]},{"h":"자유를 위해","ev":"노승은 나라가 왕이 아닌 백성의 것이라며 자신의 자유를 위해 싸우면 노비들이 목숨을 내던질 것이라 설득하고, 이자헌과 판관이 받아들인다.","feel":"단호함","who":["노승","이자헌","판관"],"q":"나라는 왕의 것이 아니라 백성의 것이오"},{"h":"중략 줄거리","ev":"방량 약속으로 조직된 노비군이 몽골군을 격퇴하고 장터에서 잔치를 즐기지만, 이자헌이 이를 금지하자 무장한 노비들의 불만과 의심이 커진다.","feel":"불안","who":["이자헌"]},{"h":"신분 질서","ev":"이자헌은 존비와 귀천이 천 년 이어 온 생활이고 다스리는 근본은 힘이라 주장하고, 노승은 힘이 아닌 인과 덕으로 다스려야 한다고 맞선다.","feel":"완고","who":["이자헌","노승"]},{"h":"약속의 배신","ev":"노승이 신의와 약속을 지켜야 한다고 하자 이자헌은 나라를 구하려 일시적으로 방량했을 뿐 제도를 마음대로 고칠 수 없다며 약속을 뒤집을 뜻을 비춘다.","feel":"변명","who":["이자헌","노승"]}],"key":"자유를 약속해 놓고 위기가 지나자 신분 질서로 돌아서는 지배층의 배신을 그린 서사극","pt":["방량을 조건으로 노비군을 꾸리자는 노승과 신분 질서를 앞세우는 이자헌의 대립","ⓐ '다스릴 군사가 없다'에서 판관의 걱정(무장한 노비를 통제하지 못함) 추론","보기(1973년 서사극, 만적의 난, 1970년대 억압적 정치)와 연결한 감상, ㉠~㉤ 연출 지시"],"src":"해설 p.77~78 · 본책 p.222~225 · 수록 부분만","g":"극·수필","s":"수특 극·수필 3강","th":"지배층의 배신과 권위적 체제 비판"},"w080":{"t":"역마(시나리오)","a":"김동리 원작·최금동·김강윤 각색","who":[["성기","역마살을 타고난 옥화의 아들, 이별 뒤 앓아눕는다"],["옥화","화개장터 주막 주인, 성기가 정착하길 바란 어머니"],["계연","체장수 동운의 딸, 성기와 가까워진 처녀"],["오동운","계연의 아버지이자 옥화의 친부인 소리꾼 출신 체장수"]],"steps":[{"h":"S#142 이별","ev":"동운이 떠나려는 날 성기가 뛰어들어오자 계연은 반가워하지만, 계연이 떠난다는 옥화의 말에 성기는 굳은 표정으로 계연만 쳐다본다.","feel":"충격","who":["성기","계연","옥화","오동운"]},{"h":"중략 줄거리","ev":"성기는 앓아누워 굶어 죽을 결심을 하고, 옥화는 계연이 이복동생이고 동운이 친부임을 알게 되었다며 계연을 보내야 했던 이유를 털어놓는다.","feel":"절망","who":["성기","옥화"]},{"h":"S#148~150","ev":"얼어붙은 강가에서 성기는 장가들겠다 약속하고 입맞춤하던 계연과의 지난날을 떠올리다, 회상에서 깨어나 눈물을 훔치고 돌아선다.","feel":"그리움","who":["성기","계연"]},{"h":"S#151 미음","ev":"옥화가 가져온 미음을 말없이 먹던 성기는 강원도도 장가도 고개를 젓더니 봄이 오면 엿판 하나만 맞춰 달라고 청하고, 옥화는 그러라고 한다.","feel":"체념","who":["성기","옥화"]},{"h":"S#153 삼거리","ev":"봄이 오자 성기는 새로 맞춘 엿목판을 지고 삼거리로 나서고, 옥화는 붉어진 눈으로 따라 나와 몸 성히 다녀오라 한다.","feel":"담담함","who":["성기","옥화"]},{"h":"S#154 길","ev":"성기는 계연이 떠난 구례 길 대신 하동 길로 들어서고, 옥화는 지난 말들을 떠올리며 눈물짓고, 성기는 육자배기 소리 속을 가볍게 걸어간다.","feel":"수용","who":["성기","옥화"]}],"key":"계연과 헤어진 성기가 운명을 받아들이고 엿장수가 되어 길을 나서는, 이별과 수용의 시나리오","pt":["원작 소설과 비교: 주변 인물·새 장면을 넣고 영상·음향 기법으로 심리 표현","S#148~153의 회상과 (E) 음향이 시간 전환과 현재 내면을 보여 주는 방식","㉠~㉤ 감독 조언: 성기·계연·옥화의 순간 심리와 표정 판별"],"src":"해설 p.79 · 본책 p.226~229 · 수록 부분만","g":"극·수필","s":"수특 극·수필 4강","th":"운명의 수용과 생의 의지"},"w081":{"t":"꽃 피는 봄이 오면(시나리오)","a":"류장하","who":[["현우","꿈을 접고 탄광촌 중학교 관악부에 온 트럼펫 연주자"],["연희","현우와 헤어진 옛 연인, 곧 다른 사람과 결혼한다"],["용석","관악부 부장, 광부 아버지가 음악을 반대하는 학생"]],"steps":[{"h":"S#5 놀이터","ev":"늦은 밤 연희는 현우와 벤치에 앉아 같은 소절만 반복해 흥얼거리며 지난 사랑을 떠올리고, 현우가 준 목걸이를 팔아 술을 마셨다고 털어놓는다.","feel":"쓸쓸함","who":["연희","현우"]},{"h":"S#5 헤어짐","ev":"음악만 하는 사람과는 못 산다던 연희는 외로워 보이냐며 허탈하게 웃고 나무를 바라보는데, 현우가 뒤돌아보면 연희는 없고 4층 창에 불이 켜진다.","feel":"허탈함","who":["현우","연희"]},{"h":"중략 줄거리","ev":"연희가 다른 사람과 결혼한다고 알리자 현우는 탄광촌 도계중학교 관악부 임시 교사로 내려오고, 용석은 광부인 아버지의 반대로 관악부를 나오지 못하게 된다.","feel":"좌절","who":["현우","연희","용석"]},{"h":"S#74 눈길","ev":"안대를 한 용석을 만난 현우는 용석 아버지가 한때 이름난 연주자였고 아들을 깊이 사랑한다는 것을 알았다며, 아버지의 말씀이 일리가 있다고 전한다.","feel":"안쓰러움","who":["현우","용석"]},{"h":"현실과 음악","ev":"현우는 공부해서 다른 일을 하는 편이 낫고 음악은 돈이 안 된다고 설득하지만, 용석은 그런 게 뭐가 중요하냐며 수정이와 이미 헤어졌다고 맞받는다.","feel":"답답함","who":["현우","용석"]},{"h":"흥분하는 현우","ev":"헤어졌다는 말에 현우는 남자가 책임져야 한다며 흥분하고, 용석이 왜 그렇게 흥분하느냐고 묻자 말을 얼버무리며 달래는 사이 눈발이 다시 날린다.","feel":"허둥댐","who":["현우","용석"]}],"key":"꿈을 접은 현우와 탄광촌 아이들이 서로의 암울한 현실을 보듬으며 희망을 되찾아 가는 이야기","pt":["미장센 ㉠~㉤: 반복되는 노랫가락·낡은 현관·링거 맨 나무·안대·눈을 읽는 문제","S#5와 S#74 비교: 현우·연희, 용석·수정의 관계와 현우의 태도","[A]에서 현우가 용석 아버지의 말을 옮겨 아들 사랑을 전하는 말하기 방식"],"src":"해설 p.80~81 · 본책 p.230~233 · 수록 부분만","g":"극·수필","s":"수특 극·수필 5강","th":"인간애를 통한 희망의 회복"},"w082":{"t":"호동서락기","a":"김금원","who":[["글쓴이","여성의 제약을 넘어 남장하고 산수를 유람하는 사람"]],"steps":[{"h":"여행 결심","ev":"하늘이 총명한 재주와 귀와 눈을 주었는데 여자라고 담장 안에만 있거나 이름 없이 사라질 수는 없다며 산수 유람을 결심한다.","feel":"굳은 의지","who":["글쓴이"],"q":"깊은 담장 안에서 문을 닫아걸고"},{"h":"출발","ev":"증점의 일을 본받겠다며 부모에게 여러 번 간청해 허락을 받자, 새장을 벗어난 매처럼 기뻐하며 남자 옷으로 갈아입고 길을 떠난다.","feel":"해방감","who":["글쓴이"]},{"h":"한양 조망","ev":"한양을 멀리 바라보며 시 한 수를 짓고, 산과 강이 에워싼 웅장한 형세와 풍부한 물산을 묘사하며 수양제와 당태종이 고구려에서 곤경을 겪은 일을 떠올린다.","feel":"감탄","who":["글쓴이"]},{"h":"남산에서","ev":"남산에 올라 대궐과 번화한 시내, 놀러 나온 젊은이들을 보며 태평한 기상을 느끼고, 시골에서 자라 좁았던 안목이 비로소 트이는 것을 느낀다.","feel":"후련함","who":["글쓴이"]},{"h":"세검정·삼계동","ev":"세검정과 탕춘대, 삼계동 별장과 백석실, 천수도 수각을 두루 찾아 경치와 유래를 적고, 괴로운 마음을 씻어 내는 시 한 편을 읊는다.","feel":"흥취","who":["글쓴이"]},{"h":"깨달음","ev":"산과 냇물은 본디 주인이 없고 바람과 달도 그 사이에 있어 노니는 사람이 차지할 뿐이라 여기며, 향기로운 풀을 밟고 기이한 경치를 찾아 다닌다.","feel":"자유로움","who":["글쓴이"],"q":"오로지 노니는 사람이 취할 뿐이다"}],"key":"여성에게 가해진 제약을 딛고 남장해 산수와 한양을 유람한 감흥을 적은 현전 최초의 여성 기행 산문","pt":["[A] 글쓴이의 태도: 옛사람(증점)의 일을 근거로 여행의 뜻을 정당화","[B] 한양 묘사와 이동 경로(전경→남산→세검정·탕춘대→삼계동·백석실)별 표현","㉠·㉡ 한시의 소재('부평초'·'나막신')와 보기: 여성 차별 비판, 색채어, 인문 지식"],"src":"해설 p.82 · 본책 p.234~237 · 수록 부분만","g":"극·수필","s":"수특 극·수필 6강","th":"여행과 산수 유람의 즐거움(여성의 기행)"},"w083":{"t":"해갑와기","a":"김석주","who":[["글쓴이","벗의 집 '해갑와'에 기문을 지어 주는 사람"],["홍언명","호수 구비에 작은 집을 짓고 게딱지라 이름 붙인 벗"]],"steps":[{"h":"제왕의 거처","ev":"옛 제왕은 흙 계단 셋뿐인 집에 살았으나 뒷사람이 이를 작다 하여 점점 키워 이십팔 리 궁전까지 지었다며, 같은 제왕인데 거처가 왜 다른지 묻는다.","feel":"의문","who":["글쓴이"]},{"h":"작음과 큼","ev":"띠풀 집도 천하를 다스리기에 충분했으니 작음을 몰랐던 것이고, 큰 궁전은 욕심을 다 채울 수 없으니 큼을 몰랐던 것이라며 크고 작음을 뒤집어 본다.","feel":"사색","who":["글쓴이"]},{"h":"벗의 해갑와","ev":"벗 홍언명이 집을 짓고 게딱지만 하다며 기문을 청하자, 글쓴이는 돌피 같은 몸에 게딱지 집이면 여유로우니 작지 않다고 답한다.","feel":"격려","who":["글쓴이","홍언명"]},{"h":"선비의 즐거움","ev":"홍언명의 집에도 띠풀 지붕과 대문, 계단이 있을 터이니 옛 제왕의 거처와 같고, 가난한 선비는 도서와 문사로 성현을 사모하며 즐기니 게딱지로 볼 수 없다고 한다.","feel":"인정","who":["글쓴이","홍언명"]},{"h":"큰 것의 기준","ev":"궁실은 클 필요가 없으나 군자의 학문과 사업은 커야 하며, 스스로를 게딱지로 여기는 선비는 어진 사람과 성인이 되어 하늘과 합치될 수 있다고 말한다.","feel":"권면","who":["글쓴이"],"q":"크지 않아서는 안 되는 것이 있느니"},{"h":"당부","ev":"홍언명이 학문에 힘써 나라에 등용되고 두보의 말처럼 가난한 선비를 감싸는 바탕을 얻는다면 집을 게딱지로 보아도 괜찮다며 힘쓰라고 당부한다.","feel":"기원","who":["글쓴이","홍언명"]}],"key":"집의 작음을 큼의 눈으로 뒤집어, 벗이 학문과 사업을 크게 이루어 쓰이기를 바란 기문","pt":["상대적 관점으로 크고 작음을 다시 해석하는 글의 전개(제왕의 거처 대조)","해갑와가 상징하는 공간의 의미: 외형이 아닌 본질, 선비가 키워야 할 학문과 사업","보기가 말하는 기문의 특성: 역설적 논리, 정신적 차원으로의 전환, 교훈 제시"],"src":"해설 p.84 · 본책 p.238~240","g":"극·수필","s":"수특 극·수필 7강","th":"작은 집과 큰 뜻"},"w084":{"t":"산촌 여정","a":"이상","who":[["글쓴이","성천 산촌에서 도회를 그리워하며 지내는 도시인"]],"steps":[{"h":"산촌의 밤","ev":"도회의 커피 맛을 잊은 지 스무 날, 신문도 잘 안 오는 산촌에서 글쓴이는 팔봉산의 짐승과 어둠, 수정처럼 맑은 공기와 별빛에 낯섦과 감탄을 느낀다.","feel":"낯섦","who":["글쓴이"]},{"h":"객줏집 등잔","ev":"객줏집 석유 등잔 아래서 소년 시절의 기억이 되살아나고, 베짱이 소리를 차장의 차표 찍는 소리와 이발소 가위 소리에 빗대는 도시적 감각으로 듣는다.","feel":"그리움","who":["글쓴이"]},{"h":"밤의 상념","ev":"시정을 비망록에 적고 맥박 소리가 방을 시계로 만든다고 느끼다 졸음 속에서 도회 소녀가 나오는 꿈을 꾸고, 남겨 둔 가난한 식구들을 보다 잠이 깬다.","feel":"걱정","who":["글쓴이"]},{"h":"화초 꿈","ev":"(중략) 내일은 종일 화초나 보며 근심을 지우고 싶다며, 화초가 만발하는 그림책 같은 꿈을 즐겁게 꾸고 싶어 한다.","feel":"소망","who":["글쓴이"]},{"h":"아침 마당","ev":"마당이 부스럭거리는 소리에 잠을 깨 불이 켜진 채 남은 등잔의 흔적과 새빨간 잠자리를 보고, 맨드라미와 봉선화가 핀 화단에서 화초의 정열을 느낀다.","feel":"생동감","who":["글쓴이"]},{"h":"흰 봉선화","ev":"처녀 손톱을 물들일 봉선화 중에 흰 것도 섞여 있어 흰 봉선화도 붉게 물들까 궁금해하다가, 조금도 이상할 것 없이 곱게 물든다고 적는다.","feel":"신선함","who":["글쓴이"]}],"key":"도시인의 감각으로 산촌의 풍물을 근대 문물에 빗대어 그린, 낯섦과 도회 향수가 섞인 수필","pt":["참신한 비유: 산촌 풍물을 근대·이국적 소재에 빗대는 효과와 감각적 이미지","ⓐ 도회와 ⓑ 산촌 공간 비교: 그리워하는 대상, 익숙한 문물, 꿈을 꾸는 모습","보기 「권태」와 비교: 같은 성천 체험, 도회 소식을 접하기 어려운 처지, 정서 차이"],"src":"해설 p.85 · 본책 p.241~243 · 수록 부분만","g":"극·수필","s":"수특 극·수필 8강","th":"도시인의 감각으로 본 산촌"},"w085":{"t":"산민","a":"김창협","who":[["나그네","말에서 내려 산골 집을 찾은 화자"],["부인","남편을 대신해 손님을 맞는 산골 아낙"],["고을 관리","백성이 무서워하는 수탈의 주체"]],"steps":[{"h":"기(1~4행)","ev":"말에서 내려 사람을 부르자 부인이 문을 열고 나와 초가로 맞아들여 나그네에게 밥상을 내온다. 산골 부인의 인정 있는 모습이다.","feel":"훈훈함","who":["나그네","부인"],"q":"나그네 위하여 밥상 내온다"},{"h":"승(5~8행)","ev":"남편은 아침에 쟁기를 들고 산에 갔는데 산밭이 너무 갈기 어려워 해가 저물도록 오지 못한다고 부인이 답한다. 산골의 고달픈 삶이 드러난다.","feel":"고달픔","who":["나그네","부인"],"q":"산밭은 너무나 갈기 어려워"},{"h":"전(9~12행)","ev":"둘러봐도 이웃이 없고 개와 닭만 비탈에서 서성인다. 숲에는 호랑이가 많아 뜯은 콩잎이 광주리에 반도 차지 않는다. 외롭고 위험한 생활이다.","feel":"외로움","who":["나그네","부인"],"q":"숲속에는 무서운 호랑이 많아"},{"h":"결(13~16행)","ev":"나그네가 이런 척박한 두메산골이 뭐가 좋아 사느냐고 묻는다. 편안한 평지로 가고 싶어도 고을 관리가 너무 무서워 가지 못한다고 한다.","feel":"고발","who":["나그네","부인","고을 관리"],"q":"가고파도 고을 관리 너무 무서워"}],"key":"관리의 수탈이 무서워 평지를 두고 두메산골에서 고달프게 사는 부부를 그린 한시이다","pt":["산골과 평지를 대비하고 부인과의 대화로 현장감을 살려 관리의 횡포를 고발한다","‘개와 닭’ 같은 친숙한 자연물로 수탈당하는 백성의 현실에 대한 비판을 드러낸다","‘바깥어른’ 대신 부인이 맞은 까닭은 ‘쟁기 들고 산에 갔다’는 답에서 확인된다"],"src":"해설 p.86~87 · 본책 p.244~249","g":"고전시가","s":"수특 갈래 복합 1","th":"관리의 수탈과 산민의 고통"},"w086":{"t":"합강정가","a":"작자 미상","who":[["화자","백성의 편에서 감사의 호화 뱃놀이를 고발하는 목소리"],["감사","순시 나와 합강정에서 뱃놀이하는 관찰사"],["관리들","감사에게 아부하느라 백성을 수탈하는 각 읍 관리"],["백성","수탈에 못 살겠다고 하소연하는 사람들"]],"steps":[{"h":"서사","ev":"구월 스무사흗날 순시 나온 감사가 합강정에서 뱃놀이를 하는데, 한 달 걸려 돌을 깨고 산을 뚫고 무덤까지 옮겼다. 감사에겐 풍류, 백성에겐 원수라고 한다.","feel":"비판","who":["화자","감사","백성"],"q":"감사에겐 풍류요 백성에겐 원수로다"},{"h":"본사 1","ev":"여러 고을 관리가 마련한 잔칫상은 백성의 피와 기름이다. 수확 없는 땅에도 세금을 매기고 길을 넓히라며 매질해 닭과 개가 사라질 지경이다.","feel":"분노","who":["화자","관리들","백성"],"q":"백성의 피와 기름 아닌가"},{"h":"본사 2","ev":"빈 부엌에서 우는 아낙이 그릇조차 빌릴 곳이 없다며, 닭과 개를 다 먹어 치우고도 집집마다 또 거두느냐고 하소연한다. 이 놀이를 다시 하면 못 살겠다고 한다.","feel":"하소연","who":["백성","관리들"],"q":"이 놀이 다시 하면 이 백성 못 살겠네"},{"h":"결사","ev":"재주만 겨루는 유생들에게 의로운 선비가 하나도 없느냐고 개탄한다. 출세운 좋은 감사를 짚으며 임금 은혜에 보답해야 하고 배은망덕하면 자손에게 화가 미친다고 말한다.","feel":"개탄","who":["화자","감사"],"q":"의로운 선비 하나 없단 말인가"}],"key":"전라 감사의 호화 뱃놀이로 백성이 받은 고통을 고발한 1792년의 현실 비판 가사이다","pt":["‘먹을 복 좋은 우리 감사 / 출세운 좋은 우리 감사’ 대구는 접대만 바라는 감사를 비판한다","관찰사의 가을 순행은 백성이 생활고 해결을 기대했지만 오히려 고통이 커진 행사이다","결사의 ‘~게 되면 ~리라’ 가정은 신하가 임금 은혜에 보답해야 한다는 가치를 강조한다"],"src":"해설 p.86~88 · 본책 p.244~249","g":"고전시가","s":"수특 갈래 복합 1","th":"관리의 횡포와 현실 풍자"},"w087":{"t":"응계설","a":"이첨","who":[["글쓴이","응방 혁파를 늦은 일이라 논평하는 신하"],["충혜왕","닭 울음에야 측은해하며 응방을 혁파한 임금"],["신하들","임금의 노여움이 두려워 간언하지 못한 이들"]],"steps":[{"h":"사실","ev":"충혜왕 때 응방 관리가 닭을 매 먹이로 주다 거의 죽게 된 닭을 자루에 넣었는데 아침에 그 닭이 울었고, 이를 들은 임금이 측은히 여겨 조정이 응방을 혁파했다.","feel":"측은함","who":["충혜왕"]},{"h":"인의 발견","ev":"닭 울음은 본성이라 보통은 무심히 듣지만 다친 닭의 울음에 임금이 감동해 관청을 없앴으니, 인(仁)이 원래 사람 마음에 있음을 알 수 있다고 본다.","feel":"성찰","who":["글쓴이"]},{"h":"백성의 고통","ev":"당시 백성은 매를 잡다 절름발이가 되거나 배가 가라앉아 빠져 죽었고 곡식 밭도 짓밟혔으니, 폐단을 호소한 말이 어찌 닭 한 마리 울음에 그치겠느냐고 따진다.","feel":"비판","who":["글쓴이"]},{"h":"임금의 마음","ev":"임금은 여러 사람의 말은 믿지 않다가 의도 없는 닭 울음에 감동했으니, 평소 백성을 자식처럼 여겼다면 닭이 울기를 기다리지 않았을 것이라고 지적한다.","feel":"질책","who":["글쓴이","충혜왕"]},{"h":"신하의 책임","ev":"매를 한창 좋아하던 임금은 충신이 간쟁해도 성을 내며 죽였을 것이나, 측은한 마음이 든 그때가 간언할 쉬운 기회였는데도 신하들이 말하지 못했다고 꼬집는다.","feel":"안타까움","who":["글쓴이","신하들"]},{"h":"결론","ev":"응방은 충혜왕이 유배 가던 도중 악양에서 죽은 뒤에야 혁파되었으니, 글쓴이는 이 또한 늦은 일이었다고 탄식한다.","feel":"탄식","who":["글쓴이","충혜왕"],"q":"아, 이 또한 늦은 일이었다."}],"key":"닭 울음에야 감동한 임금과 간언하지 못한 신하를 함께 꾸짖은, 백성을 자식처럼 돌보라는 설","pt":["ⓐ 관찰사의 순행과 ⓑ 응방: 백성의 생활을 어렵게 한 행사와 관청 비교","(다)와 「안민가」(보기): 임금·신하·백성의 도리, '어린아이를 돌보듯' 하는 정치","의도 없는 닭 울음과 사람의 말 대비, 때를 놓친 신하까지 비판한 '늦은 일이었다'"],"src":"해설 p.87 · 본책 p.246~249","g":"극·수필","s":"수특 갈래 복합 1","th":"임금의 도리와 신하의 간언"},"w088":{"t":"계녀가","a":"작자 미상","who":[["어머니","시집가는 딸에게 도리를 일러 주는 화자"],["딸(아해)","내일 신행을 앞두고 가르침을 듣는 청자"]],"steps":[{"h":"서사","ev":"내일이 신행이라 딸의 마음과 어머니의 심사가 갈피를 못 잡는다. 친정을 떠나 시가로 들어가는 딸에게 일러 둘 말이 많고 많다.","feel":"걱정","who":["어머니","딸(아해)"],"q":"아해야 들어봐라 내일이 신행이라"},{"h":"본사(봉양)","ev":"세수를 일찍 하고 문밖에서 절한 뒤 방이 따뜻한지 잠자리가 편하신지 여쭈라 한다. 식성을 물어 반찬을 맞춰 진지를 올리고, 틈이 나면 내 방에서 침착하게 일하라 한다.","feel":"당부","who":["어머니","딸(아해)"],"q":"식성을 물어가며 반찬을 맞게 하고"},{"h":"본사(양육)","ev":"자식은 장난을 말리고 음식을 아껴 먹이되 맹자의 어머니처럼 가르치라 한다. 노비는 수족이라 귀천은 달라도 혈육은 같으니 꾸짖어도 악언을 말라 한다.","feel":"가르침","who":["어머니","딸(아해)"],"q":"귀천은 다르나마 혈육은 한가지라"},{"h":"본사(살림)","ev":"살림을 하되 입치레·몸치장을 삼가고 헌 옷을 기워 입으라 한다. 남의 말과 남의 집 일, 인물 평론을 삼가고 이웃을 왕래할 때도 조심하라고 이른다.","feel":"경계","who":["어머니","딸(아해)"],"q":"남의 말 하지 말고 남의 집 내지 말아"},{"h":"결사","ev":"남의 집에서 처음엔 조심하다 세월이 가면 소홀해지기 쉬우니 처음 마음을 늙도록 변치 말라 한다. 책을 때때로 꺼내 보라 당부하고 이만 그친다.","feel":"당부","who":["어머니","딸(아해)"],"q":"처음의 가진 마음 늙도록 변치 마라"}],"key":"시집가는 딸에게 시부모 봉양·자녀와 노비 대하기·살림·처신의 도리를 일러 주는 규방 가사이다","pt":["대조적 상황 제시(‘귀타고 안을 받아…’ ‘꾸짖어도 악언 말고’)로 삶에 대한 인식을 드러낸다","맹자의 어머니 같은 전례로 이상적인 여성상을 보이며 딸에 대한 걱정을 드러낸다","노비에게 ‘귀천은 다르나마 혈육은 한가지’라 하면서도 명분을 밝히라 한다(귀천을 따짐)"],"src":"해설 p.89~90 · 본책 p.250~255","g":"고전시가","s":"수특 갈래 복합 2","th":"시집가는 딸에 대한 권계"},"w089":{"t":"상론","a":"정약용","who":[["글쓴이","관상으로 사람을 판단하는 통념을 논박하는 사람"],["세상 사람들","상이 변한 것을 보고 상 때문이라 말하는 이들"]],"steps":[{"h":"주장","ev":"상은 익히는 것에 따라 변하고 형세는 상에서 이루어진다고 하며, 형국이나 유년으로 말하는 사람은 거짓이라 잘라 말한다.","feel":"단호함","who":["글쓴이"]},{"h":"무리와 상","ev":"아이는 자라며 무리가 나뉘고 익히는 것이 달라져 상도 변하니, 서당 무리는 아름답고 시장 무리는 검은데도 사람들은 거꾸로 상 때문이라고 한다.","feel":"논박","who":["글쓴이","세상 사람들"]},{"h":"익힘과 효과","ev":"학문을 익히면 사리에 통달하고 이를 익히면 재물을 모으며 악을 익히면 패망하니, 익힘과 효과가 함께 나아가 상이 변하는데도 사람들은 상 탓을 한다.","feel":"한탄","who":["글쓴이","세상 사람들"]},{"h":"세 아이","ev":"눈동자가 빛나는 아이는 주위의 도움으로 재상에 이르고, 얼굴이 풍만한 아이는 자본을 받아 부자가 되며, 눈썹이 더부룩한 아이는 반대로 양성되지 못한다.","feel":"냉철","who":["글쓴이"]},{"h":"상 탓의 오류","ev":"재덕이 있어도 곤궁한 사람을 상 탓으로 돌리지만 상을 따지지 않고 우대했다면 재상이 되었을 것이며, 거처와 부귀, 우환에 따라 사람이 달라지니 상을 어찌 정하겠느냐고 묻는다.","feel":"반문","who":["글쓴이"]},{"h":"폐해","ev":"선비가 상을 믿으면 직업을, 대부가 믿으면 친구를, 임금이 믿으면 신하를 잃는다고 경고하고, 용모로 사람을 취하지 않은 공자를 성인이라 한다.","feel":"경계","who":["글쓴이"],"q":"용모로써 사람을 취했더라면"}],"key":"상은 타고나는 것이 아니라 익힘과 환경에 따라 바뀌니, 용모로 사람을 판단하는 통념은 틀렸다는 논","pt":["논지 전개: 익힘에 따른 상의 변화 → 여러 사례로 통념 비판 → 상을 믿을 때의 폐해","[A]·[B] 비교: 무리가 갈라져 익히는 것이 달라진다는 말이 서당·시장·목동 무리로 구체화","㉠~㉢ 사례: 주위 사람들의 평가와 지원이 성장에 영향을 준 경우로 묶어 읽기"],"src":"해설 p.89 · 본책 p.252~255","g":"극·수필","s":"수특 갈래 복합 2","th":"관상만으로 사람을 판단하는 것에 대한 경계"},"w090":{"t":"허균의 문집에 부치는 서문","a":"이항복","who":[["글쓴이","시의 효용을 의심하면서도 좋은 시에는 끌리는 사람"],["허균","불교의 말로 시를 꾸미는 문집의 주인"]],"steps":[{"h":"시에 대한 회의","ev":"시가 무엇이 귀하기에 세상이 좋아하느냐 묻고, 글을 꾸미고 웅얼거려 잠시 사람들의 입을 벌어지게 할 뿐이라며 회의를 드러낸다.","feel":"회의감","who":["글쓴이"]},{"h":"시인·광대·벌레","ev":"시인은 생각으로, 광대는 입으로, 벌레는 몸으로 소리를 내 사람을 기쁘게 하는데, 힘들기는 시인이 가장 힘든데도 세상은 시인을 가장 높이 대접한다.","feel":"의아함","who":["글쓴이"]},{"h":"시를 멀리함","ev":"글쓴이는 귀천이 같지 않음을 늦게 깨닫고 시 이야기를 피하겠다고 맹세했지만, 좋은 시를 보면 병으로 술을 끊은 사람이 술 생각이 나듯 기뻐한다.","feel":"미련","who":["글쓴이"]},{"h":"허균 비판","ev":"삼교와 제자백가에 통달한 허균이 불교의 말로 시를 장식하는 것은 좋은 벼를 뽑고 잡초를 키우는 격이며, 광대나 벌레보다 못해질 줄 모른다고 비판한다.","feel":"질책","who":["글쓴이","허균"]},{"h":"생각과 시","ev":"마음은 거북 등껍데기 같아 속을 태우면 조짐이 나타난다는 말에, 글쓴이는 생각은 물이요 시는 얼음이라 응수하며 깊은 생각에서 나온 시라야 감동을 준다고 한다.","feel":"확신","who":["글쓴이"],"q":"생각은 물과 같고 시는 얼음과 같다"},{"h":"맺음","ev":"늙어서 시를 멀리하는데도 저녁에 허균을 만나자 나도 모르게 수레에서 내렸다며, 시가 정말 좋고 귀한 것이어서인지 되묻고 글을 맺는다.","feel":"여운","who":["글쓴이","허균"]}],"key":"시 짓기의 수고와 진정성을 말하며, 꾸밈에 치우친 허균의 시풍을 경계한 서문","pt":["시인·광대·벌레를 견주어 시 창작의 수고를 부각하는 방식과 글쓴이의 회의·애정","ⓐ '마음은 거북 등껍데기'에 대한 응수: 생각이 움직여 시가 된다는 뜻","(가)와 「시」(나)를 시 창작의 고뇌와 진정한 아름다움이라는 보기로 묶어 읽기"],"src":"해설 p.91~92 · 본책 p.256~260","g":"극·수필","s":"수특 갈래 복합 3","th":"시 창작의 진정성과 가치"},"w091":{"t":"시(시나리오)","a":"이창동","who":[["미자","시를 쓰고 싶어 시 창작 강의를 듣는 할머니"],["김시인","문화원에서 시 창작을 가르치는 강사"],["수옥","미자의 딸, 빈집에서 엄마를 찾는다"]],"steps":[{"h":"작품 배경","ev":"평범한 할머니 미자는 시를 쓰고 싶어 강의를 듣다 손자가 여중생의 자살에 연루되었음을 알고, 부조리한 현실에서 아름다운 시를 쓴다는 모순에 놓인다.","feel":"혼란","who":["미자"]},{"h":"S#21 강의","ev":"김 시인이 시 쓰기는 일상에서 진정한 아름다움을 찾는 일이라 하자 미자가 시상은 언제 오느냐고 묻고, 김 시인은 찾아가서 빌어야 한다고 답한다.","feel":"간절함","who":["김시인","미자"]},{"h":"어디로요","ev":"어디로 찾아가느냐는 되물음에 김 시인은 말문이 막혀 짜증을 참으며 지금 있는 자리에서 얻는 것이라 하고, 미자는 해답을 찾는 듯한 표정을 짓는다.","feel":"곤혹","who":["김시인","미자"],"q":"설거지통 속에도 시가 있다고"},{"h":"S#92 빈집","ev":"딸 수옥이 집에 들어와 엄마를 부르지만 대답이 없고 전화도 받지 않아, 텅 빈 집에 앉아 미자의 부재에 사로잡히자 미자의 목소리가 시처럼 들리기 시작한다.","feel":"허전함","who":["수옥"]},{"h":"S#93 아파트 앞","ev":"카메라가 나무에서 틸트 다운하면 미자가 시상을 떠올리며 앉던 자리에 동네 할머니가 앉아 있고, 공터에서는 아이들이 놀며 미자의 시 낭송이 화면 밖에서 이어진다.","feel":"적막함","who":["미자"]},{"h":"S#94 정류장","ev":"미자가 늘 버스를 타던 정류장은 기다리는 사람 없이 비어 있고, 버스가 서도 아무도 내리지 않는 가운데 작별을 말하는 시 낭송이 흐른다.","feel":"이별","who":["미자"]}],"key":"시 쓰기의 의미를 묻는 영화로, 일상의 아름다움과 미자의 부재·이별을 시 낭송과 빈 공간으로 보여 준다","pt":["S#·O.S.(화면 밖 목소리)·틸트 다운의 기능과 제작 노트에서 어긋난 연출 고르기","미자의 시 낭송이 흐르는 빈집·빈 정류장이 드러내는 부재와 이별","일상에서 찾는 아름다움: 시상을 묻는 미자와 김 시인의 대화(㉠~㉤) 읽기"],"src":"해설 p.92 · 본책 p.256~260 · 수록 부분만","g":"극·수필","s":"수특 갈래 복합 3","th":"부조리한 현실과 시 쓰기의 윤리"},"w092":{"t":"규원가","a":"허난설헌","who":[["화자","집 떠난 남편을 기다리는 규방의 여인"],["임","장안 유협 경박자로 불린, 소식이 끊긴 남편"]],"steps":[{"h":"1~12행","ev":"군자를 짝으로 바랐으나 경박한 장안 유협을 꿈같이 만나 살얼음 디디듯 지냈다. 이제는 세월에 얼굴이 변해 누가 사랑하랴며 스스로 부끄러워한다.","feel":"한탄","who":["화자","임"],"q":"내 얼굴 내 보거니 어느 임이 날 괼쏘냐"},{"h":"13~26행","ev":"임이 야유원의 새 사람에게 빠졌는지 의심하며 소식조차 모른다. 인연이 끊겼다 한들 생각이야 없겠느냐며, 한숨과 눈물로 긴 날을 지새운다.","feel":"원망","who":["화자","임"],"q":"인연(因緣)을 그쳤은들 생각이야 없을쏘냐"},{"h":"27~34행","ev":"마음을 달래려 녹기금을 안고 접련화 곡조를 타지만 시름이 섞여 짝 잃은 학의 울음 같다. 적막한 방에 들어줄 이가 없어 간장만 끊어진다.","feel":"고독","who":["화자"],"q":"부용장(芙蓉帳) 적막(寂寞)하니 뉘 귀에 들릴소니"},{"h":"35~47행","ev":"꿈에라도 보려 잠들어도 바람에 지는 잎과 풀 속 짐승 소리가 깨운다. 견우직녀도 만나는데 임은 소식조차 끊겼다며, 나 같은 박명한 여인이 또 있겠느냐고 비관한다.","feel":"비관","who":["화자","임"],"q":"박명(薄命)한 홍안(紅顔)이야 날 같은 이 또 있을까"}],"key":"젊은 날을 돌아보며 집 나간 남편을 원망하고 그리워하다, 외로움 속에 처지를 비관하는 규방 가사이다","pt":["견우직녀 같은 설화 인물을 끌어오되 화자와 동일시하지 않고 대비한다","‘봄바람 가을달이 베올에 북 지나듯’ 같은 자연물 비유로 시간의 흐름을 압축한다","‘녹기금’은 근심을 달래며 고독을 대변하고, ‘실솔’은 외로움을 키우는 소재다"],"src":"해설 p.94~95 · 본책 p.261~265","g":"고전시가","s":"수특 갈래 복합 4","th":"독수공방의 한과 그리움"},"w093":{"t":"인현왕후전","a":"작자 미상","who":[["인현왕후","폐위되어 본가에서 죄인처럼 지내는 왕비"],["장희빈","왕비 자리에 올라 권세를 부리는 악인"],["숙종","장씨에게 빠졌다 뒤늦게 잘못을 깨닫는 임금"],["장희재","장씨의 오라비. 훈련대장이 되어 횡포를 부린다"]],"steps":[{"h":"폐위의 전말","ev":"병조판서 민유중의 딸 인현왕후는 덕이 높았으나 후사가 없어 왕에게 후궁을 들이길 청한다. 시녀 출신 장씨가 희빈이 되어 왕자를 낳고 거짓과 모략으로 왕후를 폐위시킨다.","feel":"인내","who":["인현왕후","장희빈","숙종"]},{"h":"송이와 눈물","ev":"폐위된 후는 본가에서 보낸 송이를 보고 대비들이 즐기던 일이 떠올라 눈물을 흘린다. 색 있는 옷과 보물을 물리치고 무명 치마와 흰 저고리만 입는 죄인으로 처신한다.","feel":"서러움","who":["인현왕후"],"q":"죄인이 어찌 색깔 있는 옷을 입으리요"},{"h":"큰 개","ev":"인적이 끊긴 처소에 큰 개가 들어와 새끼를 낳고 네 마리가 짖어 잡귀를 쫓는다. 서술자는 짐승도 도움이 되는데 왕후 폐출을 기뻐하는 조정의 소인은 금수만도 못하다고 비판한다.","feel":"담담함","who":["인현왕후"],"q":"도리어 금수만도 못하리로다"},{"h":"장씨의 횡포","ev":"장씨가 왕비가 되고 아비는 부원군, 오라비 장희재는 훈련대장이 되자 기강이 흩어진다. 세자가 책봉되자 장씨는 방약무인하게 비빈과 궁녀를 엄하게 다스린다.","feel":"교만","who":["장희빈","장희재"]},{"h":"운의 전환","ev":"삼사 년 뒤 임금은 장씨의 악독함과 후의 억울함을 깨닫는다. 장씨가 옥사를 다시 일으켜 폐비에게 사약하려 하자 임금은 옥사를 뒤집고 아첨하는 신하들을 물리친다.","feel":"깨달음","who":["숙종","장희빈"]},{"h":"어찰 사양","ev":"임금이 별감과 상궁, 신하를 보내 문 열기를 청해도 후는 죄인이 어찌 받겠느냐며 거듭 사양하다 오라버니의 간청에 바깥문만 연다. 어찰에는 지난 잘못을 뉘우치는 사연이 가득하다.","feel":"겸손","who":["인현왕후","숙종"],"q":"죄인이 어찌 외인을 접하며 감히 어찰을 받으리오"},{"h":"복위와 죽음","ev":"수록 부분 뒤 후는 복위하나 장씨의 음모 속에 복위 8년 만에 35세로 세상을 떠난다. 진상을 안 왕은 장씨에게 사약을 내리고 관련자를 처형하며 제문으로 넋을 위로한다.","feel":"애도","who":["숙종","장희빈"]}],"key":"폐위된 인현왕후의 인내와 겸손을 장희빈의 횡포와 대비하며 복위까지 그린 궁중 문학","pt":["‘큰 개’는 사안을 색다르게 인식하는 후의 모습을 부각함(4번)","ⓑ는 짐승과 견줘 도리 없는 세태를 비판, ⓔ는 반전의 조짐(5번)","장씨는 후를 없애려 했고 조정 소인들은 후의 가족 처벌을 아룀(3번)"],"src":"해설 p.94~96 · 본책 p.262~266","g":"고전산문","s":"수특 갈래 복합 4","th":"폐위와 복위, 인현 왕후의 덕행"},"w094":{"t":"목동가","a":"임유후","who":[["묻는 이(갑)","소 먹이는 아이에게 입신양명을 권하는 화자"],["목동(을)","분수를 지키며 살겠다고 답하는 아이"]],"steps":[{"h":"문가 ①","ev":"소를 먹이는 아이에게 인간 영욕을 아는지 묻고, 인생 백 년은 풀끝의 이슬이라 오래 살아도 덧없다고 한다. 장수와 단명은 운명이라 정할 수 없다고 말한다.","feel":"무상","who":["묻는 이(갑)","목동(을)"],"q":"인생 백년이 풀끝에 이슬이라"},{"h":"문가 ②","ev":"공명도 못 이루고 초목처럼 썩으면 서글프지 않으냐며, 이름을 후세에 전하는 것이 대장부의 할 일이니 입신양명에 힘쓰라고 권한다.","feel":"권유","who":["묻는 이(갑)"],"q":"아름다운 이름을 후세에 전함은 대장부의 할 일이라"},{"h":"답가 ①","ev":"초췌한 모습의 질문자를 굴원·유자후 같다고 하며 근심을 헤아린다. 영락은 운수에, 부귀는 하늘에 달렸으니 구한다고 얻겠느냐고 답한다.","feel":"달관","who":["목동(을)","묻는 이(갑)"],"q":"영락(榮落)은 운수에 달렸고 부귀는 재천(在天)이라"},{"h":"답가 ②","ev":"자유롭게 지내는 송아지, 배불리 먹어도 쟁기에 매인 소, 화려하게 꾸며져 희생으로 죽는 소를 견주어 보고 나는 내 분수만 지키겠다고 한다.","feel":"안분지족","who":["목동(을)"],"q":"우리는 잘 보아 내 분수만 지키려니"}],"key":"입신양명을 권하는 묻는 노래와 분수를 지키겠다는 목동의 답가로, 두 삶의 태도를 모두 담은 문답 가사이다","pt":["‘갑’은 입신양명을, ‘을’은 부귀공명을 구하지 않는 분수의 삶을 말하며 서로 맞선다","‘을’은 ‘갑’에게 배우려는 것이 아니라 반대 입장을 밝힌다(‘어리석어 대도를 몰라’)","세 소: 자연에서 검소하고 자유로운 삶, 넉넉하나 고단한 삶, 화려하나 위태로운 삶"],"src":"해설 p.96~98 · 본책 p.267~270","g":"고전시가","s":"수특 갈래 복합 5","th":"출사와 안분지족의 삶"},"w095":{"t":"풍계육가","a":"이정","who":[["화자","시냇가 띠집에서 청빈하게 사는 사람"],["세상 사람들","끝없는 욕심으로 작록을 좇는 이들"]],"steps":[{"h":"제1수","ev":"맑은 바람과 밝은 달이 좋아 창도 닫지 않고 잠도 들지 않는다. 옛사람이 이 두 가지를 두고 어디로 혼자 갔느냐며 자연의 좋음을 강조한다.","feel":"애호","who":["화자"],"q":"옛 사람이 두 가지 두고 어디 혼자 갔노"},{"h":"제2수","ev":"내가 무엇이라고 작록을 마음에 두겠느냐며, 시내 위에 조그만 띠집을 짓고 어젯밤 손수 닫은 문을 늦도록 닫아 둔다. 세속과 거리를 둔다.","feel":"소박","who":["화자"],"q":"내라서 누구라 하여 작록(爵祿)을 마음에 둘꼬"},{"h":"제4수","ev":"두고 또 두려는 세상 사람들의 욕심은 끝이 없다고 비판한다. 내 집을 둘러보니 낚싯대 하나 외에 걸릴 것이 전혀 없어 우습다며 청빈을 내세운다.","feel":"청빈","who":["화자","세상 사람들"],"q":"우습다 낚싯대 하나 외에 거칠 것이 전혀 없어라"},{"h":"제6수","ev":"오두미 같은 작은 녹봉 때문에 홍진에 나가지 말라고 경계한다. 바람과 비가 어지럽고 칼과 톱이 무서우니 나중에 후회해도 소용없다고 한다.","feel":"경계","who":["화자"],"q":"오두미 위하여 홍진(紅塵)에 나아가지 마라"}],"key":"맑은 바람·밝은 달을 사랑하는 자연 친화적 삶과, 작은 녹봉에 흔들리지 말라는 세속 경계의 연시조이다","pt":["열린 창(제1수, 자연과의 교감)과 닫힌 문(제2수, 세속과의 거리)의 대비","제4수 ‘낚싯대 하나 외에’는 청빈한 안분지족으로, 끝없는 세상의 욕심과 대비된다","제6수 ‘오두미’(도연명 고사)는 작은 녹봉 때문에 홍진에 들지 말라는 경계이다"],"src":"해설 p.96~98 · 본책 p.268","g":"고전시가","s":"수특 갈래 복합 5","th":"자연 친화와 세속 경계"},"w096":{"t":"고금군자은현론","a":"김시습","who":[["글쓴이","출세와 은거를 의리와 시의로 가르는 논자"],["옛 성현","의리와 시의에 따라 나아가고 물러난 인물들"],["거짓 은자","이익과 이름을 노려 은둔하는 척하는 자"]],"steps":[{"h":"문제 제기","ev":"군자의 처신은 어려워, 이롭다고 서둘러 벼슬에 나서도 안 되고 위태롭다고 거리낌 없이 물러나도 안 된다고 말한다.","feel":"신중","who":["글쓴이"]},{"h":"공자의 예","ev":"공자가 급히 제나라를 떠난 것도, 노나라를 느릿느릿 떠난 것도 억지가 아니라 의리와 시의에 맞는지에 따라 정한 것이라 설명한다.","feel":"확신","who":["글쓴이","옛 성현"],"q":"의리에 합당한가와 시의에 맞는가"},{"h":"판단 기준","ev":"선비의 거취는 의리에 맞는지, 도를 행할 만한지를 헤아려 정해야 하며, 떠났다고 어질고 벼슬했다고 구차한 것도, 은거했다고 고상한 것도 아니라고 한다.","feel":"단언","who":["글쓴이"]},{"h":"엇갈린 사례","ev":"미자는 마땅히 떠났고 이윤과 부열은 나아갈 만해 벼슬했으며, 백이·숙제의 은거도 강태공의 출사도 각자의 상황에 따랐을 뿐이어서 고상함이나 구차함으로 가를 수 없다.","feel":"균형","who":["글쓴이","옛 성현"]},{"h":"주역 인용","ev":"『주역』 고괘는 왕후를 섬기지 않는다고, 건괘는 대인을 만나 봄이 이롭다고 했으니, 상반된 말도 각각 처한 상황에 따를 뿐이라고 뒷받침한다.","feel":"차분함","who":["글쓴이"]},{"h":"거짓 은거","ev":"이익을 탐해 작록을 사양하는 간교한 신하, 이름을 얻으려 은둔하는 척하는 선비, 은자를 자처하며 남을 꾸짖는 이는 서시를 흉내 내는 추녀 같아 거론할 것도 없다고 비판한다.","feel":"비판","who":["글쓴이","거짓 은자"]}],"key":"출세와 은거는 겉모습이 아니라 의리와 시의로 가르며, 이름과 이익을 노린 거짓 은거는 비판한 논","pt":["벼슬함과 물러남을 겉모습이 아닌 '의리'와 '시의'로 판단하는 논지","공자·미자·이윤과 부열·백이와 숙제·강태공의 엇갈린 사례와 『주역』 인용이 논지를 받치는 방식","(가) 「목동가」·(나) 「풍계육가」와의 공통점(대조적 표현으로 지향 가치 강조)과 (다) 이해 문항"],"src":"해설 p.96~97 · 본책 p.268~272 · 수록 부분만","g":"극·수필","s":"수특 갈래 복합 5","th":"의리와 시의에 따른 거취"},"w097":{"t":"낙원은 가시덤불에서","a":"한용운","who":[["화자","자연의 순환에서 인생의 이치를 깨닫는 사람"],["청자","‘아십니까’로 말을 건네는 상대"]],"steps":[{"h":"1연","ev":"죽은 듯한 매화 가지에 꽃방울을 맺게 하는 쇠잔한 눈 위로 봄기운이 오는데, 그 향기가 눈에서 온 줄을 아느냐고 묻는다.","feel":"경이","who":["화자","청자"]},{"h":"2연","ev":"가을 빈 산의 붉은 단풍은 곱지만, 그것은 지난여름의 무르녹은 녹음이 준 것임을 아느냐고 묻는다.","feel":"통찰","who":["화자","청자"]},{"h":"3연 앞","ev":"한 포기 풀이 큰 불상이 되고 큰 불상이 한 포기 풀이 되며 천지는 한 보금자리라고, 작고 큼이 둘이 아님을 말한다.","feel":"깨달음","who":["화자"]},{"h":"3연 끝","ev":"자연의 거울에 인생을 비춰 보고, 고통의 가시덤불 뒤에 환희의 낙원을 세우려 님을 떠난 자신이 행복하다고 말한다.","feel":"행복","who":["화자"],"q":"나는 아아 행복입니다"}],"key":"사라짐 뒤에 새로 태어나는 자연의 순환을 인생에 비추어, 고통 뒤의 낙원에 행복해한다.","pt":["쇠잔한 눈 위의 봄기운, 빈 가을 산의 단풍 — 자연의 순환(소멸과 생성)을 인생에 대응","‘일경초가 장륙금신이 되고’는 작은 것과 큰 것이 둘이 아님을 나타내는 역설","‘님을 떠난 나는 아아 행복’은 이별의 고통 뒤에 환희가 온다는 인식을 담은 역설"],"src":"해설 p.99~101 · 본책 p.273~277","g":"현대시","s":"수특 갈래 복합 6","th":"고통의 수용과 낙원의 의미"},"w098":{"t":"산에 대하여","a":"신경림","who":[["화자","낮은 산에서 사람 사는 이치를 읽는 사람"],["낮은 산","힘없는 보통 사람들을 닮은, 의인화된 산"],["높은 산","크고 험해 사람들이 올려다보는 산"]],"steps":[{"h":"1~2행","ev":"산이라 해서 다 크고 높고 험하고 가파른 것은 아니라며 산에 대한 통념을 부정한다.","feel":"일깨움","who":["화자","높은 산"]},{"h":"3~11행","ev":"낮은 산은 큰 산 아래 웃으며 엎드려 있고, 동네까지 내려와 사람 사는 꼴을 구경하며, 오르는 이에게 길이 되고 젊은 연인에게 숨을 자리가 되어 준다.","feel":"친근함","who":["낮은 산","높은 산"]},{"h":"12~21행","ev":"낮은 산은 때에 절고 지린내가 배어도 새소리를 듣는 기쁨과, 다투다가도 넝쿨처럼 어우러지는 사람 사는 재미를 안다고 말한다.","feel":"애정","who":["화자","낮은 산"]},{"h":"22~26행","ev":"사람이 다 크고 잘난 것만이 아니듯 모든 산이 크고 높은 것은 아니라며, 산과 사람의 다양성을 말한다.","feel":"긍정","who":["화자","높은 산"],"q":"산이라 해서 모두 크고 높은 것은 아니다"}],"key":"높은 산이 아닌 낮은 산에서, 힘없는 이웃들의 겸손과 더불어 사는 삶의 기쁨을 발견한다.","pt":["낮은 산=힘없는 평범한 사람들, ‘낮음’을 겸손·친근함으로 보는 가치 전환","처음과 끝의 ‘산이라 해서 …은 아니다’ 반복이 산과 사람의 다양성에 대한 인식을 강조한다","‘흰 구름을 겨드랑이에 끼고…’는 높은 산의 모습이지 낮은 산이 더 영속적임을 뜻하지 않는다"],"src":"해설 p.100~101 · 본책 p.273~277","g":"현대시","s":"수특 갈래 복합 6","th":"겸손과 공동체적 삶"},"w099":{"t":"능양시집 서","a":"박지원","who":[["글쓴이","조카의 시집에 머리말을 쓰는 연암 박지원"],["달사·속인","이치에 밝은 사람과 본 것이 적어 의심 많은 사람"],["종선","한 가지 법에 매이지 않는 시를 쓰는 조카(계지)"]],"steps":[{"h":"달사와 속인","ev":"달사는 이상하게 여길 것이 없지만 본 것이 적은 속인은 의심이 많아, 백로로 까마귀를 비웃고 물오리로 학의 긴 다리를 위태롭다고 여긴다.","feel":"개탄","who":["글쓴이","달사·속인"]},{"h":"까마귀 빛깔","ev":"까마귀 날개는 황금빛·녹색·자주색·비췻빛으로 변하니 푸르다 해도 붉다 해도 괜찮은데, 본디 정해진 색이 없는 것을 눈과 마음이 먼저 정해 버린다고 지적한다.","feel":"비판","who":["글쓴이","달사·속인"]},{"h":"검은색의 이치","ev":"검은 것을 어둡다 하는 이는 검은색도 모르는 것이니, 물은 깊어서 비추고 옻칠은 검어서 비치듯 빛깔이 있으면 빛이, 형체가 있으면 자태가 있다고 말한다.","feel":"통찰","who":["글쓴이"]},{"h":"미인의 자태","ev":"미인은 고개 숙임과 턱 괴기, 홀로 서 있기로 시를 알게 하는데, 단정하지 않다고 나무라는 것은 양귀비에게 치통을 앓는다고 꾸짖는 격이라 한다.","feel":"풍자","who":["글쓴이"]},{"h":"종선의 시","ev":"조카 종선은 한 가지 법에 매이지 않고 온갖 시체를 두루 갖춰 동방의 대가가 되었으니, 그의 시는 성당과 한위, 송명의 시체를 넘나든다.","feel":"칭찬","who":["종선"]},{"h":"맺음","ev":"세상이 까마귀를 비웃고 학을 위태롭게 여기는 것은 심하지만 계지의 동산 까마귀는 푸르렀다 붉었다 하며, 달사는 적고 속인이 많아도 말을 그칠 수 없다고 한다.","feel":"탄식","who":["글쓴이","종선"],"q":"세상에 달사는 적고 속인은 많다"}],"key":"까마귀 빛깔과 미인의 자태 비유로 고정 관념을 깨고, 종선의 열린 시를 칭찬한 서문","pt":["까마귀·미인 비유가 뒷받침하는 논지: 선입견·고정 관념 비판과 열린 시각","[가] 학생의 말 고르기와 ⓓ·ⓔ 구절 이해: 푸르렀다 붉었다 하는 까마귀, 달사는 적은 현실","같은 작가 박지원의 「공작관문고 자서」가 9모에 비연계로 출제됨"],"src":"해설 p.100 · 본책 p.274~277","g":"극·수필","s":"수특 갈래 복합 6","th":"고정 관념 비판과 새로운 시각"},"w100":{"t":"박꽃이 피어난 집(포화옥기)","a":"이학규","who":[["글쓴이","좁은 집에서 더위와 벌레에 시달려 병든 유배객"],["과객","장사로 객지를 다닌 서울 나그네, 머슴 이야기를 전한다"],["여관 머슴·종","더럽게 지내도 편히 자고 병 없이 사는 이들"]],"steps":[{"h":"좁은 집","ev":"글쓴이의 집은 키가 한 길이 안 되고 너비도 아홉 자가 못 되어 갓이 걸리고 무릎을 굽혀야 눕는 데다, 한여름 볕에 창이 달아오른다.","feel":"답답함","who":["글쓴이"]},{"h":"박 넝쿨","ev":"담장 밑에 심은 박 넝쿨이 지붕을 덮어 그늘은 생겼으나 파리·모기와 뱀이 꾀어 밤마다 괴로워하다, 걱정과 피로로 소갈병과 우울증까지 얻는다.","feel":"괴로움","who":["글쓴이"]},{"h":"과객의 사연","ev":"과객은 무더운 여관에서 잠자리를 못 견뎌 자리를 옮겨 다녔지만, 여관 머슴과 종은 남은 음식을 먹고도 눕자마자 잠들어 병 없이 천수를 누린다고 말한다.","feel":"관찰","who":["과객","여관 머슴·종"]},{"h":"머슴의 비결","ev":"머슴과 종은 자기가 사는 곳을 여관으로 여기고 운명과 분수를 받아들여, 분개하거나 탄식으로 기운을 허비하지 않기에 병도 고통도 없다는 것이다.","feel":"달관","who":["과객","여관 머슴·종"]},{"h":"여관 속의 여관","ev":"세상이 하룻밤 묵는 여관인데 글쓴이는 그 안에서 또 후미진 골짜기에 몸을 숨겼으니, 속의 불을 돋워 원기를 해치는 셈이라고 과객이 일깨운다.","feel":"깨우침","who":["과객","글쓴이"],"q":"여관 속의 여관"},{"h":"글쓴이의 성찰","ev":"성현을 배우려는 이가 머슴과 종만도 못하냐는 물음을 들은 글쓴이는 그 말을 다듬어 벽에 적고 이 글을 박꽃이 피어난 집의 기문으로 삼는다.","feel":"성찰","who":["글쓴이"]}],"key":"여관 머슴처럼 처지를 받아들이면 고통스러운 삶의 조건도 이겨 낸다는 과객의 말에서 얻은 깨달음","pt":["좁은 집의 고통과 박 넝쿨의 양면성, 과객이 사연을 들려주는 말하기 방식","ⓐ 여관과 ⓑ 여관 속의 여관: 과객이 비유로 일깨우려는 것","㉠·㉡ 말에 담긴 의도: 상대의 지향을 상기시킴, 괴로움을 스스로 일으킨다는 지적"],"src":"해설 p.102 · 본책 p.278~282","g":"극·수필","s":"수특 갈래 복합 7","th":"삶의 조건과 극복의 지혜"},"w101":{"t":"한데서 울다","a":"공선옥","who":[["정희","시골에 살며 도시 집을 구하러 다니는 주부"],["번개탄 장수","아이를 태우고 트럭으로 물건을 파는 사내"],["남편","전원생활 출퇴근에 지친 정희의 남편"],["시어머니","시골에서 온화해져 가는 정희의 시어머니"]],"steps":[{"h":"앞부분 줄거리","ev":"집을 구하러 도시에 간 정희는 주차장에서 불쾌한 수작을 거는 사내를 맞닥뜨려 황급히 차를 몰아 돌아오며 마음이 불안하다.","feel":"불안","who":["정희"]},{"h":"가족과 정희","ev":"남편은 긴 출퇴근에 짜증을 내다 동네 처녀를 태워 다니며 누그러졌고 아이들과 시어머니는 시골에 적응했지만, 정희는 도시로 나가려는 까닭을 설명할 수 없다.","feel":"답답함","who":["정희","남편","시어머니"]},{"h":"아침의 소리","ev":"정희는 아침마다 확성기로 번개탄과 간고등어를 외치는 트럭 소리가 듣기 싫지만, 도시 산동네에서 늘 듣던 눈물겨운 삶의 소리임도 알고 있다.","feel":"짜증","who":["정희","번개탄 장수"]},{"h":"트럭과 마주침","ev":"(중략) 총기 사건으로 마을을 떠나고 싶던 일을 떠올리던 정희는 길에서 트럭과 마주쳐 모른 척하지만, 옆자리에서 손을 흔드는 아이를 보고 놀라 경적을 울려 세운다.","feel":"놀람","who":["정희","번개탄 장수"]},{"h":"대화와 외상","ev":"사내는 어제 아이 엄마가 아기를 낳았다고 하고, 정희는 간고등어와 아부래기를 사다 지갑이 없자 외상을 부탁하며 아이에게 마음이 끌린다.","feel":"누그러짐","who":["정희","번개탄 장수"]},{"h":"눈물","ev":"트럭이 떠난 뒤 시내 주차장 일이 떠올라 진저리를 치던 정희는 내일부터 시내 나갈 일도 차도 없애겠다고 다짐하다 쏟아지는 눈물에 시동을 끈다.","feel":"복받침","who":["정희"]}],"key":"도시 집을 찾아 헤매던 정희가 미워하던 번개탄 장수와 마주해 오해를 풀고 마음의 방황을 매듭짓는 이야기","pt":["[A]·[B]의 공통점: 감각적 이미지를 쓴 상황 묘사로 정희의 불쾌감을 생생하게 표현","㉠~㉤ 구절의 속뜻: 모른 척하는 정희의 반감, 삐죽거리는 속마음, 새 집을 찾지 않겠다는 다짐","보기: 타인과의 만남으로 인식이 확장됨, 번개탄 장수에 대한 부정적 인식의 전환"],"src":"해설 p.102~103 · 본책 p.279~282 · 수록 부분만","g":"현대소설","s":"수특 갈래 복합 7","th":"폭력적 도시와 물질만능주의 가치관에 상처 입은 현대인의 방황"},"w102":{"t":"남도 기행","a":"홍성원","who":[["서울 낚시꾼","낚시로 해방감을 느끼며 바다 오염에 노여워하는 사람"],["김선두","남도 토박이 뱃사람, 바다 오염의 실상을 아는 사람"]],"steps":[{"h":"새벽 바다·수록","ev":"서울 낚시꾼은 남도 바다에서 낚시하며 일상의 속박을 벗는 해방감을 맛보려 단골로 토박이 김선두의 배를 타고 새벽 바다로 나선다.","feel":"해방감","who":["서울 낚시꾼","김선두"]},{"h":"기름 유출·수록","ev":"김선두가 작년 외국 화물선 기름 유출로 다른 갯가의 양식장이 기름밭이 된 이야기를 하자, 서울 낚시꾼은 노여움에 눈을 질끈 감는다.","feel":"노여움","who":["서울 낚시꾼","김선두"]},{"h":"쓰레기 투기·수록","ev":"낚시 내내 김선두가 담뱃갑과 맥주병, 초콜릿 껍질까지 예사로 바다에 던지자, 못마땅해하던 서울 낚시꾼은 점잖게 한마디 한다.","feel":"반감","who":["서울 낚시꾼","김선두"]},{"h":"반박·수록","ev":"김선두는 들은 체 만 체하다 도리어 시비 걸듯, 바다 오염 얘기만 나오면 복장이 터진다며 비아냥 섞인 표정으로 맞선다.","feel":"울분","who":["김선두"],"q":"나가 버린 이따구 종이때기가 바다를 오염시킨다고라?"},{"h":"양식장 실상·수록","ev":"김선두는 오염의 으뜸 원인으로 연근해에 빈틈없이 설치된 양식장 시설물과, 연작으로 굴 배설물이 쌓여 오니가 된 양식장을 꼽고 서울 낚시꾼은 기막혀한다.","feel":"기막힘","who":["김선두","서울 낚시꾼"]},{"h":"뒷부분","ev":"해설에 따르면 이야기는 인간의 이기심이 인간에 대한 폭력으로도 드러남을 짚으며, 김선두가 광주민주화운동이 은폐·왜곡된 현실에 바다 오염 때만큼 분개하는 모습으로 이어진다.","feel":"분노","who":["김선두"]}],"key":"개인의 쓰레기와 구조적 오염을 맞세워 환경 파괴를 낳는 인간의 이기심을 되돌아보게 한다.","pt":["서술: [A]는 사건 정보로 상황의 심각성을, [B]는 관찰한 행동에 대한 반감을 제시(1번 ②)","ⓐ 김선두의 심리: 사람들이 아는 것과 달리 직접 원인은 양식장 시설물임을 알리고 싶어 함(3번 ④)","(가)·(나)는 생태 중심 사고로 인간의 이기적 행태를 비판 — 인간과 자연의 상호관계성(〈보기〉)"],"src":"해설 p.104~105 · 본책 p.283~287 · 뒷부분은 해설 줄거리","g":"현대소설","s":"수특 갈래 복합 8","th":"환경 파괴와 인간의 이기심"},"w103":{"t":"한 그루 나무처럼","a":"윤대녕","who":[["글쓴이","산에서 만난 참나무와 교감하며 삶을 돌아보는 사람"],["참나무","녹슨 못을 뽑아 준 글쓴이의 우주나무"]],"steps":[{"h":"녹슨 대못","ev":"약수터 옆 참나무에 박힌 녹슨 대못이 먼저 눈에 띄었으나 빼지 못하고 내려온 글쓴이는, 다음 주말 장도리를 챙겨 올라가 못을 빼내고 후련해한다.","feel":"후련함","who":["글쓴이","참나무"]},{"h":"인연","ev":"이후 마음이 심란하거나 공허할 때마다 참나무를 찾아가 그늘에서 책을 읽고 커피를 마시며, 나무가 위로의 말을 건네는 듯한 교감을 느낀다.","feel":"친근함","who":["글쓴이","참나무"]},{"h":"우주나무","ev":"지상과 천상을 잇는 우주나무 신화처럼 글쓴이는 평범한 참나무를 자신의 우주나무로 삼고, 어머니가 편찮으실 때 나무 앞에서 건강을 빌어 쾌유를 맞는다.","feel":"믿음","who":["글쓴이","참나무"]},{"h":"겨울 나무","ev":"눈 내린 주말 참나무는 잎을 모두 떨군 채 찬바람 속에 말없이 서 있고, 못을 뺀 자리의 상처는 아직 아물지 않았다.","feel":"숙연함","who":["글쓴이","참나무"]},{"h":"반성","ev":"헐벗은 나무를 보며 글쓴이는 사소한 일에 자주 흔들리고 상처를 받으면 원망했으며, 변함없이 기다려 준 적이 있었는지 스스로 돌아본다.","feel":"반성","who":["글쓴이"]},{"h":"다짐","ev":"자기 자리에 뿌리내리고 변화를 조용히 받아들이며 누군가 기대어 쉴 수 있는, 겉모습은 변해도 속마음은 변하지 않는 한 그루 나무처럼 살고 싶다고 다짐한다.","feel":"다짐","who":["글쓴이"],"q":"이제부터는 한 그루 나무처럼 살고 싶다."}],"key":"녹슨 못을 뽑으며 시작된 참나무와의 교감이, 한 그루 나무처럼 변함없이 살겠다는 다짐으로 이어진다","pt":["참나무와의 인연 전개(㉮~㉲ 도식): 대못 발견 → 못 뺌 → 자주 찾음 → 우주나무 → 겨울나무","ⓑ 헐벗은 나무가 지난날을 돌아보고 성찰하게 하는 계기가 되는 구성","보기(생태 중심 시각)로 (가) 「남도기행」과 견주기: 상처 난 자리와 인간의 반성"],"src":"해설 p.104 · 본책 p.284~287 · 수록 부분만","g":"극·수필","s":"수특 갈래 복합 8","th":"나무와의 교감과 삶의 성찰"},"w104":{"t":"참회록","a":"윤동주","who":[["화자","부끄러운 시대와 삶을 참회하며 성찰하는 사람"],["구리 거울","자기 얼굴을 비춰 성찰하게 하는 사물"]],"steps":[{"h":"1연","ev":"파란 녹이 낀 구리 거울 속에 남은 자기 얼굴을, 어느 왕조의 유물이기에 이다지도 욕되냐며 부끄러워한다.","feel":"부끄러움","who":["화자","구리 거울"]},{"h":"2연","ev":"참회의 글을 한 줄에 줄이자며, 만 스물네 해 한 달을 무슨 기쁨을 바라 살아왔느냐고 탄식한다.","feel":"탄식","who":["화자"]},{"h":"3연","ev":"언젠가 즐거운 날에는 또 한 줄의 참회록을 써야 하며, 그때는 지금의 부끄러운 고백을 참회하게 되리라 내다본다.","feel":"다짐","who":["화자"]},{"h":"4~5연","ev":"밤마다 손바닥과 발바닥으로 거울을 닦으면, 운석 밑으로 홀로 걸어가는 슬픈 사람의 뒷모양이 나타나리라 한다.","feel":"각오","who":["화자","구리 거울"]}],"key":"거울을 닦는 치열한 자기 성찰로, 현재의 참회까지 다시 참회하며 홀로 걷는 슬픈 희생의 길을 감내하려 한다.","pt":["‘구리 거울’은 자기 삶을 비춰 성찰하게 하는 매개, ‘어느 왕조’는 나라를 잃은 부끄러움과 연결","시간 구조: 과거·현재의 참회, 미래에 지금의 참회를 다시 참회하는 이중 참회","‘그 어느 즐거운 날’은 독립의 날이나, ‘무슨 기쁨을 바라’의 기쁨이 조국 독립인 것은 아니다"],"src":"해설 p.106~108 · 본책 p.288~290","g":"현대시","s":"수특 갈래 복합 9","th":"부끄러움에 대한 참회와 희생 의지"},"w105":{"t":"녹을 닦으며—공초 14","a":"허형만","who":[["화자","새 집 대문의 녹을 닦으며 지난 삶을 돌아보는 사람"],["대문의 녹","화자 생애의 회한을 비추는 사물"]],"steps":[{"h":"1~6행","ev":"이사 온 집 흑갈빛 대문의 녹을 닦으며, 자기 생애에는 얼마나 지독한 녹이 슬었을지 부끄럽고 죄스러워 손이 아린 줄도 모른다.","feel":"부끄러움","who":["화자","대문의 녹"]},{"h":"7~11행","ev":"녹을 닦다 깊고 어두운 생명 저편에서, 비늘처럼 돋은 회한의 슬픈 역사를 보고 혼신의 힘으로 일어서는 바다 위 빗방울에 견준다.","feel":"회한","who":["화자"]},{"h":"12~19행","ev":"마흔세 해의 불면과 철없던 사랑까지 영혼에 녹으로 슬어 있음을 보고, 손가락이 부르트도록 온몸으로 문지른다.","feel":"반성","who":["화자","대문의 녹"],"q":"온몸으로 온몸으로 문지르고 있었다"}],"key":"대문의 녹을 닦다가 마흔세 해 생애의 회한을 마주 보고, 치열하게 자기를 반성한다.","pt":["녹을 닦는 일이 자기 성찰로 바뀌는 구조 — 대문의 녹(사물)과 생애의 녹(회한)의 대응","부제 ‘공초’(심문받으며 하는 진술)가 더하는 자기 심문의 뜻, 전봉준의 삶에 비춘 성찰","‘온몸으로 온몸으로’ 반복이 절실한 심정을 강조하고, ‘마흔세 해’는 생애 전체의 회한"],"src":"해설 p.107~108 · 본책 p.288~290","g":"현대시","s":"수특 갈래 복합 9","th":"회한과 자기 성찰"},"w106":{"t":"선부 자화상","a":"김용준","who":[["글쓴이","자화상을 부탁받고 자신을 유쾌하게 돌아보는 사람"],["편집자","여성지에서 자화상을 청하는 약은 사람"]],"steps":[{"h":"청탁","ev":"원고를 번번이 거절해 오던 글쓴이는 여성지가 자화상을 청하자 거절하면 추남이라 그런다 할까 봐, 편집자의 약은 꾀에 넘어가 응한다.","feel":"마지못함","who":["글쓴이","편집자"]},{"h":"얼굴 자랑","ev":"자랑 삼아 자기 얼굴을 톨스토이 같기도, 문인과 묵객이 아끼는 괴석 같기도 하다며 몰리에르 코와 수염을 뽐내고 거울을 봐도 좋기만 하다고 익살을 부린다.","feel":"익살","who":["글쓴이"],"q":"내 얼굴 자랑이나 좀 해보자꾸나"},{"h":"우울의 재해석","ev":"좁고 찌푸린 양미간은 속이 빽빽해서가 아니라 깊이 숨은 우울이 나타난 것이며, 이 우울이 그림을 그리고 글을 읽으며 불량심을 바로잡게 한다고 본다.","feel":"긍정","who":["글쓴이"]},{"h":"호 선부","ev":"어느 자리에서 선부라는 호를 얻은 글쓴이는 선량하게 살고 싶다는 평생 소원이 있으면서 양심에 걸리는 일을 저지르고 참회해 왔음을 고백하며 마음이 움츠러든다.","feel":"참회","who":["글쓴이"]},{"h":"불선부도 좋다","ev":"선부가 과분하면 불선부도 좋고 친구가 그렇게 불러도 섭섭지 않다고 말하며, 자랑을 마치고 자화상을 보니 추남임에는 정이 떨어진다고 털어놓는다.","feel":"자조","who":["글쓴이"]},{"h":"마무리","ev":"아내가 늘 저런 줄 알았으면 시집을 안 왔겠다고 하는 고충도, 편집자가 얼굴을 장사하려는 속셈도 알기에 일필휘지로 자기 얼굴을 지면에 재현한다.","feel":"수용","who":["글쓴이","편집자"]}],"key":"추남이라 자랑하는 척 유머를 부리며, 우울과 '선부'라는 호에서 선하게 살려는 소원과 참회를 드러낸 수필","pt":["외모를 자랑하는 척하는 자기 희화화와 유머의 효과","우울을 그림·독서·자기 교정의 계기로 다시 보는 글쓴이의 시각","호 '선부'에 담긴 선하게 살려는 소원과 참회, ⓓ 묘사·ⓔ 인용 구절 이해"],"src":"해설 p.107 · 본책 p.289~292","g":"극·수필","s":"수특 갈래 복합 9","th":"자화상을 통한 자기 수용"},"w107":{"t":"멸치","a":"김기택","who":[["화자","식탁의 멸치를 보며 바다를 떠올리는 사람"],["멸치","굳었지만 몸에 바다의 물결을 지닌 존재"]],"steps":[{"h":"1~4행","ev":"딱딱한 멸치들은 굳기 전에 지느러미 사이의 물결이었고, 바닷속을 유유히 흘러 다니던 길이었다고 떠올린다.","feel":"회상","who":["화자","멸치"]},{"h":"5~13행","ev":"그물에 걸려 햇빛 속에서 물결이 길을 잃고 굳어, 길거리와 건어물집을 거쳐 기름에 튀겨져 접시에 담긴 과정을 짐작한다.","feel":"안쓰러움","who":["화자","멸치"]},{"h":"14~17행","ev":"젓가락 끝에 깍두기처럼 딱딱하게 집히는 멸치 속에 아직도 바다와 지느러미를 흔드는 물결이 있다고 본다.","feel":"경이","who":["화자","멸치"]},{"h":"18~21행","ev":"그 작은 물결과 무늬가 파도를 만들고 해일을 부르고 고깃배와 그물을 찢었던 힘이었다고 상상한다.","feel":"열망","who":["화자","멸치"],"q":"파도를 만들고 해일을 부르고"}],"key":"접시 위 굳은 멸치에서 바다의 물결을 다시 발견하며, 상실된 생명력의 회복을 암시적으로 소망한다.","pt":["굳은 멸치 속에서 다시 ‘바다’를 발견하는 인식 전환, 작은 물결이 파도·해일로 넓어지는 상상","‘지금’은 접시 위 멸치를 보는 때 — 굳은 멸치가 지금 생명력을 발휘한다는 뜻은 아님","바닷속→길거리→건어물집→접시의 구체적 공간으로 멸치가 이동해 온 과정과 변모를 드러낸다"],"src":"해설 p.108~110 · 본책 p.293~297","g":"현대시","s":"수특 갈래 복합 10","th":"생명력의 상실과 회복"},"w108":{"t":"버팀목에 대하여","a":"복효근","who":[["화자","쓰러진 나무와 버팀목에서 삶을 돌아보는 사람"],["나무","태풍에 쓰러졌다 버팀목 덕에 다시 선 나무"],["버팀목","삭아 사라졌지만 나무를 떠받치는 각목"],["아버지·이웃","화자의 버팀목이 되어 준 사라진 이들"]],"steps":[{"h":"1연","ev":"태풍에 쓰러진 나무를 고쳐 심고 각목으로 버팀목을 세웠던 일을 담담히 말한다.","feel":"담담함","who":["화자","나무","버팀목"]},{"h":"2~3연","ev":"산 나무가 죽은 나무에 기대어 싹이 트고 잔뿌리를 내리며 살아나고, 버팀목은 이윽고 삭아 없어진다.","feel":"차분함","who":["나무","버팀목"]},{"h":"4연","ev":"이제는 사라진 것이 나무를 버티고 있기에 큰바람이 불어와도 나무는 눕지 않는다고 말한다.","feel":"깨달음","who":["나무","버팀목"],"q":"사라진 것이 나무를 버티고 있기 때문입니다"},{"h":"5연","ev":"허위허위 길을 가다 만져 보면 죽은 아버지와 사라진 이웃들도 자신의 버팀목으로 만져진다고 말한다.","feel":"감사","who":["화자","아버지·이웃"]},{"h":"6연","ev":"언젠가 누군가의 버팀목이 되기 위해 싹 틔우고 꽃 피우며 살아가는지도 모른다고 깨닫는다.","feel":"다짐","who":["화자"]}],"key":"사라진 버팀목이 나무를 지탱하듯 아버지와 이웃의 버팀 위에 선 삶임을 알고, 나도 누군가의 버팀목이 되려 한다.","pt":["‘산 나무가 죽은 나무에 기대어 섰습니다’의 역설과, 사라진 버팀목이 나무를 버틴다는 인식","경어체(‘~습니다’)로 경건·차분한 분위기를 만들고, 자연 현상에서 사람 사이로 의미를 확장한다","버팀목 → 아버지·이웃 → 나도 누군가의 버팀목이 되겠다는, 이타적인 삶의 가치를 깨닫는 구조"],"src":"해설 p.108~110 · 본책 p.293~297","g":"현대시","s":"수특 갈래 복합 10","th":"서로 기대어 사는 삶"},"w109":{"t":"뿌리가 꽃이다","a":"정호승","who":[["글쓴이","방치한 수선화에서 뿌리의 가치를 깨닫는 사람"],["수선화","구근 덕에 어둠 속에서도 꽃을 피운 화분의 꽃"],["다산 주막 주모","유배 온 다산에게 국과 밥을 챙긴 여인"]],"steps":[{"h":"방치한 화분","ev":"1년 내내 베란다에 내버려 둔 화분에서 입춘 뒤 수선화 싹이 돋아 연노란 꽃이 피자, 글쓴이는 지난해 사 놓고 잊은 일이 미안해진다.","feel":"미안함","who":["글쓴이","수선화"]},{"h":"왜 피었나","ev":"햇빛 안 드는 1층 서향 집에서 동백은 죽었는데 수선화가 핀 까닭을 묻고, 구근이 자신의 본분과 본질을 잃지 않았기 때문이라고 답한다.","feel":"감사","who":["글쓴이","수선화"]},{"h":"역설","ev":"구근에 감사하는 순간 꽃이 뿌리로 보였다며, 꽃과 뿌리를 나누어 꽃의 가치만 중히 여기는 세태를 짚고 뿌리가 곧 꽃이고 꽃이 곧 뿌리라고 말한다.","feel":"깨달음","who":["글쓴이"],"q":"뿌리가 바로 꽃이고 꽃이 바로 뿌리다"},{"h":"회사후소","ev":"『논어』의 회사후소를 들어 흰 바탕이 있어야 그림을 그릴 수 있듯 본질적 갖춤이 있은 뒤에야 꾸밈이 가능하며, 뿌리 없이 꽃만 피어날 수는 없다고 풀이한다.","feel":"확신","who":["글쓴이"]},{"h":"다산과 주모","ev":"선비의 본질을 지킨 다산과, 유배 온 그에게 국과 밥을 챙겨 유배의 꽃을 피우게 한 주막 주모를 들며, 주모가 토양과 뿌리의 중요성을 말한 일도 소개한다.","feel":"존경","who":["글쓴이","다산 주막 주모"]},{"h":"나를 들여다봄","ev":"다시 수선화를 바라보며 글쓴이는 본질을 숨기고 가식을 두른 채 남과 비교하며 사는 자신을 보고, 뿌리에서 자신을 찾듯 나에게서 나를 찾아야 한다고 다짐한다.","feel":"반성","who":["글쓴이","수선화"]}],"key":"방치한 수선화가 핀 일에서 '뿌리가 곧 꽃'이라는 본질의 가치를 깨닫고 자신을 돌아보는 수필","pt":["'뿌리가 바로 꽃이고 꽃이 바로 뿌리다'의 역설과 ㉤ 꽃이 뿌리로 보이는 깨달음","『논어』 회사후소·다산과 주모의 예가 본질 중시의 논지를 뒷받침하는 방식","처음 장면(수선화)으로 돌아와 나를 성찰하는 구성, (가)·(나)와 묶은 보기 감상"],"src":"해설 p.109 · 본책 p.294~297","g":"극·수필","s":"수특 갈래 복합 10","th":"보이지 않는 뿌리(본질)의 가치"},"w110":{"t":"잘 익은 사과","a":"김혜순","who":[["화자","자전거를 타고 고향 마을 골목을 도는 사람"],["아가","엄마의 눈물을 받아먹다 먼 나라로 입양 가는 아기"],["할머니","구멍가게 평상에서 큰 사과를 먹는 노망든 노인"]],"steps":[{"h":"1~4행","ev":"자전거 바퀴 도는 소리가 백 마리 여치 우는 소리가 되고, 다시 정미소에 실려 온 나락이 빻아지는 소리가 된다.","feel":"몰입","who":["화자"]},{"h":"5~10행","ev":"처녀 엄마의 눈물만 받아먹다 유모차로 입양 가는 아가의 뺨보다 찬 구름이 화자의 손등을 덮어 주고, 그 구름에서 아가의 냄새가 난다.","feel":"연민","who":["화자","아가"]},{"h":"11~14행","ev":"자전거 바퀴가 골목 모퉁이를 돌 때마다 길을 둥글게 깎고, 돌아온 고향 마을만큼 큰 사과가 소리 없이 깎인다고 상상한다.","feel":"다독임","who":["화자"]},{"h":"15~17행","ev":"구멍가게 노망든 할머니가 평상에 앉아 그 큰 사과를 숟가락으로 파내 잇몸으로 오물오물 잡수신다.","feel":"평온","who":["할머니"],"q":"잇몸으로 오물오물 잘도 잡수시네요"}],"key":"자전거 소리에서 시작한 연상이 아픈 기억을 깎아 내는 사과로 이어져, 상처를 보듬는 평온한 마을에 닿는다.","pt":["9모: 자전거를 타며 얻은 감각 경험(소리)과 연상의 결합","9모: 골목을 도는 일을 사과 깎기로 보는 상상 — 고향 마을이 ‘큰 사과’","9모: 삶의 애환을 감싸 안는 공간으로의 전환"],"src":"해설 p.111~113 · 본책 p.298~301","g":"현대시","s":"수특 갈래 복합 11","th":"순환과 상처의 치유"},"w111":{"t":"강을 따라갔다 돌아왔다","a":"문태준","who":[["화자","강을 따라갔다 돌아오는 일생을 돌아보는 사람"],["강","삶의 시간과 여정, 삶의 흐름"]],"steps":[{"h":"1~3행","ev":"혼이 유빙처럼 떠가는 오늘, 이곳에서의 일생은 강을 따라갔다 돌아오는 일이라고 말한다.","feel":"쓸쓸함","who":["화자","강"]},{"h":"4~7행","ev":"붉던 꽃나무는 사라져 식은 허물이 되고, 유모차 뒤로 초라한 거지가 따라오며, 아침 노래 대신 텅 빈 둥지를 이게 되는 장면들을 본다.","feel":"허무","who":["화자"]},{"h":"8~9행","ev":"여동생과 아이들을 차례로 잃어, 슬프고 외롭고 애처로운 맨몸에 상복을 입는다.","feel":"슬픔","who":["화자"]},{"h":"10~17행","ev":"삶의 흐름이 구부러지고 갈라지는 것을 보지 않은 이가 누구냐고 되묻고, 강과 헤어지는 자신을 바라보며 집과 무덤으로 돌아온다.","feel":"무상함","who":["화자","강"]}],"key":"강을 따라갔다 돌아오는 일생의 상실과 비애를 겪고, 결국 집과 무덤으로 돌아오는 삶의 무상함을 성찰한다.","pt":["강=삶의 시간과 여정, 일생을 ‘강을 따라갔다 돌아오는 일’로 압축","‘집’과 ‘무덤’을 나란히 놓아 삶과 죽음을 한 흐름으로 보고, ‘누가 있을까’ 설의·도치를 반복","생성과 소멸의 대비(꽃나무–식은 허물, 아침 노래–텅 빈 둥지)는 이루지 못한 채 남는 현재의 공허감"],"src":"해설 p.111~113 · 본책 p.298~301","g":"현대시","s":"수특 갈래 복합 11","th":"삶의 여정과 상실"},"w112":{"t":"길의 안내자들","a":"김인숙","who":[["글쓴이","다롄에 머문 여행자, 길을 잃으면 되돌아가려 한다"],["향도","공항 길가에서 운전자 차에 동승해 길을 안내하는 사람들"]],"steps":[{"h":"여행은 터널","ev":"글쓴이는 모든 여행을 어둡지만 바깥으로 열린 터널에 빗대며, 지난 여행이 대개 실패였고 도착한 세상이 원하던 곳인 적은 드물었다고 돌아본다.","feel":"담담함","who":["글쓴이"]},{"h":"회귀하는 사람","ev":"길을 잃으면 되돌아갈 터널부터 찾는 글쓴이에게 남는 사진은 망설임과 초조함이지만, 잇몸을 드러내고 웃는 한 장이 위로가 되어 아직 살아 있음을 일깨운다.","feel":"위안","who":["글쓴이"]},{"h":"다롄의 향도","ev":"다롄 길가에 팻말을 든 향도들은 처음에 구직자로 보였으나, 운전자 차에 동승해 목적지까지 가장 빠르고 안전한 길을 안내하는 직업임을 알게 된다.","feel":"연민","who":["글쓴이","향도"]},{"h":"대가와 안내","ev":"향도는 땡볕 아래서 먼 곳을 물어 줄 손님을 기다리고, 여행자는 먼 길은 먼 만큼 대가를 치르며, 안내자는 모르는 길도 망설임 없이 일러 목적지에 닿는다.","feel":"공감","who":["글쓴이","향도"]},{"h":"그들의 귀로","ev":"글쓴이는 문득 안내자들이 멀리서 돌아오는 가난한 귀로를 떠올리고, 주먹 쥔 손 안의 몇 푼 동전을 놓치지 않으려 할 그들을 생각한다.","feel":"애잔함","who":["글쓴이","향도"],"q":"그들은 어떻게 돌아오나?"},{"h":"삶의 깨달음","ev":"삶도 아주 가난한 귀로이지만 다행히 텅 빈 손은 아니어서, 길에서 얻은 몇 푼의 동전처럼 가난해서 소중한 대가가 남는 것이 아니겠느냐고 맺는다.","feel":"깨달음","who":["글쓴이"]}],"key":"다롄 향도의 고단한 길 안내와 귀로를 보며, 삶의 여정이 남기는 '가난해서 소중한 대가'를 깨닫는다","pt":["여행을 터널(어둡지만 바깥으로 열린 길)에 빗댄 첫머리의 의미","향도의 고단한 노동과 '그들은 어떻게 돌아오나?'로 바뀌는 시선, ㉢ 귀로의 뜻","(다) 내용 이해 문항: 터널 비유, 향도에 대한 첫인상 오해, 대가를 치르고 낯선 이를 믿는 일"],"src":"해설 p.111~112 · 본책 p.299~302","g":"극·수필","s":"수특 갈래 복합 11","th":"여행과 삶의 대가"},"w113":{"t":"황새결송","a":"작자 미상","who":[["부자","경상도의 만석꾼. 송사에 진 뒤 우화로 풍자한다"],["그놈","재산 절반을 내놓으라 협박하는 패악한 일가"],["송관","청탁을 받고 그놈에게 유리하게 판결하는 관원"],["따오기","소리가 초라해 황새에게 청탁하는 새"],["황새","새들의 재판관. 청탁에 따라 판결한다"]],"steps":[{"h":"발단","ev":"경상도의 대대로 부자인 이에게 패악한 일가가 재산을 반으로 나누지 않으면 살지 못하게 하겠다며 불까지 놓으려 한다. 동리 사람들의 권유로 부자는 서울 형조에 송사를 낸다.","feel":"분함","who":["부자","그놈"],"q":"재물을 반 나누어 주면 무사하려니와"},{"h":"청탁과 판결","ev":"부자는 자기 잘못이 없다 믿고 아무도 찾지 않았지만 그놈은 형조 관리들에게 청길을 뚫어 두었다. 송관은 부자를 꾸짖으며 그놈이 달라는 대로 나누어 주라고 판결한다.","feel":"절통함","who":["부자","그놈","송관"],"q":"저놈 달라 하는 대로 나누어 주고"},{"h":"이야기 청함","ev":"분하지만 항의하면 매 맞을까 두려운 부자는 송사는 지고 가되 들음 직한 이야기 한 마디를 하겠다며 나선다. 송관은 우습게 여기나 이야기를 좋아해 허락한다.","feel":"억울함","who":["부자","송관"],"q":"들음 직한 이야기 한 마디 있사오니"},{"h":"새들의 다툼","ev":"꾀꼬리·뻐꾹새·따오기가 울음소리가 좋다고 다투다 황새에게 재판을 맡기기로 한다. 소리가 가장 초라한 따오기는 질 것을 알고 황새에게 청탁하기로 마음먹는다.","feel":"꾀","who":["따오기","황새"],"q":"아무렇거나 청촉이나 하면 필연 좋으리로다"},{"h":"황새의 판결","ev":"수록 부분 뒤 청탁을 받은 황새는 따오기에게 유리하게 판결한다. 이야기를 들은 송관과 그 무리도 청탁을 받고 잘못 판결한 자신들의 모습에 부끄러움을 느낀다.","feel":"부끄러움","who":["황새","송관"]}],"key":"청탁에 기운 송관의 판결을 부자가 꾸민 황새 재판 우화에 빗대 풍자한 액자 구성 소설","pt":["액자 구성: 부자의 송사 이야기 안에 황새 재판 우화. 뇌물 받는 관리를 겨냥","㉮ 녹비에 가로왈자: 기준을 바꾸면 진실과 무관한 판결이 나옴(3번)","[A] 뒤 전개: 청탁 후 황새의 편파 판결, 억울함과 조롱(4번, ⓐ-ⓓ-ⓔ)"],"src":"해설 p.114~115 · 본책 p.304~307","g":"고전산문","s":"수특 실전 1회","th":"송사의 부패를 우화로 풍자"},"w114":{"t":"만흥","a":"윤선도","who":[["화자","금쇄동 자연에서 분수대로 사는 사람(작가)"],["남들","띠집 짓는 화자를 비웃는 사람들"],["임금","자연의 삶을 누리게 해 준 은혜의 주체"]],"steps":[{"h":"제1수","ev":"산수 사이 바위 아래 띠집을 짓는다고 모르는 남들은 웃지만, 어리석은 내 뜻에는 그것이 내 분수인가 한다.","feel":"안분","who":["화자","남들"],"q":"어리고 햐암의 뜻에는 내 분(分)인가 하노라"},{"h":"제2수","ev":"보리밥과 풋나물을 알맞게 먹고 바위 끝 물가에서 실컷 노니, 그 밖의 여남은 일은 부러울 것이 없다.","feel":"만족","who":["화자"],"q":"그 남은 여남은 일이야 부러울 것이 있으랴"},{"h":"제3수","ev":"잔을 들고 혼자 앉아 먼 산을 바라보니 그리던 임이 온들 이만큼 반가우랴 한다. 말도 웃음도 없는 산이 못내 좋다.","feel":"기쁨","who":["화자"],"q":"그리던 임이 온들 반가움이 이러하랴"},{"h":"제4수","ev":"삼공이나 만승의 자리도 이만하랴 하며, 이제 생각하니 소부·허유가 약았더라고 한다. 임천에서 한가롭게 사는 흥취는 비길 곳이 없다.","feel":"자부","who":["화자"],"q":"임천한흥(林泉閑興)을 비길 곳이 없어라"},{"h":"제5수","ev":"천성이 게으른 줄을 하늘이 아시어 인간만사를 한 가지도 맡기지 않고, 다툴 이 없는 강산이나 지키라 하셨다고 한다.","feel":"만족","who":["화자"],"q":"인간만사(人間萬事)를 한 일도 아니 맡겨"},{"h":"제6수","ev":"강산이 좋다 한들 내 분수로 누릴 수 있었겠느냐고 묻고, 임금의 은혜를 이제 더욱 알겠다고 한다. 아무리 갚으려 해도 할 수 있는 일이 없다.","feel":"감사","who":["화자","임금"],"q":"임금 은혜(恩惠)를 이제 더욱 아나이다"}],"key":"남들의 비웃음에도 자연에서 분수대로 사는 흥취를 즐기고, 끝에서 임금의 은혜에 감사하는 6수 연시조이다","pt":["제6수는 물음(‘내 분으로 누웠느냐’)으로 자연 속 상황을 말한 뒤 ‘임금’을 부각한다","제3수 ‘그리던 임이 온들’은 먼 산을 보는 즐거움이 임보다 크다는 비교이다","제4수 ‘소부 허유가 냑돗더라’는 허유의 선택을 긍정하며 자연의 삶을 평가한다"],"src":"해설 p.115~116 · 본책 p.308","g":"고전시가","s":"수특 실전 1회","th":"자연 속 흥취와 연군지정"},"w115":{"t":"장춘정기","a":"기대승","who":[["글쓴이","정자 이름의 뜻을 묻고 마음의 봄을 일러 주는 사람"],["유중한","봄을 간직하겠다며 정자를 짓고 기문을 청한 사람"]],"steps":[{"h":"천지의 이치","ev":"천지의 조화는 쉼 없이 움직여 계절이 바뀌고 만물을 피우고 시들게 하는데, 군자는 이 이치를 음미해 마음을 쓰고 소인은 모른 채 부림을 받는다.","feel":"사색","who":["글쓴이"]},{"h":"장춘정","ev":"유중한이 죽포 어귀에 정자를 짓고 꽃을 심어 장춘정이라 이름 붙이고 글쓴이의 글도 걸려고 하자, 글쓴이가 봄을 간직한다는 그 이름의 뜻을 묻는다.","feel":"의문","who":["유중한","글쓴이"]},{"h":"유중한의 답","ev":"유중한은 봄을 간직할 수 없음을 인정하면서도 기이한 화초를 수십 종 심어 계절이 바뀌어도 꽃이 시들지 않아 늘 봄기운을 느끼며 조경순의 장춘오를 근거로 든다.","feel":"자부심","who":["유중한"]},{"h":"글쓴이의 반박","ev":"글쓴이는 형체 있는 것은 변화를 피할 수 없어 사월이 지나면 봄도 사라지니, 장자의 말처럼 봄을 간직한다는 것은 어리석고 공명과 부귀는 더욱 간직할 수 없다고 말한다.","feel":"단호함","who":["글쓴이","유중한"],"q":"봄은 조화의 자취이다"},{"h":"마음의 봄","ev":"하늘의 원·형·이·정과 사람의 인·의·예·지가 대응하고 측은지심이 모든 마음을 관통하니, 하늘이 준 것을 돌아보면 간직할 수 없는 봄이 내게 없었던 적이 없다고 한다.","feel":"확신","who":["글쓴이"],"q":"측은지심이 모든 마음을 관통한다"},{"h":"맺음","ev":"이 점을 음미해 마음을 다 쓰면 되지 않겠느냐는 말에 유중한이 그렇다고 하자, 글쓴이는 이 이야기를 정리해 장춘정의 기문으로 삼는다.","feel":"수긍","who":["유중한","글쓴이"]}],"key":"정자 이름 '봄을 간직함'을 문답으로 따져, 계절의 봄 대신 본성인 인(仁)이라는 마음의 봄을 일깨운 기문","pt":["'봄을 간직한다'는 이름을 둔 문답과 실제 봄(외적 가치)은 간직할 수 없다는 논거","결론의 '마음의 봄'은 본성인 인(仁), 원·형·이·정과 인·의·예·지의 대응","㉣ 이름의 뜻을 묻는 요청·㉤ 장자의 말 이해와 보기(공간과 장소, 장소애) 감상"],"src":"해설 p.115 · 본책 p.308~313","g":"극·수필","s":"수특 실전 1회","th":"마음속의 봄과 인(仁)"},"w116":{"t":"너무 큰 나무","a":"최일남","who":[["나","김 박사 댁 식모, 1인칭 서술자"],["아저씨(김 박사)","연구소 소장이자 유명인사, 겉과 속이 다른 사람"],["아주머니","‘참아라’를 되풀이하는 김 박사의 아내"],["심순이","월급이 오르는 옆집 식모, 비교 대상"]],"steps":[{"h":"소개","ev":"식모 ‘나’는 민족과 국가를 논하는 강연에 방송·신문 출연이 잦은 연구소 소장 아저씨가 자랑스러우면서도, 집에서 보는 그의 모습은 종종 납득이 안 된다.","feel":"자랑스러움","who":["나","아저씨(김 박사)"]},{"h":"전화·수록","ev":"전화벨이 울리면 엉덩이를 들먹이던 아저씨는 받자마자 의젓하고 점잖은 목소리와 근엄한 얼굴로 바뀌고, 식구를 대할 때와 바깥사람을 대할 때가 딴판이다.","feel":"어이없음","who":["나","아저씨(김 박사)"]},{"h":"글과 생활·수록","ev":"잡지에 식구끼리 터놓고 대화해야 한다고 쓴 아저씨가 정작 집에서는 식구들과 대화하는 일이 없음을 ‘나’는 이상하게 여긴다.","feel":"의아함","who":["나","아저씨(김 박사)"]},{"h":"월급·수록","ev":"‘나’가 옆집 심순이의 월급을 빗대어 올려 달라는 뜻을 비치자 아주머니는 참으라 하고, 아저씨가 ‘잘 달래라’ 하는 말을 엿들은 ‘나’는 서운해한다.","feel":"서운함","who":["나","아주머니","심순이","아저씨(김 박사)"],"q":"잘 달래서 따둑거리라구"},{"h":"선물 보따리·수록","ev":"아저씨 내외가 갈비짝과 비단을 차에 싣고 더 높은 분께 가는 듯하자, ‘나’는 세상에 알려진 아저씨가 왜 그러는지 고개를 갸웃거린다.","feel":"의아함","who":["나","아저씨(김 박사)","아주머니"]},{"h":"맺음·수록","ev":"멀리서 보면 아름답던 산이 막상 들어가면 별것 아니듯 가까이서 본 아저씨의 정체를 가늠하기 어려워, ‘나’는 어찌 판단할지 모른 채 혼란스러워한다.","feel":"혼란","who":["나"],"q":"아, 모르겠다. 아, 모르겠다."}],"key":"순박한 식모의 눈에 비친 김 박사의 겉과 속이 다른 모습으로 지식인의 위선을 풍자한다.","pt":["겉(잡지의 ‘대화’ 주장, 점잖은 전화)과 속(대화 없는 집안, 월급에 인색)의 괴리 = 위선 풍자","1인칭 서술: ‘나’의 마음은 직접, 아저씨의 속은 제한적으로 제시 — 선물의 의도는 독자가 추론(11번)","‘큰 나무 밑동에서는 꼭대기가 안 보인다’는 비유 — 가까이서 본 정체 판단이 어려운 난감함(14번)"],"src":"해설 p.118~119 · 본책 p.314~318 · ‘수록’ 외는 해설 줄거리","g":"현대소설","s":"수특 실전 1회","th":"지식인의 위선 풍자"},"w117":{"t":"모든 사라지는 것들은 뒤에 여백을 남긴다","a":"고정희","who":[["화자","어머니의 무덤을 찾은 자식"],["어머니","무덤에 잠들어 큰 여백을 남긴 어머니"],["너","훗날 화자가 여백으로 남고 싶은 상대"]],"steps":[{"h":"1연","ev":"무덤에 잠드신 어머니는 선산 뒤에 큰 여백을 걸어 두셨고, 그 아래 앉으면 서울에서 묻혀 온 잔소리들이 시냇물 따라 바다로 흘러간다.","feel":"그리움","who":["화자","어머니"]},{"h":"2연","ev":"‘오’ 하고 감탄하며, 모든 부재 뒤에 존재가 떠오른다고 하고 여백이 곧 쓸쓸함이자 탄생임을 깨닫는다.","feel":"깨달음","who":["화자"],"q":"그리하여 여백이란 탄생이구나"},{"h":"3연","ev":"자신도 너로부터 사라지는 날 마음의 잡초가 스러진 뒤, 노을이나 시냇물 같은 고요한 여백으로 남고 싶다고 소망한다.","feel":"소망","who":["화자","너"]}],"key":"어머니의 부재가 남긴 여백에서 쓸쓸함과 탄생을 함께 깨닫고, 자신도 누군가의 고요한 여백이 되길 바란다.","pt":["‘여백’은 부재(쓸쓸함)이자 새 탄생 — 죽음과 탄생의 순환(‘-구나’ 반복, 감탄사 ‘오’로 전환)","‘멧새의 발목을 툭, 치며’·‘쟁쟁쟁’ 음성상징어가 번잡한 일상과 멀어짐을 나타낸다","‘나도 너로부터 사라지는’은 이별이 자연스러운 이치임을 알고 닥쳐올 이별을 떠올리는 것"],"src":"해설 p.119~120 · 본책 p.319~321","g":"현대시","s":"수특 실전 1회","th":"죽음과 탄생의 순환"},"w118":{"t":"사과밭을 지나며","a":"나희덕","who":[["화자","이별한 상대를 마음에 무겁게 품어 온 사람"],["사과나무","열매를 내려놓고도 가지가 휜 채 빈 허공을 진 나무"],["나비","빈 가지에 앉았다 날아가 눈앞을 환하게 하는 존재"]],"steps":[{"h":"1연","ev":"가을엔 나비조차 부려야 할 몸이 무거운 듯 낮게 나는 것 같다고 느낀다.","feel":"무거움","who":["화자","나비"]},{"h":"2연","ev":"열매를 다 내려놓고도 사과나무의 휘어진 빈 가지는 펴지지 않고, 열매의 자리에 비어 있는 허공이 열매보다 더 무거울 것이라 여긴다.","feel":"미련","who":["화자","사과나무"]},{"h":"3연","ev":"빈 가지에 나비가 앉았다 날아가자 눈앞이 환해지고, 네가 어디선가 나를 내려놓았음을 깨닫자 옷이 나비 날개보다 가볍게 느껴진다.","feel":"홀가분함","who":["화자","나비","사과나무"],"q":"아, 네가, 네가, 어디선가 나를 내려놓았구나"},{"h":"4~5연","ev":"아주 뒤늦게 사과 한 알이 툭 떨어지고, 그 한 알을 내려놓는 데 오 년이 걸렸다고 말한다.","feel":"수용","who":["화자","사과나무"],"q":"오 년이 걸렸다"}],"key":"이별한 상대에 대한 미련이 휘어진 빈 가지처럼 남았다가, 나비를 계기로 오 년 만에 내려놓고 가벼워진다.","pt":["‘허공이 열매보다 더 무거울 것이다’의 역설 — 휘어진 빈 가지는 관계의 흔적","마지막 사과 한 알(남은 미련)을 내려놓는 ‘오 년’은 걸린 기간만 진술한 것(이유를 강조하지 않음)","나비를 계기로 옷이 ‘나비의 날개보다’ 가볍다는 홀가분함, ‘툭’은 분리의 순간을 강조"],"src":"해설 p.119~120 · 본책 p.319~321","g":"현대시","s":"수특 실전 1회","th":"이별의 수용과 극복"},"w119":{"t":"금환기봉","a":"작자 미상","who":[["장선빙","남장한 여성 영웅. 김희경의 정혼자"],["김희경","장선빙의 정혼자. 함께 장원급제한다"],["이영","장선빙을 구해 양자로 삼은 노인"],["영춘","장선빙의 시비. 걱정하며 조언한다"]],"steps":[{"h":"천상의 인연","ev":"월궁선녀와 문창성이 적강해 장자영의 딸 장선빙과 김정의 아들 김희경으로 태어나, 금지환을 주고받으며 백년가약을 맺는다.","feel":"설렘","who":["장선빙","김희경"]},{"h":"남장과 투신","ev":"유배된 아버지를 찾아가기로 한 장선빙은 위험에 대비해 남장을 하지만 아버지의 죽음을 알고, 김희경도 찾지 못하자 물에 몸을 던진다.","feel":"절망","who":["장선빙"]},{"h":"이영의 구함","ev":"남해용왕의 시녀가 준 환혼주로 깨어난 장선빙은 배 안에서 시비 설랑·영춘과 재회해 통곡한다. 이영이 내력을 묻자 장자영의 아들 수정이라 답한다.","feel":"감격","who":["장선빙","이영","영춘"],"q":"저는 전 이부상서 장자영의 아들입니다"},{"h":"과거 결심","ev":"김희경은 장선빙이 죽은 줄 알고 혼인하고, 이영은 장선빙을 양자로 삼는다. 이영의 권유로 과거를 보러 온 장선빙은 장원급제해 아버지의 원통함을 씻기로 결심한다.","feel":"결의","who":["장선빙","이영","김희경"],"q":"위로는 아버님의 원통함을 씻어 줄 수 있고"},{"h":"함께 급제","ev":"김희경은 장자영의 아들이 호명되자 놀라 의심하고, 곧 장선빙과 어전에 나란히 선다. 임금은 두 사람을 모두 쓰겠다며 김희경을 한림학사에, 장선빙을 태학사에 제수한다.","feel":"놀람·기쁨","who":["김희경","장선빙"],"q":"옥을 얻기 위해 진주를 버릴 수는 없는 법"},{"h":"영춘의 걱정","ev":"장선빙이 장원급제하고 돌아오자 시비 영춘이 기뻐하면서도 정혼자와의 맹약을 어찌하겠느냐고 걱정한다. 장선빙은 곧 그가 찾아올 것이니 답할 말이 있다고 안심시킨다.","feel":"침착함","who":["장선빙","영춘"],"q":"머지않아 나를 찾아올 것이니"},{"h":"결말","ev":"장선빙의 상소로 아버지 장자영이 청주후로 추증된다. 임금이 부마로 삼으려 하자 사정을 밝혀 김희경과 혼인하고 행복하게 살다 승천한다.","feel":"행복","who":["장선빙","김희경"]}],"key":"남장한 장선빙이 아버지의 원통함을 풀고 정혼자 김희경과 맺어지는 여성 영웅 소설","pt":["9모 연계: 남복을 입은 이유(부친의 원한 풀기)와 여성임을 밝히는 결정","9모 연계: 시비 영춘의 조언과 서로 존중하는 주종 관계","과거는 아버지의 억울함을 풀 수단(3번), 초월적 존재는 용왕의 시녀(4번)"],"src":"해설 p.120~121 · 본책 p.322~325","g":"고전산문","s":"수특 실전 2회","th":"여성 영웅의 활약과 남장 결연"},"w120":{"t":"산이 날 에워싸고","a":"박목월","who":[["화자","산에 에워싸여 소박한 삶을 일러 받는 사람"],["산","화자에게 삶의 방식을 말해 주는, 의인화된 산"]],"steps":[{"h":"1연","ev":"산이 화자를 에워싸고 씨나 뿌리고 밭이나 갈며 살라고 한다.","feel":"순응","who":["산","화자"]},{"h":"2연","ev":"짧은 산자락에 집을 모아 아들딸을 낳고 호박을 심으며, 들찔레처럼 쑥대밭처럼 살라고 한다.","feel":"소박함","who":["산","화자"]},{"h":"3연","ev":"사위어 가는 목숨을 그믐달처럼 살라고 거듭 말한다.","feel":"수긍","who":["산","화자"],"q":"그믐달처럼 살아라 한다"}],"key":"산이 일러 주는 말로, 욕심 없이 자연의 순리에 따라 소박하게 살겠다는 마음을 우회적으로 드러낸다.","pt":["산이 화자에게 말하는 구조와 ‘~살아라 한다’ 반복 — 지향하는 삶을 우회적으로 드러낸다","‘산’은 삶의 지침을 주는 존재이고, ‘그믐달’에는 차오르면 기우는 삶의 인식이 내재한다","‘들찔레’·‘쑥대밭’·‘그믐달’은 화려한 모습과 대조되는 소박하고 수수한 자연물"],"src":"해설 p.122~124 · 본책 p.326~329","g":"현대시","s":"수특 실전 2회","th":"자연 친화적 삶"},"w121":{"t":"흐름에 대하여","a":"문정희","who":[["화자","바다를 꿈꾸지만 산으로 가는 삶의 의미를 묻는 사람"],["바다","화자가 닿고 싶은 이상향"],["산","죽음으로 숙명처럼 닿게 되는 곳"]],"steps":[{"h":"1~2연","ev":"바다에 가서 바다가 되고 싶고, 흐른다는 것이 무엇인지, 흐름으로 키운 진주가 왜 슬픔처럼 영롱한지 알고 싶어 한다.","feel":"소망","who":["화자","바다"]},{"h":"3~4연","ev":"하늘은 왜 우리에게 햇살과 함께 자유를 주었는지, 우리들은 왜 흐르는지 삶의 이유와 의미를 묻는다.","feel":"의문","who":["화자"]},{"h":"5연","ev":"바다가 되지도 날개가 되지도 못한 채 약속처럼 산으로 가는 것은 왜냐고 묻는다.","feel":"안타까움","who":["화자","바다","산"]},{"h":"6연","ev":"한 벌 죽음으로 자유와 햇살을 빼앗기고 다만 혼자 제 목숨을 갖고 가는가 하고 탄식한다.","feel":"비애","who":["화자","산"],"q":"다만 혼자 제 목숨 갖고 가는가"}],"key":"바다에 닿고 싶지만 결국 죽음이라는 산으로 가는, 삶의 숙명적 한계와 비애를 묻는다.","pt":["바다(이상향)와 산(죽음으로 숙명처럼 닿는 곳)의 대비, ‘진주’는 흐름 속에 길러진 가치","‘왜 ~가’ 의문형 반복과 ‘~되지 못하고’ 부정 표현이 안타까움과 비애를 드러낸다","‘산’은 도피처가 아니라 어쩔 수 없이 닿는 운명적 공간 — 성장의 시로 읽으면 안 됨"],"src":"해설 p.122~124 · 본책 p.326~329","g":"현대시","s":"수특 실전 2회","th":"삶의 흐름과 숙명적 비애"},"w122":{"t":"한정록 서","a":"허균","who":[["글쓴이","벼슬살이 속에서 은거를 바라는 마흔두 살의 신하"],["소부·허유","요순 시대에도 귀를 씻고 세상을 버린 이들"]],"steps":[{"h":"은거의 뜻","ev":"선비가 벼슬을 하찮게 여겨 숲으로 숨고 싶겠느냐며, 도가 풍속과 어긋나고 운명이 시대와 맞지 않을 때에야 숨는 것이니 그 마음이 가엽다고 말한다.","feel":"연민","who":["글쓴이"],"q":"운명이 시대와 맞지 않을 때에만"},{"h":"소부·허유","ev":"요순이 다스리던 태평한 세상에서도 소부와 허유는 정사를 맡으라는 말을 더럽다며 귀를 씻고 떠났으니, 이들이 무엇을 보여주려는 것인지 의문을 던진다.","feel":"의아함","who":["글쓴이","소부·허유"]},{"h":"지난 삶","ev":"글쓴이는 제멋대로 자라 젊어 벼슬에 나갔다가 권세가의 미움을 사 노장과 불가로 도피했고, 마흔둘이 되도록 이룬 업적이 없는 자신이 안타깝다고 돌아본다.","feel":"자책","who":["글쓴이"]},{"h":"옛사람과 비교","ev":"골짜기를 차지해 즐기는 삶도, 자식을 키운 뒤 떠나는 삶도, 벼슬하며 산수를 즐기는 삶도 못 하고 권세를 좇아 허둥댄 자신을 옛 현자에 견주어 부끄러워한다.","feel":"부끄러움","who":["글쓴이"]},{"h":"신하의 책무","ev":"고위 벼슬아치로 임금의 교서를 짓는 자리에 있는 몸이라, 소부와 허유를 따라 임금과 모질게 결별하고 고상한 척할 수는 없다며 곧바로 숨지 못하는 처지를 밝힌다.","feel":"착잡함","who":["글쓴이","소부·허유"]},{"h":"소망","ev":"시대와 운명이 맞지 않아 옛사람과 비슷한 구석이 있으니, 몸이 건강할 때 조정에서 물러나 천수를 누리고 훗날 숲속 선비와 이 책을 논평하며 읽고 싶다고 소망한다.","feel":"소망","who":["글쓴이"]}],"key":"신하의 책무에 얽매여 곧바로 숨지 못하는 자책 속에서도 자연에 살고 싶다는 소망을 밝힌 서문","pt":["은거는 도와 운명이 시대와 맞지 않을 때의 선택이라는 관점과 ㉮ 소부·허유에 대한 생각","권세를 좇아 온 지난 삶에 대한 자책, 신하의 책무 때문에 곧바로 숨지 못하는 처지","같은 작가 허균의 「홍길동전」이 6모에서 작가 연계로 나옴"],"src":"해설 p.122 · 본책 p.327~329 · 수록 부분만","g":"극·수필","s":"수특 실전 2회","th":"은거론과 자기 성찰"},"w123":{"t":"고향","a":"이기영","who":[["김희준","동경 유학 뒤 귀향해 농민을 깨우치는 인물"],["안승학","지주를 대신해 소작농을 착취하는 교활한 마름"],["인동","수해 뒤 두렛돈을 도로 내놓는 마을 청년"],["갑숙","안승학의 딸, 가출해 공장 노동자가 된다"],["원터 사람들","수해와 소작료로 곤궁한 소작농 이웃들"]],"steps":[{"h":"발단","ev":"동경 유학에서 법학을 마친 김희준이 5년 만에 원터 마을로 돌아오니, 철도가 놓이고 제사공장이 들어섰는데도 사람들은 여전히 궁핍하다.","feel":"충격","who":["김희준","원터 사람들"]},{"h":"전개","ev":"황폐한 마을 모습에 놀란 희준은 농민을 깨우치겠다고 마음먹고 직접 소작을 부치며 활동하는 한편, 꾀 많은 마름 안승학과 부딪친다.","feel":"의지","who":["김희준","안승학"]},{"h":"수해·수록","ev":"큰물로 벼가 쓰러지고 집이 무너진 원터에서 희준은 두레 돈을 수해 입은 이들에게 나누자고 제의하고, 인동은 받은 돈을 더 어려운 이에게 돌리라며 도로 내놓는다.","feel":"동정","who":["김희준","인동","원터 사람들"]},{"h":"소작료·수록","ev":"흉작 속에 소작인들의 관심이 소작료 감면으로 쏠려 희준을 쳐다보고, 안승학이 거절하자 몰래 상경해 지주와 담판하여 타작관이 내려오게 된다.","feel":"절박함","who":["원터 사람들","안승학","김희준"]},{"h":"대립·수록","ev":"앙심을 먹은 안승학은 동생과 학삼이를 시켜 소작인들을 감시하지만, 희준은 이를 알고도 타작관의 간평 때 서두르자며 단속하고 속으로 회심의 웃음을 짓는다.","feel":"자신감","who":["안승학","김희준"]},{"h":"두레·수록","ev":"이태 동안 두레로 친목이 두터워진 원터 사람들은 서로의 사정을 살피고, 이웃을 외면한 집은 공동체의 유대에서 배제하는 힘을 보인다.","feel":"유대감","who":["원터 사람들"],"q":"한 푼이라도 남의 사정을 보려 들었다"},{"h":"결말(해설)","ev":"가출해 공장에 들어간 갑숙이 노동쟁의를 일으키자 희준이 이를 도우며 연대하고, 안승학을 압박해 소작농의 요구를 관철시킨다.","feel":"연대감","who":["갑숙","김희준","안승학"]}],"key":"수해와 소작료 문제 속에서 두레로 뭉친 원터 농민들이 희준을 중심으로 각성과 연대를 이룬다.","pt":["두레의 의미: 이기적으로 행동한 사람을 공동체 유대에서 배제해 공동 이익의 가치를 인식시키는 조직(13번 ⑤)","안승학: 근대 문물을 이용해 지위·부를 쌓았으나 농민을 착취 — 선악의 중립이라 보면 오답(12번 ③)","희준의 ‘회심의 웃음’은 혼자 속으로 하는 생각이라 민중과의 연대를 모색하는 장면은 아님(14번 ④)"],"src":"해설 p.124~125 · 본책 p.330~334 · 결말은 해설 줄거리","g":"현대소설","s":"수특 실전 2회","th":"농촌 현실과 두레를 통한 공동체 각성"},"w124":{"t":"규수상사곡","a":"작자 미상","who":[["화자","남의 아내가 된 여인을 그리는 남성"],["임","화자가 잊지 못하는, 이미 남의 아내가 된 여인"]],"steps":[{"h":"보고 싶네","ev":"임의 얼굴이 보고 싶다고 되풀이하며, 다시 못 볼 임이라 무심하고 가련하다고 한다. 임 못 봐 병이 되고 못 잊어 원수가 된다.","feel":"그리움","who":["화자","임"],"q":"보고 싶네 보고 싶네 임의 얼굴 보고 싶네"},{"h":"시름·눈물","ev":"시름이 골수에 젖어 입맛도 잠자리도 잃고 홀로 병들어 한숨만 쉰다. 임 생각에 흘린 눈물이 베개 아래 소를 이룬다고 과장한다.","feel":"괴로움","who":["화자"],"q":"임 생각하고 지는 눈물 베개 아래 소(沼)이로다"},{"h":"죽음 가정","ev":"내 무덤을 임이 찾아오겠느냐, 내가 죽으면 다시 생각이나 하겠느냐며 죽음을 가정한다. 열녀 정절을 본받는다고 천만 년을 사는 것은 아니라며 임을 설득한다.","feel":"절박","who":["화자","임"],"q":"열녀 정절 본받으면 천만 년을 살 것인가"},{"h":"호소","ev":"임을 직접 불러 목숨을 살려 달라고 애원한다. 목석이 아니면 인정이 있지 않겠느냐며, 눈에 암암 귀에 쟁쟁한 임을 못 보다 황천객이 되겠다고 호소한다.","feel":"애원","who":["화자","임"],"q":"목석이 아니거든 인정조차 없겠는가"}],"key":"남의 아내가 된 임을 향한 그리움을 반복·과장과 직접 부르는 호소로 쏟아내는 가사이다","pt":["‘보고 싶네’ 반복, ‘베개 아래 소(沼)’ 같은 과장, 임을 직접 부르는 호소가 핵심이다","제목과 달리 규수가 아니라 남성이 주체인 상사곡이다(그리는 대상은 남의 아내)","(가)는 현실에 기반한 상상, (나)는 변신 모티프의 비현실적 상상으로 그리움을 푼다"],"src":"해설 p.126 · 본책 p.335~336","g":"고전시가","s":"수특 실전 2회","th":"남의 아내가 된 임을 그리는 상사의 고통(남성 화자)"},"w125":{"t":"임 그린 상사몽이~","a":"박효관","who":[["화자","임을 그리워해 잠 못 이루는 가을밤의 사람"],["임","화자를 잊고 깊은 잠에 든 사람"]],"steps":[{"h":"초장","ev":"임을 그리워하며 꾸는 꿈이 귀뚜라미의 넋이 되기를 바란다. 사람이 아니라 귀뚜라미로 변신하겠다는 상상이다.","feel":"그리움","who":["화자"],"q":"임 그린 상사몽이 실솔의 넋이 되어"},{"h":"중장","ev":"긴 가을밤 깊은 때에 귀뚜라미의 넋으로 임의 방에 들어간다. 몸으로는 갈 수 없는 임에게 비현실적인 변신으로 다가간다.","feel":"간절함","who":["화자","임"],"q":"추야장(秋夜長) 깊은 밤에 임의 방에 들었다가"},{"h":"종장","ev":"나를 잊고 깊이 든 임의 잠을 깨워 볼까 한다. 자신을 잊은 듯한 임에 대한 서운함이 담겨 있다.","feel":"서운함","who":["화자","임"],"q":"날 잊고 깊이 든 잠을 깨워 볼까 하노라"}],"key":"귀뚜라미 넋이 되어 임의 방에 들어가 잠을 깨우겠다는 변신 상상으로 그리움을 푼 시조이다","pt":["변신 모티프로 임에게 다가가려는 비현실적 상상이 핵심이다","임을 ‘날 잊고 깊이 든 잠’을 자는 존재로 상상해 서운함을 드러낸다","「규수상사곡」은 현실에 기반한 상상, 이 시조는 비현실적 상상으로 그리움을 해소한다"],"src":"해설 p.126 · 본책 p.335~336","g":"고전시가","s":"수특 실전 2회","th":"꿈에서라도 임에게 닿고 싶은 그리움"},"r01":{"t":"SQ3R·CSQ3R","cat":"독서 개념","steps":[{"h":"1문단","ev":"복잡한 글은 중요한 내용을 놓치기 쉬워, 효율적으로 읽기 위한 전략적 독서 방법으로 SQ3R을 쓴다.","keys":["전략적 독서","SQ3R"]},{"h":"2문단 (1)","ev":"훑어보기로 제목·목차를 보며 내용을 예측하고, 질문하기로 질문을 만든 뒤, 읽기에서 그 답을 찾으며 문장·단락을 읽는다.","keys":["훑어보기","질문하기","읽기"]},{"h":"2문단 (2)","ev":"확인하기는 핵심을 자기 말로 표현하거나 답한 내용을 남과 비교하고, 재검토하기는 전체를 다시 훑으며 이해를 평가하고 비판도 한다.","keys":["확인하기","재검토하기"]},{"h":"3문단","ev":"CSQ3R은 SQ3R에 ‘시각 바꾸기’를 더한 것으로, 자신이 저자라면 어떻게 전달할지 생각하며 내용을 분석적·비판적으로 본다.","keys":["CSQ3R","시각 바꾸기"]},{"h":"4문단","ev":"배경지식을 적극 활용하고 마지막에 토론·감상문으로 표현하며, 단계는 일방향이 아니어서 필요하면 이전 단계로 돌아간다.","keys":["배경지식","단계 되돌아가기"]}],"key":"SQ3R은 5단계 읽기 전략이고, CSQ3R은 ‘시각 바꾸기’ 단계를 더한 변이형이다.","pt":["재검토하기에서도 비판·평가를 한다 — ‘비판·평가 배제’ 선지는 오답","단계별 활동 구분: 확인하기 = 핵심을 자기 말로 표현·남과 비교","CSQ3R에 더해진 단계는 ‘시각 바꾸기’(저자의 입장에서 생각)"],"src":"본책 p.9~10 · 해설 p.2","s":"수특 독서 · 독서 개념"},"r02":{"t":"형식 논리학과 후설","cat":"독서 개념","steps":[{"h":"1문단 (1)","ev":"논리학은 사고의 오류를 피하는 방법을 연구하며, 그중 형식 논리학은 논증·추론의 구조가 타당한지 분석한다.","keys":["논리학","형식 논리학"]},{"h":"1문단 (2)","ev":"명제 논리는 논리 연결어로 묶은 복합 명제의 참·거짓을 따지고, 술어 논리는 문장을 주어·서술어로 나눠 관계를 더 세밀하게 포착한다.","keys":["명제 논리","술어 논리"]},{"h":"2문단","ev":"형식 논리학은 전제와 결론이 모순 없이 이어지는 무모순성을 본다. 그래서 전제가 거짓이어도 모순 없이 결론이 나오면 타당하다고 본다.","keys":["무모순성","전제의 참·거짓"]},{"h":"3문단 (1)","ev":"후설은 형식 논리학이 논리의 타당성을 받치는 근본 근거를 못 댄다고 비판하고, 선험적 논리학으로 그 타당성이 어떻게 가능한지 묻는다.","keys":["선험적 논리학","근본 근거"]},{"h":"3문단 (2)","ev":"논리 규칙은 경험에서 귀납된 것이 아니라 의식의 선험적 구조에서 비롯되며, 이를 탐구하는 핵심 개념이 직관이다.","keys":["선험적 구조","직관"]},{"h":"3문단 (3)","ev":"직관은 감각적 인상이나 본능적 통찰이 아니라 기호의 매개 없이 본질을 직접 꿰뚫어 보는 행위이고, 선험적 논리학은 ‘논리의 논리학’이다.","keys":["직관","논리의 논리학"]}],"key":"형식 논리학은 무모순성만 보지만, 후설은 논리의 타당성 근거를 의식의 선험적 구조에서 찾는다.","pt":["직관은 ‘감각적 인상·본능적 통찰’이 아니라 기호 없이 본질을 직접 파악하는 것","형식 논리학은 전제의 실제 참·거짓과 무관하게 무모순성으로 타당성을 판단","(보기) 글 평가 기준 구분: 인용 논문이 없는데 ‘신뢰성’을 말한 ⓒ가 잘못"],"src":"본책 p.11~12 · 해설 p.2~3","s":"수특 독서 · 독서 개념"},"r03":{"t":"허구 이야기와 믿는 체하기 놀이","cat":"독서 개념","steps":[{"h":"(가) 1문단","ev":"허구 이야기를 이해하려면 문장이 지시하는 의미론적 내용(명제)과, 맥락 속에서 실제로 전달되는 사용상의 내용을 구별해야 한다.","keys":["의미론적 내용","사용상의 내용"]},{"h":"(가) 2~3문단","ev":"월턴은 허구를 ‘믿는 체하기 놀이’로 본다. 문장은 놀이의 소품이라 의미론적 내용은 비활성화되고, 독자는 거짓임을 알면서 감정적으로 반응한다.","keys":["믿는 체하기 놀이","소품"]},{"h":"(가) 4문단","ev":"허구 이름은 가리키는 대상이 없어 내용이 없으므로, 그 이름이 든 허구 문장은 참이나 거짓이 될 수 없다.","keys":["허구 이름","참·거짓 판단 불가"]},{"h":"(나) 1문단","ev":"불완전명제 이론은 허구 문장도 의미론적 내용을 갖되, 허구적 내용이 들어갈 자리가 빈 불완전명제를 표현한다고 본다.","keys":["불완전명제","의미론적 내용"]},{"h":"(나) 2~3문단","ev":"불완전명제가 인식과 감정 반응의 촉발점이 되고, 허구 문장의 참·거짓도 판단할 수 있다. ‘놀부와 흥부는 실제 인물이다’는 거짓이다.","keys":["감정 반응의 근거","참·거짓 판단 가능"]},{"h":"(나) 4문단","ev":"허구 문장도 불완전하게나마 의미를 지니므로, 허구 이야기는 예외가 아니라 언어 규칙을 따르는 일반적인 언어 행위로 이해된다.","keys":["일반적 언어 행위"]}],"key":"월턴은 허구 문장을 놀이의 소품으로, 불완전명제 이론은 빈칸이 있는 명제로 본다.","pt":["(나)의 월턴 비판: 명제를 표현하지 않으면 감정 반응의 근거를 설명하기 어렵다","월턴은 허구를 거짓말과 동일시하지 않고, 사용상의 내용은 작가 의도·맥락에 따른다","(보기) 허구 역설: (가)는 ‘사용상의 내용’, (나)는 ‘불완전한 의미론적 내용’으로 설명"],"src":"본책 p.13~15 · 해설 p.3","s":"수특 독서 · 독서 개념"},"r04":{"t":"전류 밀도","cat":"독서 개념","steps":[{"h":"1문단 (1)","ev":"전류가 흐를 때 전자와 원자의 충돌로 열이 생긴다. 같은 전류라도 단면적이 좁으면 전류 밀도가 높아져 단위 부피당 열 발생이 늘어난다.","keys":["전류 밀도","열 발생"]},{"h":"1문단 (2)","ev":"열 발생은 전력 손실을 낳고 기기 성능 저하나 회로 손상을 부를 수 있어, 설계할 때 반드시 고려해야 한다.","keys":["전력 손실","설계 시 고려"]},{"h":"2문단 (1)","ev":"교류는 자기장이 계속 변해 도선 안에 유도 전기장이 생기고, 이 때문에 소용돌이 모양의 유도 와전류가 흐른다.","keys":["유도 전기장","유도 와전류"]},{"h":"2문단 (2)","ev":"유도 와전류는 중심부의 전류 밀도를 낮추고 표면의 전류를 늘려 전류가 표면으로 몰리는 표피 효과가 생기며, 주파수가 높을수록 강하다.","keys":["표피 효과","주파수"]},{"h":"2문단 (3)","ev":"표피 효과로 전류가 흐를 유효 단면적이 줄어 저항이 커지고, 저항이 커지면 더 많은 에너지가 열로 바뀌어 열 발생이 커진다.","keys":["유효 단면적","저항 증가"]},{"h":"3문단","ev":"고주파 장치는 가는 절연선을 꼰 리츠 와이어로 자기장 영향을 상쇄하고, 중심부 금속을 빼 자원을 아끼거나 알루미늄선 표면에 구리를 씌운다.","keys":["리츠 와이어","표면에 구리"]}],"key":"전류 밀도와 표피 효과가 열 발생을 키우므로, 고주파 장치는 이를 고려해 설계한다.","pt":["표피 효과는 주파수가 높을수록 강해 표면층 두께 δ는 얇아진다(보기 ㉢)","알루미늄선 표면에 구리를 입혀야 열이 준다 — 구리선을 알루미늄으로 감싼다는 선지는 오답","서술 방식: 문제 상황과 이를 고려한 설계 사례 제시(과학자 소개·가설·비유 아님)"],"src":"본책 p.17~19 · 해설 p.4~5","s":"수특 독서 · 독서 개념"},"r05":{"t":"소비 이론","cat":"독서 개념","steps":[{"h":"1문단","ev":"소비를 좌우하는 가장 중요한 요인은 가처분 소득이다. 둘은 양의 상관관계지만 소비 증가분은 소득 증가분보다 작다. 일부를 저축하기 때문이다.","keys":["가처분 소득","양의 상관관계"]},{"h":"2문단","ev":"케인스의 소비 함수 C=a+bY는 소비를 소득의 1차 함수로 본다. 여기서 평균 소비 성향(C/Y)과 한계 소비 성향(ΔC/ΔY)을 끌어낸다.","keys":["케인스 소비 함수","평균·한계 소비 성향"]},{"h":"3문단","ev":"평균 저축 성향은 1에서 평균 소비 성향을 뺀 값이고, 한계 소비 성향과 한계 저축 성향을 더하면 항상 1이다.","keys":["평균 저축 성향","한계 저축 성향"]},{"h":"4문단","ev":"소득 외에 보유 재산, 물가 수준, 미래 소득도 소비를 좌우한다. 소비자는 예상 미래 소득까지 감안해 현재 소비를 정한다.","keys":["재산","물가 수준","미래 소득"]},{"h":"5문단","ev":"프리드먼은 소득을 항상 소득과 일시 소득으로 나눈다. 소비는 항상 소득을 보고 정하므로, 항상 소득의 한계 소비 성향이 일시 소득의 것보다 훨씬 크다.","keys":["항상 소득 이론","일시 소득"]},{"h":"6문단","ev":"모딜리아니는 소득이 청년기엔 낮고 중장년기에 높다가 은퇴 후 낮아지지만, 일생 소득을 염두에 두므로 소비는 거의 일정하다고 본다.","keys":["생애 주기 이론","일생 소득"]}],"key":"소비는 가처분 소득이 좌우하며, 항상 소득·생애 주기 이론은 장기 소득으로 소비를 설명한다.","pt":["한계 소비 성향 b가 커져도 소비 증가분이 소득 증가분보다 커지는 것은 아니다(b는 1보다 작음)","프리드먼: 항상 소득의 한계 소비 성향이 일시 소득의 것보다 크다(대소 뒤집기 주의)","평균 소비 성향 0.7이면 평균 저축 성향 0.3, 한계 소비·저축 성향의 합은 1"],"src":"본책 p.21~23 · 해설 p.5~6","s":"수특 독서 · 독서 개념"},"r06":{"t":"롤스·매킨타이어의 정의관","cat":"독서 개념","steps":[{"h":"1문단","ev":"롤스는 정의를 합리적 개인들이 원초적 상황에서 합의해 만든, 절차적 공정성을 갖춘 제도의 산물로 보고, 국가의 적극적 역할과 보편적 정의 원칙을 내세운다.","keys":["원초적 상황","절차적 공정성","보편적 원칙"]},{"h":"2문단","ev":"매킨타이어는 원초적 상황의 인간이 공동체와 유리된 존재라며 롤스를 비판한다. 공동체의 전통과 관습이 자아를 만들고, ‘나’는 공동체 이야기의 일부라고 본다.","keys":["공동체","서사적 존재"]},{"h":"3문단","ev":"공동체가 추구하는 덕목을 반복 실천해 덕을 기르는 과정에서 정의가 실현되며, 자기실현은 타인과의 결합으로만 가능하다고 본다.","keys":["덕","공동체의 선","자기실현"]},{"h":"4문단","ev":"매킨타이어는 전통 강조가 비판적 사고와 진보를 막고 상대주의로 흐를 수 있다는 비판을 받지만, 공동체 중심으로 정의를 논한 새 관점이라는 의의가 있다.","keys":["전통 강조의 한계","상대주의 우려"]}],"key":"롤스는 절차적 공정성에서 보편적 정의를, 매킨타이어는 공동체 안의 덕의 실천에서 정의를 찾는다.","pt":["비교 축: 롤스 = 절차의 공정성·보편 원칙 / 매킨타이어 = 공동체의 전통·덕의 실천","매킨타이어 비판은 ‘전통이 비판적 사고·진보를 저해’, ‘상대주의 위험’(전통을 부정했다는 것이 아님)","(보기) 공리주의 비판: 롤스는 절차의 공정성 경시를, 매킨타이어는 공동체 전통 경시를 지적"],"src":"본책 p.25~26 · 해설 p.6~7","s":"수특 독서 · 독서 개념"},"r07":{"t":"로이 리히텐슈타인","cat":"독서 개념","steps":[{"h":"1문단","ev":"1960년대 미국에서 대중매체가 발달하자 팝아트가 만화·광고 같은 대중문화 이미지를 미술로 끌어들였고, 리히텐슈타인은 만화 이미지를 쓴 대표 작가다.","keys":["팝아트","대중문화 이미지"]},{"h":"2문단","ev":"인쇄소의 벤데이 도트 기법을 빌려 기계가 찍은 듯한 점을 만들되 실제로는 수작업을 반복했고, 원색 평면과 굵은 검은 윤곽선을 대비시켰다.","keys":["벤데이 도트","기계적 재현"]},{"h":"3문단","ev":"만화의 패널을 그대로 베끼지 않고 장면을 골라 확대·병치·재배열해 정서적 긴장을 키우고, 말풍선·의성어도 시각적 조형 요소로 배치했다.","keys":["패널 재구성","텍스트 요소"]},{"h":"4문단","ev":"「꽈광!」은 전쟁 만화의 패널을 재구성해, 승리하는 전투기 대신 격추된 전투기의 폭발을 강조하고 각진 텍스트로 폭발의 격렬함과 소리까지 떠올리게 한다.","keys":["「꽈광!」","폭발 강조"]}],"key":"리히텐슈타인은 만화의 기계적 재현·패널·텍스트를 회화에 들여와 새로운 양식을 열었다.","pt":["㉠은 ‘대중문화의 기계적 재현 방식을 도입해 회화 표현을 확장’한 것(대량복제 기술 개발이 아님)","벤데이 도트는 기계처럼 보이나 실제로는 수작업·반복 과정을 거친 독창적 작품","「꽈광!」의 의도: 특정 장면의 확대·재배열로 정서적 긴장을 극대화해 주제의식을 강조"],"src":"본책 p.28~29 · 해설 p.7~8","s":"수특 독서 · 독서 개념"},"r08":{"t":"폐포의 표면 장력과 계면 활성제","cat":"독서 개념","steps":[{"h":"1문단","ev":"폐포는 탄성력이 있어 늘어났다 복원되며, 늘어나는 정도인 신전성이 클수록 일정량의 공기를 들이마실 때 에너지가 덜 든다.","keys":["폐포","신전성"]},{"h":"2문단","ev":"폐포 표면의 액체층에는 물 분자 간 인력으로 표면 장력이 작용해 폐포가 오그라들려 하지만, 이 힘과 내부 공기압이 평형을 이뤄 허탈은 거의 없다.","keys":["표면 장력","공기압 평형","허탈"]},{"h":"3문단","ev":"라플라스 법칙에 따르면 필요한 공기압은 표면 장력에 정비례하고 반지름에 반비례하므로, 폐포가 작을수록 허탈이 쉽게 일어날 수 있다.","keys":["라플라스 법칙","반지름"]},{"h":"4문단 (1)","ev":"Ⅱ형 폐포 세포가 계면 활성제를 분비해 물 분자 간 인력을 방해하면 표면 장력이 준다. 폐포가 작을수록 농도가 높아져 표면 장력이 더 줄어 허탈이 막힌다.","keys":["계면 활성제","Ⅱ형 폐포 세포"]},{"h":"4문단 (2)","ev":"계면 활성제가 부족해지면 작은 폐포의 허탈이 촉진되어 호흡 기능이 떨어지는 문제가 생긴다.","keys":["계면 활성제 부족","호흡 기능 저하"]}],"key":"작은 폐포일수록 허탈하기 쉽지만, 계면 활성제가 표면 장력을 낮춰 폐포를 안정시킨다.","pt":["물 분자 간 인력을 방해하는 것은 계면 활성제이지 표면 장력이 아니다(주체 바꾸기)","라플라스 법칙: 공기압은 표면 장력에 비례, 반지름에 반비례 — 작은 폐포가 불리","(보기) 미숙아: Ⅱ형 폐포 세포 미발달 → 인공 계면 활성제로 표면 장력을 낮춰 허탈 방지"],"src":"본책 p.31~33 · 해설 p.8~9","s":"수특 독서 · 독서 개념"},"r09":{"t":"인클루시브 디자인","cat":"독서 개념","steps":[{"h":"1문단 (1)","ev":"과거 디자인은 특정 사용자나 평균 조건만 전제해 소외되는 사람이 생겼고, 이를 줄이려 경사로처럼 하나의 표준화된 방식을 시도했다.","keys":["소외 문제","표준화된 방식"]},{"h":"1문단 (2)","ev":"표준화된 방식은 설치·활용이 쉽지만 사람마다 신체 능력·생활 패턴·문화가 달라 요구를 다 채우지 못했고, 여러 방식을 동시에 주는 인클루시브 디자인이 나왔다.","keys":["표준화의 한계","복수 방식"]},{"h":"2문단 (1)","ev":"목적은 어떤 조건에서도 모든 사용자가 안전하고 편리하게 경험하는 것이다. 접근성은 장애 요인 없이 도달·사용하게 하는 것, 포용성은 차이와 요구를 전제로 설계하는 태도다.","keys":["접근성","포용성"]},{"h":"2문단 (2)","ev":"두 성질은 서로 보완하며 함께 충족돼야 한다. 설계자는 사용자 배경·능력을 미리 조사하고 단계마다 의견을 받아 수정을 거듭한다.","keys":["상호 보완","의견 수렴"]},{"h":"3문단","ev":"특정 집단을 위한 보조 장치가 아니라 처음부터 그렇게 설계하는 것이 원칙이며, 누구나 언제든 배제될 수 있다는 전제에서 출발한다.","keys":["처음부터 설계","배제 가능성"]}],"key":"인클루시브 디자인은 여러 방식을 처음부터 함께 마련해 접근성과 포용성을 높인다.","pt":["표준화된 하나의 방식은 등장 이전의 해법이고, 복수 방식 병행이 인클루시브 디자인(시점 바꾸기)","접근성 = 도달·사용 보장, 포용성 = 차이를 전제한 설계 태도 — (보기) 옵션 다양화에 적용","(보기) 단말기 위치·높이 조절은 공간 효율이 아니라 신체 조건을 고려한 접근성 향상"],"src":"본책 p.36~37 · 해설 p.9","s":"수특 독서 · 독서 개념"},"r10":{"t":"형평 운동","cat":"독서 개념","steps":[{"h":"1문단","ev":"조선은 양천제로 양민과 천민을 나눴고, 천민 안에서도 관노비인 공천은 비교적 나은 대우를, 사노비인 사천은 멸시를 받아 위세가 같지 않았다.","keys":["양천제","공천·사천"]},{"h":"2문단","ev":"백정은 천민 중 가장 천대받았다. 1894년 갑오개혁으로 신분제가 명목상 폐지돼도 차별은 그대로였고, 일제는 소가죽 확보를 위해 백정의 계급이 유지되길 바랐다.","keys":["백정","갑오개혁","일제의 관리"]},{"h":"3문단","ev":"백정은 인권 수호와 신분 해방을 위해 1923년 형평사를 조직해 형평 운동을 시작했고, 진주에서 전국으로 퍼지며 사회 운동 단체와 합세해 평등권을 주장했다.","keys":["형평사","평등권"]},{"h":"4문단","ev":"형평 운동은 3·1운동 이후 대중 운동의 영향을 받았고, 소작인 대회·여성 운동과 같은 시기에 일어났으며 유력자·지식인의 지지도 받았다.","keys":["일제강점기 인권 운동","사회적 연대"]},{"h":"5문단","ev":"그러나 반대 움직임도 나타났다. 장시에서 노동력을 팔아 살던 양민이 경쟁자로 나선 백정 출신에게 공포와 적의를 느꼈기 때문이다.","keys":["양민의 반발","생계 경쟁"]},{"h":"6문단","ev":"갈등은 뿌리 깊은 차별 의식과 약자의 분노가 다른 약자에게 증오로 향할 수 있음을 보여주며, 계급 갈등을 넘어설 새로운 정치의 필요성을 뜻한다.","keys":["약자 간 갈등","새로운 정치"]}],"key":"형평 운동은 신분제 폐지 뒤에도 이어진 백정 차별에 맞선 인권 운동이었고, 약자 간 갈등도 드러냈다.","pt":["주체 바꾸기: 백정이 형평사를 조직했지, 사회 운동 단체가 조직한 것이 아니다","반대 움직임의 원인은 생계 경쟁 속 양민의 공포·적의(독립 회복 대중 운동의 영향이 아님)","(보기) 경찰의 태도 ↔ 소가죽 확보를 위해 백정 계급의 유지를 바란 일제의 입장"],"src":"본책 p.38~40 · 해설 p.9~10","s":"수특 독서 · 독서 개념"},"r11":{"t":"가상 메모리","cat":"독서 개념","steps":[{"h":"1문단","ev":"보조 기억 장치는 크고 영구 저장이 되며, 주기억 장치는 작고 프로그램·데이터가 일시적으로 머문다. 필요한 것을 보조에서 복사해 주기억에서 처리한다.","keys":["보조 기억 장치","주기억 장치"]},{"h":"2문단","ev":"주기억 장치가 작아 여러 작업의 프로그램을 다 올리기 어려우므로, 당장 구동할 일부만 올리고 나머지는 보조 기억 장치에 두는 가상 메모리를 쓴다.","keys":["가상 메모리","용량 한계"]},{"h":"3문단","ev":"프로그램을 같은 크기의 페이지로 나눠 페이지 단위로 주기억 장치의 페이지 프레임에 올리는 페이징이 대표적 구현 방식이며, 위치는 페이지 테이블에 기록된다.","keys":["페이징","페이지 프레임","페이지 테이블"]},{"h":"4문단","ev":"필요한 페이지가 프레임에 없으면 페이지 부재가 일어나, 보조 기억 장치에서 그 페이지를 복사해 프레임에 올린 뒤 접근한다.","keys":["페이지 부재"]},{"h":"5문단","ev":"프레임이 가득 찬 채 새 페이지가 필요하면 기존 페이지를 제거하는 페이지 교체가 일어나며, 수정된 페이지는 제거 전에 보조 기억 장치에 반영한다.","keys":["페이지 교체","수정 사항 반영"]},{"h":"6문단","ev":"교체 규칙은 FIFO(가장 먼저 들어온 것), LRU(가장 오래 안 쓴 것), LFU(가장 적게 쓴 것)이며, LFU는 동률일 때 추가 규칙이 필요하다.","keys":["FIFO","LRU","LFU"]}],"key":"가상 메모리는 필요한 페이지만 주기억 장치에 올려 쓰고, 교체는 FIFO·LRU·LFU 규칙으로 한다.","pt":["가상 메모리는 주기억 장치의 용량 한계를 보완하는 것이지, 보조 기억 장치의 부족을 메우는 것이 아니다","교체 기준: FIFO = 먼저 들어온, LRU = 오래 안 쓴, LFU = 적게 쓴 — (보기) 직접 시뮬레이션","LFU에서 사용 횟수가 같으면 FIFO 같은 추가 규칙으로 정한다(보기: A0이 삭제)"],"src":"본책 p.41~44 · 해설 p.10~12","s":"수특 독서 · 독서 개념"},"r12":{"t":"디지털 읽기","cat":"독서 개념","steps":[{"h":"1문단","ev":"디지털 읽기는 화면의 텍스트를 읽는 것으로, 문자 외에 영상 같은 복합 양식과 방대한 정보가 함께 제시될 수 있어 인쇄물 읽기와 인지 활동이 다르다.","keys":["디지털 읽기","복합 양식"]},{"h":"2문단","ev":"인쇄물은 텍스트 자체에 초점이 맞지만, 디지털 텍스트는 하이퍼텍스트 구조라 초점이 다른 텍스트로 옮겨가기 쉽고 다문서 읽기가 쉽게 일어난다.","keys":["하이퍼텍스트","다문서 읽기"]},{"h":"3문단","ev":"화면을 스크롤하며 훑어 읽는 방식이 자주 쓰이고 F형 읽기 패턴이 나타나는데, 텍스트의 가치를 빠르게 점검할 때 편리하다.","keys":["스크롤","F형 읽기 패턴"]},{"h":"4문단","ev":"스크롤 읽기는 속도는 빠르나 정확성이 낮고, 하이퍼텍스트와 시청각 정보는 인지 부담을 키우며, 멀티태스킹 환경에서는 주의가 흩어져 이해력이 떨어질 수 있다.","keys":["속도·정확성","인지 부담","주의 분산"]}],"key":"디지털 읽기는 다문서·훑어 읽기에 유리하나, 인지 부담과 주의 분산으로 이해력이 떨어질 수 있다.","pt":["F형 읽기·스크롤은 읽을 가치를 점검하기엔 편리하나 꼼꼼한 이해에 효과적이진 않다","하이퍼텍스트는 탐색을 수월하게 하지만 독자의 인지적 부담은 가중시킨다(보기 적용)","인쇄물 읽기는 주로 문자 언어(+2차원 시각 정보), 주의 분산은 디지털에서 더 잦다"],"src":"본책 p.46~47 · 해설 p.12~13","s":"수특 독서 · 독서 개념"},"r13":{"t":"복잡계 경제학","cat":"독서 개념","steps":[{"h":"1문단","ev":"기술과 금융 시장이 예측하기 어렵게 변하는 가운데, 산타페 연구소에서 나온 복잡계 경제학은 경제 주체가 늘 가장 합리적으로 선택한다는 명제를 부정한다.","keys":["복잡계 경제학","합리적 선택 부정"]},{"h":"2문단 (1)","ev":"현대 경제는 수학적 계산의 결과가 아니라 동적으로 변하는 복잡한 시스템이며, 제한된 정보 속 주체들의 상호작용이 예측 불가능한 질서를 만드는 비정형성이 특징이다.","keys":["복잡한 시스템","비정형성"]},{"h":"2문단 (2)","ev":"기술 선택에서는 효율성보다 경로 의존성이 크다. 학습 비용과 네트워크 효과가 기존 기술을 고수하는 경로 고착을 낳고, 정책·제도에서도 반복된다.","keys":["경로 의존성","학습 비용","네트워크 효과"]},{"h":"3문단","ev":"시장 질서는 설계·통제되지 않고 주체들의 상호작용 속에서 형성되며, 개별 선택의 합을 넘는 새로운 질서가 전체 수준에서만 관찰되는 것이 창발이다.","keys":["창발","전체 수준"]},{"h":"4문단","ev":"경제를 유기체로 보아, 반응과 피드백으로 스스로 적응해 질서를 재구성하는 자기 조직화 능력을 핵심 역량으로 보며, 하향식 통제보다 불확실성에 대한 대응을 강조한다.","keys":["자기 조직화","피드백","불확실성 대응"]}],"key":"복잡계 경제학은 경제를 비정형·창발·자기 조직화하는 시스템으로 보고 불확실성 대응을 강조한다.","pt":["창발한 질서는 개별 요소에 없고 전체에서만 관찰 — ‘개별 주체에서 보편적’이라는 선지는 오답","(보기) 쿼티 자판: 경로 의존성·네트워크 효과·학습 비용으로 설명, 합리성이 비정형성을 해소한다는 해석은 오답","자기 조직화가 핵심인 이유: 불확실성·상호작용·변화 가능성을 이해하고 대응하는 능력 필요"],"src":"본책 p.48~49 · 해설 p.13~14","s":"수특 독서 · 독서 개념"},"r14":{"t":"하이데거의 존재론","cat":"인문·예술","steps":[{"h":"1문단","ev":"하이데거는 인간을 물질로 보는 유물론과 의미가 인간에게서 구성된다는 주관적 관념론을 모두 거부하고, 인간과 사물의 관계에 따라 사물이 다양하게 존재한다고 본다.","keys":["유물론 비판","주관적 관념론 비판"]},{"h":"2문단 (1)","ev":"철학은 일상에서 인식하는 대상인 ‘존재자’가 아니라 그 드러남인 ‘존재’를 물어야 한다. 자신의 존재를 문제 삼는 현존재만이 존재물음을 던진다.","keys":["존재자와 존재","현존재","존재물음"]},{"h":"2문단 (2)","ev":"존재는 과거·현재·미래가 통합된 시간 구조 속에서 드러나며(‘존재는 시간이다’), 현존재는 죽음을 인식하며 존재물음을 삶의 유한성과 연결해 이해한다.","keys":["시간 구조","죽음","유한성"]},{"h":"3문단","ev":"도구는 목적대로 쓰일 때 ‘손안에 있음’, 고장 나 객관적 대상으로 인식될 때 ‘눈앞에 있음’으로 드러난다. 전통 철학은 후자로만 사물을 보았다고 비판한다.","keys":["손안에 있음","눈앞에 있음"]},{"h":"4문단","ev":"이성을 앞세운 전통 철학과 대응설을 비판하며, 사물은 객관적 실체가 아니라 만남 속에서 드러나는 존재자라고 본다. 드러남과 동시에 다른 존재 가능성은 은폐된다.","keys":["대응설 비판","실존적 지평","은폐"]},{"h":"5문단","ev":"형이상학을 새롭게 보게 한 영향력이 있으나 현존재 중심이라 대상을 부차적으로 본다는 비판도 받는다. 그래도 세계에 대한 이해를 넓혔다는 의의가 있다.","keys":["의의","현존재 중심 비판"]}],"key":"하이데거는 존재자가 인간과의 만남 속에서 드러난다고 보고, 손안에 있음·눈앞에 있음으로 이를 설명한다.","pt":["현존재만 존재물음을 던진다 — ‘현존재 외의 존재자도 가능’이라는 선지는 오답","손안에 있음 = 쓰이는 중인 도구, 눈앞에 있음 = 고장 나 대상으로 인식(보기 적용)","대응설 비판의 이유는 사물을 외부의 객관적 실체로 본 것 — ‘경험에 근거해서’가 아님"],"src":"본책 p.54~57 · 해설 p.15~16","s":"수특 독서 · 인문·예술"},"r15":{"t":"미니멀리즘 음악","cat":"인문·예술","steps":[{"h":"1문단","ev":"1960년대 이후 미국에서 시작된 현대음악 흐름으로, 소수의 음형이나 단순한 패턴을 반복해 복잡한 서사·화성 전개를 줄이고 소리 자체를 경험하게 한다.","keys":["미니멀리즘 음악","소리 자체"]},{"h":"2문단","ev":"전통 음악의 반복은 소나타 형식처럼 주제를 재확인하는 ‘같은 것의 반복’, 미니멀리즘의 반복은 음색·강세의 미세한 차이가 매 순간 드러나는 ‘차이를 생성하는 반복’이다.","keys":["같은 것의 반복","차이를 생성하는 반복"]},{"h":"3문단","ev":"라몬테 영은 완전 5도의 두 음을 오래 지속해, 같은 음처럼 들려도 배음 구조 때문에 세기·강세·높이가 달라지는 변화를 경험하게 한다.","keys":["라몬테 영","배음"]},{"h":"4문단","ev":"라이히는 위상 변위, 곧 같은 패턴을 조금 다른 속도로 연주해 점차 어긋나게 한다. 이 동어반복은 작곡가의 서사 대신 내부의 잠재성을 드러내 특정 주제에 갇히지 않는다.","keys":["스티브 라이히","위상 변위","동어반복"]},{"h":"5문단","ev":"감상자는 주제를 알아맞히는 수동적 존재에서 음의 순간적 변화를 체감하는 능동적 참여자가 되고, 음악은 미세한 차이를 경험하게 하는 개방적 미적 형식이 된다.","keys":["능동적 참여자","개방적 미적 형식"]}],"key":"미니멀리즘 음악은 ‘차이를 생성하는 반복’으로 주제 중심 서사를 해체하고 감상자를 능동적 참여자로 만든다.","pt":["㉠같은 것의 반복 = 주제 재확인(소나타 형식), ㉡차이를 생성하는 반복 = 미세한 음향 차이","ⓐ는 배음 전개로 음 자체가 변하고, ⓑ는 위상 변위로 악기 간 어긋남에서 새 사건이 생긴다","(보기) 베르그송의 ‘지속’: 감상은 작곡가 의도의 재현이 아니라 각자 내면의 시간 체험"],"src":"본책 p.58~61 · 해설 p.16~18","s":"수특 독서 · 인문·예술"},"r16":{"t":"자연법(마리탱·메스너)","cat":"인문·예술","steps":[{"h":"1문단","ev":"법은 주로 국가가 만든 실정법 중심이나 근본적 정의를 설명하기엔 부족하다. 이를 보완하는 자연법은 본성과 이성에 근거한 보편적 규범이며 실정법의 정당성을 판단하는 기준이다.","keys":["실정법","자연법","정당성의 기준"]},{"h":"2문단","ev":"자연법은 스토아학파가 체계화해 로마법과 중세 기독교 사상으로 이어졌다. 아퀴나스는 자연법을 신이 부여한 영원법의 일부로 보고, 선을 추구하는 본성 속에서 이성으로 인식한다고 했다.","keys":["스토아학파","아퀴나스","영원법"]},{"h":"3문단","ev":"마리탱은 자연법을 인간 본질에 내재한 내면적 질서로 본다. 선을 향한 성향으로 직관하지만 교육과 도덕적 성숙이 있어야 ‘인식된 자연법’으로 구현되며, 인권의 철학적 기초가 된다.","keys":["내면적 질서","존재/인식된 자연법"]},{"h":"4문단","ev":"메스너는 인간 본성에 자기 보존, 출산·교육, 타인 배려, 공익 증진 같은 실존적 목적이 있다고 보고, 자연법이 이를 사회 제도 속에서 구체적으로 구현해야 한다고 주장한다.","keys":["실존적 목적","제도적 구현"]},{"h":"5문단","ev":"둘 다 자연법을 본성과 이성에 근거한 보편적 질서로 본다. 마리탱은 도덕적 성숙이 확산된 결과로, 메스너는 공동체가 제도로 실현할 과제로 본다는 점이 다르다.","keys":["공통점","마리탱과 메스너"]}],"key":"자연법은 실정법의 정당성 기준이며, 마리탱은 도덕적 성숙에서, 메스너는 제도적 구현에서 그 실현을 본다.","pt":["아퀴나스: 자연법은 영원법(신의 뜻)의 일부 — ‘신의 뜻과 별개의 영역’이라는 선지는 오답","사회적 실현: 마리탱 = 내면적 각성·도덕적 성숙, 메스너 = 사회 제도·정책(주체 바꾸기 주의)","(보기) 나치 법률: 형식상 유효한 실정법이라도 자연법에 어긋나면 정당성이 부정된다"],"src":"본책 p.62~65 · 해설 p.18~20","s":"수특 독서 · 인문·예술"},"r17":{"t":"예술과 표현","cat":"인문·예술","steps":[{"h":"1문단","ev":"표현은 마음 상태를 드러낼 때뿐 아니라 자연에 감정을 투영할 때도 쓰이며, 가장 널리 쓰이는 분야가 예술이다. 예술과 표현의 관계에는 여러 견해가 있다.","keys":["표현","예술"]},{"h":"2~3문단","ev":"크로체·콜링우드는 표현을 예술가의 내적 활동(직관)으로 보아 예술이 내면에만 있다고 한다. 하지만 물리적 매체로 만든 작품의 의미를 포착하지 못한다.","keys":["크로체","콜링우드","직관"]},{"h":"4문단","ev":"톨스토이는 예술가가 작품으로 감정을 전해 관객도 같은 감정을 느끼게 하는 것이 예술이라 본다. 두 감정의 일치를 확인할 수 없고, 관객은 다른 감정으로도 깊이 감상할 수 있다.","keys":["톨스토이","감정 전달","소통"]},{"h":"5문단","ev":"표현을 작품 자체의 내재적 성질로 보는 견해는, 음악이 슬프게 들리는 것은 음악에 표현적 속성이 새겨져 있기 때문이라고 본다.","keys":["내재적 성질"]},{"h":"6문단","ev":"랭어는 예술이 감정 자체가 아니라 감정의 시간적 흐름에서 나타나는 육체적 변화의 패턴을 상징화한다고 본다. 다만 감정의 복잡성을 다 담지 못한다.","keys":["랭어","상징화","육체적 변화의 패턴"]},{"h":"7문단","ev":"유사성 이론은 몸과 행동에서 표현적 성질을 알아보는 우리의 자연적 경향성에 주목해, 음악 형식이 슬퍼하는 사람의 행동과 닮아 슬프게 들린다고 본다. 다만 표현 범위가 좁아진다.","keys":["유사성 이론","행동적 표현"]}],"key":"예술의 표현을 내적 직관·감정 전달·작품의 내재적 성질로 보는 세 견해는 저마다 한계가 있다.","pt":["견해-한계 짝짓기: 내적 활동설 = 작품 의미 놓침, 전달설 = 감정 일치 확인 불가","콜링우드 ㉮: 일상 경험에서도 내적 이미지가 자발적으로 생성되어 예술과 본질적 차이가 없다","(보기) 내면 이미지만 예술로 보는 크로체·콜링우드 vs 형식의 닮음으로 보는 랭어·유사성 이론"],"src":"본책 p.66~69 · 해설 p.20~22","s":"수특 독서 · 인문·예술"},"r18":{"t":"아리스토텔레스의 비극론","cat":"인문·예술","steps":[{"h":"1문단","ev":"문학의 본질은 모방이며 비극은 완결된 사건을 모방한 것이다. 비극이 주는 연민과 공포는 안정된 성품을 길러 선한 인격과 미덕, 진리 도달의 바탕이 된다고 본다.","keys":["모방","연민과 공포"]},{"h":"2문단","ev":"비극의 6요소 중 플롯이 가장 중요하다. 사건은 개연성을 갖추어야 하며, 반전(정반대로 급변)과 인지(모르다가 앎)를 포함한 복합 플롯이 단순 플롯보다 훌륭하다.","keys":["플롯","반전·인지","복합 플롯"]},{"h":"3문단","ev":"비극 주인공은 고귀하지만 결함이 있어 악행이 아닌 과오로 불행해져야 한다. 잘못보다 큰 불행에 연민을, 자신과 닮은 인물의 불운에 공포를 느낀다.","keys":["인물의 조건","연민","공포"]},{"h":"4문단","ev":"비극의 궁극적 목적은 카타르시스다. 해석은 윤리학적(감정을 정화·조절), 정신분석학적(억눌린 감정을 분출), 인지적(인식을 얻는 즐거움)으로 갈린다.","keys":["카타르시스","윤리학적","정신분석학적","인지적"]},{"h":"5문단","ev":"자연주의 연극론자는 하층 계급 인물을 주인공으로 삼았고 니체는 비극이 삶에 대한 의지를 갖게 해야 한다고 했다. 그래도 그의 이론은 지금도 영향을 준다.","keys":["자연주의 연극","니체"]}],"key":"아리스토텔레스는 개연적 플롯과 결함 있는 주인공이 연민과 공포를 일으켜 카타르시스에 이른다고 보았다.","pt":["카타르시스 해석: ㉠정화·조절 / ㉡억눌린 감정 분출 / ㉢인식 획득의 즐거움 — 짝 맞추기","희극 주인공은 보통 사람보다 모자란 인물이지 영웅적 모습이 아니다(비극과 대비)","(보기) 「안티고네」: 잘못을 깨달음 = 인지, 구하려 했으나 죽음 = 반전, 닮은 인물이라야 공포"],"src":"본책 p.70~74 · 해설 p.22~24","s":"수특 독서 · 인문·예술"},"r19":{"t":"동일성 명제(프레게·러셀)","cat":"인문·예술","steps":[{"h":"1문단","ev":"프레게는 이름의 ‘뜻’(대상을 제시하는 방법)과 ‘지시체’(실제로 가리키는 대상)를 구별한다. 샛별과 개밥바라기는 지시체는 같고 뜻이 다르다.","keys":["뜻","지시체"]},{"h":"2문단","ev":"지시체가 같다는 정보뿐이면 a=b와 a=a는 같아지지만, 뜻까지 고려하면 정보가 구분되어 ‘샛별은 개밥바라기이다’가 ‘샛별은 샛별이다’보다 더 많은 정보를 준다.","keys":["a=b와 a=a","정보의 차이"]},{"h":"3문단","ev":"뜻은 주관적 관념이 아니라 단어에 붙은 객관적 존재자다. 망원경 비유에서 천체는 지시체, 렌즈의 상은 뜻, 관찰자 망막의 영상은 관념이다.","keys":["뜻의 객관성","망원경 비유"]},{"h":"4문단","ev":"러셀은 뜻이 불필요하다며 단어의 의미를 지시체와 동일시한다. 그러면 두 동일성 명제가 모두 동어반복이 되어 정보 차이를 설명하기 어렵다.","keys":["러셀의 비판","지시체 = 의미"]},{"h":"5문단","ev":"러셀은 기술 이론으로 ‘진정한 이름’(문맥과 무관하게 대상과 직접 관련)과 ‘위장된 이름’(한정 기술구여서 분석해야 의미가 파악됨)을 구분한다.","keys":["기술 이론","진정한 이름","위장된 이름"]},{"h":"6문단","ev":"‘샛별’과 ‘개밥바라기’를 위장된 이름으로 분석하면 서로 다른 한정 기술구가 같은 대상이라는 정보가 되어, 뜻 없이도 두 명제를 구분할 수 있다.","keys":["한정 기술구","문제 해결"]}],"key":"프레게는 ‘뜻’을 도입해, 러셀은 이름을 기술구로 분석해 동일성 명제의 정보 차이를 설명한다.","pt":["프레게의 뜻은 객관적 존재자이며 지시체와 구별된다(동일시하는 쪽은 러셀)","진정한 이름 = 문맥과 무관하게 대상과 직접 관련 / 위장된 이름 = 기술 이론으로 분석해야 의미 파악","(보기) ‘육이오전쟁’·‘한국전쟁’: 프레게는 지시체 같고 뜻 다름, 러셀은 같은 대상이 곧 의미"],"src":"본책 p.75~78 · 해설 p.24~26","s":"수특 독서 · 인문·예술"},"r20":{"t":"장재·정이·주희","cat":"인문·예술","steps":[{"h":"1문단","ev":"북송 시대에 유학은 존재의 본질을 탐구하는 철학으로 발전했다. 그 대표가 장재와 정이이며, 둘의 사상을 주희가 종합해 성리학의 토대가 되었다.","keys":["북송 유학","성리학"]},{"h":"2문단 (1)","ev":"장재는 ‘기’를 우주와 존재의 근원으로 본다. ‘이’는 기와 분리된 독립 실체가 아니라 기 안에 내재한 질서의 원리이며, 우주는 스스로 변화·생성하는 ‘화육’으로 만물을 낳는다.","keys":["기","이는 기에 내재","화육"]},{"h":"2문단 (2)","ev":"인간은 화육이 최고도로 응축된 존재로 ‘인’의 본성을 가장 충만하게 타고났다. 그래서 도덕 실천이 곧 천도의 실현이라는 천인합일을 강조한다.","keys":["인","천인합일"]},{"h":"3문단","ev":"정이는 ‘이’를 만물의 본질인 선하고 보편적인 원리로 보고, ‘기’는 이가 구체화되는 수단이자 감정·욕망이 나타나는 통로라 한다. 이가 존재론적으로 앞선다.","keys":["이 중심","이의 우선성","존천리 거인욕"]},{"h":"4문단 (1)","ev":"주희는 장재와 정이를 선별해 종합했다. ‘이’는 항상 선하고 불변하는 본체, ‘기’는 이가 현실에서 작용하는 수단이며 기의 탁함·맑음에 따라 차이가 생긴다.","keys":["이기론","본체와 수단"]},{"h":"4문단 (2)","ev":"기가 탁하면 성정·기질에 편차가 생겨 도덕적 결함이 나오므로 마음을 다스려 이를 밝혀야 한다. 이와 기는 구분하되 떨어지지 않으며 기를 배제하지 않는다.","keys":["마음 수양","위계","기 배제 아님"]}],"key":"장재는 ‘기’, 정이는 ‘이’를 중심에 두었고, 주희는 이를 본체·기를 수단으로 종합한 이기론을 세웠다.","pt":["정이: 감정·욕망은 ‘기’를 통해 나타난다 — 감정이 존재의 본질인 ‘이’라는 선지는 오답","장재가 인간을 ‘인’을 충만히 타고난 존재로 본 이유는 인간이 화육의 응축이라서","주희: ‘이’를 본체, ‘기’를 발현 수단으로 위계를 세우되 ‘기’를 배제하지 않는다"],"src":"본책 p.79~82 · 해설 p.26~27","s":"수특 독서 · 인문·예술"},"r21":{"t":"롤랑 바르트의 신화론","cat":"인문·예술","steps":[{"h":"1문단","ev":"바르트는 대중매체의 이미지·텍스트가 사회·문화적 의미를 담고 있고 수용 과정에서 특정 이념이 자연스럽게 받아들여진다고 보아, 이를 ‘현대의 신화’라 불렀다.","keys":["현대의 신화","이념"]},{"h":"2문단","ev":"소쉬르에 따르면 기호는 감각적 형태인 기표와 개념적 내용인 기의로 이루어지며, 둘의 결합은 사회적 약속에 따른 자의적인 것이다.","keys":["기표","기의","자의성"]},{"h":"3문단","ev":"단일한 의미를 전하는 기호가 1차 기호 체계이고, 이것이 통째로 기표가 되어 사회적·이념적 의미가 새 기의로 덧붙은 것이 2차 기호 체계, 곧 현대의 신화다.","keys":["1차 기호 체계","2차 기호 체계"]},{"h":"4문단","ev":"신화는 현실에 일부 기반해 설득력이 있다. 구성 과정을 감추고 특정 관점의 의미를 객관적 진실처럼 보이게 하는 ‘자연화’로, 강요 없이 일상 기호로 은밀하게 이념을 퍼뜨린다.","keys":["자연화","은밀한 전파"]},{"h":"5문단","ev":"국기에 경례하는 흑인 군인 사진의 잡지 표지는 2차 체계에서 기표가 되어 ‘프랑스는 인종차별 없는 관대한 국가’라는 의미를 당연한 사실처럼 전달한다.","keys":["잡지 표지 사례"]},{"h":"6문단","ev":"대중은 2차 기호 체계가 작동할 수 있음을 알고 비판적으로 보아야 한다. 콘텐츠 배후의 사회적 맥락·역사적 조건·이념을 파악하는 능동적 해석자가 되어야 한다.","keys":["비판적 수용","능동적 해석자"]}],"key":"바르트는 1차 기호 위에 이념이 덧씌워진 2차 기호 체계를 ‘현대의 신화’로 보고 비판적 해석을 요구한다.","pt":["1차 기호 체계 전체가 2차 체계에서 기표로 작동한다 — 새 기의로 쓰인다는 선지는 오답","신화는 의미의 구성 과정을 감추는 ‘자연화’로 은밀하게 이념을 전파한다(강제 주입 아님)","(보기) 광고 포스터의 일상 장면도 이념을 자연스러운 현실처럼 받아들이게 할 위험이 있다"],"src":"본책 p.83~87 · 해설 p.27~29","s":"수특 독서 · 인문·예술"},"r22":{"t":"종 차별주의","cat":"인문·예술","steps":[{"h":"1문단","ev":"인간은 동물에게 해를 끼치며 이용하는데, 종 차별주의는 우리 종의 이익을 다른 종의 이익보다 앞세워 이를 정당화한다. 동물은 동물이기에 그렇게 대해도 된다는 것이다.","keys":["종 차별주의"]},{"h":"2문단","ev":"‘같은 인간이니 더 중요하다’가 허용되면 같은 성별·인종이라는 이유의 성차별·인종차별도 허용된다. 같은 종이라는 사실 말고 도덕적으로 의미 있는 특징을 제시해야 한다.","keys":["성·인종 차별과 같은 구조","도덕적 특징"]},{"h":"3문단","ev":"DNA 구성 같은 생물학적 근거는 피부색이나 성염색체처럼 도덕적으로 의미 없는 특성이다. DNA가 특이한 사람을 동물처럼 대해도 된다는 결론도 낳는다.","keys":["DNA","생물학적 근거"]},{"h":"4문단","ev":"정교한 언어·복잡한 사고·도덕적 이상에 따라 살 능력 같은 고차원적 정신 능력은 도덕적으로 중요한 특성일 수 있다. 다만 왜 의미가 있는지 설명해야 한다.","keys":["고차원적 정신 능력","배타적 특성"]},{"h":"5문단","ev":"그러나 종중첩논증에 취약하다. 아기·뇌손상 환자는 그 능력이 부족해도 동물처럼 대하지 않고, 일부 영장류는 더 갖췄는데도 인간과 똑같이 대우하지 않는다.","keys":["종중첩논증","아기·뇌손상 환자"]}],"key":"종 차별주의의 근거(같은 종·DNA·정신 능력)는 도덕적 근거로 부족하며, 종중첩논증을 풀어야 옹호된다.","pt":["핵심 주장: 종 차별주의를 도덕적으로 옹호하려면 종중첩논증이 해결되어야 한다","‘같은 종’ 논리는 성·인종 차별과 같은 구조라 허용될 수 없고, DNA는 도덕적으로 무의미하다","고차원적 정신 능력은 인간의 배타적 특성이 아니다 — 못 가진 인간과 가진 동물이 모두 있다"],"src":"본책 p.88~92 · 해설 p.29~31","s":"수특 독서 · 인문·예술"},"r23":{"t":"흄의 기적론","cat":"인문·예술","steps":[{"h":"1~2문단","ev":"기적은 단지 드물거나 지금 법칙으로 설명 못 하는 사건이 아니다. 알려졌든 아니든 자연법칙으로 설명되면 기적이 아니며, 자연법칙상 일어날 수 없는 초자연적 사건이 기적이다.","keys":["기적적 사건","초자연적 사건"]},{"h":"3문단 (1)","ev":"기적은 대체로 증언으로 전해져 문제는 증언의 신뢰성이 된다. 증언자가 거짓말하거나 속았다는 가설과 초자연적 사건이 실제 일어났다는 가설을 확률로 비교해야 한다.","keys":["증언의 신뢰성","두 가설","확률"]},{"h":"3문단 (2)","ev":"흄은 앞의 가설이 더 그럴듯하다고 본다. 자연법칙은 오랜 경험으로 뒷받침되고 사람들은 거짓말·착각을 잘 하므로 기적의 증언은 믿을 수 없다는 결론이다.","keys":["자연법칙","증언이 거짓일 가능성"]},{"h":"4문단","ev":"프라이스는 천만 분의 1 확률인 복권 당첨을 신문으로 확인한 예로 반박한다. 그러나 복권 당첨은 실제로 일어나지만 자연법칙에 어긋나는 사건은 확률이 현재 0이라 다른 종류다.","keys":["프라이스의 반박","복권 당첨"]},{"h":"5문단","ev":"기적은 종교의 토대지만 흄의 의도는 종교 부정이 아니다. 가장 성스러운 종교는 이성이 아닌 신앙에 기초한다는 점을 말하려는 것이다.","keys":["종교","신앙"]}],"key":"흄은 기적 증언이 거짓일 가능성이 법칙 위반의 가능성보다 크다고 보아 증언을 믿지 않는다.","pt":["기적적 사건 = 자연법칙으로 설명되지 않는 초자연적 사건(드물다는 것만으론 기적이 아님)","흄의 문제의식은 기적이 일어날 가능성이 아니라 기적 ‘증언’의 신뢰성이다","(보기) 거짓말 확률(1만 분의 1)이 사건 확률보다 낮지 않아 흄은 증언을 믿지 않는다"],"src":"본책 p.93~95 · 해설 p.31~32","s":"수특 독서 · 인문·예술"},"r24":{"t":"기원 본질주의","cat":"인문·예술","steps":[{"h":"1문단","ev":"나는 박쥐나 책상, 혹은 다른 부모의 자식일 수 없었다. 부모가 한 달만 늦게 아이를 가졌어도 난자가 달라 다른 아이가 태어났을 것이기 때문이다.","keys":["다른 부모","태어남의 조건"]},{"h":"2문단","ev":"기원 본질주의는 나를 나답게 하는 고유한 특징이 나를 태어나게 한 기원이며 기원이 정체성에 필수적이라고 본다. 삶의 모든 갈림길은 달라질 수 없는 같은 시작점에서 갈라진다.","keys":["기원","정체성","시작점"]},{"h":"3문단","ev":"나만 가진 속성은 인생 경험이 될 수 없다(바뀐 아기가 같은 경험을 할 수 있음). 유전자도 아니다(일란성 쌍둥이는 같은 유전자의 다른 개체). 그래서 기원이 남는다.","keys":["경험","유전자","기원만 남음"]},{"h":"4문단","ev":"크립키는 내가 알파 외에 베타에서도 유래할 수 있다면 두 개인이 모두 나인 시나리오가 가능한데, 나는 두 곳의 두 개인일 수 없으므로 다른 접합자에서 유래할 수 없다고 논증했다.","keys":["크립키","접합자 알파·베타"]},{"h":"5문단","ev":"매력적인 생각이지만 접합자 재활용을 가정하면, 버린 원자들이 똑같이 배열된 두 번째 접합자를 이뤄 두 아이가 모두 나여야 하는 불가능한 상황이 생긴다.","keys":["접합자 재활용","반론"]}],"key":"기원 본질주의는 정체성을 기원(접합자)에서 찾지만, 접합자 재활용 사례가 이를 흔든다.","pt":["고유 속성 후보에서 경험·유전자는 탈락(타인·일란성 쌍둥이와 공유 가능)하고 기원만 남는다","크립키의 논증: 알파·베타가 모두 나의 기원이라면 한 사람이 두 곳에 있어야 해 불가능하다","전개: 문제 제기 → 중심 이론 → 후보 검토 → 논증 → 반박(접합자 재활용)"],"src":"본책 p.96~99 · 해설 p.32~34","s":"수특 독서 · 인문·예술"},"r25":{"t":"미끄러운 비탈길 논증","cat":"인문·예술","steps":[{"h":"1문단","ev":"사소한 것을 허용하면 연쇄 과정을 거쳐 몹시 나쁜 결과에 이르므로, 애초에 사소한 것도 허용해서는 안 된다는 논증이다.","keys":["첫 걸음","연쇄 과정"]},{"h":"2문단","ev":"일상에서도 익숙하다. 베트남이 공산화되면 주변국도 쓰러진다는 도미노 이론이나, 알코올 의존증 환자에게 술 한 잔도 주면 안 된다는 주장이 그 예다.","keys":["도미노 이론","알코올 의존증"]},{"h":"3문단","ev":"생명 의료 윤리에서 새 변화에 반대하는 보수적 입장이 쓴다. 안락사를 허용하면 장애인·정치범에게까지 확대된다며, 위험 경고를 넘어 첫걸음 자체를 막는다.","keys":["생명 의료 윤리","안락사 반대"]},{"h":"4문단","ev":"연속선에 의미 있는 구분점이 없어 보여 설득력이 있다. 하지만 구분점이 없다고 둘이 같다는 대머리 논증이 오류로 취급되듯 이 논증도 오류일 수 있다.","keys":["구분점","대머리 논증"]},{"h":"5문단","ev":"중간에 평평한 땅이 있거나 내려갈 정도를 스스로 정할 수 있으면 미끄러지지 않는다. 이를 해명하지 않으면 오류이며, 안락사는 본인 의사·전문가 참여 등으로 연쇄가 일어나지 않는다.","keys":["통제 가능성","인과적 연쇄"]},{"h":"6문단","ev":"그런데도 이 논증은 미끄러짐이 불가피하다는 공포심을 일으키며 피할 수 있다는 사실을 숨기는 수사법으로 쓰이기도 한다.","keys":["수사법","공포심"]}],"key":"미끄러운 비탈길 논증은 인과적 연쇄가 입증되지 않으면 오류이며, 때로 공포심을 일으키는 수사법이 된다.","pt":["정당성의 기준은 ‘단절 지점의 유무’가 아니라 미끄러짐의 인과적 연쇄가 실제로 일어나는지","중간에 멈추거나 스스로 통제할 수 있으면 최악의 결과로 이어지지 않는다","논증의 주장: 나쁜 결과로 이어질 수 있는 행위는 처음부터, 아무리 사소해도 허용하지 말 것"],"src":"본책 p.100~103 · 해설 p.34~36","s":"수특 독서 · 인문·예술"},"r26":{"t":"주희를 따른 조선 사대부","cat":"인문·예술","steps":[{"h":"1문단","ev":"16세기 이후 사림의 성리학 연구가 깊어지며, 무이산에 은거해 정사를 짓고 후학을 기른 주희의 행적을 따르는 것이 사대부의 유행이 되었다. 수용 양상은 이황·이이 학통이 달랐다.","keys":["무이정사","「무이도가」","문화적 유행"]},{"h":"2문단","ev":"이황 학통은 「무이도가」를 차운해 시를 짓고 「무이구곡도」를 반복 제작했다. 시는 흥의 발현이자 성정 도야, 그림은 무이산을 대신하는 이미지로 보아 모사에 치중했다.","keys":["차운시","「무이구곡도」 모사"]},{"h":"3문단","ev":"이이 학통은 동경을 넘어 조선식 구곡을 경영했다. 「무이도가」를 학문의 순서로 보고 정사를 짓고 구곡시를 지었으며, 실제 경관으로 구곡도를 그렸다. 중국엔 거의 없는 사례다.","keys":["구곡 경영","「고산구곡도」","실제 경관"]},{"h":"4문단","ev":"이이 학통의 노론 문인들은 구곡 경영으로 주희에서 이이로 이어지는 학문적 계보를 노론이 이었다는 정통성을 드러내고, 「고산구곡시화도」 등으로 결속을 다졌다.","keys":["노론","학문적 계보","정통성"]}],"key":"이황 학통은 「무이구곡도」 모사에, 이이 학통은 조선식 구곡 경영에 치중했고 노론은 이를 정통성 표방에 썼다.","pt":["이황 학통 = 차운시·「무이구곡도」 모사 중심 / 이이 학통 = 조선식 구곡 경영·실제 경관 그림","「고산구곡도」는 이이 사후 그의 학통이 그린 것 — 이이가 「무이구곡도」를 참고했다는 선지는 오답","조선식 구곡 경영은 중국 유행의 모방이 아니라 중국에선 사례가 거의 없는 조선의 모습"],"src":"본책 p.104~107 · 해설 p.36~38","s":"수특 독서 · 인문·예술"},"r27":{"t":"리더십 이론","cat":"사회·문화","steps":[{"h":"1문단","ev":"피들러는 리더를 업무 지향형과 관계 지향형으로 나누고, 상황의 호의성이 매우 낮거나 높으면 업무 지향형, 중간이면 관계 지향형이 더 좋은 성과를 낸다고 본다.","keys":["피들러","상황의 호의성","적합성"]},{"h":"2문단 (1)","ev":"리더 스타일을 고정된 것으로 본다는 비판이 일자, 허시와 블랜차드가 구성원의 성숙도(역량·의지)에 따라 리더십을 바꿔야 한다는 상황적 리더십 이론을 냈다.","keys":["상황적 리더십","역량","의지"]},{"h":"2문단 (2)","ev":"리더십은 과업 행동·관계 행동의 높낮이로 네 유형이다. 역량·의지가 모두 낮으면 지시형, 의지만 높으면 코치형, 역량만 높으면 지원형, 모두 높으면 위임형이 효과적이다.","keys":["지시형","코치형","지원형","위임형"]},{"h":"3문단","ev":"번스는 보상과 처벌 중심의 거래적 리더십을 비판하고 구성원의 동기와 가치관을 바꾸는 변혁적 리더십을 강조했다. 바스는 둘이 배타적이지 않고 조합할 수 있다고 했다.","keys":["거래적 리더십","변혁적 리더십","바스"]},{"h":"4문단","ev":"로크는 뚜렷하고 도전적이며 공개된 목표가 성과를 높인다고 했고, 데시와 라이언은 스스로 결정·통제한다고 느낄 때 내적 동기가 생기며 물적 보상은 이를 줄인다고 했다.","keys":["목표 설정","자기결정이론","내적 동기"]}],"key":"리더십 이론은 상황 적합성에서 구성원 성숙도, 변혁적 리더십, 동기 부여로 초점이 옮겨 갔다.","pt":["피들러: 업무 구조가 명확할수록 호의성이 높고, 호의성이 중간일 때만 관계 지향형이 유리하다","허시·블랜차드: 역량·의지가 모두 높으면 위임형 — 과업·관계 행동을 모두 낮추고 자율성 부여","번스는 리더도 구성원에게서 변화한다고 봤고(상호 변화), 바스는 변혁·거래의 조합을 인정"],"src":"본책 p.109~113 · 해설 p.38~39","s":"수특 독서 · 사회·문화"},"r28":{"t":"정보 비대칭과 역선택","cat":"사회·문화","steps":[{"h":"1문단","ev":"경제학은 완전한 정보를 가정하지만, 현실에서는 정보 취득에 비용이 들고 비용 제약이 달라 경제 주체가 가진 정보의 양과 질이 다른 정보 비대칭이 생긴다.","keys":["완전 정보","정보 비대칭"]},{"h":"2문단","ev":"정보가 부족한 쪽이 정보가 많은 쪽 중 가장 바람직하지 않은 상대와 거래하는 것이 역선택이다. 평균 위험 보험료는 고위험 고객만 가입시켜 보험료를 올리고 저위험 고객을 내보낸다.","keys":["역선택","평균적 위험","악순환"]},{"h":"3문단 (1)","ev":"신호 발송은 정보 우위인 쪽이 비용을 들여 특성을 알리는 것(학위, 긴 보증 기간)이다. 신호로 추론해 거래해 누구도 선택을 바꿀 유인이 없는 상태가 신호 발송 균형이다.","keys":["신호 발송","신호 발송 균형"]},{"h":"3문단 (2)","ev":"신호가 유효하려면 숨겨진 특성이 우수할수록 발송 비용이 낮아야 한다. 생산성 높은 구직자는 학위를 싸게 얻고, 품질 낮은 기업은 긴 보증이 비싸 흉내 내기 어렵다.","keys":["비용 조건","학위","보증 제도"]},{"h":"4문단","ev":"선별은 정보가 부족한 쪽이 선택지를 제공해 상대가 숨겨진 특성을 스스로 드러내게 하는 방법이다. 보험사가 보험료·보장이 다른 여러 상품을 설계하는 것이 그 예다.","keys":["선별","선택지 제공"]},{"h":"5문단","ev":"반복 거래에서 품질 좋은 공급자는 평판 구축으로 특성을 알린다. 온라인 리뷰·평점 제도가 정보 비대칭을 줄이는 메커니즘이며, 이런 발전이 시장 효율성을 높인다.","keys":["평판 구축","리뷰·평점"]}],"key":"정보 비대칭은 역선택을 낳고, 신호 발송·선별·평판 구축이 이를 완화한다.","pt":["신호는 숨겨진 특성이 우수할수록 발송 비용이 낮아야 유효하다 — 비용이 같거나 높다는 선지는 오답","신호 발송은 정보 우위인 쪽이, 선별은 정보 열위인 쪽이 주도한다(주체 바꾸기 주의)","(보기) 운전습관 데이터 제출을 회사가 요구하는 것은 강제 요구라 자발적 신호 발송이 아니다"],"src":"본책 p.114~117 · 해설 p.39~41","s":"수특 독서 · 사회·문화"},"r29":{"t":"행정 대집행","cat":"사회·문화","steps":[{"h":"1문단","ev":"행정 대집행은 공법상 대체적 작위 의무를 어긴 의무자 대신 행정청이 이행하고 비용을 징수하는 제도다. 기본권을 제한하므로 명령권과는 별개의 법적 근거가 필요하다.","keys":["대체적 작위 의무","법적 근거"]},{"h":"2문단","ev":"요건은 공법상 의무의 불이행, 대체적 작위 의무, 비례의 원칙 충족이다. 부작위 의무는 대상이 아니지만 이미 불법 공작물이 설치되면 철거라는 작위 의무로 전환되어 대상이 된다.","keys":["실체적 요건 3가지","의무의 전환","비례의 원칙"]},{"h":"3문단","ev":"절차는 계고, 대집행영장에 의한 통지, 대집행 실행, 비용 징수의 네 단계다. 계고는 문서로 하며 상당한 이행 기간을 주되, 비상시나 위험이 절박하면 생략할 수 있다.","keys":["계고","영장 통지","실행","비용 징수"]},{"h":"4문단","ev":"토지·건물의 인도는 의무자만 할 수 있는 비대체적 작위 의무라 대상이 아니다. 다만 점유자가 철거 의무자이면 철거 의무에 퇴거 의무가 포함되어 강제 퇴거가 가능하다.","keys":["인도 의무","퇴거 의무"]},{"h":"5문단","ev":"위법한 대집행은 행정소송으로 다투며 계고·통지·실행·비용 납부 명령이 모두 대상이다. 그러나 실행이 끝나면 앞의 소송은 이익이 사라지므로 집행 정지를 신청해 막는 것이 중요하다.","keys":["행정소송","집행 정지","소송의 이익"]},{"h":"6문단","ev":"대집행은 행정의 실효성을 확보하는 수단이지만 기본권 보장과 법치 행정의 틀 안에서 운용되어야 하며, 재량권 남용을 통제하는 사법 심사가 중요하다.","keys":["실효성과 권익 보호","사법 심사"]}],"key":"행정 대집행은 엄격한 요건과 4단계 절차를 지켜야 하며, 위법하면 집행 정지와 함께 소송으로 다툰다.","pt":["명령권의 근거 법률이 곧 강제 집행의 근거는 아니다 — 대집행에는 별도의 법적 근거가 필요","부작위 의무 자체는 대상이 아니나, 위반 결과로 생긴 철거 작위 의무는 대상이 된다","(보기) 집행이 끝난 뒤에도 비용 납부 명령은 다툴 이익이 있다 — 계고·통지·실행 소송은 이익 상실"],"src":"본책 p.118~121 · 해설 p.42~43","s":"수특 독서 · 사회·문화"},"r30":{"t":"IS–LM·IS–MP 모형","cat":"사회·문화","steps":[{"h":"1문단","ev":"고전학파는 가격·임금의 유연성으로 시장이 스스로 완전 고용을 이룬다고 봤으나, 대공황 뒤 케인스는 낮은 총수요가 실업을 부른다며 정부 정책으로 총수요를 관리해야 한다고 주장했다.","keys":["고전학파","케인스","총수요 관리"]},{"h":"2문단","ev":"IS–LM 모형은 상품 시장과 화폐 시장이 동시에 균형인 점에서 단기 국민소득이 정해짐을 보인다. IS 곡선은 이자율이 낮아질수록 투자·소득이 늘어 우하향한다.","keys":["IS–LM 모형","IS 곡선"]},{"h":"3문단","ev":"LM 곡선은 통화량을 외생적으로 고정한 상태에서 소득이 늘면 화폐 수요가 늘어 이자율이 오르는 관계로 우상향하며, IS와 LM의 교차점이 단기 균형이다.","keys":["LM 곡선","외생적 통화량","단기 균형"]},{"h":"4문단","ev":"재정 확대·감세는 IS 곡선을 오른쪽으로, 긴축은 왼쪽으로 옮긴다. 스태그플레이션으로 한계를 보이자 신케인스학파가 기준금리 조정을 나타내는 MP 곡선의 IS–MP 모형을 내놓았다.","keys":["IS 곡선 이동","스태그플레이션","IS–MP 모형"]},{"h":"5문단","ev":"LM은 중앙은행을 시장 밖 통제자로, MP는 경제 내부 주체로 본다. 소득에 따른 금리 변화는 곡선 위의 이동이고, 정책 기조 변경(긴축 위, 완화 아래)은 곡선 자체의 이동이다.","keys":["MP 곡선","내생적 조정","곡선의 이동"]},{"h":"6문단","ev":"금리를 정책 수단으로 삼는 IS–MP는 경제 주체의 기대 변화도 분석한다. 정책 신뢰성이 낮아 불확실성이 크면 소비·투자가 줄고 현금 선호가 늘어 금리 인하 효과가 약해진다.","keys":["기대 형성","정책 신뢰성","불확실성"]}],"key":"IS–LM은 통화량 중심의 단기 균형을, IS–MP는 금리 조정과 기대까지 포함해 현실 정책을 설명한다.","pt":["LM 곡선: 중앙은행이 통화량을 외생적으로 통제 / MP 곡선: 경제 내부 주체가 금리를 내생적으로 조정","소득 변화로 인한 금리 변화는 MP 곡선 위의 이동, 정책 기조 변경은 곡선 자체의 이동","(보기) 불확실성으로 IS가 왼쪽으로 이동하면 MP를 따라 균형 금리·소득이 모두 낮아진다"],"src":"본책 p.122~126 · 해설 p.44~46","s":"수특 독서 · 사회·문화"},"r31":{"t":"착오 송금","cat":"사회·문화","steps":[{"h":"1~2문단","ev":"착오 송금은 실수로 엉뚱한 계좌에 돈을 보내는 것이다. 은행이 자발적 반환을 유도하지만 수취인이 거부하면 송금인이 직접 법적 절차를 밟아야 해 비용·시간 부담이 크다.","keys":["착오 송금","은행의 중개","송금인의 부담"]},{"h":"3문단","ev":"민사상 송금인은 민법 제741조에 따라 법률상 원인 없이 이익을 얻은 수취인에게 부당이득 반환을 청구할 수 있지만, 소송은 번거롭고 시간과 비용이 든다.","keys":["민법 제741조","부당이득 반환"]},{"h":"4문단","ev":"형사상 수취인은 반환 요청이나 은행 연락을 받으면 타인의 돈을 맡은 보관자가 된다. 송금 실수를 알고도 고의로 반환을 거부하거나 임의로 쓰면 횡령죄가 성립할 수 있다.","keys":["보관자","횡령죄"]},{"h":"5문단","ev":"쟁점은 수취인의 선의·악의다. 선의면 민사상 반환 의무만 있고, 알고도 반환하지 않거나 소비한 악의면 형사 책임이 성립한다. 2021년 판례는 소비한 수취인에게 유죄를 선고했다.","keys":["선의","악의","2021년 판례"]},{"h":"6문단 (1)","ev":"은행은 착오 송금을 일으킨 주체가 아니라 법적 책임이 없다. 소비자 보호 차원에서 연락·신고 안내를 하지만 수취인 개인정보를 줄 수 없고 반환을 강제할 권한도 없다.","keys":["은행의 역할","한계"]},{"h":"6문단 (2)","ev":"예금보험공사가 신청을 받아 부당이득반환채권을 매입해 자진 반환을 안내하고 불응하면 지급명령으로 회수한다. 요건은 건당 5만~1억 원, 송금 1년 이내, 수취인 미반환이다.","keys":["반환지원제도","신청 요건"]},{"h":"7문단","ev":"송금인·수취인·은행의 입장이 충돌하는 복합적 문제로, 개인 차원의 신중함과 공공 차원의 제도적 완성이 모두 필요하다.","keys":["이해관계 충돌","개인·공공 차원"]}],"key":"착오 송금은 민사(부당이득 반환)와 형사(악의면 횡령)로 갈리고, 은행의 한계는 반환지원제도가 보완한다.","pt":["선의 수취인은 민사 반환 의무만, 송금 실수를 알고도 반환 거부·소비한 악의 수취인은 횡령죄","은행은 반환을 강제할 권한도, 수취인 개인정보를 송금인에게 줄 권한도 없다(법적 책임도 없음)","반환지원제도는 회수 비용을 공제한 뒤 돌려준다 — 전액 환급이라는 선지는 오답"],"src":"본책 p.127~131 · 해설 p.46~48","s":"수특 독서 · 사회·문화"},"r32":{"t":"법적 혼인","cat":"사회·문화","steps":[{"h":"1문단","ev":"과거엔 결혼식 같은 사회적 관습으로 혼인이 성립한다고 보았지만, 지금은 대부분 국가가 법이 정한 절차를 따라야 성립하는 법률혼 제도를 두어 혼인신고 같은 법적 절차가 더 중요하다.","keys":["법률혼","법적 절차"]},{"h":"2문단","ev":"실질적 요건은 혼인 의사의 합치(가장 중요), 만 18세 이상의 연령(미성년자는 부모·법정대리인 동의), 8촌 이내 혈족이 아닐 것, 배우자가 없을 것이다.","keys":["혼인 의사의 합치","혼인 적령","근친혼·중혼 금지"]},{"h":"3문단","ev":"형식적 요건은 혼인신고서의 접수·수리 완료다. 이로써 법적 배우자가 되고 4촌 이내 혈족·그 배우자와 인척 관계가 생기며 부양·협조·정조의 의무가 발생한다.","keys":["혼인신고","인척 관계","법적 권리·의무"]},{"h":"4문단","ev":"혼인은 원칙상 무효·취소가 안 되나 요건에 흠이 있으면 소송으로 정리한다. 혼인무효(합의 없음, 근친혼)는 청구 기한이 없고 처음부터 없던 일이 되어 기록이 삭제된다.","keys":["혼인무효","청구 기한 없음","소급 효력"]},{"h":"5문단","ev":"혼인취소(연령 미달, 중혼, 사기·강박)는 일정 기간 내에만 청구할 수 있고 사유에 따라 청구권자가 다르다. 확정 판결 뒤 1개월 내 신고하며, 취소 전까지의 법률혼은 인정된다.","keys":["혼인취소","청구 기간 제한","취소 전 혼인 인정"]},{"h":"6문단","ev":"이혼은 적법한 혼인 이후의 종료다. 협의상 이혼은 법원이 이혼 의사의 합치만 확인하고 사유의 타당성은 따지지 않으며, 재판상 이혼은 소송에서 민법상 사유를 따진다.","keys":["협의상 이혼","재판상 이혼"]}],"key":"혼인은 실질적·형식적 요건을 갖춰야 성립하고, 요건 흠결은 무효·취소로, 성립 후 종료는 이혼으로 정리한다.","pt":["혼인무효는 청구 기한 없이 처음부터 없던 것, 혼인취소는 기간 내 청구하며 취소 전 혼인은 인정","인척 관계는 혼인신고서 접수·수리가 끝나야 형성된다(관습적 의식이나 합의만으로는 아님)","협의상 이혼은 사유의 타당성을 묻지 않고 합의 여부만 확인, 재판상 이혼은 민법상 이혼 사유를 판단"],"src":"본책 p.132~135 · 해설 p.48~49","s":"수특 독서 · 사회·문화"},"r33":{"t":"토지 행정 수단","cat":"사회·문화","steps":[{"h":"1문단","ev":"토지행정은 국토를 종합적으로 이용·개발·보존하려는 행정이다. 20세기 초까지는 불간섭주의였으나 중반부터는 균형 발전을 위해 과밀 억제 같은 적극적 정책을 펼쳤다.","keys":["토지행정","불간섭→적극 정책"]},{"h":"2문단","ev":"토지거래허가제는 급격한 지가 상승을 막으려 5년 내 규제 구역의 거래 계약에 허가를 받게 한다. 허가 없는 계약은 효력이 없고 부정하게 허가받으면 징역이나 벌금이다.","keys":["토지거래허가제","규제 구역","벌칙"]},{"h":"3문단","ev":"토지거래허가제는 헌법 제23조(공공복리)와 제122조(국토 개발 제한)에 근거해 합헌이며, 사유재산제도의 부인이 아닌 제한이다. 재산권의 본질적 내용은 침해할 수 없다.","keys":["헌법 제23조·제122조","입법형성권의 한계"]},{"h":"4문단","ev":"부동산가격공시제는 국토교통부장관이 매년 1월 1일 현재 토지의 적정 가격을 공시한다. 표준지 공시지가를 기준으로 토지가격 비준표를 써서 개별 공시지가를 산정한다.","keys":["공시지가","표준지","개별공시지가"]},{"h":"5문단","ev":"공시지가는 보상액·조세의 기준이 되어 사실상 구속적이므로, 제한적으로 처분성을 인정하는 부분 행정행위 인정설이 다수설이다. 불복은 공시지가 결정의 취소 소송으로 한다.","keys":["처분성","부분 행정행위 인정설"]}],"key":"토지거래허가제와 부동산가격공시제는 국토의 균형 발전을 위해 소유권을 제한하는 적극적 토지행정 수단이다.","pt":["개별 공시지가는 표준지 공시지가를 기준으로 토지가격 비준표로 산정한다 — 순서를 뒤집은 선지 주의","토지거래허가제는 소유권을 금지하는 것이 아니라 합헌적으로 제한하는 것이며 본질적 내용은 침해 불가","공시지가는 보상·조세의 기준이어서 구속적 기능이 있어 부분 행정행위로 인정(다수설)"],"src":"본책 p.136~139 · 해설 p.49~51","s":"수특 독서 · 사회·문화"},"r34":{"t":"특별 공공 행정 조직","cat":"사회·문화","steps":[{"h":"1문단","ev":"특별 공공 행정 조직은 법적 근거에 따라 특정 분야를 전문적으로 맡아, 국가가 직접 하기 어려운 영역을 보완하거나 정치적 중립성·효율성이 필요한 업무를 한다.","keys":["특별 공공 행정 조직","설립 목적"]},{"h":"2문단","ev":"선거관리위원회·감사원은 권력 분립 원리로 헌법에 설립돼 설립·폐지가 헌법 개정으로만 가능하고 독립성이 핵심이다. 나머지는 국회가 법률로 만들며 일반 행정부처와 구별된다.","keys":["헌법상 국가기관","독립성","법률로 설립"]},{"h":"3문단","ev":"공법상 법인은 법인격(독립된 권리·의무의 주체 자격)이 있어 계약·재산 소유·소송을 스스로 하며, 공익을 추구하는 점에서 사법상 법인과 다르다. 국민연금공단이 그 예다.","keys":["법인격","공법상 법인"]},{"h":"4문단","ev":"공공조합은 구성원이 특별법으로 만든 인적 결합체로 설립·해산에 국가 감독을 받고, 공법상 재단은 출연 재산에 법인격을 준 조직이다. 각각 대한변호사협회, 한국연구재단이 예다.","keys":["공공조합","공법상 재단"]},{"h":"5문단","ev":"기능에 따라 규제·감시형, 서비스 제공형, 정책 집행형으로 나뉜다. 정부 예산에만 의존하면 독립성·공공성은 강하나 유연성이 떨어지고, 수익을 창출하면 재정 유연성이 높다.","keys":["기능별 분류","재정 구조"]}],"key":"특별 공공 행정 조직은 법적 근거로 설립돼 공적 책무를 수행하며, 법적 지위·기능·재정 구조에 따라 나뉜다.","pt":["법인격이 있어 소송을 낼 수 있는 것은 공법상 법인 — 감사원·선관위는 헌법 기관으로 법인격이 없다","공공조합은 임의 해산이 아니라 법률 절차와 국가 감독을 따르고, 공법상 재단은 출연 재산에 법인격을 준 것","정부 예산에만 의존하면 독립성·공공성은 강해도 재정 유연성은 낮다(수익 창출 조직과 대비)"],"src":"본책 p.140~143 · 해설 p.51~52","s":"수특 독서 · 사회·문화"},"r35":{"t":"시민 참여","cat":"사회·문화","steps":[{"h":"1문단","ev":"시민 참여를 긍정하는 관점은 고전적 이론가들에서 1960년대 참여 민주주의 이론으로 발전했다. 민주 사회가 잘 기능하려면 정치 지식과 민주주의 신념이라는 시민적 자질이 필요하다.","keys":["참여 민주주의","시민적 자질"]},{"h":"2문단","ev":"루소는 일반의지는 대표될 수 없고 대의제에서 시민은 선거 때만 자유롭다며 직접 민주주의를 주장했다. 참여의 교육 효과로 공동체 소속감이 커진다고 봤다.","keys":["일반의지","직접 민주주의","교육적 기능"]},{"h":"3문단","ev":"밀은 모든 시민이 주권에 참여함이 가장 좋지만 큰 사회에서는 대의제가 이상적이라 했다. 참여는 시민적 자질을 키우며 효과는 일상에 닿는 지방 수준에서 더 커 지방자치를 중시했다.","keys":["대의제","교육적 효과","지방자치"]},{"h":"4문단","ev":"페이트먼은 참여를 투표로 제한하는 대의제를 비판하고 삶의 여러 영역에서 민주주의를 생활화해야 한다고 했다. 참여가 체제 유지의 자질을 키우므로 안정성을 해치지 않는다고 봤다.","keys":["페이트먼","생활 속 참여","체제 안정성"]},{"h":"5문단","ev":"바버는 대의제를 개인의 자유와 양립 못 하는 ‘약한 민주주의’로 규정하고, 시민 교육과 공동 목표를 추구하는 정치 공동체에 의존하는 참여 민주주의가 ‘강한 민주주의’라 했다.","keys":["약한 민주주의","강한 민주주의","정치 공동체"]}],"key":"루소·밀은 참여의 교육적 효과를, 페이트먼·바버는 대의제의 한계와 참여 민주주의를 강조한다.","pt":["루소·바버는 대의제가 개인의 자유와 양립하지 못한다고 봤다 — 양립 가능하다는 선지는 오답","밀: 참여의 교육적 효과는 일상에 직접 닿는 지방 수준에서 더 커서 지방자치를 중시","(보기) 참여 회의론: 바이마르 사례로 페이트먼을, 실증 근거 부족을 들어 밀의 교육 효과론을 반박"],"src":"본책 p.144~148 · 해설 p.52~54","s":"수특 독서 · 사회·문화"},"r36":{"t":"교류 욕구 이론","cat":"사회·문화","steps":[{"h":"1문단","ev":"터너의 교류 욕구는 사회적 상호작용에서 정도 차이는 있어도 늘 활성화되는 근본적 욕구이며, 충족 여부가 상호작용의 흐름에 큰 영향을 준다.","keys":["교류 욕구","상호작용"]},{"h":"2문단 (1)","ev":"하위 욕구 중 가장 중요한 것은 정체성을 검증받으려는 욕구다. 자아는 핵심·사회적·집단적·역할 정체성의 네 가지로 이뤄진다.","keys":["정체성 검증","네 정체성"]},{"h":"2문단 (2)","ev":"핵심·사회적 정체성은 거의 모든 상황에서 나타나며 무의식적 요소가 남지만, 집단적·역할 정체성은 특정 집단·역할 수행 과정에서 나타나 개인이 알아차리고 명료화할 수 있다.","keys":["핵심·사회적","집단적·역할"]},{"h":"3문단","ev":"타자가 정체성을 수용하면 긍정적 감정과 몰입이, 수용하지 않으면 분노·수치 같은 부정적 감정이 생긴다. 수용되지 않았음을 인식할 때에만 행동을 고치려는 동기가 생긴다.","keys":["긍정적·부정적 감정","행동 수정"]},{"h":"4문단","ev":"검증 실패의 부정적 감정은 방어 전략으로 피하는데 귀인이 핵심이다. 긍정 감정은 자신·당면한 타자에게(구심적), 부정 감정은 사회적 범주·구조 같은 먼 대상에게(원심적) 돌린다.","keys":["귀인","구심적 편향","원심적 편향"]},{"h":"5문단","ev":"정체성을 검증받게 하는 사회 구조는 개인의 몰입을 이끈다. 특정 상황에서 긍정적 감정을 거듭 경험하면 이를 사회 구조에 귀인해 구조에 대한 긍정적 감정과 몰입이 강해진다.","keys":["사회 구조","몰입"]}],"key":"터너는 정체성 검증 욕구가 감정과 귀인을 거쳐 행동과 사회 구조에 대한 태도까지 좌우한다고 본다.","pt":["핵심·사회적 정체성은 무의식적 요소가 남고, 집단적·역할 정체성은 개인이 알아차려 명료화할 수 있다","귀인 편향: 긍정 감정은 구심적(자신·당면한 타자), 부정 감정은 원심적(사회적 범주·구조)","행동 수정의 동기는 욕구 충족 때가 아니라 정체성이 수용되지 않았음을 인식할 때 생긴다"],"src":"본책 p.149~152 · 해설 p.54~55","s":"수특 독서 · 사회·문화"},"r37":{"t":"중세 청빈 논쟁(사용·소유 분리)","cat":"사회·문화","steps":[{"h":"1문단","ev":"프란체스코 수도회는 재정 어려움 속에 기부 재산을 사용하되 소유하지는 않는다는 입장을 취했고, 교황 그레고리우스 9세는 그 재산의 소유권을 편의상 교황에게 귀속시킬 수 있게 했다.","keys":["청빈","사용과 소유의 분리","교황에게 귀속"]},{"h":"2문단","ev":"물질적 풍요가 내부 반발과 지나친 배려라는 외부 비판을 부르자, 교황 인노켄티우스 4세는 개인이 아닌 수도회 자체에 재산을 소유할 수 있는 법적 인격을 부여해 사태를 진정시켰다.","keys":["법적 인격","수도회 자체"]},{"h":"3문단","ev":"보나벤투라는 법적 권리에 의한 사용과 권리와 무관한 단순한 사용을 구별했고 교황이 승인했다. 비판자들은 영구적 사용은 권리와 다름없다고 했고 올리비는 ‘가난한 사용’을 요구했다.","keys":["단순한 사실상 사용","법적 권리에 의한 사용"]},{"h":"4문단 (1)","ev":"보나그라티아는 단순한 사실상 사용이 동물의 먹이 섭취처럼 법적 인격 없이 이뤄지고, 상위법인 자연의 법에 따르므로 실정법이 금지할 수 없다고 옹호했다.","keys":["자연의 법","실정법"]},{"h":"4문단 (2)","ev":"교황 요한 22세는 소비하면 사라지는 음식 같은 소비재에서 사용과 소유를 구별할 수 없다고 비판했다. 숙소·성당은 수도회의 반발로 번복되었으나 소비재는 물러서지 않았다.","keys":["요한 22세","소비재"]},{"h":"5문단","ev":"오컴은 수도자의 윤리가 규범 복종이 아니라 근원적 자유를 전제로 의무 이상을 실천하는 데 있다고 보았다. 이들이 거부한 것은 규범 질서의 사용권이지 단순한 사실상 사용이 아니다.","keys":["근원적 자유","사용권 거부"]}],"key":"청빈 논쟁은 사용과 소유의 분리를 둘러싼 법리 다툼으로 번졌고, 오컴은 이를 근원적 자유의 문제로 보았다.","pt":["단순한 사실상 사용 = 법적 권리와 무관, 생명 유지에 필수인 물건 대상 — 반환 전제의 일시적 사용 아님","보나그라티아는 법적 인격 없는 사용(동물 비유)과 자연의 법을 근거로 들었고, 요한 22세는 소비재에서 구별을 부정","(㉮ 추론) 수도회에 법적 인격을 주면 소유권만 설명될 뿐 단순한 사용의 근거가 되지는 않는다"],"src":"본책 p.153~156 · 해설 p.56~58","s":"수특 독서 · 사회·문화"},"r38":{"t":"민주정과 공화정","cat":"사회·문화","steps":[{"h":"1문단","ev":"대중적 정부는 파벌(공동체 전체 이익과 어긋나는 일부만의 집단)의 위험에 노출된다. 파벌이 소수면 선거로 막지만 다수면 공공선과 다른 시민의 권리를 희생시킬 수 있다.","keys":["파벌","다수의 파벌"]},{"h":"2문단","ev":"매디슨은 이를 다수 지배를 핵심으로 하는 민주주의의 치명적 약점으로 본다. 다수가 자기 이익이 걸린 일에 권력을 중립적으로 쓰길 기대하기 어렵지만, 결사의 자유를 없앨 수도 없다.","keys":["민주주의의 약점","결사의 자유"]},{"h":"3문단","ev":"시민이 정부를 직접 운영하는 소규모 사회인 순수한 민주정에는 지배적 다수를 제어할 수단이 없고, 평등이 보장돼도 시민은 동등해질 수 없다. 역사적으로도 혼란 속에 단명했다.","keys":["순수한 민주정","제어 수단의 부재"]},{"h":"4문단","ev":"대안은 선출된 대표를 통해 권력을 행사하는 공화정이다. 정치적 평등이 과제가 아니며, 시민의 직접 참여를 피하는 개념이라 현대의 간접 민주주의와 같지 않다.","keys":["공화정","대표","간접 민주주의와 구별"]},{"h":"5문단","ev":"대표는 지혜·애국심·정의에 대한 사랑을 갖춘 국익의 수호자여야 하며, 이는 평민과 국왕을 견제하는 ‘중간적 권력’인 귀족에게 기대할 자질이다. 일반 시민에게는 기대하기 어려웠다.","keys":["대표의 조건","중간적 권력(귀족)"]},{"h":"6문단","ev":"그래도 공화정의 이상은 시민 스스로 공공선을 추구할 때보다 나은 결과를 약속하려는 것이다. 공공의 목소리는 시민이 직접 낼 때보다 대표가 낼 때 공익에 더 잘 공명한다고 믿었다.","keys":["공공선","대표를 통한 공명"]}],"key":"매디슨은 다수 지배의 파벌 폐해를 못 고치는 순수 민주정 대신, 대표를 통해 공공선을 추구하는 공화정을 택했다.","pt":["순수한 민주정의 치명적 약점: 다수가 당파적 이익을 쫓아도 이를 바로잡을 구조적 수단이 없다","공화정은 파벌 형성의 자유를 없애는 것도, 정치적 평등의 실현도 목표가 아니다 — 대표를 매개로 위험을 줄임","공화정의 ‘대표’는 혼합정체의 귀족정 요소에 해당하며 당파가 아닌 국익의 수호자여야 한다"],"src":"본책 p.157~161 · 해설 p.58~60","s":"수특 독서 · 사회·문화"},"r39":{"t":"법적 의제","cat":"사회·문화","steps":[{"h":"1문단","ev":"법적 의제는 사실이 아닌 것을 법적으로 사실처럼 취급하고 반대 증거가 있어도 이를 고수하는 것이다. 실종 선고를 받은 사람이 살아 있어도 취소 전까지 사망으로 보는 것이 예다.","keys":["법적 의제","실종 선고"]},{"h":"2문단","ev":"벤담은 법적 의제를 가장 해롭고 비열한 거짓말이라 비판했고, 블랙스톤은 바람직한 목표의 달성에 기여하는 유용한 수단이라며 옹호했다.","keys":["벤담","블랙스톤"]},{"h":"3문단","ev":"메인에 따르면 진보하는 사회에서는 법이 뒤처질 때마다 변화에 적응해 틈을 메우고, 법적 의제는 사회와 법의 조화를 이끄는 장치의 하나였다. 정체된 사회에서는 법이 족쇄가 된다.","keys":["메인","사회와 법의 조화"]},{"h":"4문단","ev":"좁은 의미는 사실에 어긋나는 진술을 법적 힘으로 부인 못 하게 한 것이고, 넓은 의미는 문언은 그대로인 채 실제 작용이 바뀐 사실을 숨기는 모든 가정이다.","keys":["좁은 의미","넓은 의미"]},{"h":"5문단","ev":"메인은 벤담의 비판을 무지로 보면서도, 입양처럼 유년기 사회엔 유용했으나 성숙한 사회엔 부적절하다고 본다. 개념의 체계적 분류를 저해하므로 법체계에 정착시키자는 견해에 반대한다.","keys":["유용성의 한계","체계적 분류 저해"]},{"h":"6문단","ev":"그럼에도 근대 법체계에도 법적 의제의 그림자가 짙다. 법원이 규칙을 ‘발견’했다고 하면서 실제로는 법을 바꾸는 경우처럼 의제임이 드러나지 않기도 한다.","keys":["법의 발견","숨은 의제"]}],"key":"메인은 법적 의제를 사회와 법의 조화 장치로 인정하나, 성숙한 근대 법체계에서는 부적절하다고 본다.","pt":["넓은 의미의 법적 의제는 법 규칙의 문언이 유지된다는 사실이 아니라 ‘실제 작용이 바뀐 사실’을 숨기는 가정","메인의 입장: 벤담의 비판에는 반대, 유용성은 인정하되 근대 법체계에 정착시키자는 견해엔 반대","(보기) 성년 의제는 혼인한 미성년자를 성년자로 보아 동의·취소 같은 보호 제도의 적용을 배제"],"src":"본책 p.162~165 · 해설 p.60~61","s":"수특 독서 · 사회·문화"},"r40":{"t":"후성 유전학 항암 치료","cat":"과학·기술","steps":[{"h":"1문단","ev":"후성유전은 DNA 염기서열을 바꾸지 않고 화학적 변형만으로 유전자 발현을 조절하는 과정이다.","keys":["후성유전","염기서열 불변"]},{"h":"2문단","ev":"DNA 메틸화는 전사를 막는 정지 신호이고, 히스톤 아세틸화는 DNA와의 결합을 풀어 전사를 돕지만 HDAC가 아세틸기를 떼면 다시 억제된다.","keys":["DNA 메틸화","히스톤 아세틸화","HDAC"]},{"h":"3문단","ev":"종양억제유전자가 과메틸화나 탈아세틸화로 꺼지면 세포주기 조절과 세포자살이 무너져 정상 세포가 암세포로 변한다.","keys":["종양억제유전자","세포주기","세포자살"]},{"h":"4문단","ev":"기존 항암제는 빨리 분열하는 세포를 공격해 정상 세포까지 다치게 하지만, 후성유전적 항암제는 오류를 바로잡아 암세포를 정상처럼 행동하게 한다.","keys":["기존 항암제","후성유전적 항암제"]},{"h":"4문단(약물)","ev":"5-아자사이티딘류는 DNMT를 막아 메틸화를 없애고, 보리노스타트는 HDAC를 막아 아세틸화를 유지해 종양억제유전자를 되살린다.","keys":["DNMT 저해","HDAC 저해"]},{"h":"5문단","ev":"이중적중모델은 두 대립유전자의 돌연변이를 요구했으나, 후성유전적 오류가 하나 또는 둘 모두를 대신해도 암이 생기며 이 오류는 가역적이다.","keys":["이중적중모델","가역적"]}],"key":"후성유전적 오류로 꺼진 종양억제유전자를 약물로 되살려 암세포를 정상으로 되돌린다.","pt":["약물–효소 짝 바꾸기: 메틸기 제거는 DNMT 저해제, 보리노스타트는 HDAC 저해제","㉠ 기존 항암제(분열 속도 겨냥)와 ㉡ 새 항암제(본래 세포 프로그램 복원)의 대비","보기: HDM 저해제는 메틸기 제거를 막아 발현을 되살리지만 염기서열 돌연변이는 못 고친다"],"src":"본책 p.168~171 · 해설 p.62~63","s":"수특 독서 · 과학·기술"},"r41":{"t":"양자점 디스플레이","cat":"과학·기술","steps":[{"h":"1문단","ev":"원자 하나에서는 전자의 에너지준위가 특정한 값이지만, 원자가 많이 모이면 궤도가 겹쳐 준위가 범위(에너지밴드)가 된다.","keys":["에너지준위","에너지밴드"]},{"h":"2문단","ev":"나노미터 크기의 반도체 입자인 양자점은 작을수록 전자의 에너지 변동폭이 커 푸른빛을, 클수록 붉은빛을 낸다.","keys":["양자점","에너지 변동폭","입자 크기"]},{"h":"3문단","ev":"에너지밴드 물질은 파장이 넓게 퍼지고 열이 나지만, 양자점은 좁은 파장의 빛을 내 원색에 가깝고 발열이 적다.","keys":["파장 범위","원색","발열"]},{"h":"4문단","ev":"양자점은 코어·셸·리간드로 이루어지며, 작을수록 부피보다 표면적이 덜 줄어 셸과 리간드의 영향이 커진다.","keys":["코어","셸","리간드","표면적 비"]},{"h":"5문단","ev":"독성이 있는 카드뮴 대신 갈륨·인을 쓰려 하나 결합력이 약해 합성이 어렵고 성능과 수명이 떨어져 리간드를 개선하고 있다.","keys":["갈륨·인","합성의 어려움"]}],"key":"양자점은 크기로 색이 정해지고 좁은 파장을 내 화질이 좋으며, 작을수록 셸·리간드가 중요하다.","pt":["크기↓ → 변동폭↑ → 빛에너지↑ → 파장↓(푸른빛)의 연쇄 (보기에서 큰 쪽은 붉은 B)","㉠ 이유: 작아지면 부피보다 표면적이 덜 줄어 표면층의 상대적 영향이 커진다","보기 적용: 좁은 준위는 열이 적다 / 전류를 쓰는 태양전지는 셸 대신 코어·리간드 안정화"],"src":"본책 p.172~175 · 해설 p.63~65","s":"수특 독서 · 과학·기술"},"r42":{"t":"수생 동물의 호흡","cat":"과학·기술","steps":[{"h":"1문단","ev":"육상동물은 폐가 건조해질 위험이 있고, 수생동물은 산소가 적은 물과 열 손실, 삼투압 문제 속에서 호흡해야 한다.","keys":["육상동물","수생동물","가용 산소"]},{"h":"2문단","ev":"외아가미는 몸 밖으로 돌출되어 표면적이 넓지만 많이 흔들어야 하고 손상과 공격에 취약하다.","keys":["아가미","외아가미"]},{"h":"3문단","ev":"내아가미는 덮개 안에서 보호받으며, 라멜라 속 모세혈관에서 구심성 혈관의 혈액이 원심성 혈관으로 가며 기체를 교환한다.","keys":["내아가미","라멜라","구심성·원심성"]},{"h":"4문단","ev":"물이 혈류와 반대 방향(역류)으로 라멜라 사이를 흘러 산소 압력 기울기가 유지되므로 기체 교환이 최대가 된다.","keys":["역류","압력 기울기"]},{"h":"5문단","ev":"입펌프는 입과 덮개의 공간을 넓혀 수압을 낮추고 압력 차로 물을 한 방향으로 흘리며, 고요한 물에서 쓴다.","keys":["입펌프","수압 차"]},{"h":"6문단","ev":"강제환수는 흐르는 물에서 입을 벌린 채 머물거나 유영하며 물을 통과시키는 방식으로 입펌프보다 에너지가 덜 든다.","keys":["강제환수","에너지 효율"]},{"h":"7문단","ev":"두 방식은 한 방향 관류체계라 육상의 간만환기보다 효율적이지만, 물의 밀도 때문에 환수에만 휴지대사율의 10~20%를 쓴다.","keys":["관류체계","간만환기","휴지대사율"]}],"key":"내아가미는 물과 혈액을 반대로 흐르게(역류) 해 산소를 최대로 얻고, 환수는 입펌프와 강제환수로 한다.","pt":["역류가 교환을 최대화하는 이유: 물이 계속 산소 낮은 혈액과 닿아 압력 기울기가 유지된다","㉠입펌프·㉡강제환수: 둘 다 한 방향 관류(양방향 아님), 에너지는 ㉡이 적게 든다","보기 그림: 원심성 혈관(D)의 혈액이 구심성(E)보다 산소가 많다"],"src":"본책 p.176~180 · 해설 p.65~67","s":"수특 독서 · 과학·기술"},"r43":{"t":"하디-바인베르크 평형","cat":"과학·기술","steps":[{"h":"1문단","ev":"하디는 대립유전자 빈도 p·q로 다음 세대의 유전자형 빈도를 분석하고, 바인베르크는 무작위 결합 시 유전자 빈도가 세대를 거쳐도 일정하다고 본다.","keys":["하디-바인베르크","유전자 빈도"]},{"h":"2문단","ev":"평형은 집단이 충분히 크고 무작위 교배이며 돌연변이·이주·자연선택이 없을 때 유지된다.","keys":["집단 크기","무작위 교배","돌연변이·이주","자연선택"]},{"h":"3문단(1)","ev":"유전자 빈도는 전체 유전자 수에서 해당 대립유전자 수가 차지하는 비율이며, 두 빈도의 합 p+q는 1이다.","keys":["유전자 빈도","p+q=1"]},{"h":"3문단(2)","ev":"유전자형 빈도는 AA는 p², Aa는 2pq, aa는 q²이며 합이 1이고, 빈도가 유지되면 다음 세대에서도 일정하다.","keys":["p²","2pq","q²"]},{"h":"4문단","ev":"열성 유전병 보인자 추정, 멸종위기종의 유전적 다양성 분석, 친자 확인, 법의학 DNA 증거의 우연 일치 확률 계산에 응용된다.","keys":["보인자 추정","친자 확인","법의학"]}],"key":"다섯 조건이 충족되면 유전자 빈도가 세대 간 일정해, p²·2pq·q²로 유전자형 빈도를 예측한다.","pt":["유전자 빈도는 개체 수가 아니라 유전자 수의 비율이라는 점(선지 함정)","보기: 포식자에게 잡아먹힘은 이입(㉣)이 아니라 자연선택(㉤) 위반","X 연관 열성 보기: 남성 발현 q, 여성 발현 q², 여성 보인자 2pq의 크기 비교"],"src":"본책 p.181~185 · 해설 p.67~69","s":"수특 독서 · 과학·기술"},"r44":{"t":"이동식 크레인","cat":"과학·기술","steps":[{"h":"1문단","ev":"이동식 크레인은 바퀴나 무한궤도로 이동하며 동력으로 화물을 들어올리고 옮겨 건설을 빠르고 효율적으로 만든다.","keys":["이동식 크레인"]},{"h":"2문단","ev":"붐은 도달 범위와 높이를 정하고 수직 움직임은 기복, 수평 움직임은 선회이며, 길이를 유압실린더로 조절하는 붐은 유압식 붐이다.","keys":["붐","기복","선회","아웃트리거"]},{"h":"3문단(1)","ev":"안정모멘트(크레인 중량×무게중심~전도축 거리)가 양중모멘트(물체 무게×물체~전도축 거리) 이상이어야 전도가 일어나지 않을 수 있다.","keys":["안정모멘트","양중모멘트","전도축"]},{"h":"3문단(2)","ev":"양중능력표의 값은 물체 무게에 후크 등 부가 하중까지 포함해 임계하중의 75~85% 수준으로 잡으며, 전도는 시작되면 되돌릴 수 없다.","keys":["양중능력표","임계하중"]},{"h":"4문단","ev":"받침목은 지면 압력을 분산해 가라앉지 않게 하고, 하중 반대쪽 평형추는 안정모멘트를 키워 전도를 막는다.","keys":["크레인 받침목","평형추"]}],"key":"안정모멘트가 양중모멘트 이상이어야 전도가 없고, 받침목과 평형추가 이를 돕는다.","pt":["붐 구분 뒤바꿈 주의: 수직=기복, 수평=선회, 길이 조절은 유압식 붐","양중모멘트=물체 무게×거리 → 거리가 짧아지면 양중능력은 커진다(보기 표)","전도 방지: 압력을 한곳에 집중하는 게 아니라 분산하고, 평형추로 안정모멘트를 키운다"],"src":"본책 p.186~189 · 해설 p.69~70","s":"수특 독서 · 과학·기술"},"r45":{"t":"식물의 생장","cat":"과학·기술","steps":[{"h":"1문단","ev":"식물은 분열조직으로 계속 자라며, 측생분열조직은 부피생장을, 정단분열조직은 길이생장을 맡는다.","keys":["측생분열조직","정단분열조직"]},{"h":"2문단","ev":"관다발형성층은 물관·체관 사이에서 관다발 조직을 만들고, 코르크형성층은 표피 아래에서 수분 손실을 막는 보호조직을 만든다.","keys":["관다발형성층","코르크형성층"]},{"h":"3문단","ev":"뿌리 끝은 분열대에서 시원세포가 분열하고, 신장대에서 세포가 늘어나며, 성숙대에서 분열 없이 조직으로 분화한다.","keys":["분열대","신장대","성숙대"]},{"h":"4문단","ev":"슈트정단분열조직은 슈트의 맨 끝에서 시원세포가 계속 분열해 새로운 기관을 만든다.","keys":["슈트","시원세포"]},{"h":"5문단","ev":"네겔리의 정단세포설과 한스타인의 조직원설이 종자식물에 맞지 않자 슈미트의 초층-내체설과 포스터의 구역화설로 이어진다.","keys":["정단세포설","조직원설","초층-내체설","구역화설"]},{"h":"6문단","ev":"WUS는 시원세포를 미분화로 유지하고 CLV3를 활성화하며 CLV3는 WUS를 억제해 균형을 이루고, 사이토키닌은 WUS를 촉진하고 옥신은 잎·곁눈 위치를 정한다.","keys":["WUS·CLV3","사이토키닌","옥신"]}],"key":"분열조직이 부피·길이 생장을 맡고, 슈트 끝은 WUS–CLV3 되먹임과 호르몬이 시원세포 수를 조절한다.","pt":["㉠ 네겔리·한스타인 학설의 한계: 식물 전체에 보편 적용이 안 됨(층 구조는 일부에만)","분열대=세포분열 가장 활발, 신장대=길게 늘어남, 성숙대=분열·신장 없음(보기 ㄷ·ㄹ)","WUS↑ → CLV3↑ → WUS 억제; 사이토키닌은 WUS 촉진, 옥신은 위치 결정(보기 실험)"],"src":"본책 p.190~193 · 해설 p.70~72","s":"수특 독서 · 과학·기술"},"r46":{"t":"임베딩과 유사도","cat":"과학·기술","steps":[{"h":"1문단","ev":"원-핫 인코딩은 단어집합 크기만큼의 차원에서 해당 색인에 1, 나머지에 0을 두는 방식이라 단순하지만 단어 간 관계를 담지 못한다.","keys":["원-핫 인코딩","단어집합"]},{"h":"2문단","ev":"임베딩은 원-핫 값을 적절히 계산해 모든 실수로 더 낮은 차원의 숫자를 부여하며(워드투벡), 이 과정이 학습이다.","keys":["임베딩","워드투벡","학습"]},{"h":"3문단","ev":"앞뒤 단어를 주면 사이의 단어를 맞히도록 학습하며, 앞뒤 단어를 계산해 만든 [h1, h2]는 중간 계산 결과이다.","keys":["전후 문맥","[h1, h2]"]},{"h":"4문단","ev":"한 단어를 주면 이웃한 단어(범위는 임의로 정함)가 나올 확률이 높아지도록 학습한다.","keys":["이웃 단어 범위"]},{"h":"5문단","ev":"비슷한 문장에 자주 나오는 단어는 좌표에서 가깝고, 거리는 유클리드 거리와 코사인 유사도(각도 0°면 +1, 90°면 0)로 나타낸다.","keys":["유클리드 거리","코사인 유사도"]}],"key":"원-핫의 한계를 낮은 차원의 임베딩으로 보완해 단어 간 유사도를 거리와 각도로 나타낸다.","pt":["임베딩은 차원을 높이는 게 아니라 원-핫보다 낮은 차원으로 표현한다(㉡ 선지 함정)","코사인 유사도 0은 직각일 뿐이고, 유클리드 거리 0은 두 점이 같다는 뜻이다","보기: 이웃 범위가 1이면 ‘오늘’의 이웃은 기분·날씨뿐 — 범위에 따라 이웃이 달라진다"],"src":"본책 p.194~197 · 해설 p.72~73","s":"수특 독서 · 과학·기술"},"r47":{"t":"GPU","cat":"과학·기술","steps":[{"h":"1문단","ev":"복잡한 범용 작업은 고성능 코어 여러 개의 CPU가 맡았으나, 같은 연산을 대량 반복하는 작업이 늘며 병렬 연산에 강한 GPU가 떠오른다.","keys":["CPU","GPU","병렬 연산"]},{"h":"2문단","ev":"GPU는 단순 연산 전용 코어 수백~수천 개를 모아 같은 명령어를 많은 데이터에 반복 적용하며 인공지능·영상·기상 계산 등에 쓰인다.","keys":["단순 연산 코어","동일 명령어 반복"]},{"h":"3문단","ev":"코어가 묶인 연산 유닛에서 스레드가 명령어를 실행하고, 스케줄러가 스레드 블록을 유닛에 분배하며 고르지 않으면 일부가 대기한다.","keys":["스레드 블록","스케줄러","연산 유닛"]},{"h":"4문단","ev":"전역 메모리는 크지만 느려 연산 중에는 레지스터와 공유 메모리를 쓰고, 같은 블록의 스레드가 같은 공간에 동시 접근하면 충돌한다.","keys":["전역 메모리","공유 메모리","레지스터"]},{"h":"5문단","ev":"블록의 스레드는 같은 명령어를 동시에 수행하므로 분기문이 끼면 일부 스레드가 대기해 병렬성이 손실된다.","keys":["분기문","병렬성 손실"]},{"h":"6문단","ev":"CPU와 GPU의 강점을 나누어, 연산 작업의 성격에 따라 두 장치의 연산 흐름을 조정하는 구조로 발전하고 있다.","keys":["CPU·GPU 역할 분담"]}],"key":"다수의 단순 코어가 같은 연산을 병렬 처리하는 GPU는 분기문에 약해 CPU와 역할을 나눈다.","pt":["㉮ 이유: 블록 내 스레드가 같은 명령어를 동시에 수행하도록 설계돼 분기 시 일부가 대기함","CPU(㉠)도 다양한 연산이 가능하고 GPU(㉡)는 동일 연산 반복에 특화 — ‘불가능’ 선지는 오답","보기 적용: 반복 계산은 메모리 충돌을 피하게 조정, 복잡한 제어는 CPU와 분담"],"src":"본책 p.198~202 · 해설 p.73~75","s":"수특 독서 · 과학·기술"},"r48":{"t":"에너지 대사와 항상성","cat":"과학·기술","steps":[{"h":"1문단","ev":"음식물은 ATP로 전환돼 쓰이고, 섭취가 소비를 넘는 상태가 이어지면 남은 에너지가 지방산으로 지방세포에 쌓여 대사질환 위험이 커진다.","keys":["ATP","지방산","대사질환"]},{"h":"2문단","ev":"기초대사량(소비의 60~70%)이 낮거나, 과잉 에너지가 백색지방세포에 쌓이고 갈색지방세포의 활성이 낮으면 에너지 균형이 깨지기 쉽다.","keys":["기초대사량","백색지방세포","갈색지방세포"]},{"h":"3문단(1)","ev":"시상하부가 에너지 상태를 감지해 식욕과 소비를 조절하고 렙틴이 식욕을 억제하지만, 렙틴 저항성이 생기면 억제가 약해진다.","keys":["시상하부","렙틴","렙틴 저항성"]},{"h":"3문단(2)","ev":"그렐린은 공복에 늘어 식욕을 높이고, 인슐린은 혈당을 낮추며, 글루카곤은 혈당이 낮을 때 글리코젠을 포도당으로 바꿔 혈당을 지킨다.","keys":["그렐린","인슐린","글루카곤"]},{"h":"4문단","ev":"운동·규칙적인 식사·충분한 수면·적정한 추위 노출이 도움이 되고, 백색지방이 베이지지방으로 전환되는 현상이 새 방법으로 주목받는다.","keys":["신체활동","수면","베이지지방세포"]}],"key":"인체는 호르몬 조절과 생활 요인으로 섭취·소비 에너지의 균형(항상성)을 유지한다.","pt":["저장된 포도당은 그대로 에너지원이 아니라 ATP로 전환돼야 쓰인다(선지 함정)","남는 에너지가 지방산으로 쌓여 지방세포가 커지는 것 — 인과 순서를 뒤집은 선지에 주의","보기(GLP-1 유사체): 시상하부에 작용해 렙틴↑·그렐린↓로 식욕을 억제, 지방세포 전환과는 무관"],"src":"본책 p.203~206 · 해설 p.75~77","s":"수특 독서 · 과학·기술"},"r49":{"t":"지자기 역전","cat":"과학·기술","steps":[{"h":"1문단","ev":"블래킷은 자전하는 지구의 각운동량이 자기장을 만든다고 주장하지만, 잔류지자기에서 자기장 방향이 바뀐 것이 드러나 가설이 반박된다.","keys":["블래킷 가설","잔류지자기"]},{"h":"2문단","ev":"같은 시기의 암석이 지역마다 다른 자극을 가리켜 대륙이 움직였다는 쪽이 힘을 얻고 베게너의 대륙이동설이 되살아난다.","keys":["자극 이동 가설","대륙이동설"]},{"h":"3문단","ev":"암석의 자기가 완전히 반대로 나타나는 변칙을 두고, 암석 자체 역전 가설은 물리적 증거가 없어 지구자기장 역전 가설이 정설이 된다.","keys":["지자기 역전","변칙"]},{"h":"4문단(1)","ev":"뤼턴은 정확한 시간 규모를 못 재지만, 방사성 포타슘이 일정한 비율로 아르곤이 되는 점을 쓴 연대측정으로 시간표가 가능해진다.","keys":["포타슘-아르곤","붕괴 비율"]},{"h":"4문단(2)","ev":"캘리포니아 대학팀과 호주 과학자들의 시간표가 달라 채취 깊이에 주의가 필요함이 드러나고, 하라미요 역전이 약 100만 년 전으로 확정돼 지자기 역전이 사실로 받아들여진다.","keys":["하라미요 역전","채취 깊이"]}],"key":"잔류지자기 연구가 대륙이동설을 되살리고, 포타슘-아르곤 연대측정으로 지자기 역전이 사실로 굳는 과정이다.","pt":["[A]: 후속 경험적 증거가 한쪽 가설만 지지해 판정된 사례(논증의 철저함·이론 연역이 아님)","추론: 지자기 역전은 전 지구적 현상이고, 암석 자체 역전과 지구자기장 역전은 서로 상충한다","㉠: 방사성 포타슘 대비 아르곤 비율이 큰 암석이 더 오래되었다고 판정(변환 비율은 일정 가정)"],"src":"본책 p.207~210 · 해설 p.77~79","s":"수특 독서 · 과학·기술"},"r50":{"t":"CFC와 오존층","cat":"과학·기술","steps":[{"h":"1문단","ev":"성층권에서 태양복사선과 산소 분자로 오존이 생성되고 질소산화물 관련 과정으로 분해되어, 두 과정의 균형이 오존 농도를 일정하게 지킨다.","keys":["오존층","생성과 분해의 균형"]},{"h":"2문단(1)","ev":"CFC는 반응성이 낮은 무독성 기체로 널리 쓰였으나 비에 분해되지 않고 성층권 상층부에서 자외선에 분해되어 염소원자를 낸다.","keys":["CFC","염소원자"]},{"h":"2문단(2)","ev":"염소원자는 오존을 산소로 분해하는 반응을 매개하면서 스스로 보존되는 촉매이고, 염소원천화합물이 분해돼 자유라디칼 염소원자를 계속 공급한다.","keys":["촉매","염소원천화합물","자유라디칼"]},{"h":"3문단","ev":"1985년 남극 오존구멍이 발견되고 1987년 몬트리올의정서로 CFC 사용을 줄였으나 구멍은 한동안 커졌다가 서서히 회복 추세이다.","keys":["남극 오존구멍","몬트리올의정서"]}],"key":"CFC에서 나온 염소원자가 촉매로 오존을 계속 분해해 남극 오존구멍을 일으킨 과정과 대응이다.","pt":["CFC는 성층권에서 합성되는 것이 아니라 분해되어 염소원자를 내놓는다(선지 함정)","㉠ 자유라디칼 염소원자: 염소원천화합물이 태양복사선에 분해돼 생기며, 태양복사선 때문에 소멸하는 것은 아님","보기 그래프: 8월 20km 부근은 오존 농도가 높아 ‘분해가 더 촉진’이라 할 수 없고, 10월엔 70% 이상 감소"],"src":"본책 p.211~213 · 해설 p.79~81","s":"수특 독서 · 과학·기술"},"r51":{"t":"물리적 실재","cat":"과학·기술","steps":[{"h":"1문단","ev":"물리적 실재는 지각 주체와 독립적으로 있다고 보지만 감각만으로는 온전히 알 수 없어, 그 개념은 추론으로 구성되고 새 증거에 따라 고쳐진다.","keys":["물리적 실재","추론","개정"]},{"h":"2문단","ev":"뉴턴은 공간·시간·입자와 힘으로 실재를 설명하고, 입자는 관성과 병진운동만 가진 질점으로 진공 속 원격작용인 중력을 받아 움직인다.","keys":["질점","원격작용","중력"]},{"h":"3문단","ev":"뉴턴은 빛도 무게 없는 입자로 보고, 18세기 뉴턴주의자들은 무게 없는 입자와 고유한 힘으로 빛·전기·자기를 설명한다.","keys":["빛의 입자관","뉴턴주의"]},{"h":"4문단","ev":"패러데이는 공간이 텅 빈 것이 아니라 매질로 차 있다고 보고, 전기력·자기력이 전달되는 방식을 역선과 장으로 나타낸다.","keys":["연속체","역선","장"]},{"h":"5문단","ev":"맥스웰은 패러데이의 장 개념을 다변수 함수의 미적분으로 표현하고 빛을 전자기적 파동으로 보아 전자기파를 예견한다.","keys":["다변수 함수","전자기파"]},{"h":"6문단","ev":"헤르츠가 전자기파를 확인하고 로렌츠는 물질을 전자기적 연속체로 서술하며, 아인슈타인은 중력까지 장(시공간 왜곡)으로 표현한다.","keys":["헤르츠","로렌츠","중력장"]}],"key":"물리적 실재 개념이 뉴턴의 입자·원격작용에서 패러데이 이후의 연속체·장 개념으로 확장돼 간 과정이다.","pt":["뉴턴(진공 속 질점·원격작용)과 패러데이(매질로 찬 공간·장)의 대비","㉠ 연속체 개념은 ‘빈 공간에서 떨어진 물체 간의 힘’으로 전기·자기를 다루는 것이 아님","보기(데카르트): 진공 부정·접촉 압력 설명이 뉴턴·패러데이·아인슈타인과 어떻게 같고 다른지"],"src":"본책 p.214~217 · 해설 p.81~84","s":"수특 독서 · 과학·기술"},"r52":{"t":"샤딩","cat":"과학·기술","steps":[{"h":"1문단","ev":"분산파일관리체계는 저렴한 저성능 기계 여러 대로 데이터를 나눠 관리해 비용을 줄이고, 고장이나 해킹의 피해도 줄인다.","keys":["분산파일관리체계","저성능 기계"]},{"h":"2문단(1)","ev":"샤딩은 데이터를 샤드로 나눠 저장하고, 라우터가 해당 샤드를 찾아 조회하며 설정서버가 분할·위치 정보를 관리한다.","keys":["샤드","라우터","설정서버"]},{"h":"2문단(2)","ev":"저장소 분산은 저가 기계를 합쳐 비용을 줄이고, 부하 분산은 쓰기·읽기·연산을 기계마다 나눠 신속히 처리하게 한다.","keys":["저장소 분산","부하 분산"]},{"h":"3문단(1)","ev":"필요한 데이터가 여러 샤드에 흩어지면 성능 병목이 생기므로 한 요청의 데이터를 한 샤드에 두는 지역성을 확보해야 한다.","keys":["성능 병목","데이터 지역성"]},{"h":"3문단(2)","ev":"샤드마다 내용이 달라 복구가 어려워 장애허용성이 낮은데, 같은 내용을 다른 기계에 두는 복제를 결합하면 복구와 읽기 분산이 된다.","keys":["장애허용성","복제"]},{"h":"3~4문단","ev":"복제의 쓰기는 원본과 모든 복제본에 일관되게 적용해야 해 느려지고, 통신 지연으로 일관성이 일시적으로 깨지는 문제는 남는다.","keys":["쓰기 일관성","일시적 불일치"]}],"key":"샤딩은 데이터를 쪼개 여러 기계에 나눠 비용·부하를 줄이고, 복제를 결합해 약한 복구력을 보완한다.","pt":["샤딩의 약점: 통신 지연이 단일 기계의 연산 부하 지연보다 클 수 있다 — ‘더 짧다’ 선지는 오답","라우터는 요청에 맞는 샤드를 조회해 클라이언트에 전달(서버 아님), 설정서버가 위치·로그 저장","복제 보기: 마스터–슬레이브는 마스터가 하나, 피어 투 피어는 대등 — 어느 쪽이든 일시적 불일치"],"src":"본책 p.218~221 · 해설 p.84~86","s":"수특 독서 · 과학·기술"},"r53":{"t":"왕필·곽상","cat":"주제 통합","steps":[{"h":"(가) 1~2문단","ev":"위진남북조에 존재의 근원을 묻는 논의가 일어나고, 왕필은 무를 만물을 가능케 하는 절대적 원리로 보아 유는 무에서 비롯된다고 본다.","keys":["왕필","무(無)","유는 무에서 비롯"]},{"h":"(가) 3문단","ev":"무위는 ‘하지 않음’이 아니라 ‘억지로 하지 않음’이며, 군주는 도의 질서를 거스르지 않고 백성이 자율적으로 역할을 하도록 여건만 마련한다.","keys":["무위","군주의 역할"]},{"h":"(가) 4문단","ev":"왕필은 도에 따른 통치가 무위이치로 실현된다고 보며, 질서는 규율이 아니라 구성원이 도의 이치를 내면화해 자발적으로 행동할 때 생기고 이는 유가와 도가의 융합이다.","keys":["무위이치","내면화","유가와 융합"]},{"h":"(나) 1~2문단","ev":"곽상은 제물론에서 만물이 우열 없이 동등하다고 보고, 존재가 스스로의 원리로 저절로 생겨 변한다는 독화론과 고정된 규범이 없다는 유동적 세계관을 편다.","keys":["제물론","독화론"]},{"h":"(나) 3문단","ev":"곽상은 왕필의 무일원론이 다양성과 개체의 자율성을 놓친다고 비판하며, 무를 실체가 아니라 존재들의 관계 속에서 드러나는 배경 조건으로 본다.","keys":["무일원론 비판","배경적 조건"]},{"h":"(나) 4문단","ev":"곽상의 사상은 성리학의 ‘이’ 해석에 영향을 주고 불교의 공 사상과 통하며, 존재의 자율성과 다양성을 강조해 현대 다원주의 사회에도 통찰을 준다.","keys":["후대 영향","다원주의"]}],"key":"왕필은 무를 근원으로 한 무위의 통치를, 곽상은 이를 비판해 존재의 독립성·다양성을 내세운다.","pt":["(가)·(나) 공통: 철학자의 사상을 제시하고 그 사상이 후대 사상에 미친 영향까지 서술","㉠의 전제: 도에는 스스로 조화를 이루는 질서가 있어 인간이 그에 따라 자율적으로 살 수 있다","곽상은 무를 실제 존재하는 사물로 보지 않았다 / ㉯독화론은 개체의 독립성을 인정(선지 뒤바꿈)"],"src":"본책 p.223~227 · 해설 p.87~89","s":"수특 독서 · 주제 통합"},"r54":{"t":"부르디외·기든스의 세계화","cat":"주제 통합","steps":[{"h":"(가) 1문단","ev":"부르디외는 세계화를 기득권이 지배를 유지·확장하는 전략으로 보고, 자본을 경제·사회·문화·상징자본으로 나누어 위계와 불평등이 커진다고 본다.","keys":["경제·사회자본","문화·상징자본"]},{"h":"(가) 2문단","ev":"지배층은 비물리적 상징폭력으로 사람들의 무의식적 습성인 아비투스에 영향을 줘 지배질서를 재생산하고, 세계화를 협동의 통합으로 받아들이게 한다.","keys":["상징폭력","아비투스"]},{"h":"(가) 3문단","ev":"부르디외는 세계화로 국가권력이 약해져 복지가 줄어드는 것을 우려해 공공서비스 확대, 시민교육, 국제주의 연대로 맞서야 한다고 본다.","keys":["공공서비스 확대","시민교육","국제주의 연대"]},{"h":"(나) 1문단","ev":"기든스는 세계화를 근대성의 확장으로 보고, 시간과 공간이 분리되고 삶이 특정 장소에 묶이지 않는 장소귀속 탈피가 일어난다고 본다.","keys":["근대성의 확장","장소귀속 탈피"]},{"h":"(나) 2문단","ev":"근대의 특징은 인간이 만든 ‘제조된 위험’이며 대응에 따라 부를 얻거나 재앙을 맞고, 세계화에는 정치 민주화·경제적 이익 같은 긍정도 있다고 본다.","keys":["제조된 위험","외부적 위험"]},{"h":"(나) 3문단","ev":"기든스는 신자유주의도 복지주의도 아닌 제3의 길로, 인적자본에 투자하는 사회투자국가와 시장·정부가 균형을 이룬 신혼합경제로 삶의 정치를 이루려 한다.","keys":["제3의 길","사회투자국가","삶의 정치"]}],"key":"부르디외는 세계화를 지배 전략으로 비판하고, 기든스는 위험과 기회를 함께 보며 제3의 길을 내세운다.","pt":["(가)는 세계화의 부정적 측면 중심, (나)는 위험과 긍정을 함께 제시 — 장단점 나열 구도가 아님","아비투스: 사회구조의 영향으로 형성되면서 기존 질서의 재생산에도 기여한다(㉮의 의미)","보기 적용: 기든스는 정부 주도가 아니라 시장·정부가 균형을 이룬 신혼합경제체제를 주장"],"src":"본책 p.228~232 · 해설 p.89~92","s":"수특 독서 · 주제 통합"},"r55":{"t":"찻주전자 효과와 젖음성","cat":"주제 통합","steps":[{"h":"(가) 1문단","ev":"찻주전자 효과(드리블링)는 따르는 속력이 줄면 액체가 주둥이에서 떨어지지 않고 바깥면을 타고 흐르는 현상이다.","keys":["찻주전자 효과","드리블링"]},{"h":"(가) 2문단","ev":"이탈각이 작을수록 효과가 크며, 주둥이의 젖음성이 클수록·곡률반경이 클수록·유속이 느릴수록 이탈각이 줄고, 점성은 영향이 없다.","keys":["이탈각","젖음성","곡률반경","점성 무관"]},{"h":"(가) 3문단","ev":"해결책은 속력을 일정값 이상으로 유지하거나, 곡률반경을 줄이거나(와인 따르개), 초소수성 재료로 주둥이 끝을 코팅하는 것이다.","keys":["속력 유지","곡률반경 감소","초소수성 코팅"]},{"h":"(나) 1문단","ev":"젖음성은 고체 표면에서 액체가 퍼지는 정도이고, 접촉각이 작을수록 젖음성이 크다(10°는 납작, 150°는 둥근 모양).","keys":["젖음성","접촉각"]},{"h":"(나) 2~3문단","ev":"표면에너지는 경계면의 면적을 줄이려는 경향이며, 고체–액체 값이 고체–기체 값보다 작으면 퍼져 접촉각이 90°보다 작고 크면 뭉쳐 90°보다 크다.","keys":["표면에너지","경계면 면적"]},{"h":"(나) 4문단","ev":"물의 접촉각이 0~90°면 친수성, 90~180°면 소수성, 150° 이상이면 초소수성이며 특수 가공한 테플론이 그 예이다.","keys":["친수성","소수성","초소수성"]}],"key":"찻주전자 효과의 요인과 해결책을, 접촉각·표면에너지로 젖음성을 설명하는 글이 보완한다.","pt":["(가)에서 생긴 의문 중 (나)로 풀리는 것: 초소수성 재료가 왜 물에 대한 젖음성이 작은가","고체–액체 표면에너지가 고체–기체보다 커지면 접촉각이 90°보다 커져 180°에 가까워진다","보기 그래프: 곡률반경이 작을수록 유속이 느려도 이탈각이 크게 유지돼 와인 따르개에 유리(c1)"],"src":"본책 p.233~237 · 해설 p.92~95","s":"수특 독서 · 주제 통합"},"r56":{"t":"사변적 실재론","cat":"주제 통합","steps":[{"h":"(가) 1문단","ev":"상관주의는 주체와 대상의 불가분 관계를 강조해 인식 주체를 벗어난 실재 논의를 거부하고, 실재를 언어적·사회적 구성물로 본다.","keys":["상관주의","구성 조건 분석"]},{"h":"(가) 2문단","ev":"사변적 실재론은 인식과 무관하게 존재하는 실재가 있다고 보고, 실험·관찰이 아닌 순수한 이성적 사유로 탐구해 철학의 권한을 회복하려 한다.","keys":["사변적 실재론","순수 이성적 사유"]},{"h":"(가) 3~4문단","ev":"브라시에는 우주의 소멸·멸종처럼 인간의 의미 구성을 넘어서는 사건을 실재로 보고, 메이야수는 어떤 존재도 필연적이지 않고 우연적이라는 사실론성의 원리를 편다.","keys":["브라시에: 소멸","메이야수: 우연성"]},{"h":"(나) 1문단","ev":"(나)는 사변적 실재론의 의의를 인정하되, 실재 존재의 부정이 아니라 실재를 사유하는 철학적 태도의 한계를 비판한다.","keys":["의의와 비판","철학적 태도"]},{"h":"(나) 2문단","ev":"가브리엘은 실재가 주체의 인식·문화와 연결된 ‘의미의 장’ 속에서만 파악된다고 보며, 탈상관주의는 의미 구성 과정을 배제해 설명력이 약해진다고 한다.","keys":["의미의 장","탈상관주의 비판"]},{"h":"(나) 3~4문단","ev":"페라리스는 실재를 철학 밖의 절대적 실체로 두면 언어적 정당성을 잃는다며 기록·언어·제도의 매개 구조를 강조하고, 철학은 그 구조를 분석해야 한다고 본다.","keys":["페라리스","매개 구조","형이상학적 순진성"]}],"key":"(가)는 인간 인식 너머의 실재를 이성으로 사유하자는 입장이고, (나)는 의미·매개 구조를 간과했다고 비판한다.","pt":["(가)=상관주의 비판·실재 중심 사유 복원, (나)=의미 구성의 매개 역할 강조라는 대비","사변적 사유는 실험·관찰이 아닌 순수한 이성적 사유 — ‘과학적 방법으로 접근’ 선지는 오답","보기 적용: 매개 구조 강조는 ‘실재가 사회적 합의로 구성됨’의 증명이 아니다(페라리스)"],"src":"본책 p.238~242 · 해설 p.95~98","s":"수특 독서 · 주제 통합"},"r57":{"t":"조세 법률주의·상속세·증여세","cat":"주제 통합","steps":[{"h":"(가) 1문단","ev":"조세법률주의는 세금의 부과와 징수가 반드시 법률에 근거해야 한다는 원칙으로, 자의적 과세를 막아 국민의 재정적 권리와 예측가능성을 지킨다.","keys":["조세법률주의","예측가능성"]},{"h":"(가) 2문단","ev":"조세열거주의는 법률에 명시된 사항만 엄격히 적용해 과세하므로 납세자 권리를 최대한 보장하고 국가의 조세권 남용을 막는다.","keys":["조세열거주의","권리 보호"]},{"h":"(가) 3문단","ev":"조세포괄주의는 문언뿐 아니라 입법취지·과세목적을 종합해 유사한 거래에도 과세하므로 조세 회피를 줄이고 형평성을 확보한다.","keys":["조세포괄주의","조세 형평성"]},{"h":"(가) 4문단","ev":"문언만 따르면 과세 공백이, 지나치게 포괄하면 납세자 권리 침해가 생기므로 두 입장의 균형으로 조세정의를 실현한다.","keys":["균형","조세정의"]},{"h":"(나) 1~2문단","ev":"상속세와 증여세는 모두 무상 이전에 붙는 세금이며, 상속세는 사망을 기준으로 상속재산 전체에 한 번 과세되고 납세 의무는 상속받은 사람에게 있다.","keys":["상속세","사망 기준","재산 전체"]},{"h":"(나) 3문단","ev":"증여세는 생전의 무상 이전에 재산을 받은 사람을 기준으로 증여 때마다 부과되며(일정 기간 합산), 특별한 경우 증여자가 대신 낼 수 있다.","keys":["증여세","개별 증여 행위","합산 과세"]}],"key":"(가)는 조세법률주의를 열거주의와 포괄주의의 균형으로, (나)는 상속세와 증여세의 차이를 설명한다.","pt":["조세포괄주의는 법조문보다 과세목적을 ‘항상’ 우선하는 게 아니라 문언·취지·목적을 종합한다","상속세=사망 기준·재산 전체에 1회, 증여세=증여마다 여러 차례(납세자는 받는 사람)","보기: 제13조 1항(사망 전 10년 내 증여 합산)대로 과세한 것은 열거주의적 해석"],"src":"본책 p.243~247 · 해설 p.98~100","s":"수특 독서 · 주제 통합"},"r58":{"t":"예술 형식과 매체","cat":"주제 통합","steps":[{"h":"(가) 1~2문단","ev":"레싱은 ‘시는 그림과 같이’라는 호라티우스의 고전적 관점이 회화의 원칙을 시에 적용해 두 예술의 경계를 흐린다고 비판한다.","keys":["호라티우스","시와 회화의 경계"]},{"h":"(가) 3문단","ev":"레싱은 시와 회화가 정보를 처리하는 방식이 달라 근본 차이가 생긴다며, 공통 기능 미메시스를 회화에서는 표현, 서술에서는 재현으로 나눈다.","keys":["매체의 차별성","표현","재현"]},{"h":"(가) 4문단","ev":"이미지예술은 공간적이라 동시적 묘사에, 문자예술은 시간적이라 연속적 묘사에 강하며, 레싱은 문자예술이 상상을 더 자극해 우월하다고 선언한다.","keys":["동시적 묘사","연속적 묘사","상상력"]},{"h":"(나) 1문단","ev":"매체 환경이 변하며 예술형식의 경계가 무너지자, 상호매체성은 매체를 예술형식과 같다고 보는 통합 관점과 매체의 작동 방식에 주목하는 관점으로 나뉜다.","keys":["상호매체성","두 관점"]},{"h":"(나) 2문단","ev":"통합 관점에서 지마는 문자·이미지·소리가 하나로 녹아든 오페라나 영화처럼 예술형식들이 통합되는 것을 예술의 이상으로 본다.","keys":["지마","매체 통합"]},{"h":"(나) 3~4문단","ev":"페히는 통합 관점이 매체와 형식을 구분하지 못한다고 보아 매체를 형식의 기술적 조건으로 따로 놓고, 둘의 위치는 고정되지 않는다고 한다.","keys":["페히","기술적 조건","위치 변화"]}],"key":"레싱은 문자·이미지 예술의 매체적 차이를, 페히는 예술형식과 매체의 구분을 내세운다.","pt":["레싱: 문자(시)=시간적·연속적 묘사, 이미지(회화)=공간적·동시적 묘사 — 뒤바꾼 선지 주의","레싱·페히의 공통 동의: 예술형식 간 차이를 매체의 차이로 분석할 수 있다(경계 해체는 통합 관점)","보기: 레싱은 회화 ⓑ를 재현이 아니라 표현으로, 페히는 회화가 영상에서 매체로 기능한다고 본다"],"src":"본책 p.248~251 · 해설 p.100~101","s":"수특 독서 · 주제 통합"},"r59":{"t":"건축물과 공간","cat":"주제 통합","steps":[{"h":"(가) 1~2문단","ev":"건축구조는 정하중·활하중에 맞서 생기는 내력(인장력·압축력 등)을 견디게 설계하며, 과하면 균열(당김)이나 좌굴(눌림)이 생긴다.","keys":["하중","내력","응력","좌굴"]},{"h":"(가) 구조","ev":"트러스는 삼각형 반복으로 하중을 분산하고, 아치는 하중을 압축력으로 전달하며, 골조는 기둥과 보로 공간 구성의 자유도를 높인다.","keys":["트러스","아치","골조"]},{"h":"(가) 3문단","ev":"콘크리트는 압축에 강하고 철근은 인장·압축 모두 강해 철근콘크리트로 보완하며, 목재는 가볍고 자연친화적이고 유리는 개방감과 확장감을 준다.","keys":["콘크리트","철근","철근콘크리트","유리"]},{"h":"(가) 4문단","ev":"칼라트라바는 트러스 구조로 접히고 펼쳐지는 날개 형태의 밀워키 아트 뮤지엄을, 하디드는 곡면과 콘크리트·복합소재로 헤이다르 알리예프 센터를 설계한다.","keys":["칼라트라바","하디드"]},{"h":"(나) 세 공간","ev":"르페브르는 공간을 사회적 산물로 보고, 지각된 공간(실제 사용), 개념화된 공간(전문가의 계획), 체험된 공간(주관적 경험)이 한 공간에 중첩된다고 한다.","keys":["지각된 공간","개념화된 공간","체험된 공간"]},{"h":"(나) 모순공간","ev":"자본주의 사회의 공간은 권력과 자본이 기획한 지배 공간인 모순공간이며, 이에 맞서는 대안이 차이공간이다.","keys":["모순공간","차이공간"]},{"h":"(나) 시민","ev":"시민은 공간에 접근하고 참여하며 바꿀 권리가 있고, 지배 공간의 기획을 벗어나 공간을 다시 구성하는 탈영토화는 공간의 민주화와 이어진다.","keys":["탈영토화","공간의 민주화"]}],"key":"(가)는 건축구조·재료의 원리를, (나)는 르페브르의 공간 이론(세 공간·모순공간·민주화)을 설명한다.","pt":["내력은 인장력·압축력 등을 포함하는 힘이지, 합이 일정한 값이 아니다(선지 함정)","아치는 하중을 압축력으로 전달 → 압축강도가 큰 재료가 적합, 철근콘크리트는 인장을 보완","보기: 세 공간은 중첩된다 — 체험된 공간이 개념화된 공간에 한정된다고 보면 오답"],"src":"본책 p.252~257 · 해설 p.101~103","s":"수특 독서 · 주제 통합"},"r60":{"t":"바디우·랑시에르","cat":"주제 통합","steps":[{"h":"(가) 1문단","ev":"바디우는 정치를 진리 탐구 절차로 보고, 제도는 사회구조의 영향을 받으므로 지도자나 제도 개선만으로는 안 되고 구조 자체가 바뀌어야 한다고 본다.","keys":["사회구조의 변화","진정한 정치"]},{"h":"(가) 2문단","ev":"사건은 기존 질서를 벗어나 기존 언어로 설명할 수 없고 질서를 뒤흔드는 충격이며, 존재하지 않고 우연히 발생했다가 사라진다.","keys":["사건","우연성"]},{"h":"(가) 3~4문단","ev":"사건은 ‘이름’을 남기고, 구성원이 제도·행위가 사건의 충격을 잇는지 판단하는 탐색을 거쳐 사건에 충실한 요소들의 집합인 진리가 생긴다.","keys":["이름","탐색","진리"]},{"h":"(나) 1~2문단","ev":"랑시에르는 정치를 역할 분할에 이의를 제기하는 ‘불화’로 보고, 기존 질서를 누구의 목소리가 들리는지 정하는 인식 구조인 ‘감각적인 것의 분할’이라 한다.","keys":["불화","감각적인 것의 분할"]},{"h":"(나) 3문단","ev":"불화는 단순한 의견 차이가 아니라 말할 수 없던 자들이 목소리를 내 분할에 균열을 내고 새 주체로 나타나는 예측 불가능한 순간이다.","keys":["말할 수 없는 자들","새로운 주체"]},{"h":"(나) 4문단","ev":"사회 발전은 제도의 개선이 아니라 불화로 평등을 다시 구성하는 과정이며, 평등은 목표가 아닌 전제이다.","keys":["평등의 재구성","평등은 전제"]}],"key":"바디우는 사건에 충실한 진리의 형성을, 랑시에르는 배제된 자들의 불화를 사회 변화의 동력으로 본다.","pt":["바디우: 지도자·제도 개선만으로는 사회구조가 안 바뀐다 — 제도가 구조를 바꾼다는 선지는 오답","사건=발생했다 사라지는 우연(이름이 남음) / 불화=의견 차이가 아닌 말할 수 없던 자들의 등장","보기 ㄷ은 방향 뒤집기: 제도·법체계가 사회구조의 영향을 받지, 그 반대가 아니다(바디우)"],"src":"본책 p.258~261 · 해설 p.103~105","s":"수특 독서 · 주제 통합"},"r61":{"t":"형사법상 인과 관계","cat":"주제 통합","steps":[{"h":"(가) 1~2문단","ev":"조건설(등가설)은 결과를 낳는 전체 조건의 개개 조건을 모두 동등한 원인으로 보고, 행위를 제거해도 결과가 생기는지 묻는 조건공식으로 조건관계를 확인한다.","keys":["조건설(등가설)","조건공식"]},{"h":"(가) 3문단","ev":"조건공식의 ‘선행사실이 없었다면 후행사실도 없었다’는 원인을 필요조건으로 보는 것이고, ‘있으면 있다’는 충분조건이다.","keys":["필요조건","충분조건"]},{"h":"(가) 4문단","ev":"단독으로도 결과를 낳는 복수의 독립 행위(택일적 인과관계)에 조건공식을 쓰면 어느 행위도 조건관계가 없어 원인이 아니게 되어 타당성이 의심된다.","keys":["택일적 인과관계","조건공식의 한계"]},{"h":"(나) 1문단","ev":"인과는 단순한 조건적 결합이 아니라 ‘야기’이며, 행위가 합법칙적으로 연결된 변화들을 거쳐 결과에 이를 때 원인이고 판단은 일반적 법칙에 의존한다.","keys":["야기","합법칙적 연결"]},{"h":"(나) 2~3문단","ev":"합법칙적 조건설은 조건공식을 버리고 일반적 법칙과 구체적 사건 진술에서 전건긍정식으로 결과를 도출하며, 법칙이 알려지지 않으면 판단이 불가능하다.","keys":["합법칙적 조건설","전건긍정식","포섭"]},{"h":"(나) 4문단","ev":"택일적 인과관계 사례는 일반적 법칙에 의문이 없어, 합법칙적 조건설에서는 복수의 행위가 각각 결과의 원인으로 인정된다.","keys":["택일적 인과관계","각각 원인"]}],"key":"조건설은 택일적 인과관계에서 한계를 보이고, 합법칙적 조건설은 법칙 포섭으로 이를 해결한다.","pt":["합법칙적 조건설은 조건공식을 ‘수정’한 것이 아니라 ‘포기’하고 법칙 포섭으로 판단(선지 함정)","조건설은 원인을 필요조건으로 보고, 전건긍정식의 전제에 등장하는 원인은 충분조건이다","보기: 조건설은 ‘행위 제거 시 결과 유무’로, 합법칙적 조건설은 법칙으로 이어진 행위만 원인으로 본다"],"src":"본책 p.262~264 · 해설 p.106~107","s":"수특 독서 · 주제 통합"},"r62":{"t":"시민 불복종과 소크라테스","cat":"주제 통합","steps":[{"h":"(가) 1~2문단","ev":"시민불복종은 부당한 법을 바꾸려고 의도적으로 법을 어기는 행동으로, 처벌은 감수하되 자신이 상위 규범에 부합한다고 보며 법이 부당하다고 진심으로 믿어야 한다.","keys":["시민불복종","상위 규범","처벌 감수"]},{"h":"(가) 3문단","ev":"간디·킹·3·1운동 같은 사례가 있고, 폭력과의 양립은 논란이지만 법이나 통치가 충분히 불의하면 도덕적으로 정당화될 수 있다고 본다.","keys":["사례","도덕적 정당화"]},{"h":"(가) 4문단","ev":"반대 쪽은 민주정부에는 합법적 방법이 있으므로 법을 지켜 모범을 보여야 하고, 법 존중이 약해지면 작은 위법도 무법 상태로 번진다고 본다.","keys":["합법적 방법","법 존중","미끄러운 비탈길"]},{"h":"(가) 5문단","ev":"선거로는 소수 의견이 무시된다는 비판에 반대 쪽은 다수결의 대가라 하지만, 그 원리를 따르면 불복종하는 쪽이 다수일 때는 오히려 옹호될 수 있다.","keys":["소수 의견","다수결의 원리"]},{"h":"(나) 합의","ev":"소크라테스는 정의로운 합의는 이행해야 하고, 탈옥하면 판결이 무력해져 법률과 나라를 파멸시킨다고 말한다.","keys":["합의 이행","법률과 국가"]},{"h":"(나) 비유","ev":"국가는 부모·주인처럼 우리를 낳고 길렀으니 시민이 되갚음식으로 맞설 수 없고, 70년간 숙고해 묵시적으로 합의했으니 법률을 준수해야 한다고 한다.","keys":["부모·주인 비유","묵시적 합의"]}],"key":"(가)는 시민불복종의 정당화 조건과 찬반 논거를, (나)는 법률과 합의를 지켜야 한다는 소크라테스의 입장을 보인다.","pt":["(가)는 정당화 조건을 소개하고 (나)는 불복종 실천의 부당성을 제시 — 단순한 찬반 대립이 아님","(가)의 특성: 법 위반·처벌 감수·부당하다는 진심. ‘폭력 불가’는 논란이라 특성으로 보기 어렵다","(나)는 ‘악법도 법’이 아니라 정의로운 합의 이행을 근거로 탈옥을 거부 / 국가는 설득의 대상"],"src":"본책 p.265~268 · 해설 p.107~109","s":"수특 독서 · 주제 통합"},"r63":{"t":"법 해석과 유추","cat":"주제 통합","steps":[{"h":"(가) 1문단","ev":"전통적으로 법 해석은 규범에서 사례로 가는 연역이고, 유추는 적용할 규범이 없을 때 비슷한 사례의 규범을 쓰는 흠결 보충의 보조 수단으로 여겨진다.","keys":["연역","흠결 보충"]},{"h":"(가) 2문단","ev":"그러나 법은 순수한 연역으로 발견되지 않고 사실과 규범을 오가며 정제되며, 유추도 두 사례를 잇는 제3의 비교점(일반적 명제)을 거친다.","keys":["제3의 비교점","규범 정제"]},{"h":"(가) 3문단","ev":"모든 법 해석이 규범과 사실관계를 맞추는 동화 과정이므로 유추가 해석의 본질이며, 둘의 구분을 없애고 방만함을 통제해야 유추금지 취지에 맞는다.","keys":["동화 과정","유추금지 원칙"]},{"h":"(나) 1문단","ev":"유추는 과거 사례와 현재 사례를 직접 비교해 유사성과 차이로 결론을 내는 것으로 여겨지며, 선례 기속과 유연성의 균형 같은 장점이 있다고 한다.","keys":["사례의 직접 비교","선례 기속"]},{"h":"(나) 2문단","ev":"유사점은 무한해 법적으로 중요한 것을 고르려면 규칙이나 원리가 필요하고, 그것이 정해지면 결론은 유사성이 아니라 일반적 명제가 정한다.","keys":["일반적 명제","유사성의 한계"]},{"h":"(나) 3문단","ev":"순전히 직관적인 비교는 추론도 선례의 기속도 아니고 자의적이어서 사법적 판단의 최소 요건을 못 갖추므로, 유추로 법을 확장할 수 없다.","keys":["자의성","사법적 판단"]}],"key":"(가)는 유추를 법해석의 본질로, (나)는 사례의 직접 비교로서의 유추가 성립하기 어렵다고 본다.","pt":["(가)는 유추를 규범과 사실의 동화(일반적 명제를 거침)로, (나)는 직접 비교로 보고 비판 — 대비","(가): 형사법에서 확장해석 등으로 처벌 규범을 우회 확대하는 것은 유추금지 취지에 반한다","보기: (나)는 규칙·원리를 더해도 유추의 규범 확장 효과가 강화된다고 보지 않는다(선지 함정)"],"src":"본책 p.269~272 · 해설 p.109~111","s":"수특 독서 · 주제 통합"},"r64":{"t":"페니실린","cat":"주제 통합","steps":[{"h":"(가) 1~2문단","ev":"탐구 목적과 무관하게 우연히 이룬 큰 발견을 세런디피티라 하며, 플레밍은 방치된 배양접시에서 푸른곰팡이 주변의 포도상구균이 파괴된 것을 보고 페니실린이라 부른다.","keys":["세런디피티","플레밍"]},{"h":"(가) 3문단","ev":"플레밍은 페니실린이 희석해도 박테리아에 듣고 동물에 무해함을 확인하지만, 불안정하고 즉각적이지 않아 더 연구하지 않고 의약계의 동기도 약하다.","keys":["연구 중단","백신"]},{"h":"(가) 4문단","ev":"플로리 연구팀은 정제한 페니실린이 생쥐의 감염을 치료함을 보이고, 히틀리가 대량 배양으로 인체용 양을 얻으며, 열·오한은 불순물 탓이라 제거한다.","keys":["플로리 연구팀","불순물 제거"]},{"h":"(가) 5문단","ev":"1941년 미국 농무성 연구소의 도움으로 옥수수 침지액 대량 배양과 생산량이 약 200배 많은 곰팡이를 얻고, 전쟁 중 효과가 입증돼 페니실린이 전 세계에서 생산된다.","keys":["대량 배양","상용화"]},{"h":"(나) 1~2문단","ev":"페니실린은 베타-락탐 고리가 트랜스펩티데이스와 결합해 펩티도글리칸 합성을 막아 세포벽을 약화시키므로, 세포벽이 없는 동물 세포는 해치지 않는다.","keys":["베타-락탐","펩티도글리칸","세포벽"]},{"h":"(나) 3문단","ev":"그람 음성균은 펩티도글리칸 층이 얇아도 세포벽 바깥에 외막이 있어 페니실린이 세포벽을 해치지 못하므로 효과가 없다.","keys":["그람 양성균","그람 음성균","외막"]}],"key":"(가)는 페니실린의 발견과 상용화 과정을, (나)는 펩티도글리칸 합성 방해라는 항균 원리를 설명한다.","pt":["(가)의 의문 중 (나)가 푸는 것: 동물엔 무해하고 박테리아만 죽이는 이유(세포벽의 유무)","푸른곰팡이 배양액의 저해 효과 확인은 예상한 실험, 우연한 것은 집락이 파괴된 것의 발견","펩티도글리칸은 양성균·음성균 모두 세포벽에 있으나, 음성균은 외막 때문에 페니실린에 죽지 않는다"],"src":"본책 p.273~277 · 해설 p.112~114","s":"수특 독서 · 주제 통합"},"r65":{"t":"독서 공간","cat":"실전 학습","steps":[{"h":"1문단","ev":"독서공간은 책을 읽는 공간이며, 물리적 독서공간은 서재·도서관 같은 본원적 공간과 버스처럼 원래 목적은 다르나 책을 읽는 곳으로 쓰이는 전용된 공간으로 나뉜다.","keys":["본원적 독서공간","전용된 독서공간"]},{"h":"2문단","ev":"침실 겸 서재나 카페처럼 둘의 구분이 어려운 경우가 있으며, 교실은 본원적 공간에 가깝지만 시험공부용으로 만들어진 독서실은 본원적 공간이 아니다.","keys":["구분의 모호함","독서실"]},{"h":"3문단","ev":"수업시간이나 독서모임처럼 독자의 의식 속에 형성된 인식적 독서공간은 물리적 제약에 구속받지 않고 선택과 관계에 따라 새로 구성·확장된다.","keys":["인식적 독서공간","물리적 제약"]},{"h":"4문단","ev":"전용할 수 있는 공간이 많고 디지털 기술로 가상공간에서 독서공간을 무한히 확장할 수 있어, 독서공간의 이해와 확장 노력이 더 중요해진다.","keys":["가상공간","독서공간 확장"]}],"key":"독서공간은 물리적(본원적·전용)과 인식적으로 나뉘며 디지털 시대에 무한히 확장된다.","pt":["독서실은 본원적 독서공간이 아니다(교실은 가깝다) — ‘교실처럼 독서실도’ 선지 함정","㉡전용된 공간은 ㉠물리적 공간의 일부이고, ㉡이면서 ㉢인식적인 곳은 존재하지 않는다","보기: 사가독서(독서 휴가)는 물리적 공간이 아니라 인식적 독서공간이다"],"src":"본책 p.280~282 · 해설 p.115~116","s":"수특 독서 · 실전 학습"},"r66":{"t":"야스퍼스의 한계 상황","cat":"실전 학습","steps":[{"h":"1문단","ev":"야스퍼스는 인간을 상황 내 존재로 보고, 인간을 구속하는 상황은 스스로 선택한 것이 아니며 상황에 대한 물음이 철학의 시작이라고 본다.","keys":["상황 내 존재","철학의 근원"]},{"h":"2문단","ev":"죽음·고통·투쟁·죄책감은 능동적 노력으로 바꿀 수 없는 한계상황이며, 인간은 이 앞에서 지식과 행동의 근거에 회의를 느끼고 불안과 좌절을 겪는다.","keys":["한계상황","불안과 좌절"]},{"h":"3문단","ev":"한계상황은 인간의 유한성을 깨닫게 하고 이를 회피하면 자기를 포기하는 것이며, 그 좌절은 인간이 초월자를 감지하는 계기가 된다.","keys":["유한성","초월자를 감지"]},{"h":"4문단","ev":"세계가 그 자체로는 이해되지 않는 불완전한 것임을 깨달을 때 인간은 언어로 설명할 수 없는 초월자에게 다가가며, 한계상황의 경험이 곧 실존이다.","keys":["초월자","세계의 불완전성"]},{"h":"5문단","ev":"초월자는 가능적 실존에게만 다의적인 암호로 나타나며, 각자의 방식으로 암호를 해독하는 과정에서 인간이 실존을 회복한다.","keys":["가능적 실존","암호 해독","실존 회복"]}],"key":"한계상황의 좌절이 초월자를 감지하는 계기가 되어, 암호를 해독하며 실존을 회복한다.","pt":["상황은 인간이 스스로 선택한 것이 아니다 — ‘스스로 선택한 상황에 구속’ 선지는 오답","㉠ 한계상황 경험이 긍정적인 이유: 좌절이 초월자를 감지하는 계기가 되기 때문","보기: 야스퍼스는 죽음에서 유한성을 깨닫고 초월자와의 만남이 필요하다고 보며 사르트르와 구별"],"src":"본책 p.283~285 · 해설 p.116~117","s":"수특 독서 · 실전 학습"},"r67":{"t":"동시 다중 라운드 경매","cat":"실전 학습","steps":[{"h":"1문단","ev":"미국은 처음에 사업계획서를 심사해 주파수를 할당하지만, 평가와 이의 제기 절차 때문에 할당까지 수년이 걸리는 시간의 문제가 있다.","keys":["심사 방식","시간 문제"]},{"h":"2문단","ev":"제비뽑기는 시간을 줄이지만 재판매가 가능해 투기꾼이 주파수를 얻고, 사용권이 지역별로 쪼개져 전국망 통신사업자가 나타나기 힘들어진다.","keys":["제비뽑기","투기","사용권 파편화"]},{"h":"3문단","ev":"경매의 목표는 효율적 분배와 정부 수입 극대화인데, 뉴질랜드는 모든 주파수를 한 번에 결정해 입찰 정보를 모르는 채 낙찰이 운에 좌우되고 가격도 낮다.","keys":["경매의 두 목표","뉴질랜드 경매"]},{"h":"4문단","ev":"동시 다중 라운드 경매는 모든 주파수를 동시에 입찰하고 라운드마다 최고가와 입찰자를 공개하며, 새 입찰이 없을 때까지 이전보다 높은 가격으로만 입찰하게 한다.","keys":["동시 입찰","정보 공개","라운드 반복"]},{"h":"4문단(2)","ev":"이전 라운드보다 많은 주파수에 입찰할 수 없게 한 것은 자기 정보는 숨기고 남의 정보만 보는 불공정 행위를 막기 위해서이다.","keys":["입찰 개수 제한","불공정 행위 예방"]},{"h":"5문단","ev":"동시 경매로 입찰 주저를 막고 정보 공개로 효율을 높여 사업자는 합리적인 가격에 낙찰받고 정부는 수입을 극대화하며, 영국 등 다른 나라도 따른다.","keys":["입찰 주저 방지","정부 수입 극대화"]}],"key":"심사·제비뽑기·기존 경매의 한계를 동시 다중 라운드 경매가 정보 공개와 동시 입찰로 해결했다.","pt":["인과 뒤집기 주의: 전국망 사업자 부재는 제비뽑기를 쓴 이유가 아니라 그 결과였다","뉴질랜드가 두 번째로 높은 입찰가를 받은 이유: 승자의 저주를 걱정해 낮게 입찰하는 것을 막으려고(보기)","입찰 개수 제한의 목적은 무리한 경쟁 예방이 아니라 정보를 숨기고 남의 정보만 보는 행위 예방"],"src":"본책 p.286~289 · 해설 p.117~118","s":"수특 독서 · 실전 학습"},"r68":{"t":"초전도체·초유체","cat":"실전 학습","steps":[{"h":"1문단","ev":"거시적 물리계는 온도가 높으면 주변과의 에너지 교환이 커 에너지준위가 중요하지 않게 되므로, 온도가 아주 낮아야 양자역학적 현상을 발견할 수 있다.","keys":["거시적 물리계","낮은 온도"]},{"h":"2문단","ev":"절대영도 근처 도체의 저항에 대해 마티센은 불순물 때문에 저항이 남는다고, 듀어는 불순물이 없으면 완전히 사라진다고, 켈빈은 전자가 얼어붙어 오히려 커진다고 본다.","keys":["마티센","듀어","켈빈"]},{"h":"3문단","ev":"오너스는 액체 헬륨으로 수은을 4.2K 가까이 냉각해 저항이 0이 되는 초전도 현상을 처음 관측하며, 불순물을 줄이기 쉬운 상온 액체 수은이 적합하다.","keys":["초전도 현상","수은","불순물 효과"]},{"h":"4문단","ev":"헬륨은 2.2K 아래에서도 얼지 않는데, 가벼워 영점운동이 크고 비활성 기체라 이를 구속할 힘이 부족해 절대영도에서도 액체인 양자액체이다.","keys":["영점운동","양자액체"]},{"h":"5문단","ev":"액체 헬륨의 밀도·비열이 2.2K 근처에서 최댓값을 가져 상전이가 확인되고, 그 아래의 헬륨 II는 점성이 사라져 저항 없이 흐르는 초유체로 밝혀진다.","keys":["상전이","람다점","초유체"]}],"key":"오너스의 극저온 실험이 저항 0의 초전도체와 점성이 사라진 초유체의 발견으로 이어졌다.","pt":["마티센·듀어·켈빈의 전망 대비: 불순물로 저항 잔존 / 불순물 없으면 완전 소멸 / 전자 동결로 저항 증가","㉠ 비활성기체 헬륨: 약한 인력 → 영점운동을 구속할 힘 부족 → 절대영도에서도 액체(삼중점 없음)","보기 그래프: 비열 최댓값(2.2K, λ점) 아래는 저항 없이 흐르는 액체이며 삼중점은 존재하지 않는다"],"src":"본책 p.290~295 · 해설 p.119~121","s":"수특 독서 · 실전 학습"},"r69":{"t":"담화 공동체 독자","cat":"실전 학습","steps":[{"h":"1문단","ev":"독자는 필자와의 관계에서 자아독자와 타자독자(수신자독자·허구적독자)로 나뉘어 왔고, 담화공동체 독자의 등장으로 이 구분의 범주에 변화가 생긴다.","keys":["자아독자","타자독자","담화공동체 독자"]},{"h":"2문단","ev":"담화공동체는 담화관습과 규약을 공유하는 집단이며, 필자와 독자는 지식·표현 방식을 함께 발전시키는 공동의 담화 생산자로서 대등하다.","keys":["담화관습","대등한 위상"]},{"h":"3문단","ev":"모든 텍스트는 다른 텍스트와 연결되며(상호텍스트성), 포터는 이를 반복과 전제로 설명하고 담화공동체는 반복과 전제로 연결된 집단이다.","keys":["상호텍스트성","반복","전제"]},{"h":"4문단","ev":"독자를 담화공동체로 보면 독자를 동질적 집단으로 단순화해 실제 독자의 다양성을 놓치고, 명료한 관습이 없는 공동체를 설명하기 어렵다.","keys":["동질화","독자의 다양성","명료한 관습 부재"]}],"key":"독자를 필자와 대등한 담화공동체로 보는 관점은 상호텍스트성과 연결되나 다양성 설명에 한계가 있다.","pt":["㉠ 이유: 담화공동체 독자는 필자와 대등한 담화 형성의 참여 주체라 필자·독자의 구분이 흐려진다","담화공동체 독자 개념은 공동체의 공통 특징에 주목해 독자의 다양성을 부각하지 못한다(선지 함정)","보기: ‘필자·독자 역할이 고정’이라는 반응은 오답 — 독자도 담화 형성에 참여한다"],"src":"본책 p.296~298 · 해설 p.121~122","s":"수특 독서 · 실전 학습"},"r70":{"t":"마음 업로딩","cat":"실전 학습","steps":[{"h":"(가) 1문단","ev":"커즈와일·보스트룀은 기억·가치관 같은 자아 구성 요소를 정보 패턴으로 보존하면 신체가 죽어도 생존한다고 보며, 이는 인격 동일성의 심리적 연속성 이론과 관련된다.","keys":["심리적 연속성","정보 패턴"]},{"h":"(가) 2문단","ev":"계산기능주의는 뇌를 생물학적 컴퓨터로 보고 정신을 정보 처리로 이해하며, 하나의 정신 상태를 여러 물질이 실현할 수 있다는 복수실현가능성(㉠)을 전제한다.","keys":["계산기능주의","복수실현가능성"]},{"h":"(가) 3~4문단","ev":"복수실현가능성에 따라 시냅스 과정을 스캔해 컴퓨터로 재현하는 업로딩이 가능하고, 알고리즘과 계산 구성이 유지되면 신체를 바꿔도 인간이 존재한다고 본다.","keys":["업로딩","알고리즘 유지"]},{"h":"(나) 1~2문단","ev":"업로딩이 원하는 생존이 되려면 심리적 특성이 거의 다 보존되어야 하고, 업로딩 가능 주장은 신체가 정신 구조에 차이를 만들지 않는다는 신체중립성(㉡)을 전제한다.","keys":["손실 없는 보존","신체중립성"]},{"h":"(나) 3문단","ev":"체화된 인지는 뇌 중심주의를 거부해 인지가 신체와 환경까지 포함한다고 보고, 몸의 종류에 따라 마음의 구조와 표상 방식이 달라 정신을 온전히 이전하기 어렵다고 한다.","keys":["체화된 인지","뇌 중심주의 거부"]},{"h":"(나) 4문단","ev":"개념도 신체와 결부되어, 신체가 다른 유기체는 세계를 이해하는 방식이 달라 외계인과 생각을 공유하기 어렵다.","keys":["신체 결부 개념","개념 공유의 어려움"]}],"key":"(가)는 계산기능주의에 근거해 마음 업로딩을 통한 영생을, (나)는 체화된 인지로 이를 비판한다.","pt":["㉠복수실현가능성이 참이면 ㉡신체중립성도 참 — 상반된 입장이라는 선지는 오답","(가)=업로딩 입장 제시, (나)=그 입장에 대한 비판 — 절충하거나 새 결론을 내는 글이 아님","보기: 계산기능주의는 A의 원격 이동에 동의, 체화된 인지는 B의 기능적 동일성 한계 지적에 동의"],"src":"본책 p.299~303 · 해설 p.122~125","s":"수특 독서 · 실전 학습"},"r71":{"t":"법인세","cat":"실전 학습","steps":[{"h":"1문단","ev":"법인세는 법인에 부과되어 수입에서 비용을 뺀 소득을 과세하며, 납세자 능력에 따른 부담 원칙을 적용하기 어려워 세율 구조가 단순하고 누진성과 무관하다.","keys":["법인세","단순한 세율"]},{"h":"2문단","ev":"법인세가 투자된 자본에 대한 과세(㉠)라면 부담이 자본 소유자에게 일차적으로 가고, 경제적 이윤에 대한 과세(㉡)라면 주주에게 전적으로 귀착된다.","keys":["자본 과세","경제적 이윤 과세","부담 귀착"]},{"h":"3문단(1)","ev":"자기자본 귀속이자(㉢)는 비용이 안 되지만 차입 이자는 비용이 되어 부채 의존을 부추기므로, 중립적 제도를 위해 감가상각을 경제적 감가상각과 일치시켜야 한다.","keys":["중립적 법인세","경제적 감가상각"]},{"h":"3문단(2)","ev":"경제적 감가상각은 중고 자본재 가격의 하락 속도를 보는 가격중심적 접근이나 물리적 특성 변화를 보는 비가격적 접근으로 측정한다.","keys":["가격중심적 접근","비가격적 접근"]},{"h":"4문단","ev":"계산이 복잡해 자본재를 그룹으로 나눠 내용기간 기준 정액법 등으로 감가상각하게 하고, 정부는 투자를 유도하려 더 빠른 감가상각을 허용해 세 부담을 줄이기도 한다.","keys":["정액법","내용기간","빠른 감가상각"]},{"h":"5문단","ev":"감가상각이 취득 당시의 역사적 비용에 기초해 인플레이션 때 대체 비용보다 작아지므로, 감가상각의 실질 가치가 떨어지고 법인의 실질 세 부담이 무거워진다.","keys":["역사적 비용","대체 비용","인플레이션"]}],"key":"법인세는 부담의 귀착, 감가상각 방식, 인플레이션에 따라 기업의 행동과 실질 세 부담이 달라진다.","pt":["㉠의 입장에서 ㉢(자기자본 귀속이자 비용 불가)을 근거로 ㉡(경제적 이윤 과세)을 반박하는 구도","ⓐ 이유: 빠른 감가상각은 비용을 늘려 세 부담을 줄이고 투자를 유인한다(계산 편의 아님)","보기: 내용기간이 짧아지면 감가상각이 커져 비용이 늘고 세 부담은 낮아진다(이윤은 감소)"],"src":"본책 p.304~307 · 해설 p.125~126","s":"수특 독서 · 실전 학습"},"r72":{"t":"역노화 기술","cat":"실전 학습","steps":[{"h":"1문단","ev":"노화는 DNA 손상 복구 효율이 떨어져 유전체가 불안정해지고 줄기세포가 고갈되는 등 세포 손상이 쌓여 생기며, 이를 거스르려는 연구 중 세포리프로그래밍이 주목받는다.","keys":["유전체 불안정성","줄기세포 고갈"]},{"h":"2문단","ev":"세포리프로그래밍은 분화된 세포를 줄기세포로 되돌리는 것으로, 야마나카 인자 4가지를 넣어 역분화시켜 만든 줄기세포가 유도만능줄기세포이다.","keys":["세포리프로그래밍","야마나카 인자","유도만능줄기세포"]},{"h":"3문단(1)","ev":"리프로그래밍된 세포는 노화 징후가 사라지지만 체세포로서 가졌던 고유의 정체성과 기능을 잃는 문제가 있다.","keys":["정체성 상실"]},{"h":"3문단(2)","ev":"2~4일만 야마나카 인자를 발현시키는 부분적 리프로그래밍은 정체성을 유지한 채 핵 구조와 DNA 손상을 개선하며, 근래 c-Myc를 뺀 3개로도 성공한다.","keys":["부분적 리프로그래밍","c-Myc 제외"]},{"h":"4문단","ev":"치료로 쓰려면 테라토마(기형종) 위험 같은 안전성, 회춘 지점과 필요한 발현 기간, 역노화 상태의 지속 기간이 해결 과제로 남아 있다.","keys":["테라토마","회춘 지점","지속성"]}],"key":"야마나카 인자로 세포를 부분적으로 되돌려 노화를 늦추는 역노화 기술의 원리와 과제이다.","pt":["야마나카 인자 4가지를 모두 써야 역분화가 되는 것은 아니다(c-Myc를 뺀 3개로도 성공)","㉠의 개선 방향: 완전 리프로그래밍은 정체성을 잃게 해, 중간 단계까지만 하는 부분적 방식으로 기능 유지","보기: 가역적 변화를 이끈 것이지 비가역으로 바꾼 게 아님 / 악성종양을 피하려 c-Myc를 뺌"],"src":"본책 p.308~310 · 해설 p.126~128","s":"수특 독서 · 실전 학습"}};
